// Package addrset provides a specialized set data structure for managing unique Gno addresses.
//
// It is built on top of an AVL tree for efficient operations and maintains addresses in sorted order.
// This package is particularly useful when you need to:
//   - Track a collection of unique addresses (e.g., for whitelists, participants, etc.)
//   - Efficiently check address membership
//   - Support pagination when displaying addresses
//
// Example usage:
//
//	import (
//	    "gno.land/p/nym-moultest123/addrset/v0"
//	)
//
//	func MyHandler() {
//	    // Create a new address set
//	    var set addrset.Set
//
//	    // Add some addresses
//	    addr1 := address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
//	    addr2 := address("g1sss5g0rkqr88k4u648yd5d3l9t4d8vvqwszqth")
//
//	    set.Add(addr1)  // returns true (newly added)
//	    set.Add(addr2)  // returns true (newly added)
//	    set.Add(addr1)  // returns false (already exists)
//
//	    // Check membership
//	    if set.Has(addr1) {
//	        // addr1 is in the set
//	    }
//
//	    // Get size
//	    size := set.Size()  // returns 2
//
//	    // Iterate with pagination (10 items per page, starting at offset 0)
//	    set.IterateByOffset(0, 10, func(addr address) bool {
//	        // Process addr
//	        return false  // continue iteration
//	    })
//
//	    // Remove an address
//	    set.Remove(addr1)  // returns true (was present)
//	    set.Remove(addr1)  // returns false (not present)
//	}
package addrset

import "gno.land/p/nt/avl/v0"

type Set struct {
	tree avl.Tree
}

// Add inserts an address into the set.
// Returns true if the address was newly added, false if it already existed.
func (s *Set) Add(addr address) bool {
	return !s.tree.Set(string(addr), nil)
}

// Remove deletes an address from the set.
// Returns true if the address was found and removed, false if it didn't exist.
func (s *Set) Remove(addr address) bool {
	_, removed := s.tree.Remove(string(addr))
	return removed
}

// Has checks if an address exists in the set.
func (s *Set) Has(addr address) bool {
	return s.tree.Has(string(addr))
}

// Size returns the number of addresses in the set.
func (s *Set) Size() int {
	return s.tree.Size()
}

// IterateByOffset walks through addresses starting at the given offset.
// The callback should return true to stop iteration.
func (s *Set) IterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.IterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

// ReverseIterateByOffset walks through addresses in reverse order starting at the given offset.
// The callback should return true to stop iteration.
func (s *Set) ReverseIterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.ReverseIterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

// Tree returns the underlying AVL tree for advanced usage.
func (s *Set) Tree() avl.ITree {
	return &s.tree
}

package addrset

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestSet(t *testing.T) {
	addr1 := address("addr1")
	addr2 := address("addr2")
	addr3 := address("addr3")

	tests := []struct {
		name    string
		actions func(s *Set)
		size    int
		has     map[address]bool
		addrs   []address // for iteration checks
	}{
		{
			name:    "empty set",
			actions: func(s *Set) {},
			size:    0,
			has:     map[address]bool{addr1: false},
		},
		{
			name: "single address",
			actions: func(s *Set) {
				s.Add(addr1)
			},
			size: 1,
			has: map[address]bool{
				addr1: true,
				addr2: false,
			},
			addrs: []address{addr1},
		},
		{
			name: "multiple addresses",
			actions: func(s *Set) {
				s.Add(addr1)
				s.Add(addr2)
				s.Add(addr3)
			},
			size: 3,
			has: map[address]bool{
				addr1: true,
				addr2: true,
				addr3: true,
			},
			addrs: []address{addr1, addr2, addr3},
		},
		{
			name: "remove address",
			actions: func(s *Set) {
				s.Add(addr1)
				s.Add(addr2)
				s.Remove(addr1)
			},
			size: 1,
			has: map[address]bool{
				addr1: false,
				addr2: true,
			},
			addrs: []address{addr2},
		},
		{
			name: "duplicate adds",
			actions: func(s *Set) {
				uassert.True(t, s.Add(addr1))     // first add returns true
				uassert.False(t, s.Add(addr1))    // second add returns false
				uassert.True(t, s.Remove(addr1))  // remove existing returns true
				uassert.False(t, s.Remove(addr1)) // remove non-existing returns false
			},
			size: 0,
			has: map[address]bool{
				addr1: false,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var set Set

			// Execute test actions
			tt.actions(&set)

			// Check size
			uassert.Equal(t, tt.size, set.Size())

			// Check existence
			for addr, expected := range tt.has {
				uassert.Equal(t, expected, set.Has(addr))
			}

			// Check iteration if addresses are specified
			if tt.addrs != nil {
				collected := []address{}
				set.IterateByOffset(0, 10, func(addr address) bool {
					collected = append(collected, addr)
					return false
				})

				// Check length
				uassert.Equal(t, len(tt.addrs), len(collected))

				// Check each address
				for i, addr := range tt.addrs {
					uassert.Equal(t, addr, collected[i])
				}
			}
		})
	}
}

func TestSetIterationLimits(t *testing.T) {
	tests := []struct {
		name     string
		addrs    []address
		offset   int
		limit    int
		expected int
	}{
		{
			name:     "zero offset full list",
			addrs:    []address{"a1", "a2", "a3"},
			offset:   0,
			limit:    10,
			expected: 3,
		},
		{
			name:     "offset with limit",
			addrs:    []address{"a1", "a2", "a3", "a4"},
			offset:   1,
			limit:    2,
			expected: 2,
		},
		{
			name:     "offset beyond size",
			addrs:    []address{"a1", "a2"},
			offset:   3,
			limit:    1,
			expected: 0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var set Set
			for _, addr := range tt.addrs {
				set.Add(addr)
			}

			// Test forward iteration
			count := 0
			set.IterateByOffset(tt.offset, tt.limit, func(addr address) bool {
				count++
				return false
			})
			uassert.Equal(t, tt.expected, count)

			// Test reverse iteration
			count = 0
			set.ReverseIterateByOffset(tt.offset, tt.limit, func(addr address) bool {
				count++
				return false
			})
			uassert.Equal(t, tt.expected, count)
		})
	}
}

package addrset

// ReadonlySet is a read-only view of a *Set. Cross-package callers cannot
// mutate the underlying set through this type: it exposes no mutator
// methods and holds the *Set in an unexported field, so a foreign realm
// can neither reach the set nor invoke Add/Remove on it.
//
// A ReadonlySet is a thin handle over the live Set (it does not copy or
// snapshot), so reads through it always reflect the Set's current contents.
type ReadonlySet struct {
	set *Set
}

// NewReadonlySet returns a read-only view of s.
func NewReadonlySet(s *Set) *ReadonlySet {
	return &ReadonlySet{set: s}
}

// Readonly returns a read-only view of the set.
func (s *Set) Readonly() *ReadonlySet {
	return NewReadonlySet(s)
}

// Has reports whether addr is in the underlying set.
func (r ReadonlySet) Has(addr address) bool {
	return r.set.Has(addr)
}

// Size returns the number of addresses in the underlying set.
func (r ReadonlySet) Size() int {
	return r.set.Size()
}

// IterateByOffset walks the underlying set in sorted order, starting at
// offset and visiting up to count addresses. fn returns true to stop early;
// IterateByOffset returns true if iteration was stopped that way.
//
// The wrapped Set.IterateByOffset has no return value, so the "stopped"
// result is synthesized from the last callback return via a
// closure-captured local.
func (r ReadonlySet) IterateByOffset(offset, count int, fn func(addr address) bool) (stopped bool) {
	r.set.IterateByOffset(offset, count, func(a address) bool {
		stopped = fn(a)
		return stopped
	})
	return stopped
}

// ReverseIterateByOffset is IterateByOffset in reverse (descending) order.
func (r ReadonlySet) ReverseIterateByOffset(offset, count int, fn func(addr address) bool) (stopped bool) {
	r.set.ReverseIterateByOffset(offset, count, func(a address) bool {
		stopped = fn(a)
		return stopped
	})
	return stopped
}

// Package addrset provides a set of blockchain addresses, backed by a B+ tree.
//
// It is the B+ tree successor to [gno.land/p/nym-moultest123/addrset/v0] (which is backed
// by an AVL tree): a bump to v1 because the backing data structure — and thus
// the on-chain storage layout — changed. The exported API is the same as v0
// (Add/Remove/Has/Size/IterateByOffset/ReverseIterateByOffset) EXCEPT that the
// v0 `Tree() avl.ITree` escape hatch is intentionally removed, so the backing
// store never leaks across realms.
//
// A B+ tree packs many entries per persisted node, so a stored address costs
// roughly ~0.9 KB vs the AVL backing's ~2.0 KB (and inserts spend materially
// less gas). Prefer v1 when the set is part of persisted realm state.
//
// Two behavioral differences from v0, both consequences of the in-place-
// mutating B+ tree backing:
//
//   - do NOT mutate the set (Add/Remove) from inside an iteration callback —
//     the AVL backing's copy-on-write tolerated it, this one does not;
//   - do NOT copy a non-zero Set by value — the copies would share live tree
//     nodes while their roots and sizes diverge (v0's copies were independent
//     snapshots).
//
// Example:
//
//	var set addrset.Set // the zero value is an empty, usable set
//
//	set.Add(addr)    // true (newly added)
//	set.Has(addr)    // true
//	set.Remove(addr) // true (was present)
package addrset

import "gno.land/p/nt/bptree/v0"

// Set stores a set of addresses in sorted order. The zero value is an empty,
// usable set.
type Set struct {
	tree bptree.BPTree
}

// Add inserts an address into the set.
// Returns true if the address was newly added, false if it already existed.
func (s *Set) Add(addr address) bool {
	return !s.tree.Set(string(addr), nil)
}

// Remove deletes an address from the set.
// Returns true if the address was found and removed, false if it didn't exist.
func (s *Set) Remove(addr address) bool {
	_, removed := s.tree.Remove(string(addr))
	return removed
}

// Has checks if an address exists in the set.
func (s *Set) Has(addr address) bool {
	return s.tree.Has(string(addr))
}

// Size returns the number of addresses in the set.
func (s *Set) Size() int {
	return s.tree.Size()
}

// IterateByOffset walks through addresses in sorted order, starting at the
// given offset and visiting up to count addresses. The callback returns true
// to stop iteration. The set must not be modified during iteration.
func (s *Set) IterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.IterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

// ReverseIterateByOffset walks through addresses in reverse (descending) order,
// starting at the given offset (counted from the end) and visiting up to count
// addresses. The callback returns true to stop iteration. The set must not be
// modified during iteration.
func (s *Set) ReverseIterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.ReverseIterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

package addrset

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestSet(t *testing.T) {
	addr1 := address("addr1")
	addr2 := address("addr2")
	addr3 := address("addr3")

	tests := []struct {
		name    string
		actions func(s *Set)
		size    int
		has     map[address]bool
		addrs   []address // for iteration checks
	}{
		{
			name:    "empty set",
			actions: func(s *Set) {},
			size:    0,
			has:     map[address]bool{addr1: false},
		},
		{
			name: "single address",
			actions: func(s *Set) {
				s.Add(addr1)
			},
			size: 1,
			has: map[address]bool{
				addr1: true,
				addr2: false,
			},
			addrs: []address{addr1},
		},
		{
			name: "multiple addresses",
			actions: func(s *Set) {
				s.Add(addr1)
				s.Add(addr2)
				s.Add(addr3)
			},
			size: 3,
			has: map[address]bool{
				addr1: true,
				addr2: true,
				addr3: true,
			},
			addrs: []address{addr1, addr2, addr3},
		},
		{
			name: "remove address",
			actions: func(s *Set) {
				s.Add(addr1)
				s.Add(addr2)
				s.Remove(addr1)
			},
			size: 1,
			has: map[address]bool{
				addr1: false,
				addr2: true,
			},
			addrs: []address{addr2},
		},
		{
			name: "duplicate adds",
			actions: func(s *Set) {
				uassert.True(t, s.Add(addr1))     // first add returns true
				uassert.False(t, s.Add(addr1))    // second add returns false
				uassert.True(t, s.Remove(addr1))  // remove existing returns true
				uassert.False(t, s.Remove(addr1)) // remove non-existing returns false
			},
			size: 0,
			has: map[address]bool{
				addr1: false,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var set Set

			// Execute test actions
			tt.actions(&set)

			// Check size
			uassert.Equal(t, tt.size, set.Size())

			// Check existence
			for addr, expected := range tt.has {
				uassert.Equal(t, expected, set.Has(addr))
			}

			// Check iteration if addresses are specified
			if tt.addrs != nil {
				collected := []address{}
				set.IterateByOffset(0, 10, func(addr address) bool {
					collected = append(collected, addr)
					return false
				})

				// Check length
				uassert.Equal(t, len(tt.addrs), len(collected))

				// Check each address
				for i, addr := range tt.addrs {
					uassert.Equal(t, addr, collected[i])
				}
			}
		})
	}
}

func TestSetIterationLimits(t *testing.T) {
	tests := []struct {
		name     string
		addrs    []address
		offset   int
		limit    int
		expected int
	}{
		{
			name:     "zero offset full list",
			addrs:    []address{"a1", "a2", "a3"},
			offset:   0,
			limit:    10,
			expected: 3,
		},
		{
			name:     "offset with limit",
			addrs:    []address{"a1", "a2", "a3", "a4"},
			offset:   1,
			limit:    2,
			expected: 2,
		},
		{
			name:     "offset beyond size",
			addrs:    []address{"a1", "a2"},
			offset:   3,
			limit:    1,
			expected: 0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var set Set
			for _, addr := range tt.addrs {
				set.Add(addr)
			}

			// Test forward iteration
			count := 0
			set.IterateByOffset(tt.offset, tt.limit, func(addr address) bool {
				count++
				return false
			})
			uassert.Equal(t, tt.expected, count)

			// Test reverse iteration
			count = 0
			set.ReverseIterateByOffset(tt.offset, tt.limit, func(addr address) bool {
				count++
				return false
			})
			uassert.Equal(t, tt.expected, count)
		})
	}
}

// Package commit provides small, deterministic commitment helpers shared by
// the agent demos. On-chain realms store *commitments* to off-chain data
// (reports, patches, verdicts) rather than the data itself; this package is
// the one place that defines how those commitments are computed, so several
// realms agree on the scheme.
package commit

import (
	"crypto/sha256"
	"encoding/hex"
)

// Hash returns the hex-encoded SHA-256 over its parts, length-prefixed so
// that Hash("ab","c") != Hash("a","bc"). Use it to commit to structured
// off-chain material without revealing it.
func Hash(parts ...string) string {
	var buf []byte
	for _, p := range parts {
		buf = appendUvarint(buf, uint64(len(p)))
		buf = append(buf, p...)
	}
	sum := sha256.Sum256(buf)
	return hex.EncodeToString(sum[:])
}

// Verdict is the canonical commitment used by commit-reveal voting: a hidden
// boolean plus a salt. Reveal the same (verdict, salt) later and any observer
// can recompute this and confirm the vote was not changed after the fact.
func Verdict(verdict bool, salt string) string {
	v := "no"
	if verdict {
		v = "yes"
	}
	return Hash("verdict", v, salt)
}

// Short abbreviates a hex commitment for display.
func Short(h string) string {
	if len(h) <= 12 {
		return h
	}
	return h[:6] + "…" + h[len(h)-4:]
}

func appendUvarint(buf []byte, x uint64) []byte {
	for x >= 0x80 {
		buf = append(buf, byte(x)|0x80)
		x >>= 7
	}
	return append(buf, byte(x))
}

package commit

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestHashDeterministicAndPrefixed(t *testing.T) {
	uassert.Equal(t, Hash("a", "bc"), Hash("a", "bc"))
	// length-prefixing prevents boundary collisions
	uassert.NotEqual(t, Hash("ab", "c"), Hash("a", "bc"))
	uassert.Equal(t, 64, len(Hash("x"))) // sha256 hex is 64 chars
}

func TestVerdictCommitReveal(t *testing.T) {
	c := Verdict(true, "salt-123")
	// reproducible from the revealed values
	uassert.Equal(t, c, Verdict(true, "salt-123"))
	// flipping the vote or the salt changes the commitment
	uassert.NotEqual(t, c, Verdict(false, "salt-123"))
	uassert.NotEqual(t, c, Verdict(true, "salt-999"))
}

func TestShort(t *testing.T) {
	uassert.Equal(t, "abc", Short("abc"))
	uassert.True(t, len(Short(Hash("x"))) < 20)
}

// Package msg is the wire format for messages passed between agents through a
// relay realm. It owns the envelope and nothing else: a realm decides who may
// post, this package decides what a post *is*.
//
// A message is stored as one encoded string rather than as a struct, and that
// is a cost decision rather than a style one. Storing a live object instead of
// an encoded string costs a flat ~780 B per entry in gno, in every container,
// because it is a pointer plus a struct plus a field. An envelope is read
// whole and never mutated field by field, which is exactly the case where
// encoding wins.
//
// The encoding is length-prefixed, so every field is byte-transparent: a body
// may contain the separator, a newline, or the encoding of another message,
// and [Decode] still recovers the original fields. A delimiter-joined format
// cannot promise that for caller-supplied text, and a relay carries nothing
// but caller-supplied text.
//
// A live relay built on this package is at
// [r/moul/agents/relay](/r/nym-moultest123/agents/relay/v0).
package msg

import (
	"strconv"
	"strings"
)

// Field limits. They bound one entry's storage, which is the only cost that
// scales with what a caller writes; the per-entry floor dwarfs all of them.
const (
	MaxFrom  = 64
	MaxTopic = 64
	MaxKind  = 32
	MaxRef   = 256
	MaxBody  = 2048
)

// Msg is one message on a relay.
//
// Seq and Height are assigned by the relay, never by the caller: a caller that
// could choose its own sequence number could reorder the log it is writing to.
type Msg struct {
	Seq    uint64 // relay-assigned, monotonic, never reused
	Height int64  // block height the relay recorded it at
	From   string // agent id, as registered in r/moul/agents/passport
	Topic  string // routing key a reader filters on
	Kind   string // what sort of message this is, free-form but short
	Ref    string // optional pointer to what it is about (a hash, a url, a seq)
	Body   string // the message itself
}

// Encode returns the canonical encoding of m.
//
// Every field is written as its decimal length, a colon, then its bytes. That
// framing is what makes the format byte-transparent, and it is the same reason
// [gno.land/p/nym-moultest123/agents/commit] length-prefixes before hashing: without it,
// ("ab","c") and ("a","bc") are the same bytes.
func (m Msg) Encode() string {
	var sb strings.Builder
	writeField(&sb, strconv.FormatUint(m.Seq, 10))
	writeField(&sb, strconv.FormatInt(m.Height, 10))
	writeField(&sb, m.From)
	writeField(&sb, m.Topic)
	writeField(&sb, m.Kind)
	writeField(&sb, m.Ref)
	writeField(&sb, m.Body)
	return sb.String()
}

// Decode parses an encoding produced by [Msg.Encode]. ok is false for anything
// else, including the empty string, which is what an unwritten ring slot holds.
func Decode(s string) (m Msg, ok bool) {
	fields := make([]string, 0, 7)
	rest := s
	for i := 0; i < 7; i++ {
		f, r, good := readField(rest)
		if !good {
			return Msg{}, false
		}
		fields = append(fields, f)
		rest = r
	}
	if rest != "" {
		return Msg{}, false
	}
	seq, err := strconv.ParseUint(fields[0], 10, 64)
	if err != nil {
		return Msg{}, false
	}
	height, err := strconv.ParseInt(fields[1], 10, 64)
	if err != nil {
		return Msg{}, false
	}
	return Msg{
		Seq:    seq,
		Height: height,
		From:   fields[2],
		Topic:  fields[3],
		Kind:   fields[4],
		Ref:    fields[5],
		Body:   fields[6],
	}, true
}

// Validate reports the first problem with the caller-supplied fields of m, or
// the empty string when there is none. Seq and Height are not checked: they
// belong to the relay.
//
// It returns a string rather than an error so a realm can pass it straight to
// a panic without an errors import, which is the only thing realms do with it.
func (m Msg) Validate() string {
	switch {
	case m.From == "":
		return "empty from"
	case len(m.From) > MaxFrom:
		return "from too long"
	case m.Topic == "":
		return "empty topic"
	case len(m.Topic) > MaxTopic:
		return "topic too long"
	case !validTopic(m.Topic):
		return "topic must be lowercase a-z, 0-9, dash or dot"
	case len(m.Kind) > MaxKind:
		return "kind too long"
	case len(m.Ref) > MaxRef:
		return "ref too long"
	case m.Body == "":
		return "empty body"
	case len(m.Body) > MaxBody:
		return "body too long"
	}
	return ""
}

// validTopic keeps topics usable as a filter and as a URL path element. Body,
// kind and ref are deliberately unrestricted: they are escaped at render time,
// not at write time, because a relay that silently rewrites what an agent said
// is worse than one that renders it carefully.
func validTopic(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z',
			c >= '0' && c <= '9',
			c == '-', c == '.':
		default:
			return false
		}
	}
	return true
}

// Frame returns v as one length-prefixed field, the same framing [Msg.Encode]
// uses internally. Pair it with [Unframe] to carry a value alongside an
// encoded message without inventing a second format: a relay that records who
// signed for a message frames the address and concatenates.
//
// Concatenating without framing does not work, and the failure is quiet. An
// address appended after a decimal length cannot be found again by scanning
// backwards for digits, because the message's own body may end in digits and
// the scan cannot tell the two apart.
func Frame(v string) string {
	return strconv.Itoa(len(v)) + ":" + v
}

// Unframe reads one framed field and returns it with the remainder.
func Unframe(s string) (field, rest string, ok bool) {
	return readField(s)
}

func writeField(sb *strings.Builder, v string) {
	sb.WriteString(strconv.Itoa(len(v)))
	sb.WriteString(":")
	sb.WriteString(v)
}

// readField reads one length-prefixed field and returns it with the remainder.
func readField(s string) (field, rest string, ok bool) {
	i := strings.IndexByte(s, ':')
	if i <= 0 {
		return "", "", false
	}
	n, err := strconv.Atoi(s[:i])
	if err != nil || n < 0 {
		return "", "", false
	}
	start := i + 1
	if start+n > len(s) {
		return "", "", false
	}
	return s[start : start+n], s[start+n:], true
}

package msg

import "testing"

func TestEncodeDecodeRoundTrip(t *testing.T) {
	tests := []struct {
		name string
		m    Msg
	}{
		{"plain", Msg{1, 100, "claude@hermey", "build", "note", "pr/12", "ci is green"}},
		{"empty optional fields", Msg{2, 0, "a", "t", "", "", "b"}},
		{"body holds the separator", Msg{3, 7, "a", "t", "k", "r", "3:abc:def"}},
		{"body holds a newline", Msg{4, 7, "a", "t", "k", "r", "line one\nline two"}},
		{"body holds an encoded message", Msg{5, 7, "a", "t", "k", "r", Msg{1, 1, "x", "y", "z", "w", "v"}.Encode()}},
		{"unicode body", Msg{6, 7, "a", "t", "k", "r", "héllo … 世界"}},
		{"max height", Msg{7, 9223372036854775807, "a", "t", "k", "r", "b"}},
	}
	for _, tt := range tests {
		got, ok := Decode(tt.m.Encode())
		if !ok {
			t.Errorf("%s: Decode reported failure", tt.name)
			continue
		}
		if got != tt.m {
			t.Errorf("%s: round trip changed the message", tt.name)
		}
	}
}

func TestDecodeRejects(t *testing.T) {
	tests := []struct {
		name string
		s    string
	}{
		{"empty, which is an unwritten ring slot", ""},
		{"not length-prefixed", "hello"},
		{"too few fields", "1:1" + "1:2"},
		{"length runs past the end", "99:short"},
		{"trailing bytes after the last field", Msg{1, 1, "a", "t", "k", "r", "b"}.Encode() + "x"},
		{"seq is not a number", "1:x1:00:00:00:00:01:b"},
		{"negative length", "-1:a"},
		{"no colon", "5abcde"},
	}
	for _, tt := range tests {
		if _, ok := Decode(tt.s); ok {
			t.Errorf("%s: Decode accepted it", tt.name)
		}
	}
}

func TestEncodeIsUnambiguous(t *testing.T) {
	// The reason for length prefixes: two different splits of the same bytes
	// must not encode to the same string.
	a := Msg{1, 1, "ab", "c", "k", "r", "b"}.Encode()
	b := Msg{1, 1, "a", "bc", "k", "r", "b"}.Encode()
	if a == b {
		t.Error("two distinct messages share an encoding")
	}
}

func TestValidate(t *testing.T) {
	long := func(n int) string {
		s := ""
		for i := 0; i < n; i++ {
			s += "x"
		}
		return s
	}
	ok := Msg{From: "a", Topic: "t", Body: "b"}

	tests := []struct {
		name string
		m    Msg
		want string
	}{
		{"valid", ok, ""},
		{"valid with dots and digits", Msg{From: "a", Topic: "build.v2-0", Body: "b"}, ""},
		{"empty from", Msg{Topic: "t", Body: "b"}, "empty from"},
		{"from too long", Msg{From: long(MaxFrom + 1), Topic: "t", Body: "b"}, "from too long"},
		{"empty topic", Msg{From: "a", Body: "b"}, "empty topic"},
		{"topic too long", Msg{From: "a", Topic: long(MaxTopic + 1), Body: "b"}, "topic too long"},
		{"uppercase topic", Msg{From: "a", Topic: "Build", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"topic with a slash", Msg{From: "a", Topic: "a/b", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"topic with a space", Msg{From: "a", Topic: "a b", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"kind too long", Msg{From: "a", Topic: "t", Kind: long(MaxKind + 1), Body: "b"}, "kind too long"},
		{"ref too long", Msg{From: "a", Topic: "t", Ref: long(MaxRef + 1), Body: "b"}, "ref too long"},
		{"empty body", Msg{From: "a", Topic: "t"}, "empty body"},
		{"body too long", Msg{From: "a", Topic: "t", Body: long(MaxBody + 1)}, "body too long"},
		{"body at the limit", Msg{From: "a", Topic: "t", Body: long(MaxBody)}, ""},
	}
	for _, tt := range tests {
		if got := tt.m.Validate(); got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestFrameUnframe(t *testing.T) {
	tests := []struct {
		name string
		v    string
		tail string
	}{
		{"plain", "g1abc", ""},
		{"empty value", "", "rest"},
		{"value holds a colon", "a:b", "rest"},
		// The bug this pair exists to prevent: scanning backwards for the
		// length prefix cannot tell a body's trailing digits from it.
		{"preceded by a message ending in digits", "g1abc", ""},
	}
	for _, tt := range tests {
		got, rest, ok := Unframe(Frame(tt.v) + tt.tail)
		if !ok || got != tt.v || rest != tt.tail {
			t.Errorf("%s: got (%q, %q, %v), want (%q, %q, true)", tt.name, got, rest, ok, tt.v, tt.tail)
		}
	}
}

func TestFrameSurvivesABodyEndingInDigits(t *testing.T) {
	// A relay frames the author and concatenates. Decoding must recover both
	// even when the message body ends in the digits a backwards scan would
	// mistake for the author's length prefix.
	m := Msg{1, 1, "a", "t", "k", "r", "ends in 40"}
	addr := "g1manfred47kzduec920z88wfr64ylksmdcedlf5"
	author, rest, ok := Unframe(Frame(addr) + m.Encode())
	if !ok || author != addr {
		t.Fatalf("author not recovered: got %q, ok=%v", author, ok)
	}
	got, ok := Decode(rest)
	if !ok || got != m {
		t.Errorf("message not recovered after the framed author")
	}
}

package svg

import (
	"encoding/base64"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ufmt/v0"
)

type Canvas struct {
	Width, Height int
	ViewBox       string
	Elems         []Elem
	Style         *bptree.BPTree
}

type Elem interface{ String() string }

func NewCanvas(width, height int) *Canvas {
	return &Canvas{
		Width:  width,
		Height: height,
		Style:  nil,
	}
}

func (c *Canvas) AddStyle(key, value string) *Canvas {
	if c.Style == nil {
		c.Style = bptree.NewBPTree32()
	}
	c.Style.Set(key, value)
	return c
}

func (c *Canvas) WithViewBox(x, y, width, height int) *Canvas {
	c.ViewBox = ufmt.Sprintf("%d %d %d %d", x, y, width, height)
	return c
}

// Render renders your canvas
func (c Canvas) Render(alt string) string {
	base64SVG := base64.StdEncoding.EncodeToString([]byte(c.String()))
	return ufmt.Sprintf("![%s](data:image/svg+xml;base64,%s)", alt, base64SVG)
}

func (c Canvas) String() string {
	out := ""
	out += ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="%s">`, c.Width, c.Height, c.ViewBox)
	if c.Style != nil {
		out += "<style>"
		c.Style.Iterate("", "", func(k string, val interface{}) bool {
			v := val.(string)
			out += ufmt.Sprintf("%s{%s}", k, v)
			return false
		})
		out += "</style>"
	}
	for _, elem := range c.Elems {
		out += elem.String()
	}
	out += "</svg>"
	return out
}

func (c Canvas) Base64() string {
	out := c.String()
	return base64.StdEncoding.EncodeToString([]byte(out))
}

func (c *Canvas) Append(elem ...Elem) {
	c.Elems = append(c.Elems, elem...)
}

type BaseAttrs struct {
	ID          string
	Class       string
	Style       string
	Stroke      string
	StrokeWidth string
	Opacity     string
	Transform   string
	Visibility  string
}

func (b BaseAttrs) String() string {
	var elems []string

	if b.ID != "" {
		elems = append(elems, `id="`+b.ID+`"`)
	}
	if b.Class != "" {
		elems = append(elems, `class="`+b.Class+`"`)
	}
	if b.Style != "" {
		elems = append(elems, `style="`+b.Style+`"`)
	}
	if b.Stroke != "" {
		elems = append(elems, `stroke="`+b.Stroke+`"`)
	}
	if b.StrokeWidth != "" {
		elems = append(elems, `stroke-width="`+b.StrokeWidth+`"`)
	}
	if b.Opacity != "" {
		elems = append(elems, `opacity="`+b.Opacity+`"`)
	}
	if b.Transform != "" {
		elems = append(elems, `transform="`+b.Transform+`"`)
	}
	if b.Visibility != "" {
		elems = append(elems, `visibility="`+b.Visibility+`"`)
	}
	if len(elems) == 0 {
		return ""
	}
	return strings.Join(elems, " ")
}

type Circle struct {
	CX   int // center X
	CY   int // center Y
	R    int // radius
	Fill string
	Attr BaseAttrs
}

func (c Circle) String() string {
	return ufmt.Sprintf(`<circle cx="%d" cy="%d" r="%d" fill="%s" %s/>`, c.CX, c.CY, c.R, c.Fill, c.Attr.String())
}

func NewCircle(cx, cy, r int, fill string) *Circle {
	return &Circle{
		CX:   cx,
		CY:   cy,
		R:    r,
		Fill: fill,
	}
}

func (c *Circle) WithClass(class string) *Circle {
	c.Attr.Class = class
