func ExampleBlocks() {
	print(Paragraph("This is a paragraph."))
	// Blockquote adds multiple newlines which Output doesn't allow, so trim
	println(strings.TrimSpace(Blockquote("This is a blockquote\nSpanning multiple lines")))

