	// > Spanning multiple lines
}

func ExampleCode() {
	println(InlineCode("inline `code`"))
	println(CodeBlock("line1\nline2"))
	println(LanguageCodeBlock("go", "func main() {\nprintln(\"Hello, world!\")\n}"))
	println(HorizontalRule())

	// Output:
