}

func TestBackwardIterator(t *testing.T) {
	d := New()
	d.PushBack("x", "y", "z")

	var items []any
	iter := d.Backward()
	iter(func(value any) bool {
		items = append(items, value)
		return true // continue
	})

	if len(items) != 3 {
		t.Errorf("Expected 3 items, got %d", len(items))
	}
	if items[0] != "z" || items[1] != "y" || items[2] != "x" {
