	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := Combine(tt.errors...)
			if got := err.Error(); got != tt.expected {
				t.Errorf("Combine() = %q, want %q", got, tt.expected)
			}
		})
	}
}

func TestUnwrapNilReceiver(t *testing.T) {
	var merr *multiError
	errs := merr.Unwrap()
	if errs != nil {
		t.Errorf("Expected nil slice for nil receiver, got %v", errs)
	}
}

func TestMultiErrorUnwrap(t *testing.T) {
	var nilMulti *multiError
	if got := nilMulti.Unwrap(); got != nil {
		t.Errorf("Unwrap on nil receiver: expected nil, got %v", got)
	}

	empty := &multiError{errors: nil}
	if got := empty.Unwrap(); got != nil {
		t.Errorf("Unwrap on empty: expected nil, got %v", got)
	}

	single := &multiError{errors: []error{newError("foo")}}
	got := single.Unwrap()
	if len(got) != 1 || got[0].Error() != "foo" {
		t.Errorf("Unwrap on single: expected [foo], got %v", got)
	}

	multi := &multiError{errors: []error{newError("foo"), newError("bar")}}
	got = multi.Unwrap()
	if len(got) != 2 || got[0].Error() != "foo" || got[1].Error() != "bar" {
		t.Errorf("Unwrap on multi: expected [foo bar], got %v", got)
	}
}

// Package fifo implements a fixed-size FIFO (First-In-First-Out) list data structure
// using a singly-linked list. The implementation prioritizes storage efficiency by minimizing
// storage operations - each add/remove operation only updates 1-2 pointers, regardless of
// list size.
//
// Key features:
// - Fixed-size with automatic removal of oldest entries when full
// - Support for both prepend (add at start) and append (add at end) operations
// - Constant storage usage through automatic pruning
// - O(1) append operations and latest element access
// - Iterator support for sequential access
// - Dynamic size adjustment via SetMaxSize
//
// This implementation is optimized for frequent updates, as insertions and deletions only
// require updating 1-2 pointers. However, random access operations are O(n) as they require
// traversing the list. For use cases where writes are rare, a slice-based
// implementation might be more suitable.
//
// The linked list structure is equally efficient for storing both small values (like pointers)
// and larger data structures, as each node maintains a single next-pointer regardless of the
// stored value's size.
//
// Example usage:
//
//	list := fifo.New(3)        // Create a new list with max size 3
//	list.Append("a")           // List: [a]
//	list.Append("b")           // List: [a b]
//	list.Append("c")           // List: [a b c]
//	list.Append("d")           // List: [b c d] (oldest element "a" was removed)
//	latest := list.Latest()    // Returns "d"
//	all := list.Entries()      // Returns ["b", "c", "d"]
package fifo

// node represents a single element in the linked list
type node struct {
	value any
	next  *node
}

// List represents a fixed-size FIFO list
type List struct {
	head    *node
	tail    *node
	size    int
	maxSize int
}

// New creates a new FIFO list with the specified maximum size
func New(maxSize int) *List {
	return &List{
		maxSize: maxSize,
	}
}

// Prepend adds a new entry at the start of the list. If the list exceeds maxSize,
// the last entry is automatically removed.
func (l *List) Prepend(entry any) {
	if l.maxSize == 0 {
		return
	}

	newNode := &node{value: entry}

	if l.head == nil {
		l.head = newNode
		l.tail = newNode
		l.size = 1
		return
	}

	newNode.next = l.head
	l.head = newNode

	if l.size < l.maxSize {
		l.size++
		return
	}

	// Remove last element by traversing to second-to-last
	if l.size == 1 {
		// Special case: if size is 1, just update both pointers
		l.head = newNode
		l.tail = newNode
		newNode.next = nil
		return

	}

	// Find second-to-last node
	current := l.head
	for current.next != l.tail {
		current = current.next
	}
	current.next = nil
	l.tail = current

}

// Append adds a new entry at the end of the list. If the list exceeds maxSize,
// the first entry is automatically removed.
func (l *List) Append(entry any) {
	if l.maxSize == 0 {
		return
	}

	newNode := &node{value: entry}

	if l.head == nil {
		l.head = newNode
		l.tail = newNode
		l.size = 1
		return
	}

	l.tail.next = newNode
	l.tail = newNode

	if l.size < l.maxSize {
		l.size++
	} else {
		l.head = l.head.next
	}
}

// Get returns the entry at the specified index.
// Index 0 is the oldest entry, Size()-1 is the newest.
func (l *List) Get(index int) any {
	if index < 0 || index >= l.size {
		return nil
	}

	current := l.head
	for i := 0; i < index; i++ {
		current = current.next
	}
	return current.value
}

// Size returns the current number of entries in the list
func (l *List) Size() int {
	return l.size
}

// MaxSize returns the maximum size configured for this list
func (l *List) MaxSize() int {
	return l.maxSize
}

// Entries returns all current entries as a slice
func (l *List) Entries() []any {
	entries := make([]any, l.size)
	current := l.head
	for i := 0; i < l.size; i++ {
		entries[i] = current.value
		current = current.next
	}
	return entries
}

// Iterator returns a function that can be used to iterate over the entries
// from oldest to newest. Returns nil when there are no more entries.
func (l *List) Iterator() func() any {
	current := l.head
	return func() any {
		if current == nil {
			return nil
		}
		value := current.value
		current = current.next
		return value
	}
}

// Latest returns the most recent entry.
// Returns nil if the list is empty.
func (l *List) Latest() any {
	if l.tail == nil {
		return nil
	}
	return l.tail.value
}

// SetMaxSize updates the maximum size of the list.
// If the new maxSize is smaller than the current size,
// the oldest entries are removed to fit the new size.
func (l *List) SetMaxSize(maxSize int) {
	if maxSize < 0 {
		maxSize = 0
	}

	// If new maxSize is smaller than current size,
	// remove oldest entries until we fit
	if maxSize < l.size {
		// Special case: if new maxSize is 0, clear the list
		if maxSize == 0 {
			l.head = nil
			l.tail = nil
			l.size = 0
		} else {
			// Keep the newest entries by moving head forward
			diff := l.size - maxSize
			for i := 0; i < diff; i++ {
				l.head = l.head.next
			}
			l.size = maxSize
		}
	}

	l.maxSize = maxSize
}

// Delete removes the element at the specified index.
// Returns true if an element was removed, false if the index was invalid.
func (l *List) Delete(index int) bool {
	if index < 0 || index >= l.size {
		return false
	}

	// Special case: deleting the only element
	if l.size == 1 {
		l.head = nil
		l.tail = nil
		l.size = 0
		return true
	}

	// Special case: deleting first element
	if index == 0 {
		l.head = l.head.next
		l.size--
		return true
	}

	// Find the node before the one to delete
	current := l.head
	for i := 0; i < index-1; i++ {
		current = current.next
	}

	// Special case: deleting last element
	if index == l.size-1 {
		l.tail = current
		current.next = nil
	} else {
		current.next = current.next.next
	}

	l.size--
	return true
}

package forge

import "gno.land/p/nt/avl/v0"

// Change states.
const (
	StateOpen   = "open"
	StateMerged = "merged"
	StateClosed = "closed"
)

// Review verdicts.
const (
	VerdictApprove        = "approve"
	VerdictRequestChanges = "request-changes"
	VerdictComment        = "comment"
)

// Change is a change request (a pull request): a claim that TargetRef should be
// moved to include HeadOID, plus the reviews of that claim.
//
// Reviews are bound to the object id they reviewed, not to the change. Push a
// new head and every earlier approval stops counting: not by a policy toggle a
// maintainer can switch off, but because the approval names an object that is
// no longer what is being merged.
type Change struct {
	ID         int64
	Title      string
	Body       string
	Author     address
	SourceRepo string // forge repo id, or a mirror locator; "" means this repo
	SourceRef  string
	HeadOID    string
	TargetRef  string
	State      string
	CreatedAt  int64
	UpdatedAt  int64

	MergedOID string // the object TargetRef moved to
	MergedBy  address
	MergedAt  int64

	reviews     *avl.Tree // address string -> *Review (latest per reviewer)
	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Review is one reviewer's verdict on one object id.
type Review struct {
	Reviewer address
	Verdict  string
	OID      string // the head the reviewer actually looked at
	Body     string
	Height   int64
}

// OpenChange files a change request. Permissionless, like an issue: the
// proposal costs its author gas and deposit, and costs a maintainer nothing
// until they choose to look.
func (r *Repo) OpenChange(actor address, height int64, title, body, sourceRepo, sourceRef, headOID, targetRef string) (*Change, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if sourceRepo != "" && !ValidRepoID(sourceRepo) && !ValidMirror(sourceRepo) {
		return nil, ErrInvalidRepoID
	}
	if sourceRef != "" && !ValidRefName(sourceRef) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(headOID) {
		return nil, ErrInvalidOID
	}
	if !ValidRefName(targetRef) {
		return nil, ErrInvalidRefName
	}
	c := &Change{
		ID:         r.nextChange,
		Title:      title,
		Body:       body,
		Author:     actor,
		SourceRepo: sourceRepo,
		SourceRef:  sourceRef,
		HeadOID:    headOID,
		TargetRef:  targetRef,
		State:      StateOpen,
		CreatedAt:  height,
		UpdatedAt:  height,
		reviews:    avl.NewTree(),
		comments:   avl.NewTree(),
	}
	r.changes.Set(seqKey(c.ID), c)
	r.nextChange++
	return c, nil
}

// UpdateChangeHead repoints an open change at a new object. The author may
// always update their own; a writer may update anyone's (the "maintainer pushed
// a fixup" case).
func (r *Repo) UpdateChangeHead(actor address, height, id int64, headOID string) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleWriter) {
		return ErrUnauthorized
	}
	if !ValidOID(headOID) {
		return ErrInvalidOID
	}
	if headOID == c.HeadOID {
		return ErrSameOID
	}
	c.HeadOID = headOID
	c.UpdatedAt = height
	return nil
}

// ReviewChange records a verdict against the change's current head. Anyone may
// review; only a writer's approval counts toward the merge policy (see
// CountApprovals): an unprivileged review is signal, not authority.
func (r *Repo) ReviewChange(actor address, height, id int64, verdict, body string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	switch verdict {
	case VerdictApprove, VerdictRequestChanges, VerdictComment:
	default:
		return ErrInvalidVerdict
	}
	if verdict == VerdictApprove && actor == c.Author && !r.AllowSelfApproval {
		return ErrSelfApproval
	}
	if !ValidText(body, MaxCommentLen) {
		return ErrInvalidText
	}
	c.reviews.Set(actor.String(), &Review{
		Reviewer: actor,
		Verdict:  verdict,
		OID:      c.HeadOID,
		Body:     body,
		Height:   height,
	})
	c.UpdatedAt = height
	return nil
}

// CommentChange appends a reply to a change request.
func (r *Repo) CommentChange(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	cm := &Comment{ID: c.nextComment, Author: actor, Body: body, CreatedAt: height}
	c.comments.Set(seqKey(cm.ID), cm)
	c.nextComment++
	c.UpdatedAt = height
	return cm, nil
}

// CloseChange withdraws or rejects a change. Author or maintainer.
func (r *Repo) CloseChange(actor address, height, id int64) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	c.State = StateClosed
	c.UpdatedAt = height
	return nil
}

// CountApprovals counts approvals that still apply: cast by a writer or above,
// against the change's current head, and (unless the repo allows it) not the
// author's own.
func (r *Repo) CountApprovals(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict != VerdictApprove || rv.OID != c.HeadOID {
			return false
		}
		if rv.Reviewer == c.Author && !r.AllowSelfApproval {
			return false
		}
		if !r.Can(rv.Reviewer, RoleWriter) {
			return false
		}
		n++
		return false
	})
	return n
}

// CountBlocking counts writers who requested changes on the current head.
func (r *Repo) CountBlocking(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict == VerdictRequestChanges && rv.OID == c.HeadOID && r.Can(rv.Reviewer, RoleWriter) {
			n++
		}
		return false
	})
	return n
}

// MergeChange moves TargetRef to mergedOID and records the move as one more
// entry in the reference log, tagged with the change it came from.
//
// expectedTargetOID is a compare-and-swap on the target ref ("" when the ref
// does not exist yet): a change approved against one base cannot be merged onto
// a base that moved underneath it. mergedOID is computed off chain by whoever
// performs the merge: the chain records the claim, signed, ordered and
// attributed, and a client with the objects verifies that the result actually
// contains HeadOID.
func (r *Repo) MergeChange(actor address, height, id int64, expectedTargetOID, mergedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if c.State != StateOpen {
		return nil, ErrChangeNotOpen
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidOID(mergedOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	if r.CountBlocking(c) > 0 {
		return nil, ErrChangesRequested
	}
	if r.CountApprovals(c) < r.RequiredApprovals {
		return nil, ErrNotEnoughApproval
	}
	cur := r.Ref(c.TargetRef)
	switch {
	case cur == nil && expectedTargetOID != "":
		return nil, ErrRefNotFound
	case cur != nil && cur.OID != expectedTargetOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == mergedOID:
		return nil, ErrSameOID
	}
	old := ""
	if cur != nil {
		old = cur.OID
	}
	r.refs.Set(c.TargetRef, &Ref{Name: c.TargetRef, OID: mergedOID, UpdatedAt: height, UpdatedBy: actor})
	e := r.appendLog(actor, height, c.TargetRef, old, mergedOID, KindMerge, c.ID, note)
	c.State = StateMerged
	c.MergedOID = mergedOID
	c.MergedBy = actor
	c.MergedAt = height
	c.UpdatedAt = height
	return e, nil
}

// Change returns a change by id, or nil.
func (r *Repo) Change(id int64) *Change {
	v := r.changes.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Change)
}

// IterateChanges walks change requests newest-first.
func (r *Repo) IterateChanges(offset, count int, cb func(*Change) bool) {
	if count <= 0 {
		count = r.changes.Size()
	}
	r.changes.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Change))
	})
}

// OpenChangeCount counts change requests still open.
func (r *Repo) OpenChangeCount() int {
	n := 0
	r.changes.Iterate("", "", func(_ string, value any) bool {
		if value.(*Change).State == StateOpen {
			n++
		}
		return false
	})
	return n
}

// ReviewCount is the number of reviewers who have weighed in (latest verdict
// per reviewer, on any head).
func (c *Change) ReviewCount() int { return c.reviews.Size() }

// Review returns a reviewer's latest verdict, or nil.
func (c *Change) Review(a address) *Review {
	v := c.reviews.Get(a.String())
	if v == nil {
		return nil
	}
	return v.(*Review)
}

// IterateReviews walks reviews in reviewer-address order.
func (c *Change) IterateReviews(cb func(*Review) bool) {
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Review))
	})
}

// CommentCount is the number of replies on the change.
func (c *Change) CommentCount() int { return c.comments.Size() }

// IterateComments walks replies oldest-first.
func (c *Change) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = c.comments.Size()
	}
	c.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

// Stale reports whether a review no longer applies to the change's head.
func (c *Change) Stale(rv *Review) bool { return rv.OID != c.HeadOID }

// Package forge is the domain engine of an on-chain software forge: repos,
// roles, an append-only reference log, issues and change requests (pull
// requests), with no chain imports of its own.
//
// What it does NOT do, on purpose: store blobs, trees or packfiles. Git objects
// stay wherever git already puts them (a mirror, an IPFS CID, a peer) and this
// package records what a forge is actually trusted for and what git alone does
// not authenticate:
//
//  1. which object id a ref points at, in what order it got there, and who said
//     so: an append-only, hash-chained reference log (the same shape as
//     gittuf's reference state log, with consensus playing the notary);
//  2. who is allowed to move which ref, and under what review policy;
//  3. the social layer: issues, change requests, reviews: bound to addresses
//     rather than to platform accounts;
//  4. the merge decision itself, recorded as one more entry in the same log.
//
// The chain cannot see the object graph, so it cannot verify that a new tip
// descends from the old one. It does not pretend to: every ref move is a
// compare-and-swap against the tip the caller expected (git's
// --force-with-lease, moved somewhere the forge operator cannot rewrite), any
// move that abandons that discipline is recorded as a force, and ancestry is
// checked by a client that has the objects. Ordering, attribution and policy
// are on chain; proof is local.
//
// All state lives in avl trees so every listing is ordered and paginatable, and
// every mutation takes the actor and the block height from the caller: the
// package is pure, deterministic and unit-testable without a chain.
//
// Live demo: gno.land/r/nym-moultest123/forge/v0.
package forge

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Role is a repo-scoped capability level. Roles are totally ordered: every
// check is "at least this role", so there is one comparison to audit.
type Role int

const (
	RoleNone       Role = iota // not a member
	RoleReader                 // explicit read (all repos are public in v0)
	RoleWriter                 // move non-protected refs, update own changes
	RoleMaintainer             // force-move refs, merge changes, triage issues
	RoleAdmin                  // manage members and repo settings
	RoleOwner                  // admin + transfer; at least one always exists
)

// String renders the role as the lowercase token used by the realm API.
func (r Role) String() string {
	switch r {
	case RoleReader:
		return "reader"
	case RoleWriter:
		return "writer"
	case RoleMaintainer:
		return "maintainer"
	case RoleAdmin:
		return "admin"
	case RoleOwner:
		return "owner"
	default:
		return "none"
	}
}

// ParseRole is the inverse of Role.String.
func ParseRole(s string) (Role, error) {
	switch s {
	case "none":
		return RoleNone, nil
	case "reader":
		return RoleReader, nil
	case "writer":
		return RoleWriter, nil
	case "maintainer":
		return RoleMaintainer, nil
	case "admin":
		return RoleAdmin, nil
	case "owner":
		return RoleOwner, nil
	}
	return RoleNone, ErrInvalidRole
}

// Forge is the top-level registry: repo id -> repo.
type Forge struct {
	repos *avl.Tree // "<namespace>/<name>" -> *Repo
}

// New returns an empty forge.
func New() *Forge {
	return &Forge{repos: avl.NewTree()}
}

// Repo is one repository. Nothing here is the code: Mirrors says where the
// objects can be fetched, Refs says what the objects are supposed to be.
type Repo struct {
	ID          string // "<namespace>/<name>", immutable
	Description string
	DefaultRef  string // fully-qualified, e.g. "refs/heads/main"
	Mirrors     []string
	ParentID    string // fork lineage, "" for a root repo
	CreatedAt   int64  // block height
	Archived    bool

	// Merge policy.
	RequiredApprovals int  // approvals needed to merge a change
	AllowSelfApproval bool // may the change author's own approval count

	members *avl.Tree // address string -> Role
	refs    *avl.Tree // ref name -> *Ref
	log     *avl.Tree // padded seq -> *LogEntry (append-only)
	issues  *avl.Tree // padded id -> *Issue
	changes *avl.Tree // padded id -> *Change

	head       string // digest of the last log entry ("" when the log is empty)
	nextSeq    int64
	nextIssue  int64
	nextChange int64
}

// CreateRepo registers a repo owned by actor.
func (f *Forge) CreateRepo(actor address, height int64, id, description, defaultRef string) (*Repo, error) {
	if !ValidRepoID(id) {
		return nil, ErrInvalidRepoID
	}
	if !ValidText(description, MaxDescLen) {
		return nil, ErrInvalidText
	}
	if defaultRef == "" {
		defaultRef = "refs/heads/main"
	}
	if !ValidRefName(defaultRef) {
		return nil, ErrInvalidRefName
	}
	if f.repos.Has(id) {
		return nil, ErrRepoExists
	}
	r := &Repo{
		ID:                id,
		Description:       description,
		DefaultRef:        defaultRef,
		CreatedAt:         height,
		RequiredApprovals: 1,
		members:           avl.NewTree(),
		refs:              avl.NewTree(),
		log:               avl.NewTree(),
		issues:            avl.NewTree(),
		changes:           avl.NewTree(),
	}
	r.members.Set(actor.String(), RoleOwner)
	f.repos.Set(id, r)
	return r, nil
}

// Fork registers newID as a fork of srcID and copies the parent's current refs
// into the child's log, so the fork records exactly what it forked from. The
// objects are not copied: they never were on chain: so the child inherits the
// parent's mirrors as its initial fetch locators.
func (f *Forge) Fork(actor address, height int64, srcID, newID string) (*Repo, error) {
	src := f.Repo(srcID)
	if src == nil {
		return nil, ErrRepoNotFound
	}
	child, err := f.CreateRepo(actor, height, newID, src.Description, src.DefaultRef)
	if err != nil {
		return nil, err
	}
	child.ParentID = srcID
	child.Mirrors = append([]string{}, src.Mirrors...)
	note := "fork of " + srcID + " at seq " + strconv.FormatInt(src.nextSeq, 10)
	if len(note) > MaxNoteLen {
		note = "fork of " + srcID
	}
	n := 0
	src.refs.Iterate("", "", func(key string, value any) bool {
		ref := value.(*Ref)
		child.appendLog(actor, height, ref.Name, "", ref.OID, KindCreate, 0, note)
		child.refs.Set(ref.Name, &Ref{Name: ref.Name, OID: ref.OID, UpdatedAt: height, UpdatedBy: actor})
		n++
		return n >= 32 // a fork records a snapshot, not an unbounded copy
	})
	return child, nil
}

// Repo returns the repo, or nil.
func (f *Forge) Repo(id string) *Repo {
	v := f.repos.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Repo)
}

// HasRepo reports whether the id is taken.
func (f *Forge) HasRepo(id string) bool { return f.repos.Has(id) }

// Size is the number of repos.
func (f *Forge) Size() int { return f.repos.Size() }

// IterateRepos walks repos in id order, newest-last, and stops when cb returns
// true. offset/count page the walk; count <= 0 means "to the end".
func (f *Forge) IterateRepos(offset, count int, cb func(*Repo) bool) {
	if count <= 0 {
		count = f.repos.Size()
	}
	f.repos.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Repo))
	})
}

// IterateNamespace walks the repos of one namespace in id order.
func (f *Forge) IterateNamespace(ns string, cb func(*Repo) bool) {
	f.repos.Iterate(ns+"/", ns+"0", func(_ string, value any) bool { // '0' is '/'+1
		return cb(value.(*Repo))
	})
}

// RoleOf returns the member's role, RoleNone when not a member.
func (r *Repo) RoleOf(a address) Role {
	v := r.members.Get(a.String())
	if v == nil {
		return RoleNone
	}
	return v.(Role)
}

// Can reports whether a holds at least the given role.
func (r *Repo) Can(a address, min Role) bool { return r.RoleOf(a) >= min }

// MemberCount is the number of members with an explicit role.
func (r *Repo) MemberCount() int { return r.members.Size() }

// IterateMembers walks members in address order.
func (r *Repo) IterateMembers(cb func(addr string, role Role) bool) {
	r.members.Iterate("", "", func(key string, value any) bool {
		return cb(key, value.(Role))
	})
}

// SetMember grants or revokes a role. Admins manage members; only an owner may
// mint another owner, and the last owner cannot be demoted: a repo with no
// owner is a repo nobody can ever unarchive.
func (r *Repo) SetMember(actor address, target address, role Role) error {
	if role < RoleNone || role > RoleOwner {
		return ErrInvalidRole
	}
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if role == RoleOwner && !r.Can(actor, RoleOwner) {
		return ErrUnauthorized
	}
	cur := r.RoleOf(target)
	if cur == RoleOwner && role != RoleOwner {
		if !r.Can(actor, RoleOwner) {
			return ErrUnauthorized // an admin cannot demote an owner
		}
		if r.ownerCount() == 1 {
			return ErrLastOwner
		}
	}
	if role == RoleNone {
		r.members.Remove(target.String())
		return nil
	}
	r.members.Set(target.String(), role)
	return nil
}

func (r *Repo) ownerCount() int {
	n := 0
	r.members.Iterate("", "", func(_ string, value any) bool {
		if value.(Role) == RoleOwner {
			n++
		}
		return false
	})
	return n
}

// SetDescription updates the one-line description.
func (r *Repo) SetDescription(actor address, description string) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if !ValidText(description, MaxDescLen) {
		return ErrInvalidText
	}
	r.Description = description
	return nil
}

// SetMirrors replaces the fetch locators. The first one is the canonical
// remote; the rest are fallbacks. The chain records them, it never fetches.
func (r *Repo) SetMirrors(actor address, mirrors []string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if len(mirrors) > MaxMirrors {
		return ErrTooMany
	}
	for _, m := range mirrors {
		if !ValidMirror(m) {
			return ErrInvalidMirror
		}
	}
	r.Mirrors = append([]string{}, mirrors...)
	return nil
}

// SetDefaultRef points the repo at another default branch.
func (r *Repo) SetDefaultRef(actor address, name string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if !ValidRefName(name) {
		return ErrInvalidRefName
	}
	r.DefaultRef = name
	return nil
}

// SetPolicy sets the merge policy: how many approvals a change needs, and
// whether the author's own approval counts.
func (r *Repo) SetPolicy(actor address, requiredApprovals int, allowSelfApproval bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if requiredApprovals < 0 || requiredApprovals > 16 {
		return ErrTooMany
	}
	r.RequiredApprovals = requiredApprovals
	r.AllowSelfApproval = allowSelfApproval
	return nil
}

// SetArchived freezes (or unfreezes) the repo. An archived repo takes no
// mutation except unarchiving: the log stays readable forever.
func (r *Repo) SetArchived(actor address, archived bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	r.Archived = archived
	return nil
}

// Counts for rendering.
func (r *Repo) RefCount() int    { return r.refs.Size() }
func (r *Repo) IssueCount() int  { return r.issues.Size() }
func (r *Repo) ChangeCount() int { return r.changes.Size() }

// seqKey zero-pads an id to a fixed width so avl keys sort numerically.
// ufmt has no width flags in gno, so the padding is done by hand: "%016d"
// silently returns the bare number and would sort 10 before 2.
func seqKey(n int64) string {
	s := strconv.FormatInt(n, 10)
	if len(s) >= 16 {
		return s
	}
	return strings.Repeat("0", 16-len(s)) + s
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/urequire/v0"
)

// Deterministic, checksum-valid test addresses.
var (
	alice = testutils.TestAddress("alice") // owner
	bob   = testutils.TestAddress("bob")   // maintainer
	carol = testutils.TestAddress("carol") // writer
	dave  = testutils.TestAddress("dave")  // reader
	eve   = testutils.TestAddress("eve")   // stranger
)

// oid builds a well-formed 40-hex object id out of one hex digit.
func oid(c string) string { return strings.Repeat(c, 40) }

// newRepo returns a repo owned by alice with the standard cast: bob
// maintainer, carol writer, dave reader, eve nothing.
func newRepo(t *testing.T) (*Forge, *Repo) {
	t.Helper()
	f := New()
	r, err := f.CreateRepo(alice, 100, "moul/forge", "an on-chain forge", "")
	urequire.NoError(t, err)
	urequire.NoError(t, r.SetMember(alice, bob, RoleMaintainer))
	urequire.NoError(t, r.SetMember(alice, carol, RoleWriter))
	urequire.NoError(t, r.SetMember(alice, dave, RoleReader))
	return f, r
}

package forge

import "gno.land/p/nt/avl/v0"

// Issue is a discussion thread bound to a repo. Anyone with an address may open
// one: the spam gate is not a moderator, it is that the author pays gas and
// locks the storage deposit for every byte they write.
type Issue struct {
	ID        int64
	Title     string
	Body      string
	Author    address
	Open      bool
	Labels    []string
	CreatedAt int64
	UpdatedAt int64

	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Comment is one reply, on an issue or on a change request.
type Comment struct {
	ID        int64
	Author    address
	Body      string
	CreatedAt int64
}

// OpenIssue files an issue. Permissionless by design.
func (r *Repo) OpenIssue(actor address, height int64, title, body string, labels []string) (*Issue, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if err := checkLabels(labels); err != nil {
		return nil, err
	}
	i := &Issue{
		ID:        r.nextIssue,
		Title:     title,
		Body:      body,
		Author:    actor,
		Open:      true,
		Labels:    append([]string{}, labels...),
		CreatedAt: height,
		UpdatedAt: height,
		comments:  avl.NewTree(),
	}
	r.issues.Set(seqKey(i.ID), i)
	r.nextIssue++
	return i, nil
}

// CommentIssue appends a reply. Closed issues still take comments (closing is a
// triage state, not a gag); an archived repo takes none.
func (r *Repo) CommentIssue(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return nil, ErrIssueNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	c := &Comment{ID: i.nextComment, Author: actor, Body: body, CreatedAt: height}
	i.comments.Set(seqKey(c.ID), c)
	i.nextComment++
	i.UpdatedAt = height
	return c, nil
}

// SetIssueOpen closes or reopens an issue. The author can always close their
// own; maintainers can close anyone's.
func (r *Repo) SetIssueOpen(actor address, height, id int64, open bool) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if i.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	i.Open = open
	i.UpdatedAt = height
	return nil
}

// SetIssueLabels replaces an issue's labels. Triage is a maintainer action.
func (r *Repo) SetIssueLabels(actor address, height, id int64, labels []string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if err := checkLabels(labels); err != nil {
		return err
	}
	i.Labels = append([]string{}, labels...)
	i.UpdatedAt = height
	return nil
}

// Issue returns an issue by id, or nil.
func (r *Repo) Issue(id int64) *Issue {
	v := r.issues.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Issue)
}

// IterateIssues walks issues newest-first.
func (r *Repo) IterateIssues(offset, count int, cb func(*Issue) bool) {
	if count <= 0 {
		count = r.issues.Size()
	}
	r.issues.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Issue))
	})
}

// OpenIssueCount counts issues still open.
func (r *Repo) OpenIssueCount() int {
	n := 0
	r.issues.Iterate("", "", func(_ string, value any) bool {
		if value.(*Issue).Open {
			n++
		}
		return false
	})
	return n
}

// CommentCount is the number of replies on the issue.
func (i *Issue) CommentCount() int { return i.comments.Size() }

// IterateComments walks replies oldest-first.
func (i *Issue) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = i.comments.Size()
	}
	i.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

func checkLabels(labels []string) error {
	if len(labels) > MaxLabels {
		return ErrTooMany
	}
	for _, l := range labels {
		if !ValidLabel(l) {
			return ErrInvalidText
		}
	}
	return nil
}

package forge

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// Log entry kinds.
const (
	KindCreate = "create" // a ref that did not exist now points somewhere
	KindUpdate = "update" // compare-and-swap succeeded
	KindForce  = "force"  // the tip was replaced without a matching expectation
	KindDelete = "delete" // the ref is gone (the log is not)
	KindMerge  = "merge"  // an update performed by merging a change request
)

// Ref is the current state of one reference. The history of how it got here is
// in the repo log, which nothing can rewrite.
type Ref struct {
	Name      string
	OID       string
	UpdatedAt int64
	UpdatedBy address
}

// LogEntry is one link of the repo's reference log. The log is append-only and
// hash-chained: Digest commits to every earlier entry, so publishing a single
// digest (in a release note, a package manifest, a tweet) pins the entire
// history of every ref up to that point.
type LogEntry struct {
	Seq      int64
	Ref      string
	OldOID   string // "" when the ref did not exist
	NewOID   string // "" on delete
	Actor    address
	Height   int64
	Kind     string
	ChangeID int64 // the merged change, 0 otherwise
	Note     string
	Digest   string // hex sha256 over the previous digest and this entry
}

// EntryDigest computes the chain digest of e given the previous entry's digest.
// It is exported so an off-chain verifier can recompute the chain byte for byte
// from the values it read back; the field order below is the wire format and
// must not change within a version.
func EntryDigest(prev string, e *LogEntry) string {
	fields := []string{
		prev,
		strconv.FormatInt(e.Seq, 10),
		e.Ref,
		e.OldOID,
		e.NewOID,
		e.Actor.String(),
		strconv.FormatInt(e.Height, 10),
		e.Kind,
		strconv.FormatInt(e.ChangeID, 10),
		e.Note,
	}
	sum := sha256.Sum256([]byte(strings.Join(fields, "\n")))
	return hex.EncodeToString(sum[:])
}

// appendLog writes one entry and advances the chain head. Callers have already
// authorized and validated; this never fails.
func (r *Repo) appendLog(actor address, height int64, ref, oldOID, newOID, kind string, changeID int64, note string) *LogEntry {
	e := &LogEntry{
		Seq:      r.nextSeq,
		Ref:      ref,
		OldOID:   oldOID,
		NewOID:   newOID,
		Actor:    actor,
		Height:   height,
		Kind:     kind,
		ChangeID: changeID,
		Note:     note,
	}
	e.Digest = EntryDigest(r.head, e)
	r.log.Set(seqKey(e.Seq), e)
	r.head = e.Digest
	r.nextSeq++
	return e
}

// SetRef moves a ref by compare-and-swap: expectedOID must be the tip the
// caller last saw ("" to create a ref that does not exist yet). This is git's
// --force-with-lease, except the lease is held by consensus rather than by the
// server you are pushing to, so a concurrent push cannot be silently lost and a
// rewritten history cannot be presented as if it had always been that way.
//
// The chain cannot check that newOID descends from expectedOID: it has no
// objects. That check belongs to a client holding the repo, which is exactly
// why every move is recorded rather than merely applied.
func (r *Repo) SetRef(actor address, height int64, name, expectedOID, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleWriter) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	switch {
	case cur == nil && expectedOID != "":
		return nil, ErrRefNotFound
	case cur != nil && expectedOID == "":
		return nil, ErrRefExists
	case cur != nil && cur.OID != expectedOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == newOID:
		return nil, ErrSameOID
	}
	kind := KindUpdate
	old := ""
	if cur == nil {
		kind = KindCreate
	} else {
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, kind, 0, note), nil
}

// ForceSetRef moves a ref without an expectation. It needs RoleMaintainer and
// is permanently recorded as KindForce: the point is not to forbid a force-push
// (sometimes it is the right call) but to make one impossible to hide.
func (r *Repo) ForceSetRef(actor address, height int64, name, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	old := ""
	if cur := r.Ref(name); cur != nil {
		if cur.OID == newOID {
			return nil, ErrSameOID
		}
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, KindForce, 0, note), nil
}

// DeleteRef removes a ref by compare-and-swap. The ref disappears from the
// current state; the log keeps every object it ever pointed at.
//
// Maintainer-only for an economic reason as much as a safety one: on gno.land
// the storage-deposit refund goes to whoever frees the bytes, not to whoever
// paid for them (`receiver := caller` in the vm keeper's deposit path, gno
// master 2026-09-19), so an open delete path pays for vandalism.
func (r *Repo) DeleteRef(actor address, height int64, name, expectedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	if cur == nil {
		return nil, ErrRefNotFound
	}
	if cur.OID != expectedOID {
		return nil, ErrStaleRef
	}
	if name == r.DefaultRef {
		return nil, ErrUnauthorized // the default branch is not deletable
	}
	r.refs.Remove(name)
	return r.appendLog(actor, height, name, cur.OID, "", KindDelete, 0, note), nil
}

// Ref returns the current state of a ref, or nil.
func (r *Repo) Ref(name string) *Ref {
	v := r.refs.Get(name)
	if v == nil {
		return nil
	}
	return v.(*Ref)
}

// IterateRefs walks refs in name order.
func (r *Repo) IterateRefs(cb func(*Ref) bool) {
	r.refs.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Ref))
	})
}

// LogHead is the digest of the last entry, "" for an empty log. Pin this value
// anywhere off chain and the whole history becomes falsifiable.
func (r *Repo) LogHead() string { return r.head }

// LogSize is the number of entries ever appended.
func (r *Repo) LogSize() int { return r.log.Size() }

// LogEntryAt returns one entry by sequence number, or nil.
func (r *Repo) LogEntryAt(seq int64) *LogEntry {
	v := r.log.Get(seqKey(seq))
	if v == nil {
		return nil
	}
	return v.(*LogEntry)
}

// IterateLog walks the log oldest-first.
func (r *Repo) IterateLog(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// IterateLogReverse walks the log newest-first, which is what a UI wants.
func (r *Repo) IterateLogReverse(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// VerifyLog recomputes the whole digest chain and reports the first entry whose
// digest does not follow from its predecessor. It should be impossible on a
// live chain: it is here because a transparency log nobody can verify is just
// a log, and a client should be running this against the values it read back.
func (r *Repo) VerifyLog() (bool, int64) {
	prev := ""
	bad := int64(-1)
	r.log.Iterate("", "", func(_ string, value any) bool {
		e := value.(*LogEntry)
		if EntryDigest(prev, e) != e.Digest {
			bad = e.Seq
			return true
		}
		prev = e.Digest
		return false
	})
	return bad < 0, bad
}

package forge

import "strings"

// Size caps. Every string the chain stores is bounded: an unbounded field is an
// unbounded storage deposit, and on gno.land the deposit is paid per byte by
// whoever writes it (100ugnot/byte at the time of writing).
const (
	MaxRepoPartLen = 39   // per side of "<namespace>/<name>"
	MaxRefNameLen  = 255  // git's own limit for a single ref name
	MaxTitleLen    = 200  // issue / change title
	MaxBodyLen     = 8192 // issue / change body
	MaxCommentLen  = 4096
	MaxDescLen     = 512
	MaxNoteLen     = 140 // single-line note attached to a log entry
	MaxMirrorLen   = 512
	MaxMirrors     = 8
	MaxLabels      = 10
	MaxLabelLen    = 32
)

// ValidOID reports whether s is a git object id: 40 (SHA-1) or 64 (SHA-256)
// lowercase hex characters. Case is fixed so the same object always has the
// same on-chain key and the same digest-chain input.
func ValidOID(s string) bool {
	if len(s) != 40 && len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// ValidRefName reports whether s is a fully-qualified ref name this forge
// accepts: a "refs/"-rooted subset of git-check-ref-format(1).
//
// Deliberately stricter than git: the name must be fully qualified, so there is
// never an ambiguity between "main" the branch and "main" the tag, and a client
// can map an on-chain name onto a local ref without a lookup table.
func ValidRefName(s string) bool {
	if s == "" || len(s) > MaxRefNameLen {
		return false
	}
	if !strings.HasPrefix(s, "refs/") {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "@{") {
		return false
	}
	if strings.HasSuffix(s, "/") || strings.HasSuffix(s, ".") {
		return false
	}
	parts := strings.Split(s, "/")
	if len(parts) < 2 {
		return false
	}
	for _, p := range parts {
		if p == "" || p == "@" {
			return false
		}
		if strings.HasPrefix(p, ".") || strings.HasSuffix(p, ".lock") {
			return false
		}
		for i := 0; i < len(p); i++ {
			if !refByteOK(p[i]) {
				return false
			}
		}
	}
	return true
}

// refByteOK rejects the bytes git itself rejects in a ref component: ASCII
// control characters, space, DEL, and the pathspec/revision metacharacters.
func refByteOK(c byte) bool {
	if c <= 0x20 || c == 0x7f {
		return false
	}
	switch c {
	case '~', '^', ':', '?', '*', '[', '\\':
		return false
	}
	return true
}

// ValidRepoID reports whether s is "<namespace>/<name>". The name is always a
// lowercase slug; the namespace is either a slug (a claimed user name) or a
// bech32 address (the caller's own). The two shapes cannot collide: an address
// is 40 characters and a slug caps at MaxRepoPartLen, which is 39.
//
// This layer validates the SHAPE only. Whether the caller may claim a given
// namespace is an ownership question that needs a chain, so it belongs to the
// realm (see the realm's README).
func ValidRepoID(s string) bool {
	ns, name, ok := SplitRepoID(s)
	if !ok {
		return false
	}
	return (validSlug(ns) || AddressNamespace(ns)) && validSlug(name)
}

// SplitRepoID splits "<namespace>/<name>" into its two halves. It does not
// validate either half; ok is false only when the id is not two slash-separated
// non-empty parts.
func SplitRepoID(s string) (ns, name string, ok bool) {
	i := strings.Index(s, "/")
	if i <= 0 || i == len(s)-1 || strings.Count(s, "/") != 1 {
		return "", "", false
	}
	return s[:i], s[i+1:], true
}

// AddressNamespace reports whether ns is shaped like a gno bech32 address, the
// namespace every account owns without registering anything. The realm still
// checks that it is the CALLER's address; this only says which of the two
// ownership rules applies.
func AddressNamespace(ns string) bool {
	if len(ns) != 40 || !strings.HasPrefix(ns, "g1") {
		return false
	}
	for i := 2; i < len(ns); i++ {
		if !strings.ContainsRune(bech32Charset, rune(ns[i])) {
			return false
		}
	}
	return true
}

// bech32Charset is bech32's data alphabet: lowercase alphanumerics minus the
// four characters it drops to avoid transcription errors (1, b, i, o).
const bech32Charset = "023456789acdefghjklmnpqrstuvwxyz"

// validSlug: 1..MaxRepoPartLen chars, [a-z0-9] at both ends, [a-z0-9-_.] inside,
// no "..", no "--". Mixed case is rejected rather than folded: two ids that
// differ only in case would be two avl keys and one human-visible name.
func validSlug(s string) bool {
	if s == "" || len(s) > MaxRepoPartLen {
		return false
	}
	if !alnum(s[0]) || !alnum(s[len(s)-1]) {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "--") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if alnum(c) || c == '-' || c == '_' || c == '.' {
			continue
		}
		return false
	}
	return true
}

func alnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
}

// ValidText reports whether s fits in max bytes and carries no control
// characters other than newline and tab. Render output is markdown served by
// gnoweb, so a stray control byte is a rendering bug for every reader forever.
func ValidText(s string, max int) bool {
	if len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\t' {
			continue
		}
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidLine reports whether s is single-line text within max bytes. Used for
// titles and for log-entry notes, which are fields of the digest chain: a
// newline there would let one note impersonate two.
func ValidLine(s string, max int) bool {
	if strings.ContainsAny(s, "\n\t") {
		return false
	}
	return ValidText(s, max)
}

// ValidMirror reports whether s looks like a fetch locator. The chain does not
// resolve it: it only records where the maintainers say the objects are: so
// the check is a shape check, not a promise that anything is reachable.
func ValidMirror(s string) bool {
	if !ValidLine(s, MaxMirrorLen) || s == "" {
		return false
	}
	for _, p := range []string{"https://", "http://", "git://", "ssh://", "ipfs://", "ipns://", "ar://", "rad://", "git@"} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// ValidLabel reports whether s is an issue label.
func ValidLabel(s string) bool {
	return s != "" && ValidLine(s, MaxLabelLen) && !strings.Contains(s, ",")
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestValidOID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"sha1", strings.Repeat("a", 40), true},
		{"sha256", strings.Repeat("0", 64), true},
		{"mixed hex", "0123456789abcdef0123456789abcdef01234567", true},
		{"empty", "", false},
		{"too short", strings.Repeat("a", 39), false},
		{"between lengths", strings.Repeat("a", 41), false},
		{"uppercase", strings.Repeat("A", 40), false},
		{"non hex", strings.Repeat("z", 40), false},
		{"abbreviated", "deadbeef", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidOID(tc.in), tc.name)
	}
}

func TestValidRefName(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"branch", "refs/heads/main", true},
		{"nested branch", "refs/heads/feat/on-chain-log", true},
		{"tag", "refs/tags/v1.0.0", true},
		{"stash-like", "refs/stash", true},
		{"unqualified", "main", false},
		{"empty", "", false},
		{"double slash", "refs/heads//main", false},
		{"double dot", "refs/heads/a..b", false},
		{"at brace", "refs/heads/a@{0}", false},
		{"trailing slash", "refs/heads/", false},
		{"trailing dot", "refs/heads/main.", false},
		{"dot prefix", "refs/heads/.hidden", false},
		{"lock suffix", "refs/heads/main.lock", false},
		{"space", "refs/heads/my branch", false},
		{"caret", "refs/heads/main^", false},
		{"colon", "refs/heads/a:b", false},
		{"tilde", "refs/heads/main~1", false},
		{"question", "refs/heads/what?", false},
		{"star", "refs/heads/*", false},
		{"backslash", "refs/heads/a\\b", false},
		{"control", "refs/heads/a\x01b", false},
		{"too long", "refs/heads/" + strings.Repeat("a", 300), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRefName(tc.in), tc.name)
	}
}

func TestValidRepoID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"simple", "moul/forge", true},
		{"digits", "ns0/repo9", true},
		{"dots and dashes", "moul/gno-contracts.x", true},
		{"underscore", "moul/my_repo", true},
		{"no slash", "forge", false},
		{"two slashes", "a/b/c", false},
		{"empty ns", "/forge", false},
		{"empty name", "moul/", false},
		{"uppercase", "Moul/forge", false},
		{"leading dash", "moul/-forge", false},
		{"trailing dot", "moul/forge.", false},
		{"double dot", "moul/fo..rge", false},
		{"double dash", "moul/fo--rge", false},
		{"space", "moul/my forge", false},
		{"too long", "moul/" + strings.Repeat("a", 40), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRepoID(tc.in), tc.name)
	}
}

func TestAddressNamespace(t *testing.T) {
	addr := testutils.TestAddress("alice").String()
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"a real address", addr, true},
		{"wrong prefix", "x1" + addr[2:], false},
		{"too short", addr[:39], false},
		{"too long", addr + "a", false},
		{"bech32 drops b i o 1", "g1" + strings.Repeat("b", 38), false},
		{"uppercase", "G1" + addr[2:], false},
		{"a slug is not an address", "moul", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, AddressNamespace(tc.in), tc.name)
	}

	// An address namespace is a valid repo id, and it cannot collide with a
	// claimed name: 40 characters is past the slug cap.
	uassert.True(t, ValidRepoID(addr+"/forge"))
	uassert.False(t, ValidRepoID(strings.Repeat("a", 40)+"/forge"))
	uassert.False(t, ValidRepoID(addr+"/"+addr), "the name half is always a slug")
}

func TestSplitRepoID(t *testing.T) {
	ns, name, ok := SplitRepoID("moul/forge")
	uassert.True(t, ok)
	uassert.Equal(t, "moul", ns)
	uassert.Equal(t, "forge", name)

	for _, bad := range []string{"", "moul", "/forge", "moul/", "a/b/c"} {
		_, _, ok := SplitRepoID(bad)
		uassert.False(t, ok, bad)
	}
}

func TestValidTextAndLine(t *testing.T) {
	uassert.True(t, ValidText("hello\nworld\ttab", 64))
	uassert.False(t, ValidText("bell\x07", 64))
	uassert.False(t, ValidText("too long", 3))
	uassert.True(t, ValidText("", 3))

	uassert.True(t, ValidLine("a single line", 64))
	uassert.False(t, ValidLine("two\nlines", 64))
	uassert.False(t, ValidLine("a\ttab", 64))
}

func TestValidMirrorAndLabel(t *testing.T) {
	cases := []struct {
		in   string
		want bool
	}{
		{"https://github.com/moul/gno-contracts.git", true},
		{"git@github.com:moul/gno-contracts.git", true},
		{"ipfs://bafybeihdwdcefgh4dqkjv67uzcmw7ojee6xedzdetojuzjevtenxquvyku", true},
		{"rad://z3gqcJUoA1n9HaHKufZs5FCSGazv5", true},
		{"ar://1QKPaf1AmsK_tSSdUgtVDEYGLuQBOKTNr", true},
		{"ftp://example.com/repo.git", false},
		{"not a url", false},
		{"", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidMirror(tc.in), tc.in)
	}

	uassert.True(t, ValidLabel("bug"))
	uassert.False(t, ValidLabel(""))
	uassert.False(t, ValidLabel("a,b"))
	uassert.False(t, ValidLabel(strings.Repeat("x", 33)))
}

func TestParseRoleRoundTrip(t *testing.T) {
	for _, r := range []Role{RoleNone, RoleReader, RoleWriter, RoleMaintainer, RoleAdmin, RoleOwner} {
		got, err := ParseRole(r.String())
		uassert.NoError(t, err, r.String())
		uassert.Equal(t, int(r), int(got), r.String())
	}
	_, err := ParseRole("root")
	uassert.ErrorIs(t, err, ErrInvalidRole)
}

package forge

import "gno.land/p/nt/avl/v0"

// Change states.
const (
	StateOpen   = "open"
	StateMerged = "merged"
	StateClosed = "closed"
)

// Review verdicts.
const (
	VerdictApprove        = "approve"
	VerdictRequestChanges = "request-changes"
	VerdictComment        = "comment"
)

// Change is a change request (a pull request): a claim that TargetRef should be
// moved to include HeadOID, plus the reviews of that claim.
//
// Reviews are bound to the object id they reviewed, not to the change. Push a
// new head and every earlier approval stops counting: not by a policy toggle a
// maintainer can switch off, but because the approval names an object that is
// no longer what is being merged.
type Change struct {
	ID         int64
	Title      string
	Body       string
	Author     address
	SourceRepo string // forge repo id, or a mirror locator; "" means this repo
	SourceRef  string
	HeadOID    string
	TargetRef  string
	State      string
	CreatedAt  int64
	UpdatedAt  int64

	MergedOID string // the object TargetRef moved to
	MergedBy  address
	MergedAt  int64

	reviews     *avl.Tree // address string -> *Review (latest per reviewer)
	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Review is one reviewer's verdict on one object id.
type Review struct {
	Reviewer address
	Verdict  string
	OID      string // the head the reviewer actually looked at
	Body     string
	Height   int64
}

// OpenChange files a change request. Permissionless, like an issue: the
// proposal costs its author gas and deposit, and costs a maintainer nothing
// until they choose to look.
func (r *Repo) OpenChange(actor address, height int64, title, body, sourceRepo, sourceRef, headOID, targetRef string) (*Change, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if sourceRepo != "" && !ValidRepoID(sourceRepo) && !ValidMirror(sourceRepo) {
		return nil, ErrInvalidRepoID
	}
	if sourceRef != "" && !ValidRefName(sourceRef) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(headOID) {
		return nil, ErrInvalidOID
	}
	if !ValidRefName(targetRef) {
		return nil, ErrInvalidRefName
	}
	c := &Change{
		ID:         r.nextChange,
		Title:      title,
		Body:       body,
		Author:     actor,
		SourceRepo: sourceRepo,
		SourceRef:  sourceRef,
		HeadOID:    headOID,
		TargetRef:  targetRef,
		State:      StateOpen,
		CreatedAt:  height,
		UpdatedAt:  height,
		reviews:    avl.NewTree(),
		comments:   avl.NewTree(),
	}
	r.changes.Set(seqKey(c.ID), c)
	r.nextChange++
	return c, nil
}

// UpdateChangeHead repoints an open change at a new object. The author may
// always update their own; a writer may update anyone's (the "maintainer pushed
// a fixup" case).
func (r *Repo) UpdateChangeHead(actor address, height, id int64, headOID string) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleWriter) {
		return ErrUnauthorized
	}
	if !ValidOID(headOID) {
		return ErrInvalidOID
	}
	if headOID == c.HeadOID {
		return ErrSameOID
	}
	c.HeadOID = headOID
	c.UpdatedAt = height
	return nil
}

// ReviewChange records a verdict against the change's current head. Anyone may
// review; only a writer's approval counts toward the merge policy (see
// CountApprovals): an unprivileged review is signal, not authority.
func (r *Repo) ReviewChange(actor address, height, id int64, verdict, body string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	switch verdict {
	case VerdictApprove, VerdictRequestChanges, VerdictComment:
	default:
		return ErrInvalidVerdict
	}
	if verdict == VerdictApprove && actor == c.Author && !r.AllowSelfApproval {
		return ErrSelfApproval
	}
	if !ValidText(body, MaxCommentLen) {
		return ErrInvalidText
	}
	c.reviews.Set(actor.String(), &Review{
		Reviewer: actor,
		Verdict:  verdict,
		OID:      c.HeadOID,
		Body:     body,
		Height:   height,
	})
	c.UpdatedAt = height
	return nil
}

// CommentChange appends a reply to a change request.
func (r *Repo) CommentChange(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	cm := &Comment{ID: c.nextComment, Author: actor, Body: body, CreatedAt: height}
	c.comments.Set(seqKey(cm.ID), cm)
	c.nextComment++
	c.UpdatedAt = height
	return cm, nil
}

// CloseChange withdraws or rejects a change. Author or maintainer.
func (r *Repo) CloseChange(actor address, height, id int64) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	c.State = StateClosed
	c.UpdatedAt = height
	return nil
}

// CountApprovals counts approvals that still apply: cast by a writer or above,
// against the change's current head, and (unless the repo allows it) not the
// author's own.
func (r *Repo) CountApprovals(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict != VerdictApprove || rv.OID != c.HeadOID {
			return false
		}
		if rv.Reviewer == c.Author && !r.AllowSelfApproval {
			return false
		}
		if !r.Can(rv.Reviewer, RoleWriter) {
			return false
		}
		n++
		return false
	})
	return n
}

// CountBlocking counts writers who requested changes on the current head.
func (r *Repo) CountBlocking(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict == VerdictRequestChanges && rv.OID == c.HeadOID && r.Can(rv.Reviewer, RoleWriter) {
			n++
		}
		return false
	})
	return n
}

// MergeChange moves TargetRef to mergedOID and records the move as one more
// entry in the reference log, tagged with the change it came from.
//
// expectedTargetOID is a compare-and-swap on the target ref ("" when the ref
// does not exist yet): a change approved against one base cannot be merged onto
// a base that moved underneath it. mergedOID is computed off chain by whoever
// performs the merge: the chain records the claim, signed, ordered and
// attributed, and a client with the objects verifies that the result actually
// contains HeadOID.
func (r *Repo) MergeChange(actor address, height, id int64, expectedTargetOID, mergedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if c.State != StateOpen {
		return nil, ErrChangeNotOpen
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidOID(mergedOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	if r.CountBlocking(c) > 0 {
		return nil, ErrChangesRequested
	}
	if r.CountApprovals(c) < r.RequiredApprovals {
		return nil, ErrNotEnoughApproval
	}
	cur := r.Ref(c.TargetRef)
	switch {
	case cur == nil && expectedTargetOID != "":
		return nil, ErrRefNotFound
	case cur != nil && cur.OID != expectedTargetOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == mergedOID:
		return nil, ErrSameOID
	}
	old := ""
	if cur != nil {
		old = cur.OID
	}
	r.refs.Set(c.TargetRef, &Ref{Name: c.TargetRef, OID: mergedOID, UpdatedAt: height, UpdatedBy: actor})
	e := r.appendLog(actor, height, c.TargetRef, old, mergedOID, KindMerge, c.ID, note)
	c.State = StateMerged
	c.MergedOID = mergedOID
	c.MergedBy = actor
	c.MergedAt = height
	c.UpdatedAt = height
	return e, nil
}

// Change returns a change by id, or nil.
func (r *Repo) Change(id int64) *Change {
	v := r.changes.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Change)
}

// IterateChanges walks change requests newest-first.
func (r *Repo) IterateChanges(offset, count int, cb func(*Change) bool) {
	if count <= 0 {
		count = r.changes.Size()
	}
	r.changes.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Change))
	})
}

// OpenChangeCount counts change requests still open.
func (r *Repo) OpenChangeCount() int {
	n := 0
	r.changes.Iterate("", "", func(_ string, value any) bool {
		if value.(*Change).State == StateOpen {
			n++
		}
		return false
	})
	return n
}

// ReviewCount is the number of reviewers who have weighed in (latest verdict
// per reviewer, on any head).
func (c *Change) ReviewCount() int { return c.reviews.Size() }

// Review returns a reviewer's latest verdict, or nil.
func (c *Change) Review(a address) *Review {
	v := c.reviews.Get(a.String())
	if v == nil {
		return nil
	}
	return v.(*Review)
}

// IterateReviews walks reviews in reviewer-address order.
func (c *Change) IterateReviews(cb func(*Review) bool) {
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Review))
	})
}

// CommentCount is the number of replies on the change.
func (c *Change) CommentCount() int { return c.comments.Size() }

// IterateComments walks replies oldest-first.
func (c *Change) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = c.comments.Size()
	}
	c.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

// Stale reports whether a review no longer applies to the change's head.
func (c *Change) Stale(rv *Review) bool { return rv.OID != c.HeadOID }

// Package forge is the domain engine of an on-chain software forge: repos,
// roles, an append-only reference log, issues and change requests (pull
// requests), with no chain imports of its own.
//
// What it does NOT do, on purpose: store blobs, trees or packfiles. Git objects
// stay wherever git already puts them (a mirror, an IPFS CID, a peer) and this
// package records what a forge is actually trusted for and what git alone does
// not authenticate:
//
//  1. which object id a ref points at, in what order it got there, and who said
//     so: an append-only, hash-chained reference log (the same shape as
//     gittuf's reference state log, with consensus playing the notary);
//  2. who is allowed to move which ref, and under what review policy;
//  3. the social layer: issues, change requests, reviews: bound to addresses
//     rather than to platform accounts;
//  4. the merge decision itself, recorded as one more entry in the same log.
//
// The chain cannot see the object graph, so it cannot verify that a new tip
// descends from the old one. It does not pretend to: every ref move is a
// compare-and-swap against the tip the caller expected (git's
// --force-with-lease, moved somewhere the forge operator cannot rewrite), any
// move that abandons that discipline is recorded as a force, and ancestry is
// checked by a client that has the objects. Ordering, attribution and policy
// are on chain; proof is local.
//
// All state lives in avl trees so every listing is ordered and paginatable, and
// every mutation takes the actor and the block height from the caller: the
// package is pure, deterministic and unit-testable without a chain.
//
// Live demo: gno.land/r/nym-moultest123/forge/v0.
package forge

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Role is a repo-scoped capability level. Roles are totally ordered: every
// check is "at least this role", so there is one comparison to audit.
type Role int

const (
	RoleNone       Role = iota // not a member
	RoleReader                 // explicit read (all repos are public in v0)
	RoleWriter                 // move non-protected refs, update own changes
	RoleMaintainer             // force-move refs, merge changes, triage issues
	RoleAdmin                  // manage members and repo settings
	RoleOwner                  // admin + transfer; at least one always exists
)

// String renders the role as the lowercase token used by the realm API.
func (r Role) String() string {
	switch r {
	case RoleReader:
		return "reader"
	case RoleWriter:
		return "writer"
	case RoleMaintainer:
		return "maintainer"
	case RoleAdmin:
		return "admin"
	case RoleOwner:
		return "owner"
	default:
		return "none"
	}
}

// ParseRole is the inverse of Role.String.
func ParseRole(s string) (Role, error) {
	switch s {
	case "none":
		return RoleNone, nil
	case "reader":
		return RoleReader, nil
	case "writer":
		return RoleWriter, nil
	case "maintainer":
		return RoleMaintainer, nil
	case "admin":
		return RoleAdmin, nil
	case "owner":
		return RoleOwner, nil
	}
	return RoleNone, ErrInvalidRole
}

// Forge is the top-level registry: repo id -> repo.
type Forge struct {
	repos *avl.Tree // "<namespace>/<name>" -> *Repo
	// packages is the forge-wide index behind PackageRepo: a deployed package
	// path resolves to the repo claiming it without scanning every repo. It
	// lives here rather than only on the repo because the question an explorer
	// asks starts from the path and does not know the repo yet.
	packages *avl.Tree // package path -> *Package
}

// New returns an empty forge.
func New() *Forge {
	return &Forge{repos: avl.NewTree(), packages: avl.NewTree()}
}

// Repo is one repository. Nothing here is the code: Mirrors says where the
// objects can be fetched, Refs says what the objects are supposed to be.
type Repo struct {
	ID          string // "<namespace>/<name>", immutable
	Description string
	DefaultRef  string // fully-qualified, e.g. "refs/heads/main"
	Mirrors     []string
	ParentID    string // fork lineage, "" for a root repo
	CreatedAt   int64  // block height
	Archived    bool

	// Merge policy.
	RequiredApprovals int  // approvals needed to merge a change
	AllowSelfApproval bool // may the change author's own approval count

	members *avl.Tree // address string -> Role
	refs    *avl.Tree // ref name -> *Ref
	log     *avl.Tree // padded seq -> *LogEntry (append-only)
	issues  *avl.Tree // padded id -> *Issue
	changes *avl.Tree // padded id -> *Change

	packages *avl.Tree // package path -> *Package (this repo's half of the index)
	releases *avl.Tree // tag -> *Release
	// releaseOrder is cut order, which is the only order the forge knows to be
	// true. Tags are not required to be semver, so sorting the release tree by
	// key would present v10 before v2 and call it newest.
	releaseOrder *avl.Tree // padded seq -> tag

	head       string // digest of the last log entry ("" when the log is empty)
	nextSeq    int64
	nextIssue  int64
	nextChange int64
}

// CreateRepo registers a repo owned by actor.
func (f *Forge) CreateRepo(actor address, height int64, id, description, defaultRef string) (*Repo, error) {
	if !ValidRepoID(id) {
		return nil, ErrInvalidRepoID
	}
	if !ValidText(description, MaxDescLen) {
		return nil, ErrInvalidText
	}
	if defaultRef == "" {
		defaultRef = "refs/heads/main"
	}
	if !ValidRefName(defaultRef) {
		return nil, ErrInvalidRefName
	}
	if f.repos.Has(id) {
		return nil, ErrRepoExists
	}
	r := &Repo{
		ID:                id,
		Description:       description,
		DefaultRef:        defaultRef,
		CreatedAt:         height,
		RequiredApprovals: 1,
		members:           avl.NewTree(),
		refs:              avl.NewTree(),
		log:               avl.NewTree(),
		issues:            avl.NewTree(),
		changes:           avl.NewTree(),
		// A fork routes through here too, and inherits neither: the parent
		// publishes those package paths and cut those releases, not the child.
		packages:     avl.NewTree(),
		releases:     avl.NewTree(),
		releaseOrder: avl.NewTree(),
	}
	r.members.Set(actor.String(), RoleOwner)
	f.repos.Set(id, r)
	return r, nil
}

// Fork registers newID as a fork of srcID and copies the parent's current refs
// into the child's log, so the fork records exactly what it forked from. The
// objects are not copied: they never were on chain: so the child inherits the
// parent's mirrors as its initial fetch locators.
func (f *Forge) Fork(actor address, height int64, srcID, newID string) (*Repo, error) {
	src := f.Repo(srcID)
	if src == nil {
		return nil, ErrRepoNotFound
	}
	child, err := f.CreateRepo(actor, height, newID, src.Description, src.DefaultRef)
	if err != nil {
		return nil, err
	}
	child.ParentID = srcID
	child.Mirrors = append([]string{}, src.Mirrors...)
	note := "fork of " + srcID + " at seq " + strconv.FormatInt(src.nextSeq, 10)
	if len(note) > MaxNoteLen {
		note = "fork of " + srcID
	}
	n := 0
	src.refs.Iterate("", "", func(key string, value any) bool {
		ref := value.(*Ref)
		child.appendLog(actor, height, ref.Name, "", ref.OID, KindCreate, 0, note)
		child.refs.Set(ref.Name, &Ref{Name: ref.Name, OID: ref.OID, UpdatedAt: height, UpdatedBy: actor})
		n++
		return n >= 32 // a fork records a snapshot, not an unbounded copy
	})
	return child, nil
}

// Repo returns the repo, or nil.
func (f *Forge) Repo(id string) *Repo {
	v := f.repos.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Repo)
}

// HasRepo reports whether the id is taken.
func (f *Forge) HasRepo(id string) bool { return f.repos.Has(id) }

// Size is the number of repos.
func (f *Forge) Size() int { return f.repos.Size() }

// IterateRepos walks repos in id order, newest-last, and stops when cb returns
// true. offset/count page the walk; count <= 0 means "to the end".
func (f *Forge) IterateRepos(offset, count int, cb func(*Repo) bool) {
	if count <= 0 {
		count = f.repos.Size()
	}
	f.repos.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Repo))
	})
}

// IterateNamespace walks the repos of one namespace in id order.
func (f *Forge) IterateNamespace(ns string, cb func(*Repo) bool) {
	f.repos.Iterate(ns+"/", ns+"0", func(_ string, value any) bool { // '0' is '/'+1
		return cb(value.(*Repo))
	})
}

// RoleOf returns the member's role, RoleNone when not a member.
func (r *Repo) RoleOf(a address) Role {
	v := r.members.Get(a.String())
	if v == nil {
		return RoleNone
	}
	return v.(Role)
}

// Can reports whether a holds at least the given role.
func (r *Repo) Can(a address, min Role) bool { return r.RoleOf(a) >= min }

// MemberCount is the number of members with an explicit role.
func (r *Repo) MemberCount() int { return r.members.Size() }

// IterateMembers walks members in address order.
func (r *Repo) IterateMembers(cb func(addr string, role Role) bool) {
	r.members.Iterate("", "", func(key string, value any) bool {
		return cb(key, value.(Role))
	})
}

// SetMember grants or revokes a role. Admins manage members; only an owner may
// mint another owner, and the last owner cannot be demoted: a repo with no
// owner is a repo nobody can ever unarchive.
func (r *Repo) SetMember(actor address, target address, role Role) error {
	if role < RoleNone || role > RoleOwner {
		return ErrInvalidRole
	}
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if role == RoleOwner && !r.Can(actor, RoleOwner) {
		return ErrUnauthorized
	}
	cur := r.RoleOf(target)
	if cur == RoleOwner && role != RoleOwner {
		if !r.Can(actor, RoleOwner) {
			return ErrUnauthorized // an admin cannot demote an owner
		}
		if r.ownerCount() == 1 {
			return ErrLastOwner
		}
	}
	if role == RoleNone {
		r.members.Remove(target.String())
		return nil
	}
	r.members.Set(target.String(), role)
	return nil
}

func (r *Repo) ownerCount() int {
	n := 0
	r.members.Iterate("", "", func(_ string, value any) bool {
		if value.(Role) == RoleOwner {
			n++
		}
		return false
	})
	return n
}

// SetDescription updates the one-line description.
func (r *Repo) SetDescription(actor address, description string) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if !ValidText(description, MaxDescLen) {
		return ErrInvalidText
	}
	r.Description = description
	return nil
}

// SetMirrors replaces the fetch locators. The first one is the canonical
// remote; the rest are fallbacks. The chain records them, it never fetches.
func (r *Repo) SetMirrors(actor address, mirrors []string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if len(mirrors) > MaxMirrors {
		return ErrTooMany
	}
	for _, m := range mirrors {
		if !ValidMirror(m) {
			return ErrInvalidMirror
		}
	}
	r.Mirrors = append([]string{}, mirrors...)
	return nil
}

// SetDefaultRef points the repo at another default branch.
func (r *Repo) SetDefaultRef(actor address, name string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if !ValidRefName(name) {
		return ErrInvalidRefName
	}
	r.DefaultRef = name
	return nil
}

// SetPolicy sets the merge policy: how many approvals a change needs, and
// whether the author's own approval counts.
func (r *Repo) SetPolicy(actor address, requiredApprovals int, allowSelfApproval bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if requiredApprovals < 0 || requiredApprovals > 16 {
		return ErrTooMany
	}
	r.RequiredApprovals = requiredApprovals
	r.AllowSelfApproval = allowSelfApproval
	return nil
}

// SetArchived freezes (or unfreezes) the repo. An archived repo takes no
// mutation except unarchiving: the log stays readable forever.
func (r *Repo) SetArchived(actor address, archived bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	r.Archived = archived
	return nil
}

// Counts for rendering.
func (r *Repo) RefCount() int    { return r.refs.Size() }
func (r *Repo) IssueCount() int  { return r.issues.Size() }
func (r *Repo) ChangeCount() int { return r.changes.Size() }

// seqKey zero-pads an id to a fixed width so avl keys sort numerically.
// ufmt has no width flags in gno, so the padding is done by hand: "%016d"
// silently returns the bare number and would sort 10 before 2.
func seqKey(n int64) string {
	s := strconv.FormatInt(n, 10)
	if len(s) >= 16 {
		return s
	}
	return strings.Repeat("0", 16-len(s)) + s
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/urequire/v0"
)

// Deterministic, checksum-valid test addresses.
var (
	alice = testutils.TestAddress("alice") // owner
	bob   = testutils.TestAddress("bob")   // maintainer
	carol = testutils.TestAddress("carol") // writer
	dave  = testutils.TestAddress("dave")  // reader
	eve   = testutils.TestAddress("eve")   // stranger
)

// oid builds a well-formed 40-hex object id out of one hex digit.
func oid(c string) string { return strings.Repeat(c, 40) }

// newRepo returns a repo owned by alice with the standard cast: bob
// maintainer, carol writer, dave reader, eve nothing.
func newRepo(t *testing.T) (*Forge, *Repo) {
	t.Helper()
	f := New()
	r, err := f.CreateRepo(alice, 100, "moul/forge", "an on-chain forge", "")
	urequire.NoError(t, err)
