		{"page", s.Page(PageTxs), b + "/txs?network=mainnet"},
		{"page nested", s.Page(PageGasRealms), b + "/gas/realms?network=mainnet"},
		{"page slashed", s.Page("/blocks/"), b + "/blocks?network=mainnet"},
		{"realm qualified", s.Realm("gno.land/r/nym-moultest123/home"), b + "/realm/r/nym-moultest123/home?network=mainnet"},
		{"realm bare", s.Realm("r/moul/home"), b + "/realm/r/nym-moultest123/home?network=mainnet"},
		{"realm tab", s.Realm("r/moul/home", TabSource), b + "/realm/r/nym-moultest123/home?network=mainnet&tab=source"},
