		{"realm file", s.RealmFile("r/moul/home", "render.gno", 42), b + "/realm/r/nym-moultest123/home?file=render.gno&line=42&network=mainnet&tab=source"},
		{"realm file no line", s.RealmFile("r/moul/home", "render.gno", 0), b + "/realm/r/nym-moultest123/home?file=render.gno&network=mainnet&tab=source"},
		{"address", s.Address("g1manfred47kzduec920z88wfr64ylksmdcedlf5"), b + "/address/g1manfred47kzduec920z88wfr64ylksmdcedlf5?network=mainnet"},
		{"address empty", s.Address(""), b + "/accounts?network=mainnet"},
