// Package pausable is the switch a realm checks before it acts: a parsed pause
// state, the rule for combining two of them, and the asserts that stop a call.
//
// # Three levels, because "paused" is usually too blunt
//
// Taking a realm fully offline hides the thing people came to read. Most
// incidents only need the writes stopped: a board keeps rendering, an exchange
// keeps quoting, and nothing new lands while the fix is prepared. So the
// levels are Running, ReadOnly and Paused, and a realm normally guards its
// mutating functions with AssertWritable and leaves Render alone.
//
//	func Post(cur realm, body string) {
//		config.AssertWritable()  // aborts while the realm is ReadOnly or Paused
//		…
//	}
//
//	func Render(path string) string {
//		return config.TopBlock() + body  // the banner explains itself
//	}
//
// # It fails closed
//
// MustParse turns a value it does not recognise into Paused, not Running. A
// pause switch that a typo silently disables is not a pause switch, and the
// failure is loud and one transaction from fixed, where the opposite failure
// is silent and discovered during the incident it was meant to cover.
//
// The cost of that choice is a typo taking a realm offline, so the writer is
// expected to validate: Parse reports ok=false and the storing realm refuses
// the write. Validate on the way in, fail closed on the way out.
//
// # The stricter of two states wins
//
// A global pause and a per-realm pause combine with Strictest, so a stale
// per-realm entry can never re-open a realm during a global halt. The cost is
// that exempting one realm from a global pause is not expressible; clear the
// global and set the others instead.
package pausable

import "strings"

// Level is how much of a realm is still allowed to work.
type Level int

const (
	// Running is the normal state, and what an unset value means.
	Running Level = iota
	// ReadOnly still renders and still answers queries; it refuses writes.
	ReadOnly
	// Paused refuses everything, reads included.
	Paused
)

// The canonical spelling of each level, which is what a value round-trips to.
const (
	runningWord  = "running"
	readOnlyWord = "readonly"
	pausedWord   = "paused"
)

// reasonSep separates the level from the human explanation in a stored value:
// "paused: migrating storage, back in an hour".
const reasonSep = ":"

func (l Level) String() string {
	switch l {
	case Running:
		return runningWord
	case ReadOnly:
		return readOnlyWord
	case Paused:
		return pausedWord
	default:
		// Not reachable through Parse, and not worth panicking over in a
		// Render path: an unknown level reads as the strictest one.
		return pausedWord
	}
}

// AllowsRead reports whether rendering and querying are still allowed.
func (l Level) AllowsRead() bool { return l != Paused }

// AllowsWrite reports whether state-changing calls are still allowed.
func (l Level) AllowsWrite() bool { return l == Running }

// State is a parsed pause setting: a level and an optional reason to show.
//
// The zero State is Running with no reason, which is what an unset setting
// means, so a realm that never configures anything is never paused.
type State struct {
	Level  Level
	Reason string
}

// Parse reads a stored value: "", "running", "readonly", "paused", each
// optionally followed by ": <reason>".
//
// ok is false for anything else. A caller that is STORING the value should
// refuse on !ok; a caller that is READING one should use MustParse, which
// fails closed instead.
func Parse(raw string) (State, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return State{}, true
	}

	word, reason := raw, ""
	if i := strings.Index(raw, reasonSep); i >= 0 {
		word = strings.TrimSpace(raw[:i])
		reason = strings.TrimSpace(raw[i+1:])
	}

	switch strings.ToLower(word) {
	case runningWord:
		return State{Level: Running, Reason: reason}, true
	case readOnlyWord:
		return State{Level: ReadOnly, Reason: reason}, true
	case pausedWord:
		return State{Level: Paused, Reason: reason}, true
	default:
		return State{}, false
	}
}

// MustParse is Parse for a reader, failing closed: a value it cannot read
// becomes Paused, carrying the raw text as the reason so whoever hits it can
// see what is wrong.
func MustParse(raw string) State {
	if s, ok := Parse(raw); ok {
		return s
	}
	return State{Level: Paused, Reason: "unreadable pause setting: " + strings.TrimSpace(raw)}
}

// String renders a State back into a storable value. It round-trips through
// Parse, and the zero State renders empty so an unset setting stays unset.
func (s State) String() string {
	if s.Level == Running && s.Reason == "" {
		return ""
	}
	if s.Reason == "" {
		return s.Level.String()
	}
	return s.Level.String() + reasonSep + " " + s.Reason
}

// Strictest returns whichever of the two stops more, keeping the reason that
// belongs to the level it returns. On a tie the first argument wins, so a
// caller passing (global, scoped) keeps the global explanation when both say
// the same thing, and the scoped one when it is the stricter.
func Strictest(a, b State) State {
	if b.Level > a.Level {
		return b
	}
	return a
}

// AllowsRead reports whether rendering and querying are still allowed.
func (s State) AllowsRead() bool { return s.Level.AllowsRead() }

// AllowsWrite reports whether state-changing calls are still allowed.
func (s State) AllowsWrite() bool { return s.Level.AllowsWrite() }

// IsPaused reports whether anything at all is being held back. It is true for
// ReadOnly as well as Paused, because the question a caller usually means by
// "is it paused" is "is it behaving normally".
func (s State) IsPaused() bool { return s.Level != Running }

// AssertWritable aborts unless writes are allowed. This is the one a realm
// puts at the top of every state-changing function.
func (s State) AssertWritable() {
	if !s.AllowsWrite() {
		panic(s.message("writes are paused"))
	}
}

// AssertReadable aborts unless reads are allowed. Most realms do not want this
// in Render: a page that aborts tells a reader nothing, while Notice tells
// them what happened and when to come back.
func (s State) AssertReadable() {
	if !s.AllowsRead() {
		panic(s.message("paused"))
	}
}

func (s State) message(what string) string {
	if s.Reason == "" {
		return what
	}
	return what + reasonSep + " " + s.Reason
}

// Notice is the banner a Render puts above its content, or "" while running.
//
// It is a markdown blockquote, so it reads as set apart from the page without
// needing any style the renderer might not have.
func (s State) Notice() string {
	if s.Level == Running {
		return ""
	}
	head := "**Paused.** This realm is not accepting anything right now."
	if s.Level == ReadOnly {
		head = "**Read-only.** This realm is still readable, but not accepting changes."
	}
	if s.Reason == "" {
		return "> " + head
	}
	// The reason is text a manager typed, and it lands inside a blockquote
	// where a newline would end the quote and let the rest render as page
	// content. Folding it to a single line keeps the banner one block.
	return "> " + head + " " + oneLine(s.Reason)
}

// oneLine collapses every run of whitespace, newlines included, into single
// spaces.
func oneLine(s string) string {
	var b strings.Builder
	space := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			space = true
			continue
		}
		if space && b.Len() > 0 {
			b.WriteByte(' ')
		}
		space = false
		b.WriteByte(c)
	}
	return b.String()
}

package pausable

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestParse(t *testing.T) {
	tests := []struct {
		raw        string
		wantLevel  Level
		wantReason string
		wantOK     bool
	}{
		{"", Running, "", true},
		{"   ", Running, "", true},
		{"running", Running, "", true},
		{"readonly", ReadOnly, "", true},
		{"paused", Paused, "", true},
		{"Paused", Paused, "", true},   // case-insensitive
		{"  paused  ", Paused, "", true},
		{"paused: migrating storage", Paused, "migrating storage", true},
		{"readonly:  spaced  ", ReadOnly, "spaced", true},
		{"running: nothing wrong", Running, "nothing wrong", true},
		// A reason containing the separator keeps everything after the first
		// one, so a URL or a time survives.
		{"paused: back at 14:00 UTC", Paused, "back at 14:00 UTC", true},
		// Not recognised. These are exactly the values that must NOT read as
		// Running.
		{"yes", Running, "", false},
		{"true", Running, "", false},
		{"1", Running, "", false},
		{"stop", Running, "", false},
		{"read-only", Running, "", false},
	}
	for _, tt := range tests {
		got, ok := Parse(tt.raw)
		uassert.Equal(t, tt.wantOK, ok, "Parse("+tt.raw+") ok")
		if !ok {
			continue
		}
		uassert.Equal(t, int(tt.wantLevel), int(got.Level), "Parse("+tt.raw+") level")
		uassert.Equal(t, tt.wantReason, got.Reason, "Parse("+tt.raw+") reason")
	}
}

// TestMustParseFailsClosed is the whole safety argument of this package. Every
// value here is something a person might plausibly type, and every one of them
// has to stop the realm rather than quietly leave it running.
func TestMustParseFailsClosed(t *testing.T) {
	for _, raw := range []string{"yes", "true", "1", "on", "stop", "PAUSE", "pasued"} {
		got := MustParse(raw)
		uassert.Equal(t, int(Paused), int(got.Level), "MustParse("+raw+") must fail closed")
		uassert.False(t, got.AllowsWrite(), "MustParse("+raw+") must refuse writes")
		uassert.True(t, len(got.Reason) > 0, "MustParse("+raw+") must say why")
	}

	// And the values it does understand are untouched.
	uassert.Equal(t, int(Running), int(MustParse("").Level))
	uassert.Equal(t, int(ReadOnly), int(MustParse("readonly").Level))
}

func TestAllows(t *testing.T) {
	tests := []struct {
		level     Level
		read      bool
		write     bool
		isPaused  bool
	}{
		{Running, true, true, false},
		{ReadOnly, true, false, true},
		{Paused, false, false, true},
	}
	for _, tt := range tests {
		s := State{Level: tt.level}
		uassert.Equal(t, tt.read, s.AllowsRead(), tt.level.String()+" read")
		uassert.Equal(t, tt.write, s.AllowsWrite(), tt.level.String()+" write")
		uassert.Equal(t, tt.isPaused, s.IsPaused(), tt.level.String()+" isPaused")
	}
}

func TestStrictest(t *testing.T) {
	run := State{Level: Running}
	ro := State{Level: ReadOnly, Reason: "scoped"}
	paused := State{Level: Paused, Reason: "global"}

	uassert.Equal(t, int(ReadOnly), int(Strictest(run, ro).Level))
	uassert.Equal(t, int(ReadOnly), int(Strictest(ro, run).Level))
	uassert.Equal(t, int(Paused), int(Strictest(paused, ro).Level))
	uassert.Equal(t, int(Paused), int(Strictest(ro, paused).Level))

	// A stale per-realm entry can never re-open a realm during a global halt.
	// This is the property the whole precedence rule exists for.
	uassert.Equal(t, int(Paused), int(Strictest(paused, run).Level),
		"a per-realm 'running' cannot defeat a global pause")

	// The reason travels with the level that won.
	uassert.Equal(t, "global", Strictest(paused, ro).Reason)
	uassert.Equal(t, "scoped", Strictest(run, ro).Reason)

	// On a tie the first argument wins, so a caller passing (global, scoped)
	// keeps the global explanation.
	a := State{Level: Paused, Reason: "first"}
	b := State{Level: Paused, Reason: "second"}
	uassert.Equal(t, "first", Strictest(a, b).Reason)
}

func TestStringRoundTrips(t *testing.T) {
	for _, raw := range []string{"", "readonly", "paused", "paused: migrating storage"} {
		s, ok := Parse(raw)
		uassert.True(t, ok, "Parse("+raw+")")
		again, ok := Parse(s.String())
		uassert.True(t, ok, "Parse(String()) for "+raw)
		uassert.Equal(t, int(s.Level), int(again.Level), "level round-trip for "+raw)
		uassert.Equal(t, s.Reason, again.Reason, "reason round-trip for "+raw)
	}

	// The zero State renders empty, so an unset setting stays unset rather
	// than being written back as the word "running".
	uassert.Equal(t, "", State{}.String())
	uassert.Equal(t, "running: why", State{Reason: "why"}.String())
}

func TestAsserts(cur realm, t *testing.T) {
	State{}.AssertWritable()
	State{}.AssertReadable()
	State{Level: ReadOnly}.AssertReadable()

	uassert.PanicsWithMessage(t, cur, "writes are paused", func() {
		State{Level: ReadOnly}.AssertWritable()
	})
	uassert.PanicsWithMessage(t, cur, "writes are paused: migrating", func() {
		State{Level: Paused, Reason: "migrating"}.AssertWritable()
	})
	uassert.PanicsWithMessage(t, cur, "paused: migrating", func() {
		State{Level: Paused, Reason: "migrating"}.AssertReadable()
	})
}

func TestNotice(t *testing.T) {
	uassert.Equal(t, "", State{}.Notice(), "a running realm shows no banner")

	uassert.Equal(t,
		"> **Read-only.** This realm is still readable, but not accepting changes.",
		State{Level: ReadOnly}.Notice())

	uassert.Equal(t,
		"> **Paused.** This realm is not accepting anything right now. back in an hour",
		State{Level: Paused, Reason: "back in an hour"}.Notice())
}

// TestNoticeStaysOneBlock covers the reason a manager typed. It lands inside a
// markdown blockquote, where a newline ends the quote and lets the rest render
// as ordinary page content, so it is folded to one line.
func TestNoticeStaysOneBlock(t *testing.T) {
	s := State{Level: Paused, Reason: "line one\n\nline two\n# not a heading"}
	uassert.Equal(t,
		"> **Paused.** This realm is not accepting anything right now. line one line two # not a heading",
		s.Notice())
}

// Package pilot is a realm-driven account: one realm holds the funds and the
// identity, a key pilots it, and its powers are separate realms installed
// afterwards without ever redeploying it. The gno answer to a Gnosis Safe
// with modules.
//
// An account realm keeps a *Pilot private and hands modules a narrow
// [Account] handle. Everything privileged stays on *Pilot, which is never
// returned, so a module can only reach the two methods it needs.
//
// Two ways to delegate, and they differ in exactly one property:
//
//   - A [Purse] is revocable. Every method on it re-enters the declaring
//     package and re-checks the live roster and budget, so Revoke and
//     SetBudget take effect immediately, even on a purse a module retained.
//   - A sub-identity token (rlm.Sub) is permanent. It lets the module act as
//     "<account>#<subpath>" toward any other realm, which a purse cannot do,
//     but the module can mint a banker from it and keep it forever. Removing
//     the module does not take that back; only emptying the sub-address does.
//     Grant one only to code you have read.
//
// Live instance: r/moul/pilot. Demo module: r/moul/x/pilotdemo.
package pilot

import (
	"chain"
	"chain/banker"
	"errors"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Module is implemented by a module realm and installed into an account.
// The account never imports it: it learns the module only as this interface.
//
// Run is threaded (the leading int keeps it out of crossing-function
// territory, which a /p/ package may not declare). rlm is whatever the
// account chose to delegate: its own sub-identity token for a trusted
// module, or a zero value when the module was installed purse-only.
type Module interface {
	Name() string
	Run(_ int, rlm realm, args string) string
}

// Grant says what a module was given.
type Grant uint8

const (
	// GrantPurse is funds only, revocable at any time.
	GrantPurse Grant = iota
	// GrantIdentity also lends the account's sub-identity. Permanent.
	GrantIdentity
)

func (g Grant) String() string {
	if g == GrantIdentity {
		return "identity"
	}
	return "purse"
}

var (
	ErrNotOwner     = errors.New("pilot: not the owner")
	ErrNotApproved  = errors.New("pilot: path not approved")
	ErrNotInstalled = errors.New("pilot: module not installed")
	ErrRevoked      = errors.New("pilot: module revoked")
	ErrOverBudget   = errors.New("pilot: over budget")
	ErrStaleRealm   = errors.New("pilot: stale realm value")
	ErrBadName      = errors.New("pilot: a path and a subpath are [a-zA-Z0-9._/-] and not empty")
)

type slot struct {
	mod     Module
	subpath string
	grant   Grant
	budget  int64
	spent   int64
	runs    int64
	live    bool
}

// Pilot is the account. The realm that constructs it owns it and must not
// hand it out; hand out [Pilot.Handle] instead.
type Pilot struct {
	owner   address
	host    string        // the account realm's own pkgpath
	vault   banker.Banker // over host's address, minted once at New
	slots   *avl.Tree     // module pkgpath -> *slot
	handle  *Account
}

// Account is the module-facing half: two methods, both keyed on the calling
// realm's OWN pkgpath, which a realm cannot forge for another.
type Account struct {
	p *Pilot
}

// New builds an account owned by the caller of the crossing function that
// reaches it. Call it once, from the account realm, passing that realm's cur.
func New(_ int, rlm realm) *Pilot {
	assertCurrent(0, rlm)
	p := &Pilot{
		owner: rlm.Previous().Address(),
		host:  rlm.PkgPath(),
		vault: banker.NewBanker(banker.BankerTypeRealmSend, rlm),
		slots: avl.NewTree(),
	}
	p.handle = &Account{p: p}
	return p
}

// assertPlain is why Render can interpolate a path without escaping it: the
// only two strings a caller ever puts in the roster are checked here, at write
// time, against the charset a package path and a subpath are built from.
func assertPlain(s string) {
	if s == "" {
		panic(ErrBadName)
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == '.', c == '/', c == '-', c == '_':
		default:
			panic(ErrBadName)
		}
	}
}

func assertCurrent(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
}

// AssertOwner panics unless the user behind rlm owns the account. Only the
// account realm may call this: rlm must be its own live cur, so that
// rlm.Previous() is the signer and not some intermediary's caller.
func (p *Pilot) AssertOwner(_ int, rlm realm) {
	assertCurrent(0, rlm)
	if rlm.PkgPath() != p.host {
		panic(ErrNotOwner)
	}
	if rlm.Previous().Address() != p.owner {
		panic(ErrNotOwner)
	}
}

// Handle is what an account realm exposes to modules.
func (p *Pilot) Handle() *Account { return p.handle }

func (p *Pilot) Owner() address { return p.owner }
func (p *Pilot) Host() string   { return p.host }

// Address is the account's main treasury.
func (p *Pilot) Address() address { return chain.PackageAddress(p.host) }

// SubAddress is one module's own treasury, derivable off-chain by anyone.
func (p *Pilot) SubAddress(path string) address {
	s := p.mustSlot(path)
	return chain.DerivePkgSubAddr(p.host, s.subpath)
}

func (p *Pilot) mustSlot(path string) *slot {
	s, ok := p.slots.Get(path).(*slot)
	if !ok {
		panic(ErrNotInstalled)
	}
	return s
}

// Approve authorises a package path to install itself later. The code does
// not have to exist yet, which is the whole point: the account is deployed
// once and learns new powers afterwards.
func (p *Pilot) Approve(_ int, rlm realm, path, subpath string, grant Grant, budget int64) {
	p.AssertOwner(0, rlm)
	assertPlain(path)
	assertPlain(subpath)
	if old, ok := p.slots.Get(path).(*slot); ok {
		old.subpath = subpath
		old.grant = grant
		old.budget = budget
		old.spent = 0 // a new approval is a new allowance
		return
	}
	p.slots.Set(path, &slot{subpath: subpath, grant: grant, budget: budget})
}

// SetBudget is the live knob. It applies to a purse a module already holds.
func (p *Pilot) SetBudget(_ int, rlm realm, path string, budget int64) {
	p.AssertOwner(0, rlm)
	p.mustSlot(path).budget = budget
}

// Revoke stops a module. It takes back its purse immediately; it does NOT
// take back a sub-identity that was granted, nor any banker minted from one.
func (p *Pilot) Revoke(_ int, rlm realm, path string) {
	p.AssertOwner(0, rlm)
	p.mustSlot(path).live = false
}

// Fund moves coins from the account's main treasury into a module's
// sub-treasury. For an identity grant this is the permanent blast radius.
func (p *Pilot) Fund(_ int, rlm realm, path string, amount int64) {
	p.AssertOwner(0, rlm)
	s := p.mustSlot(path)
	p.vault.SendCoins(p.Address(), chain.DerivePkgSubAddr(p.host, s.subpath),
		chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Exec drives an installed module. rlm must be the account realm's own live
// cur: an identity grant mints its sub-token from it, which only the account
// realm's namespace can do.
func (p *Pilot) Exec(_ int, rlm realm, path, args string) string {
	p.AssertOwner(0, rlm)
	s := p.mustSlot(path)
	if !s.live {
		panic(ErrRevoked)
	}
	s.runs++
	if s.grant == GrantIdentity {
		return s.mod.Run(0, rlm.Sub(s.subpath), args)
	}
	return s.mod.Run(0, rlm, args)
}

// Register is called BY the module realm, with its own live cur. The account
// reads the path from the runtime and never from an argument.
func (a *Account) Register(_ int, rlm realm, m Module) {
	assertCurrent(0, rlm)
	path := rlm.PkgPath()
	s, ok := a.p.slots.Get(path).(*slot)
	if !ok {
		panic(ErrNotApproved)
	}
	s.mod = m
	s.live = true
}

// PurseFor hands the calling module its revocable purse.
func (a *Account) PurseFor(_ int, rlm realm) *Purse {
	assertCurrent(0, rlm)
	path := rlm.PkgPath()
	if _, ok := a.p.slots.Get(path).(*slot); !ok {
		panic(ErrNotApproved)
	}
	return &Purse{p: a.p, path: path}
}

// Purse is a capability this package declares, so every use of it runs here
// and is re-checked against live state. That is what makes it revocable,
// where a banker minted from a lent realm token is not.
type Purse struct {
	p    *Pilot
	path string
}

// Pay spends from the account's main treasury, against the module's budget.
func (u *Purse) Pay(to address, amount int64) {
	s, ok := u.p.slots.Get(u.path).(*slot)
	if !ok {
		panic(ErrNotInstalled)
	}
	if !s.live {
		panic(ErrRevoked)
	}
	if amount <= 0 || amount > s.budget-s.spent {
		panic(ErrOverBudget)
	}
	s.spent += amount
	u.p.vault.SendCoins(u.p.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Left is what this module may still spend.
func (u *Purse) Left() int64 {
	s, ok := u.p.slots.Get(u.path).(*slot)
	if !ok || !s.live {
		return 0
	}
	return s.budget - s.spent
}

// Render is the account page. The account realm forwards its Render here.
func (p *Pilot) Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# " + p.host + "\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString("| owner | " + p.owner.String() + " |\n")
	sb.WriteString("| treasury | " + p.Address().String() + " |\n")
	sb.WriteString(ufmt.Sprintf("| balance | %d ugnot |\n\n", p.balance(p.Address())))

	if p.slots.Size() == 0 {
		sb.WriteString("No power installed yet.\n")
		return sb.String()
	}

	sb.WriteString("## powers\n\n")
	sb.WriteString("| path | grant | identity | state | left | runs | sub-treasury |\n")
	sb.WriteString("|---|---|---|---|---|---|---|\n")
	p.slots.Iterate("", "", func(key string, v any) bool {
		s := v.(*slot)
		state := "approved"
		if s.live {
			state = "installed"
		} else if s.mod != nil {
			state = "revoked"
		}
		sub := chain.DerivePkgSubAddr(p.host, s.subpath)
		sb.WriteString(ufmt.Sprintf("| `%s` | %s | `%s#%s` | %s | %d | %d | %d ugnot |\n",
			key, s.grant.String(), p.host, s.subpath, state,
			s.budget-s.spent, s.runs, p.balance(sub)))
		return false
	})
	return sb.String()
}

func (p *Pilot) balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, "ugnot")
}

