				"float": 3.14,
			},
			expected: "map[bool:true float:3.14 int:42 str:hello]",
		},
		{
			name: "mixed types map",
			input: map[any]any{
				42:         "number",
				"string":   123,
				true:       []int{1, 2, 3},
