	uassert.True(t, d.Connected(0, 2))
	uassert.False(t, d.Connected(0, 3))
	uassert.Equal(t, 4, d.Groups()) // {0,1,2} {3} {4} {5}
	uassert.Equal(t, 3, d.Size(0))
