func rank(es []Entry) string {
	parts := make([]string, len(es))
	for i, e := range es {
		parts[i] = e.Elem + ":" + strconv.Itoa(e.Count)
	}
	return strings.Join(parts, ",")
}

// Package orderedmap is a map that remembers the order its keys were inserted,
// as a pure, reusable package.
//
// This matters more on chain than off it. gno map iteration order is
// unspecified, so a realm that ranges over a built-in map to build its Render
// can emit a different page on every call — which is a consensus bug, not a
// cosmetic one. This type gives back a deterministic order without needing the
// keys to be sortable.
//
// Backed by a built-in map for O(1) lookup plus a slice holding insertion
// order. Delete is O(n) in the number of keys, because it has to close the gap
// in that slice — an honest trade for O(1) Get and an allocation-free walk.
// Re-Setting an existing key updates the value and KEEPS its original position:
// insertion order means first insertion, not last write.
//
// A live demo of this package is at
// [r/moul/x/daily/orderedmapdemo](/r/nym-moultest123/x/daily/orderedmapdemo/v0).
package orderedmap

// MaxKeys bounds the map so gas stays predictable.
const MaxKeys = 4096

// OrderedMap is a string-keyed map with deterministic iteration.
type OrderedMap struct {
	m    map[string]string
	keys []string
}

// New returns an empty OrderedMap.
func New() *OrderedMap {
	return &OrderedMap{m: map[string]string{}}
}

// Len returns the number of entries.
func (o *OrderedMap) Len() int { return len(o.keys) }

// Set inserts or updates k. Updating an existing key keeps its original
// position — insertion order means FIRST insertion. Returns false when the map
// is full and k is new.
func (o *OrderedMap) Set(k, v string) bool {
	if _, ok := o.m[k]; ok {
		o.m[k] = v
		return true
	}
	if len(o.keys) >= MaxKeys {
		return false
	}
	o.m[k] = v
	o.keys = append(o.keys, k)
	return true
}

// Get returns the value for k.
func (o *OrderedMap) Get(k string) (string, bool) {
	v, ok := o.m[k]
	return v, ok
}

// Has reports whether k is present.
func (o *OrderedMap) Has(k string) bool {
	_, ok := o.m[k]
	return ok
}

// Delete removes k and reports whether it was present. O(n): the key's slot in
// the order slice has to be closed up, and the remaining keys shifted, so that
// order is preserved.
func (o *OrderedMap) Delete(k string) bool {
	if _, ok := o.m[k]; !ok {
		return false
	}
	delete(o.m, k)
	for i, kk := range o.keys {
		if kk == k {
			o.keys = append(o.keys[:i], o.keys[i+1:]...)
			break
		}
	}
	return true
}

// Keys returns the keys in insertion order, as an independent copy.
func (o *OrderedMap) Keys() []string {
	out := make([]string, len(o.keys))
	copy(out, o.keys)
	return out
}

// Values returns the values in key-insertion order.
func (o *OrderedMap) Values() []string {
	out := make([]string, 0, len(o.keys))
	for _, k := range o.keys {
		out = append(out, o.m[k])
	}
	return out
}

// Iterate calls fn for each entry in insertion order, stopping early if fn
// returns true. The map must not be mutated from inside fn — the walk is over
// a live slice.
func (o *OrderedMap) Iterate(fn func(k, v string) bool) {
	for _, k := range o.keys {
		if fn(k, o.m[k]) {
			return
		}
	}
}

// At returns the i-th entry in insertion order.
func (o *OrderedMap) At(i int) (k, v string, ok bool) {
	if i < 0 || i >= len(o.keys) {
		return "", "", false
	}
	k = o.keys[i]
	return k, o.m[k], true
}

// Clone returns an independent copy preserving order.
func (o *OrderedMap) Clone() *OrderedMap {
	c := New()
	for _, k := range o.keys {
		c.Set(k, o.m[k])
	}
	return c
}

package orderedmap

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestSetGetOrder(t *testing.T) {
	o := New()
	o.Set("z", "1")
	o.Set("a", "2")
	o.Set("m", "3")
	uassert.Equal(t, "z,a,m", strings.Join(o.Keys(), ","))   // insertion, not sorted
	uassert.Equal(t, "1,2,3", strings.Join(o.Values(), ",")) // values follow keys
	v, ok := o.Get("a")
	uassert.True(t, ok)
	uassert.Equal(t, "2", v)
	uassert.Equal(t, 3, o.Len())
}

// Insertion order means FIRST insertion: updating must not move a key.
func TestUpdateKeepsPosition(t *testing.T) {
	o := New()
	o.Set("a", "1")
	o.Set("b", "2")
	o.Set("a", "99")
	uassert.Equal(t, "a,b", strings.Join(o.Keys(), ","))
	v, _ := o.Get("a")
	uassert.Equal(t, "99", v)
	uassert.Equal(t, 2, o.Len())
}

func TestDeletePreservesOrder(t *testing.T) {
	o := New()
	for _, k := range []string{"a", "b", "c", "d"} {
		o.Set(k, k)
	}
	uassert.True(t, o.Delete("b"))
	uassert.Equal(t, "a,c,d", strings.Join(o.Keys(), ","))
	uassert.False(t, o.Has("b"))
	uassert.False(t, o.Delete("b")) // already gone
	uassert.Equal(t, 3, o.Len())
}

// Re-inserting after a delete appends at the END — it is a new insertion.
func TestReinsertAfterDeleteGoesLast(t *testing.T) {
	o := New()
	for _, k := range []string{"a", "b", "c"} {
		o.Set(k, k)
	}
	o.Delete("a")
	o.Set("a", "again")
	uassert.Equal(t, "b,c,a", strings.Join(o.Keys(), ","))
}

func TestMissingKey(t *testing.T) {
	o := New()
	v, ok := o.Get("nope")
	uassert.False(t, ok)
	uassert.Equal(t, "", v)
	uassert.False(t, o.Has("nope"))
}

func TestAt(t *testing.T) {
	o := New()
	o.Set("x", "1")
	o.Set("y", "2")
	k, v, ok := o.At(1)
	uassert.True(t, ok)
	uassert.Equal(t, "y", k)
	uassert.Equal(t, "2", v)
	_, _, ok = o.At(2)
	uassert.False(t, ok)
	_, _, ok = o.At(-1)
	uassert.False(t, ok)
}

func TestIterateStopsEarly(t *testing.T) {
	o := New()
	for _, k := range []string{"a", "b", "c"} {
		o.Set(k, k)
	}
	seen := []string{}
	o.Iterate(func(k, v string) bool {
		seen = append(seen, k)
		return k == "b" // stop after b
	})
	uassert.Equal(t, "a,b", strings.Join(seen, ","))
}

// The whole point: the order is stable across identical builds, where a
// built-in map gives no such guarantee.
func TestOrderIsStable(t *testing.T) {
	build := func() string {
		o := New()
		for _, k := range []string{"delta", "alpha", "charlie", "bravo"} {
			o.Set(k, k)
		}
		return strings.Join(o.Keys(), ",")
	}
	first := build()
	for i := 0; i < 20; i++ {
		uassert.Equal(t, first, build())
	}
	uassert.Equal(t, "delta,alpha,charlie,bravo", first)
}

func TestKeysIsACopy(t *testing.T) {
	o := New()
	o.Set("a", "1")
	ks := o.Keys()
	ks[0] = "mutated"
	uassert.Equal(t, "a", strings.Join(o.Keys(), ","))
}

func TestCloneIsIndependent(t *testing.T) {
	o := New()
	o.Set("a", "1")
	c := o.Clone()
	c.Set("b", "2")
	uassert.Equal(t, "a", strings.Join(o.Keys(), ","))
	uassert.Equal(t, "a,b", strings.Join(c.Keys(), ","))
}

func TestFullMapRejectsNewKeys(t *testing.T) {
	o := New()
	for i := 0; i < MaxKeys; i++ {
		uassert.True(t, o.Set(itoa(i), "v"))
	}
	uassert.False(t, o.Set("overflow", "v")) // new key refused
	uassert.True(t, o.Set("0", "updated"))   // existing key still updatable
	uassert.Equal(t, MaxKeys, o.Len())
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	return string(b)
}

// Package piglatin ports the classic "Pig Latin" translator — a staple Go
// beginner exercise — to gno.land as a reusable pure package.
//
// Rules implemented (the standard English game):
//   - A word that starts with a vowel gets "way" appended:   "apple" -> "appleway"
//   - A word that starts with one or more consonants has that leading
//     consonant cluster moved to the end, followed by "ay":  "string" -> "ingstray"
//   - "y" acts as a consonant only when it is the first letter of the word
//     ("yellow" -> "ellowyay"); elsewhere it counts as a vowel ("myth" -> "ythmay").
//   - Original capitalization of the word is preserved (title-case in, title-case
//     out): "Hello" -> "Ellohay".
//   - Trailing/leading punctuation attached to a word is preserved in place:
//     "Hello," -> "Ellohay,".
//
// Everything is pure strings/unicode — deterministic and reproducible on-chain.
//
// A live demo of this package (an interactive sentence translator) is at
// [r/moul/x/daily/piglatindemo](/r/nym-moultest123/x/daily/piglatindemo/v0).
package piglatin

import (
	"strings"
	"unicode"
)

const suffixVowel = "way"
const suffixConsonant = "ay"

func isVowel(r rune) bool {
	switch unicode.ToLower(r) {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// isLetter reports whether r is an ASCII/unicode letter (word character).
func isLetter(r rune) bool {
	return unicode.IsLetter(r)
}

// translateWord converts a single "core" alphabetic word (no surrounding
// punctuation) to Pig Latin, preserving its capitalization pattern.
func translateWord(word string) string {
	if word == "" {
		return word
	}
	runes := []rune(word)

	// Find the leading consonant cluster. 'y' is a consonant only in position 0.
	start := 0
	for i, r := range runes {
		if isVowel(r) {
			break
		}
		// 'y' after the first letter behaves like a vowel: stop the cluster.
		if i > 0 && unicode.ToLower(r) == 'y' {
			break
		}
		start = i + 1
	}

	var out []rune
	if start == 0 {
		// Starts with a vowel.
		out = append(out, runes...)
		out = append(out, []rune(suffixVowel)...)
	} else if start >= len(runes) {
		// All consonants (no vowel found), e.g. "shh" — just append "ay".
		out = append(out, runes...)
		out = append(out, []rune(suffixConsonant)...)
	} else {
		out = append(out, runes[start:]...)
		out = append(out, runes[:start]...)
		out = append(out, []rune(suffixConsonant)...)
	}

	return applyCase(word, string(out))
}

// applyCase re-applies the capitalization shape of the original word to the
// translated word. Two common shapes are handled: ALL CAPS and Title-case;
// everything else is returned lowercase.
func applyCase(orig, translated string) string {
	origRunes := []rune(orig)
	if len(origRunes) == 0 {
		return translated
	}

	// Count letters and uppercase letters in the original.
	letters, uppers := 0, 0
	for _, r := range origRunes {
		if unicode.IsLetter(r) {
			letters++
			if unicode.IsUpper(r) {
				uppers++
			}
		}
	}

	low := strings.ToLower(translated)
	switch {
	case letters > 0 && uppers == letters && letters > 1:
		// ALL CAPS -> keep upper.
		return strings.ToUpper(low)
	case unicode.IsUpper(origRunes[0]):
		// Title-case -> capitalize first letter of the result.
		tr := []rune(low)
		if len(tr) > 0 {
			tr[0] = unicode.ToUpper(tr[0])
		}
		return string(tr)
	default:
		return low
	}
}

// splitAffixes separates a token into (leading punctuation, core word,
// trailing punctuation) where the core is the contiguous run of letters
// (apostrophes inside are kept as part of the core, e.g. "don't").
func splitAffixes(token string) (string, string, string) {
	runes := []rune(token)
	i := 0
	for i < len(runes) && !isLetter(runes[i]) {
		i++
	}
	j := len(runes)
	for j > i && !isLetter(runes[j-1]) {
		j--
	}
	if i >= j {
		return token, "", "" // no letters at all
	}
	return string(runes[:i]), string(runes[i:j]), string(runes[j:])
}

// TranslateToken translates a single whitespace-delimited token, preserving
// any punctuation glued to its edges.
func TranslateToken(token string) string {
	lead, core, trail := splitAffixes(token)
	if core == "" {
		return token
	}
	return lead + translateWord(core) + trail
}

// Translate applies Pig Latin to every word in the sentence while preserving
// the original whitespace between words.
func Translate(sentence string) string {
	var b strings.Builder
	var word strings.Builder
	flush := func() {
		if word.Len() > 0 {
			b.WriteString(TranslateToken(word.String()))
			word.Reset()
		}
	}
	for _, r := range sentence {
		if unicode.IsSpace(r) {
			flush()
			b.WriteRune(r)
			continue
		}
		word.WriteRune(r)
	}
	flush()
	return b.String()
}

