	uassert.Equal(t, "...", lead)
	uassert.Equal(t, "", core)
	uassert.Equal(t, "", trail)
}

// Package pullpayment is the escrow ledger behind the pull-payment pattern, as
// a pure, reusable package.
//
// The pattern is the classic Solidity answer to reentrancy: never push value to
// an address, credit it and let the recipient withdraw. A push sends control to
// the recipient in the middle of your state transition, and a malicious
// recipient re-enters before you have finished updating. Pull inverts that —
// the recipient calls in, and their own withdrawal is the only state being
// touched.
//
// This package is the BOOKKEEPING half only: who is owed what, and the
// checks-effects-interactions ordering that makes a withdrawal safe. It moves
// no coins. The realm that holds the funds performs the transfer AFTER calling
// Withdraw, which is exactly the ordering the pattern demands — the balance is
// already zeroed when the transfer happens, so a reentrant call finds nothing
// left to take.
//
// Iteration is over sorted addresses, never a built-in map range: gno map
// iteration order is unspecified and a Render built from one can differ between
// nodes, which is a consensus bug rather than a cosmetic one.
//
// A live demo of this package is at
// [r/moul/x/daily/pullpaymentdemo](/r/nym-moultest123/x/daily/pullpaymentdemo/v0).
package pullpayment

import (
	"errors"
	"sort"
)

// MaxPayees bounds the ledger so gas stays predictable.
const MaxPayees = 4096

var (
	ErrBadAmount = errors.New("pullpayment: amount must be positive")
	ErrFull      = errors.New("pullpayment: too many payees")
	ErrNothing   = errors.New("pullpayment: nothing to withdraw")
	ErrOverflow  = errors.New("pullpayment: credit would overflow")
)

const maxInt64 = int64(9223372036854775807)

// Ledger records what each address is owed.
type Ledger struct {
	owed      map[string]int64
	total     int64
	withdrawn int64
}

// New returns an empty Ledger.
func New() *Ledger { return &Ledger{owed: map[string]int64{}} }

// Credit records that payee is owed amount more. Amounts accumulate: crediting
// twice owes the sum.
func (l *Ledger) Credit(payee string, amount int64) error {
	if amount <= 0 {
		return ErrBadAmount
	}
	cur, seen := l.owed[payee]
	if !seen && len(l.owed) >= MaxPayees {
		return ErrFull
	}
	if cur > maxInt64-amount || l.total > maxInt64-amount {
		return ErrOverflow
	}
	l.owed[payee] = cur + amount
	l.total += amount
	return nil
}

// Balance returns what payee is currently owed; zero when nothing.
func (l *Ledger) Balance(payee string) int64 { return l.owed[payee] }

// Withdraw zeroes payee's balance and returns what was owed.
//
// The caller transfers the returned amount AFTER this call. That ordering is
// the point of the pattern: the credit is already gone from the ledger when
// control passes to the recipient, so a reentrant Withdraw returns ErrNothing.
func (l *Ledger) Withdraw(payee string) (int64, error) {
	amount, ok := l.owed[payee]
	if !ok || amount == 0 {
		return 0, ErrNothing
	}
	delete(l.owed, payee) // effects before interactions
	l.total -= amount
	l.withdrawn += amount
	return amount, nil
}

// Forfeit drops a payee's credit without paying it, returning what was dropped.
func (l *Ledger) Forfeit(payee string) (int64, error) {
	amount, ok := l.owed[payee]
	if !ok || amount == 0 {
		return 0, ErrNothing
	}
	delete(l.owed, payee)
	l.total -= amount
	return amount, nil
}

// TotalOwed returns the sum of every outstanding balance — what the holding
// realm must keep in reserve.
func (l *Ledger) TotalOwed() int64 { return l.total }

// TotalWithdrawn returns the lifetime sum of successful withdrawals.
func (l *Ledger) TotalWithdrawn() int64 { return l.withdrawn }

// Payees returns every address with an outstanding balance, sorted.
func (l *Ledger) Payees() []string {
	out := make([]string, 0, len(l.owed))
	for p := range l.owed {
		out = append(out, p)
	}
	sort.Strings(out)
	return out
}

// Count returns how many payees are owed something.
func (l *Ledger) Count() int { return len(l.owed) }

// IsEmpty reports whether nothing is owed to anyone.
func (l *Ledger) IsEmpty() bool { return len(l.owed) == 0 }

// Iterate calls fn for each payee in sorted order. Returning true stops.
func (l *Ledger) Iterate(fn func(payee string, amount int64) bool) {
	for _, p := range l.Payees() {
		if fn(p, l.owed[p]) {
			return
		}
	}
}

// CreditMany credits several payees, applying nothing unless every entry is
// valid — a partial split would leave the ledger disagreeing with the funds.
func (l *Ledger) CreditMany(payees []string, amounts []int64) error {
	if len(payees) != len(amounts) {
		return ErrBadAmount
	}
	// Validate first.
	for _, a := range amounts {
		if a <= 0 {
			return ErrBadAmount
		}
	}
	probe := len(l.owed)
	for _, p := range payees {
		if _, seen := l.owed[p]; !seen {
			probe++
		}
	}
	if probe > MaxPayees {
		return ErrFull
	}
	var sum int64
	for _, a := range amounts {
		if sum > maxInt64-a {
			return ErrOverflow
		}
		sum += a
	}
	if l.total > maxInt64-sum {
		return ErrOverflow
	}
	// Then apply.
	for i, p := range payees {
		l.owed[p] += amounts[i]
	}
	l.total += sum
	return nil
}

// Consistent reports whether TotalOwed equals the sum of the balances. Always
// true through the public API; exported so callers can assert the invariant.
func (l *Ledger) Consistent() bool {
	var sum int64
	for _, a := range l.owed {
		sum += a
	}
	return sum == l.total
}

// Package ratelimit is a deterministic token-bucket rate limiter — a port of
// golang.org/x/time/rate with the wall clock replaced by a caller-supplied
// monotonic tick (on-chain, that tick is the block height).
//
// It is a pure library: it imports no chain APIs and reads no ambient state.
// A [Limiter] owns a set of per-key token buckets sharing one rate/burst
// config; the caller decides what a key is (typically an address string) and
// supplies the current tick on every call. Between two observations at ticks
// `last` and `now`, a bucket gains (now-last)*rate tokens, capped at `burst`.
// Everything is integer/float arithmetic over persistent avl state, hence
// deterministic and replayable.
//
// A realm wires it up by holding a *Limiter in a package-level var and feeding
// it runtime.ChainHeight() as the tick. For a complete, live example see the
// demo realm [r/moul/x/daily/ratelimitdemo](/r/nym-moultest123/x/daily/ratelimitdemo/v0).
package ratelimit

import "gno.land/p/nt/avl/v0"

// bucket is the per-key state persisted in the avl tree.
type bucket struct {
	tokens float64 // tokens available as of `last`
	last   int64   // tick at which `tokens` was computed
}

// Limiter is a set of per-key token buckets sharing one rate/burst config.
// The zero value is not usable; construct one with [New].
type Limiter struct {
	rate    float64   // tokens replenished per tick
	burst   float64   // bucket capacity (max tokens, largest single burst)
	buckets *avl.Tree // key string -> *bucket, ordered by key (deterministic)
}

// New returns a Limiter replenishing `rate` tokens per tick, each bucket capped
// at `burst`. rate is clamped to >= 0, burst to >= 1.
func New(rate, burst float64) *Limiter {
	l := &Limiter{buckets: avl.NewTree()}
	l.SetConfig(rate, burst)
	return l
}

// SetConfig updates the shared rate and burst. rate is clamped to >= 0, burst
// to >= 1. Existing buckets keep their stored tokens; the new config applies
// from the next refill.
func (l *Limiter) SetConfig(rate, burst float64) {
	if rate < 0 {
		rate = 0
	}
	if burst < 1 {
		burst = 1
	}
	l.rate = rate
	l.burst = burst
}

// Config returns the current rate (tokens/tick) and burst (capacity).
func (l *Limiter) Config() (rate, burst float64) { return l.rate, l.burst }

// Allow consumes one token for `key` at tick `now` and reports whether the
// request is permitted. When the bucket is empty it returns false and consumes
// nothing. Equivalent to AllowN(key, now, 1).
func (l *Limiter) Allow(key string, now int64) bool {
	return l.AllowN(key, now, 1)
}

// AllowN consumes `n` tokens for `key` at tick `now` and reports whether the
// request is permitted. When fewer than `n` tokens are available it returns
// false and consumes nothing. A key is seen for the first time with a full
// bucket of `burst` tokens.
func (l *Limiter) AllowN(key string, now int64, n float64) bool {
	b := l.load(key, now)
	ok := b.tokens >= n
	if ok {
		b.tokens -= n
	}
	l.buckets.Set(key, b)
	return ok
}

// Tokens is a read-only view of how many whole tokens `key` has available at
// tick `now`, without mutating any state.
func (l *Limiter) Tokens(key string, now int64) int {
	if !l.buckets.Has(key) {
		return tokensToInt(l.burst)
	}
	b := l.buckets.Get(key).(*bucket)
	return tokensToInt(refill(b.tokens, b.last, now, l.rate, l.burst))
}

// Len returns the number of keys the limiter has seen.
func (l *Limiter) Len() int { return l.buckets.Size() }

// Iterate calls fn for every known key in ascending order, passing the whole
// tokens available at tick `now` and the last tick the key was observed.
// Returning true from fn stops the iteration early; Iterate reports whether it
// was stopped that way.
func (l *Limiter) Iterate(now int64, fn func(key string, tokens int, last int64) bool) bool {
	return l.buckets.Iterate("", "", func(key string, value any) bool {
		b := value.(*bucket)
		return fn(key, tokensToInt(refill(b.tokens, b.last, now, l.rate, l.burst)), b.last)
	})
}

// load returns the live bucket for key, refilled to `now`, creating a full
// bucket the first time a key is seen. The returned bucket is not yet stored;
// callers that mutate it must Set it back.
func (l *Limiter) load(key string, now int64) *bucket {
	if l.buckets.Has(key) {
		b := l.buckets.Get(key).(*bucket)
		b.tokens = refill(b.tokens, b.last, now, l.rate, l.burst)
		b.last = now
		return b
	}
	return &bucket{tokens: l.burst, last: now}
}

// --- pure helpers (unit-tested) -------------------------------------------

// fmin returns the smaller of two float64 values.
func fmin(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

// refill returns the token count at tick `now` given `tokens` observed at tick
// `last`, replenishing at `r` tokens/tick up to capacity `cap`. It never
// decreases below the stored value and never exceeds `cap`.
func refill(tokens float64, last, now int64, r, cap float64) float64 {
	if now <= last {
		return fmin(tokens, cap)
	}
	elapsed := float64(now - last)
	return fmin(cap, tokens+elapsed*r)
}

// tokensToInt floors a token count to a whole, non-negative token.
func tokensToInt(t float64) int {
	if t < 0 {
		return 0
	}
	return int(t)
}

