func TestRootMatchesTendermint(t *testing.T) {
	for _, n := range []int{1, 2, 3, 4, 5, 7} {
		got := New(leaves(n)).RootHex()
		if got != goldenRoots[n] {
			t.Errorf("n=%d: root = %s, tm2 says %s", n, got, goldenRoots[n])
		}
	}
}

func TestProofMatchesTendermint(t *testing.T) {
	for n, want := range goldenAunts {
		tree := New(leaves(n))
		for i, w := range want {
			p, err := tree.Proof(i)
			if err != nil {
				t.Fatalf("n=%d i=%d: Proof: %v", n, i, err)
			}
			if got := p.Hex(); got != w {
				t.Errorf("n=%d i=%d:\n got  %s\n want %s", n, i, got, w)
			}
		}
	}
}

// Every leaf of every tree shape up to 33 must produce a proof the native
// verifier accepts. This is the property that matters; the golden vectors only
// pin the encoding.
func TestEveryProofVerifies(t *testing.T) {
	for n := 1; n <= 33; n++ {
		ls := leaves(n)
		tree := New(ls)
		root := tree.Root()
		for i := 0; i < n; i++ {
			p, err := tree.Proof(i)
			if err != nil {
				t.Fatalf("n=%d i=%d: Proof: %v", n, i, err)
			}
			if !p.Verify(root, ls[i]) {
				t.Errorf("n=%d i=%d: valid proof rejected", n, i)
			}
		}
	}
}

func TestRejects(t *testing.T) {
	ls := leaves(8)
	tree := New(ls)
	root := tree.Root()
	p0, _ := tree.Proof(0)
	p1, _ := tree.Proof(1)

	tests := []struct {
		name  string
		proof Proof
		root  []byte
		leaf  []byte
	}{
		{"forged leaf", p0, root, []byte("not-a-leaf")},
		{"another real leaf at the wrong index", p0, root, ls[1]},
		{"proof replayed at a different index", Proof{Index: 1, Total: p0.Total, Siblings: p0.Siblings}, root, ls[1]},
		{"sibling list of another leaf", Proof{Index: 0, Total: 8, Siblings: p1.Siblings}, root, ls[0]},
		{"wrong root", p0, LeafHash([]byte("nope")), ls[0]},
		{"index beyond total", Proof{Index: 8, Total: 8, Siblings: p0.Siblings}, root, ls[0]},
		{"negative index", Proof{Index: -1, Total: 8, Siblings: p0.Siblings}, root, ls[0]},
		{"zero total", Proof{Index: 0, Total: 0, Siblings: p0.Siblings}, root, ls[0]},
		{"truncated proof", Proof{Index: 0, Total: 8, Siblings: p0.Siblings[:1]}, root, ls[0]},
		{"short root", p0, root[:31], ls[0]},
	}
	for _, tc := range tests {
		if tc.proof.Verify(tc.root, tc.leaf) {
			t.Errorf("%s: accepted, must be rejected", tc.name)
		}
	}
}

func TestMaxDepthCap(t *testing.T) {
	sibs := make([][]byte, MaxDepth+1)
	for i := range sibs {
		sibs[i] = make([]byte, HashSize)
	}
	p := Proof{Index: 0, Total: 1 << 20, Siblings: sibs}
	if p.Verify(make([]byte, HashSize), []byte("x")) {
		t.Error("proof deeper than MaxDepth accepted")
	}
	if !VerifySorted(make([]byte, HashSize), make([]byte, HashSize), sibs[:MaxDepth]) == false {
		t.Error("unreachable")
	}
	if VerifySorted(make([]byte, HashSize), make([]byte, HashSize), sibs) {
		t.Error("sorted proof deeper than MaxDepth accepted")
	}
}

func TestParseProofRoundTrip(t *testing.T) {
	tree := New(leaves(7))
	for i := 0; i < 7; i++ {
		want, _ := tree.Proof(i)
		got, err := ParseProof(i, 7, want.Hex())
		if err != nil {
			t.Fatalf("i=%d: ParseProof: %v", i, err)
		}
		if got.Hex() != want.Hex() || got.Index != want.Index || got.Total != want.Total {
			t.Errorf("i=%d: round trip lost data", i)
		}
		if !got.Verify(tree.Root(), []byte("leaf-"+strconv.Itoa(i))) {
			t.Errorf("i=%d: reparsed proof does not verify", i)
		}
	}
}

func TestParseProofErrors(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want error
	}{
		{"not hex", "zz", ErrBadHex},
		{"wrong size", "abcd", ErrBadHashSize},
		{"too deep", tooDeepHex(), ErrProofTooDeep},
	}
	for _, tc := range tests {
		if _, err := ParseProof(0, 2, tc.in); err != tc.want {
			t.Errorf("%s: err = %v, want %v", tc.name, err, tc.want)
		}
	}
	// An empty sibling list is the one-leaf proof, not an error.
	p, err := ParseProof(0, 1, "  ")
	if err != nil {
		t.Fatalf("empty siblings: %v", err)
	}
	one := New(leaves(1))
	if !p.Verify(one.Root(), []byte("leaf-0")) {
		t.Error("one-leaf proof with no siblings rejected")
	}
}

func tooDeepHex() string {
	h := hex.EncodeToString(make([]byte, HashSize))
	out := h
	for i := 0; i < MaxDepth; i++ {
		out += "," + h
	}
	return out
}

func TestTreeErrors(t *testing.T) {
	if _, err := New(nil).Proof(0); err != ErrEmptyTree {
		t.Errorf("empty tree: err = %v, want %v", err, ErrEmptyTree)
	}
	if New(nil).Root() != nil {
		t.Error("empty tree root should be nil, like Tendermint")
	}
	tree := New(leaves(3))
	for _, i := range []int{-1, 3, 99} {
		if _, err := tree.Proof(i); err != ErrIndexRange {
			t.Errorf("index %d: err = %v, want %v", i, err, ErrIndexRange)
		}
	}
}

// New must copy its input: a caller mutating the slice afterwards cannot be
// allowed to change what the tree committed to.
func TestNewCopiesLeaves(t *testing.T) {
	ls := [][]byte{[]byte("a"), []byte("b")}
	tree := New(ls)
	before := tree.RootHex()
	ls[0][0] = 'z'
	if tree.RootHex() != before {
		t.Error("mutating the caller's slice changed the committed root")
	}
}

// The reason this package exists. In a scheme without domain separation an
// INNER NODE hash is also a valid LEAF hash, so anyone who can choose a
// 64-byte leaf preimage can prove membership of a leaf that was never in the
// tree. This test performs that forgery against VerifySorted, then shows the
// Tendermint scheme refuses the same move.
func TestSecondPreimageForgery(t *testing.T) {
	// A 4-leaf commutative tree, built the OpenZeppelin way.
	h := make([][]byte, 4)
	for i := range h {
		s := sha256.Sum256([]byte("leaf-" + strconv.Itoa(i)))
		h[i] = s[:]
	}
	n01 := hashSortedPair(h[0], h[1])
	n23 := hashSortedPair(h[2], h[3])
	root := hashSortedPair(n01, n23)

	// Sanity: a real leaf really does verify.
	if !VerifySorted(root, h[0], [][]byte{h[1], n23}) {
		t.Fatal("honest sorted proof rejected")
	}

	// The forgery: present the inner node n01 as if it were a leaf hash. Its
	// preimage is the 64 bytes sorted(h0, h1), so an application whose leaves
	// can be 64 bytes long hands the attacker a membership proof for data that
	// was never committed.
	if !VerifySorted(root, n01, [][]byte{n23}) {
		t.Fatal("expected the second-preimage forgery to succeed against VerifySorted")
	}

	// Same shape, Tendermint scheme. Leaves are tagged 0x00 and inner nodes
	// 0x01, so no leaf preimage can ever hash to an inner node, and the proof
	// is bound to an index besides.
	tree := New(leaves(4))
	inner := InnerHash(LeafHash(tree.leaves[0]), LeafHash(tree.leaves[1]))
	forged := Proof{Index: 0, Total: 2, Siblings: [][]byte{InnerHash(LeafHash(tree.leaves[2]), LeafHash(tree.leaves[3]))}}
	if forged.Verify(tree.Root(), inner) {
		t.Error("domain separation failed: an inner node was accepted as a leaf")
	}
}

func TestLeafAndInnerHashAreTagged(t *testing.T) {
	leafOfEmpty := LeafHash(nil)
	taggedLeaf := sha256.Sum256([]byte{0x00})
	if hex.EncodeToString(leafOfEmpty) != hex.EncodeToString(taggedLeaf[:]) {
		t.Error("LeafHash is not SHA256(0x00 || leaf)")
	}
	l := make([]byte, 32)
	r := make([]byte, 32)
	r[0] = 1
	got := InnerHash(l, r)
	want := sha256.Sum256(append(append([]byte{0x01}, l...), r...))
	if hex.EncodeToString(got) != hex.EncodeToString(want[:]) {
		t.Error("InnerHash is not SHA256(0x01 || left || right)")
	}
}

func TestSplitPointMatchesTendermint(t *testing.T) {
	// largest power of two strictly below length
	tests := []struct{ in, want int }{
		{2, 1}, {3, 2}, {4, 2}, {5, 4}, {7, 4}, {8, 4}, {9, 8}, {16, 8}, {17, 16},
	}
	for _, tc := range tests {
		if got := splitPoint(tc.in); got != tc.want {
			t.Errorf("splitPoint(%d) = %d, want %d", tc.in, got, tc.want)
		}
	}
}

// Package pair is the whole behaviour of one constant-product AMM pair, as a
// pure package, so that a realm holding a single pair can be twenty lines of
// glue.
//
// It is the shared half of the instance-per-realm pattern: deploy this once,
// then deploy one tiny realm per token couple, each owning its own state, its
// own funds and its own storage deposit, all running this identical code. The
// Ethereum shape it copies (a factory spawning one UniswapV2Pair per couple)
// needs EIP-1167 clones to make the duplication affordable; an import makes it
// free.
//
// # How an instance uses it
//
//	var p *pair.Pair
//
//	func init(cur realm) {
//		p = pair.New(keyA, keyB, grc20reg.MustGet(keyA), grc20reg.MustGet(keyB))
//		pairreg.Register(cross(cur), p)
//	}
//
//	func Swap(cur realm, keyIn string, amountIn, minOut int64) int64 {
//		return p.Swap(0, cur, keyIn, amountIn, minOut)
//	}
//
// # Why the methods look like that
//
// Every state-changing method is shaped (_ int, rlm realm, ...). The leading
// dummy is mandatory: gno rejects a function whose FIRST parameter is realm
// when it is declared in a pure package ("crossing function declared in
// non-realm package"), and the parameter cannot be named cur either. Same
// reason grc20's tellers are Transfer(_ int, rlm realm, ...). The realm value
// arrives non-crossing, which is exactly what is wanted: the frame stays the
// instance realm, so funds move to and from the INSTANCE's address, and
// rlm.IsCurrent() still holds for grc20's spoof check.
//
// A pure package also cannot import a realm at all, so this package never
// resolves a token by path. The instance passes *grc20.Token handles in.
//
// # The economics, unchanged from the single-realm design
//
// Constant product x*y=k with a 30 bps fee kept by the pool, reserves stored
// and never derived from BalanceOf (so a direct transfer to the realm is
// inert, and permanently stuck), first deposit minting shares equal to the
// token-A amount with no sqrt and no MINIMUM_LIQUIDITY burn, and every reserve
// capped so the int64 arithmetic cannot overflow. The reasoning behind each of
// those is in https://github.com/moul/gno-contracts/issues/135 and is not
// repeated here; this package is that design with one pool per realm instead
// of many pools in one realm.
//
// Consequence worth repeating, because it bites: with a 1000x fee denominator
// on int64 amounts, this is unusable with 18-decimal tokens. Six to nine
// decimals is the practical band.
package pair

import (
	"chain"
	"math"
	"math/bits"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// feeNum/feeDen is the swap fee kept by the pool: 997/1000, i.e. 30 bps.
	feeNum = 997
	feeDen = 1000

	// maxReserve is the largest reserve a pair will hold, in base units.
	//
	// Pricing computes den = reserveIn*feeDen + amountIn*feeNum in plain
	// int64 before handing off to the 128-bit mulDiv. Capping every reserve,
	// and every post-swap reserve, at MaxInt64/feeDen makes that sum provably
	// safe:
	//
	//	den < (reserveIn + amountIn) * feeDen <= maxReserve * feeDen
	//	    = 9223372036854775000 <= MaxInt64 = 9223372036854775807
	MaxReserve = math.MaxInt64 / feeDen // 9223372036854775
)

// Pair is one token couple and its liquidity. Fields are concrete by design:
// the registry realm holds a live pointer to this struct and reads it while
// rendering, so an interface or a func field here would let a hostile
// instance hand foreign code to the registry's frame.
//
// keyA < keyB always holds; New canonicalises.
type Pair struct {
	keyA, keyB  string
	tokA, tokB  *grc20.Token
	resA, resB  int64
	totalShares int64
	shares      *avl.Tree // address string -> int64
}

// New builds an empty pair from two grc20reg keys and the matching token
// handles, in canonical order. The caller (the instance realm) is responsible
// for resolving the handles, because a pure package cannot import the
// registry realm that holds them.
func New(keyA, keyB string, tokA, tokB *grc20.Token) *Pair {
	if keyA == "" || keyB == "" {
		panic("pair: empty token key")
	}
	if keyA == keyB {
		panic("pair: a pair needs two different tokens")
	}
	if tokA == nil || tokB == nil {
		panic("pair: nil token")
	}
	if keyA > keyB {
		keyA, keyB = keyB, keyA
		tokA, tokB = tokB, tokA
	}
	return &Pair{keyA: keyA, keyB: keyB, tokA: tokA, tokB: tokB, shares: avl.NewTree()}
}

//
// Writes. Each one takes the instance realm's own cur, forwarded.
//

// AddLiquidity deposits up to maxA of token A and maxB of token B and mints LP
// shares to the caller. On an existing pair the deposit is trimmed to the
// current reserve ratio, so pass the amounts you are willing to spend, not the
// amounts you insist on spending.
//
// The caller must first Approve the INSTANCE realm's address on both tokens.
// Returns the shares minted.
func (p *Pair) AddLiquidity(_ int, rlm realm, maxA, maxB int64) int64 {
	if maxA <= 0 || maxB <= 0 {
		panic("pair: both deposit amounts must be > 0")
	}
	amtA, amtB := maxA, maxB

	var minted int64
	if p.totalShares == 0 {
		// First position: the depositor sets the price and the share unit is
		// token A at seed time. No sqrt, no MINIMUM_LIQUIDITY burn.
		minted = amtA
	} else {
		// Trim to the current ratio, then mint from whichever side is scarcer.
		// Both divisions floor, and taking the minimum means an off-ratio
		// deposit is rounded against the depositor, never against the pool.
		if want := mulDiv(amtA, p.resB, p.resA); want <= amtB {
			amtB = want
		} else {
			amtA = mulDiv(amtB, p.resA, p.resB)
		}
		if amtA <= 0 || amtB <= 0 {
			panic("pair: deposit too small for the current ratio")
		}
		minted = min64(
			mulDiv(amtA, p.totalShares, p.resA),
			mulDiv(amtB, p.totalShares, p.resB),
		)
	}
	if minted <= 0 {
		panic("pair: deposit mints zero shares")
	}
	if p.resA+amtA > MaxReserve || p.resB+amtB > MaxReserve {
		panic("pair: reserve cap exceeded")
	}

	provider := rlm.Previous().Address()
	self := rlm.Address()
	pull(0, rlm, p.tokA, provider, self, amtA)
	pull(0, rlm, p.tokB, provider, self, amtB)

	p.resA += amtA
	p.resB += amtB
	p.totalShares += minted
	p.setShares(provider, p.SharesOf(provider)+minted)

	chain.Emit("AddLiquidity",
		"pair", p.ID(),
		"provider", provider.String(),
		"amountA", itoa(amtA),
		"amountB", itoa(amtB),
		"shares", itoa(minted),
	)
	return minted
}

// RemoveLiquidity burns shares held by the caller and returns the
// proportional amounts of both tokens, in (A, B) order.
//
// Burning the entire share supply pays out the whole reserve, so the last
// provider out leaves nothing unclaimable behind and the pair can be reseeded
// at a fresh price.
func (p *Pair) RemoveLiquidity(_ int, rlm realm, shares int64) (int64, int64) {
	if shares <= 0 {
		panic("pair: shares must be > 0")
	}
	owner := rlm.Previous().Address()
	held := p.SharesOf(owner)
	if held < shares {
		panic("pair: insufficient shares")
	}

	var amtA, amtB int64
	if shares == p.totalShares {
		amtA, amtB = p.resA, p.resB
	} else {
		amtA = mulDiv(shares, p.resA, p.totalShares)
		amtB = mulDiv(shares, p.resB, p.totalShares)
	}
	if amtA <= 0 || amtB <= 0 {
		panic("pair: burn would return nothing on one side")
	}

	p.resA -= amtA
	p.resB -= amtB
	p.totalShares -= shares
	p.setShares(owner, held-shares)

	push(0, rlm, p.tokA, owner, amtA)
	push(0, rlm, p.tokB, owner, amtB)

	chain.Emit("RemoveLiquidity",
		"pair", p.ID(),
		"provider", owner.String(),
		"amountA", itoa(amtA),
		"amountB", itoa(amtB),
		"shares", itoa(shares),
	)
	return amtA, amtB
}

// Swap sells amountIn of keyIn for the other token and aborts unless at least
// minOut comes back. The caller must first Approve the instance realm's
// address on keyIn.
//
// minOut is the only protection against being sandwiched or against the pair
// moving between quoting and execution. Pass a real bound; passing 0 means
// accepting any price at all.
func (p *Pair) Swap(_ int, rlm realm, keyIn string, amountIn, minOut int64) int64 {
	if amountIn <= 0 {
		panic("pair: amountIn must be > 0")
	}
	if minOut < 0 {
		panic("pair: minOut must be >= 0")
	}
	flipped := p.mustSide(keyIn)

	resIn, resOut := p.resA, p.resB
	tokIn, tokOut := p.tokA, p.tokB
	if flipped {
		resIn, resOut = p.resB, p.resA
		tokIn, tokOut = p.tokB, p.tokA
	}

	out := AmountOut(amountIn, resIn, resOut)
	if out <= 0 {
		panic("pair: output rounds to zero")
	}
	if out < minOut {
		panic("pair: slippage, output below minOut")
	}

	trader := rlm.Previous().Address()
	pull(0, rlm, tokIn, trader, rlm.Address(), amountIn)

	newIn, newOut := resIn+amountIn, resOut-out
	// The invariant holds by construction (out is floored), so this can only
	// fire if the pricing above is ever edited into being wrong. It is exact:
	// both products are compared in 128 bits.
	if cmpProd(newIn, newOut, resIn, resOut) < 0 {
		panic("pair: constant product regression")
	}
	if flipped {
		p.resB, p.resA = newIn, newOut
	} else {
		p.resA, p.resB = newIn, newOut
	}

	push(0, rlm, tokOut, trader, out)

	chain.Emit("Swap",
		"pair", p.ID(),
		"trader", trader.String(),
		"tokenIn", tokIn.GetSymbol(),
		"amountIn", itoa(amountIn),
		"amountOut", itoa(out),
	)
	return out
}

//
// Reads. Safe for the registry realm to call on another realm's Pair.
//

// AmountOut is the pricing function, fee included, as a pure function of the
// two reserves. Exported so a caller can quote off chain against reserves it
// already holds, and so the arithmetic is testable on its own.
func AmountOut(amountIn, reserveIn, reserveOut int64) int64 {
	if amountIn <= 0 {
		panic("pair: amountIn must be > 0")
	}
	if reserveIn <= 0 || reserveOut <= 0 {
		panic("pair: pair has an empty reserve")
	}
	if reserveIn > MaxReserve || reserveOut > MaxReserve {
		panic("pair: reserve above cap")
	}
	if amountIn > MaxReserve-reserveIn {
		panic("pair: reserve cap exceeded")
	}
	inFee := amountIn * feeNum
	den := reserveIn*feeDen + inFee
	return mulDiv(inFee, reserveOut, den)
}

// Quote prices amountIn of keyIn against the live reserves. It is the number
// Swap would return right now, which is not a promise about the next block.
func (p *Pair) Quote(keyIn string, amountIn int64) int64 {
	if p.totalShares == 0 {
		return 0
	}
	if p.mustSide(keyIn) {
		return AmountOut(amountIn, p.resB, p.resA)
	}
	return AmountOut(amountIn, p.resA, p.resB)
}

// Keys returns the two grc20reg keys in canonical order.
func (p *Pair) Keys() (string, string) { return p.keyA, p.keyB }

// Symbols returns the two token symbols in canonical order.
func (p *Pair) Symbols() (string, string) { return p.tokA.GetSymbol(), p.tokB.GetSymbol() }

// ID is the canonical identifier of the couple, "keyA~keyB". The separator is
// "~" and not "|": a "|" inside a markdown table cell breaks the row.
func (p *Pair) ID() string { return p.keyA + "~" + p.keyB }

// Reserves returns the two reserves in canonical order.
func (p *Pair) Reserves() (int64, int64) { return p.resA, p.resB }

// TotalShares returns the LP share supply.
func (p *Pair) TotalShares() int64 { return p.totalShares }

// Providers returns how many addresses hold shares.
func (p *Pair) Providers() int { return p.shares.Size() }

// SharesOf returns owner's LP shares.
func (p *Pair) SharesOf(owner address) int64 {
	v := p.shares.Get(owner.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// Render is the instance realm's whole page: what the couple is, what it
// holds, and how to trade it.
func (p *Pair) Render(path string) string {
	symA, symB := p.Symbols()
	out := "# " + symA + " / " + symB + "\n\n"
	out += "One constant-product pair, `x*y=k`, 30 bps to the liquidity providers. "
	out += "Logic lives in [p/moul/x/pair/v0](/p/nym-moultest123/x/pair/v0); this realm is the instance.\n\n"

	if p.totalShares == 0 {
		out += "_Empty. The first `AddLiquidity` sets the price._\n\n"
	} else {
		out += ufmt.Sprintf("| side | reserve | key |\n|---|---|---|\n| %s | %d | `%s` |\n| %s | %d | `%s` |\n\n",
			symA, p.resA, p.keyA, symB, p.resB, p.keyB)
		out += ufmt.Sprintf("- LP shares: **%d** across %d provider(s)\n",
			p.totalShares, p.shares.Size())
		out += ufmt.Sprintf("- Spot: 1 %s buys ~%d %s (before fee and slippage)\n\n",
			symA, p.spot(), symB)
	}
	out += "Approve this realm's address on the token you are selling, then call `Swap`.\n"
	return out
}

//
// Internals.
//

// spot is the display-only mid price, floor(resB/resA). Never price anything
// off it: it is a spot reserve ratio that any trader can move in one tx.
func (p *Pair) spot() int64 {
	if p.resA == 0 {
		return 0
	}
	return p.resB / p.resA
}

// mustSide reports whether key is the B side, and panics if it is neither.
func (p *Pair) mustSide(key string) bool {
	switch key {
	case p.keyA:
		return false
	case p.keyB:
		return true
	}
	panic("pair: " + key + " is not in this pair")
}

func (p *Pair) setShares(owner address, n int64) {
	if n == 0 {
		p.shares.Remove(owner.String())
		return
	}
	p.shares.Set(owner.String(), n)
}

// pull moves amount of tok from `from` into the instance realm, spending the
// allowance `from` granted to the instance realm's address.
//
// Non-crossing on purpose: `_ int, rlm realm` is the only shape a pure
// package can declare, and it keeps rlm the instance's own live frame.
// RealmTeller binds the spender eagerly to rlm.Address(), which is therefore
// the instance, not this package (a pure package has no address at all).
func pull(_ int, rlm realm, tok *grc20.Token, from, to address, amount int64) {
	err := tok.RealmTeller(0, rlm).TransferFrom(0, rlm, from, to, amount)
	if err != nil {
		panic("pair: cannot take " + tok.GetSymbol() + ": " + err.Error())
	}
}

// push sends amount of tok from the instance realm to `to`.
func push(_ int, rlm realm, tok *grc20.Token, to address, amount int64) {
	err := tok.RealmTeller(0, rlm).Transfer(0, rlm, to, amount)
	if err != nil {
		panic("pair: cannot send " + tok.GetSymbol() + ": " + err.Error())
	}
}

// mulDiv returns floor(a*b/c) through a 128-bit intermediate, which plain
// int64 arithmetic cannot do: a*b is routinely wider than 63 bits here even
// when the quotient is small.
func mulDiv(a, b, c int64) int64 {
	if a < 0 || b < 0 {
		panic("pair: negative operand")
	}
	if c <= 0 {
		panic("pair: division by a non-positive value")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	// bits.Div64 panics for y <= hi; refusing here turns that into a named
	// abort and also covers every quotient that would not fit in 64 bits.
	if hi >= uint64(c) {
		panic("pair: quotient overflows int64")
	}
	q, _ := bits.Div64(hi, lo, uint64(c))
	if q > uint64(math.MaxInt64) {
		panic("pair: quotient overflows int64")
	}
	return int64(q)
}

// cmpProd compares a*b with c*d exactly, in 128 bits, and returns -1, 0 or 1.
func cmpProd(a, b, c, d int64) int {
	h1, l1 := bits.Mul64(uint64(a), uint64(b))
	h2, l2 := bits.Mul64(uint64(c), uint64(d))
	if h1 != h2 {
		if h1 < h2 {
			return -1
		}
		return 1
	}
	if l1 != l2 {
		if l1 < l2 {
			return -1
		}
		return 1
	}
	return 0
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func itoa(v int64) string { return strconv.FormatInt(v, 10) }

package pair

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// The pricing function, on its own, is the part worth pinning numerically: it
// is pure, it is where the 128-bit arithmetic lives, and every instance in the
// ecosystem runs this exact code.
func TestAmountOut(t *testing.T) {
	cases := []struct {
		name                    string
		in, resIn, resOut, want int64
	}{
		{"balanced pool, small trade", 1_000, 1_000_000, 1_000_000, 996},
		{"balanced pool, 1%", 10_000, 1_000_000, 1_000_000, 9_871},
		{"balanced pool, 10%", 100_000, 1_000_000, 1_000_000, 90_661},
		{"balanced pool, 50%", 500_000, 1_000_000, 1_000_000, 332_665},
		{"skewed pool", 100_000, 1_000_000, 4_000_000, 362_644},
		{"near drain", 1_000, 1, 1_000_000, 998_997},
		{"dust rounds to zero", 1, 1_000_000, 1_000_000, 0},
		{"reserves at the cap", MaxReserve / 2, MaxReserve / 2, MaxReserve, 4_604_758_097_518_382},
	}
	for _, tc := range cases {
		got := AmountOut(tc.in, tc.resIn, tc.resOut)
		uassert.Equal(t, tc.want, got, tc.name)
	}
}

// The fee is what stays behind: k must never decrease across a swap.
func TestConstantProductNeverRegresses(t *testing.T) {
	resIn, resOut := int64(1_000_000), int64(4_000_000)
	for _, in := range []int64{1, 1_000, 100_000, 999_999} {
		out := AmountOut(in, resIn, resOut)
		uassert.True(t, cmpProd(resIn+in, resOut-out, resIn, resOut) >= 0,
			"k must not regress")
	}
}

func TestAmountOutGuards(t *testing.T) {
	mustPanic(t, "pair: amountIn must be > 0", func() {
		AmountOut(0, 1_000, 1_000)
	})
	mustPanic(t, "pair: pair has an empty reserve", func() {
		AmountOut(1, 0, 1_000)
	})
	mustPanic(t, "pair: reserve above cap", func() {
		AmountOut(1, MaxReserve+1, 1_000)
	})
	mustPanic(t, "pair: reserve cap exceeded", func() {
		AmountOut(2, MaxReserve-1, 1_000)
	})
}

// mulDiv is the only place a 128-bit intermediate is required, and the only
// place bits.Div64 could panic. Both ends are asserted rather than argued.
func TestMulDiv(t *testing.T) {
	uassert.Equal(t, int64(2), mulDiv(4, 3, 6))
	uassert.Equal(t, int64(0), mulDiv(1, 1, 3), "floors")
	uassert.Equal(t, int64(4_611_686_018_427_387_903), mulDiv(9_223_372_036_854_775_807, 1, 2),
		"operands near MaxInt64 stay exact through the 128-bit path")

	mustPanic(t, "pair: division by a non-positive value", func() {
		mulDiv(1, 1, 0)
	})
	mustPanic(t, "pair: quotient overflows int64", func() {
		mulDiv(9_223_372_036_854_775_807, 9_223_372_036_854_775_807, 1)
	})
}

func TestCmpProd(t *testing.T) {
	uassert.Equal(t, 0, cmpProd(6, 7, 42, 1))
	uassert.Equal(t, -1, cmpProd(6, 6, 42, 1))
	uassert.Equal(t, 1, cmpProd(7, 7, 42, 1))
	// Both products exceed int64 and differ only in the low word.
	uassert.Equal(t, -1, cmpProd(4_000_000_000, 4_000_000_000, 4_000_000_000, 4_000_000_001))
}

// mustPanic is uassert.PanicsWithMessage without the realm argument: a pure
// package cannot produce a `cur` to hand it, since it can never declare a
// crossing function in the first place.
func mustPanic(t *testing.T, want string, f func()) {
	t.Helper()
	defer func() {
		r := recover()
		if r == nil {
			t.Errorf("expected panic %q, got none", want)
			return
		}
		got, ok := r.(string)
		if !ok {
			t.Errorf("expected a string panic %q, got %v", want, r)
			return
		}
		if got != want {
			t.Errorf("expected panic %q, got %q", want, got)
		}
	}()
	f()
}

// Package ninep is a Plan 9 shaped file abstraction for gno.
//
// It implements the SEMANTICS of 9P2000, not its wire format: there is no
// socket on a chain, the VM call is the transport. What it keeps is the part
// that made 9P useful, namely that every resource answers the same four
// questions (stat, walk, read, readdir), so a client written today can browse
// a file server deployed tomorrow.
//
// One interface, not two. 9P reads a directory with the same Tread it uses for
// a file, so splitting File from Dir would be less faithful, and a single
// interface means no type assertion across a realm boundary.
//
// Deliberate divergences from 9P2000, all of them forced:
//
//   - Data is a string, not []byte. Every consumer on this chain is text and
//     Render returns a string.
//   - Mtime is a block height, not a wall clock. It is the only clock that
//     every validating node agrees on.
//   - There is no open/clunk pair. Without a session there are no fids, so
//     Walk returns the file itself and nothing has to be released.
//   - File is READ-ONLY. A crossing method would mint the caller's realm frame
//     for the callee, which is a confused-deputy hazard (compare r/gov/dao's
//     Executor, and p/nt/grc20's deliberate refusal to make Teller crossing).
//     Mutation lives in Mutable, which is only safe on a tree your own realm
//     owns.
//
// See gno.land/p/nym-moultest123/x/plan9/ns for the namespace that binds these trees
// together, and gno.land/p/nym-moultest123/x/plan9/memfs for the reference server.
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This package is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package ninep

import (
	"errors"
	"path"
	"strconv"
	"strings"
)

// Qid type bits, as in 9P2000.
const (
	QTFILE   uint8 = 0x00 // a plain file
	QTTMP    uint8 = 0x04 // not archived
	QTAUTH   uint8 = 0x08 // authentication file
	QTMOUNT  uint8 = 0x10 // mounted channel
	QTEXCL   uint8 = 0x20 // exclusive use
	QTAPPEND uint8 = 0x40 // append only
	QTDIR    uint8 = 0x80 // a directory
)

// Perm holds the 9P mode word: the low nine bits are rwx for owner, group and
// other, the high bits are the DM* kind flags.
type Perm uint32

// Mode bits, as in 9P2000.
const (
	DMTMP    Perm = 0x04000000
	DMAUTH   Perm = 0x08000000
	DMMOUNT  Perm = 0x10000000
	DMEXCL   Perm = 0x20000000
	DMAPPEND Perm = 0x40000000
	DMDIR    Perm = 0x80000000

	PermMask Perm = 0777 // the rwxrwxrwx bits

	// Conventional defaults, matching what Plan 9's ramfs hands out.
	DirPerm  Perm = DMDIR | 0755
	FilePerm Perm = 0644
)

// IsDir reports whether the mode marks a directory.
func (p Perm) IsDir() bool { return p&DMDIR != 0 }

// String renders the mode the way ls -l does: a kind letter then nine rwx
// bits. The kind letter is 'd' for a directory, 'a' for append-only, 'l' for
// exclusive-use, '-' otherwise.
func (p Perm) String() string {
	var b strings.Builder
	switch {
	case p&DMDIR != 0:
		b.WriteByte('d')
	case p&DMAPPEND != 0:
		b.WriteByte('a')
	case p&DMEXCL != 0:
		b.WriteByte('l')
	default:
		b.WriteByte('-')
	}
	const rwx = "rwxrwxrwx"
	for i := 0; i < 9; i++ {
		if p&(1<<uint(8-i)) != 0 {
			b.WriteByte(rwx[i])
		} else {
			b.WriteByte('-')
		}
	}
	return b.String()
}

// Qid is the server's unique handle for a file. Path identifies the file
// within one server for its whole lifetime; Version increments on every write,
// so a client can tell "same file, changed" from "different file" without
// reading either.
type Qid struct {
	Type    uint8
	Version uint32
	Path    uint64
}

// IsDir reports whether the qid marks a directory.
func (q Qid) IsDir() bool { return q.Type&QTDIR != 0 }

// String renders the qid as Plan 9 does, "(path version type)", with the path
// in hex.
func (q Qid) String() string {
	kind := "f"
	if q.IsDir() {
		kind = "d"
	}
	return "(" + strconv.FormatUint(q.Path, 16) + " " +
		strconv.FormatUint(uint64(q.Version), 10) + " " + kind + ")"
}

// Stat is 9P's directory entry, minus the fields that only mean something on a
// wire (type, dev) or on a host clock (atime).
type Stat struct {
	Qid    Qid
	Mode   Perm
	Mtime  int64 // block height of the last write
	Length int64 // in bytes; zero for a directory, as in 9P
	Name   string
	Uid    string // owner; a bech32 address, or a well-known name
	Gid    string // group
	Muid   string // last writer
}

// IsDir reports whether the entry is a directory.
func (s Stat) IsDir() bool { return s.Mode.IsDir() }

// Line renders the entry the way ls -l does.
func (s Stat) Line() string {
	return s.Mode.String() + " " + pad(s.Uid, 12) + " " + pad(s.Gid, 8) + " " +
		lpad(strconv.FormatInt(s.Length, 10), 7) + " " + s.Name
}

// pad right-pads to n runes. ufmt has no width flags in gno, so padding is by
// hand everywhere in this suite.
func pad(s string, n int) string {
	for len(s) < n {
		s += " "
	}
	return s
}

func lpad(s string, n int) string {
	for len(s) < n {
		s = " " + s
	}
	return s
}

// File is a 9P file server's whole read surface. Every method must be free of
// side effects: a File is routinely reached across a realm boundary, where the
// running frame belongs to the CALLER, so mutating anything here would be both
// a VM error and a confused deputy.
type File interface {
	// Stat returns the entry for this file.
	Stat() Stat
	// Walk resolves exactly one path element. It returns ErrNotDir on a
	// plain file and ErrNotExist when the name is absent. It never sees
	// "." or "..": both are removed lexically before resolution starts.
	Walk(name string) (File, error)
	// Read returns at most count bytes starting at off. A negative count
	// means "to the end". It returns ErrIsDir on a directory.
	Read(off, count int64) (string, error)
	// ReadDir returns the directory's entries in a deterministic order. It
	// returns ErrNotDir on a plain file.
	ReadDir() ([]Stat, error)
}

// Mutable is the write half, kept out of File on purpose.
//
// It is NOT safe across a realm boundary: a non-crossing method runs in the
// caller's frame, so a foreign realm calling these would be trying to mutate
// objects it does not own. Only call Mutable on a tree your own realm created.
// The caller supplies now (a block height) rather than the tree reading the
// chain itself, so the same code is testable off chain.
type Mutable interface {
	File
	Create(name string, perm Perm, now int64) (File, error)
	Remove(name string) error
	Write(off int64, data string, now int64) (int64, error)
	Truncate(size int64, now int64) error
}

// Plan 9 error strings, kept lowercase and verbatim where they exist.
var (
	ErrNotExist = errors.New("file does not exist")
	ErrNotDir   = errors.New("not a directory")
	ErrIsDir    = errors.New("is a directory")
	ErrExist    = errors.New("file already exists")
	ErrPerm     = errors.New("permission denied")
	ErrNoCreate = errors.New("create prohibited")
	ErrReadOnly = errors.New("read-only file server")
	ErrBadName  = errors.New("bad character in file name")
	ErrNotEmpty = errors.New("directory not empty")
	ErrTooDeep  = errors.New("path too deep")
)

// MaxDepth bounds a walk. Resolution costs one cross-realm call per element
// per union member, so depth is capped rather than trusted.
const MaxDepth = 32

// ValidName reports whether name is usable as a single path element. Plan 9
// rejects the empty name, "." and "..", and any name containing a slash.
func ValidName(name string) bool {
	if name == "" || name == "." || name == ".." {
		return false
	}
	return !strings.Contains(name, "/")
}

// Clean returns p as a cleaned absolute path. "." and ".." are resolved
// lexically, before any server sees them, which is what makes ".." undo the
// name you typed rather than the directory you landed in (see "Lexical File
// Names in Plan 9").
func Clean(p string) string {
	if !strings.HasPrefix(p, "/") {
		p = "/" + p
	}
	return path.Clean(p)
}

// Abs resolves p against cwd, then cleans it.
func Abs(cwd, p string) string {
	if p == "" {
		return Clean(cwd)
	}
	if strings.HasPrefix(p, "/") {
		return Clean(p)
	}
	if cwd == "" {
		cwd = "/"
	}
	return Clean(cwd + "/" + p)
}

// Elems splits a cleaned absolute path into its elements. The root yields nil.
func Elems(p string) []string {
	p = Clean(p)
	if p == "/" {
		return nil
	}
	return strings.Split(p[1:], "/")
}

// Base returns the last element of p, or "/" for the root.
func Base(p string) string { return path.Base(Clean(p)) }

// Dir returns p's parent.
func Dir(p string) string { return path.Dir(Clean(p)) }

// Join appends name to dir.
func Join(dir, name string) string { return Clean(dir + "/" + name) }

// Walk resolves elems from f, one element at a time. It is the plain,
// namespace-free walk: no binds, no unions. Use ns.Ns for those.
func Walk(f File, elems []string) (File, error) {
	if len(elems) > MaxDepth {
		return nil, ErrTooDeep
	}
	for _, e := range elems {
		next, err := f.Walk(e)
		if err != nil {
			return nil, err
		}
		f = next
	}
	return f, nil
}

// ReadAll reads a whole file.
func ReadAll(f File) (string, error) { return f.Read(0, -1) }

// Slice applies 9P's read window to s: at most count bytes from off, with a
// negative count meaning "to the end". An offset past the end reads empty,
// which is what makes a read loop terminate rather than fail.
func Slice(s string, off, count int64) string {
	if off < 0 {
		off = 0
	}
	n := int64(len(s))
	if off >= n {
		return ""
	}
	end := n
	if count >= 0 && off+count < n {
		end = off + count
	}
	return s[off:end]
}

package ninep

import "testing"

func TestPermString(t *testing.T) {
	tests := []struct {
		name string
		perm Perm
		want string
	}{
		{"dir 0755", DMDIR | 0755, "drwxr-xr-x"},
		{"file 0644", 0644, "-rw-r--r--"},
		{"file 0600", 0600, "-rw-------"},
		{"file 0777", 0777, "-rwxrwxrwx"},
		{"file 0000", 0, "----------"},
		{"append only", DMAPPEND | 0644, "arw-r--r--"},
		{"exclusive", DMEXCL | 0600, "lrw-------"},
		{"dir default", DirPerm, "drwxr-xr-x"},
		{"file default", FilePerm, "-rw-r--r--"},
	}
	for _, tt := range tests {
		if got := tt.perm.String(); got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestPermIsDir(t *testing.T) {
	if !(DMDIR | 0755).IsDir() {
		t.Error("DMDIR|0755 should be a directory")
	}
	if Perm(0644).IsDir() {
		t.Error("0644 should not be a directory")
	}
}

func TestQidString(t *testing.T) {
	tests := []struct {
		name string
		qid  Qid
		want string
	}{
		{"root", Qid{Type: QTDIR, Version: 0, Path: 0}, "(0 0 d)"},
		{"file", Qid{Type: QTFILE, Version: 3, Path: 17}, "(11 3 f)"},
		{"big path", Qid{Type: QTFILE, Version: 1, Path: 255}, "(ff 1 f)"},
	}
	for _, tt := range tests {
		if got := tt.qid.String(); got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestStatLine(t *testing.T) {
	s := Stat{
		Qid:    Qid{Type: QTFILE, Path: 2, Version: 1},
		Mode:   0644,
		Length: 12,
		Name:   "greeting",
		Uid:    "glenda",
		Gid:    "sys",
	}
	want := "-rw-r--r-- glenda       sys           12 greeting"
	if got := s.Line(); got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestValidName(t *testing.T) {
	tests := []struct {
		name string
		want bool
	}{
		{"dev", true},
		{"a.b", true},
		{"with space", true},
		{"", false},
		{".", false},
		{"..", false},
		{"a/b", false},
		{"/", false},
	}
	for _, tt := range tests {
		if got := ValidName(tt.name); got != tt.want {
			t.Errorf("ValidName(%q): got %v, want %v", tt.name, got, tt.want)
		}
	}
}

func TestClean(t *testing.T) {
	tests := []struct {
		in   string
		want string
	}{
		{"", "/"},
		{"/", "/"},
		{"dev", "/dev"},
		{"/dev/", "/dev"},
		{"/dev//height", "/dev/height"},
		{"/dev/./height", "/dev/height"},
		{"/dev/../srv", "/srv"},
		{"/../..", "/"},
		{"/a/b/../../c", "/c"},
	}
	for _, tt := range tests {
		if got := Clean(tt.in); got != tt.want {
			t.Errorf("Clean(%q): got %q, want %q", tt.in, got, tt.want)
		}
	}
}

func TestAbs(t *testing.T) {
	tests := []struct {
		cwd  string
		in   string
		want string
	}{
		{"/", "dev", "/dev"},
		{"/usr/glenda", "bin", "/usr/glenda/bin"},
		{"/usr/glenda", "/dev", "/dev"},
		{"/usr/glenda", "..", "/usr"},
		{"/usr/glenda", "", "/usr/glenda"},
		{"", "dev", "/dev"},
	}
	for _, tt := range tests {
		if got := Abs(tt.cwd, tt.in); got != tt.want {
			t.Errorf("Abs(%q, %q): got %q, want %q", tt.cwd, tt.in, got, tt.want)
		}
	}
}

func TestElems(t *testing.T) {
	tests := []struct {
		in   string
		want []string
	}{
		{"/", nil},
		{"", nil},
		{"/dev", []string{"dev"}},
		{"/dev/height", []string{"dev", "height"}},
		{"/a/b/../c", []string{"a", "c"}},
	}
	for _, tt := range tests {
		got := Elems(tt.in)
		if len(got) != len(tt.want) {
			t.Errorf("Elems(%q): got %v, want %v", tt.in, got, tt.want)
			continue
		}
		for i := range got {
			if got[i] != tt.want[i] {
				t.Errorf("Elems(%q)[%d]: got %q, want %q", tt.in, i, got[i], tt.want[i])
			}
		}
	}
}

func TestBaseDirJoin(t *testing.T) {
	if got := Base("/dev/height"); got != "height" {
		t.Errorf("Base: got %q", got)
	}
	if got := Base("/"); got != "/" {
		t.Errorf("Base of root: got %q", got)
	}
	if got := Dir("/dev/height"); got != "/dev" {
		t.Errorf("Dir: got %q", got)
	}
	if got := Join("/dev", "height"); got != "/dev/height" {
		t.Errorf("Join: got %q", got)
	}
	if got := Join("/", "dev"); got != "/dev" {
		t.Errorf("Join at root: got %q", got)
	}
}

func TestSlice(t *testing.T) {
	const s = "hello world"
	tests := []struct {
		name  string
		off   int64
		count int64
		want  string
	}{
		{"whole", 0, -1, "hello world"},
		{"prefix", 0, 5, "hello"},
		{"middle", 6, 5, "world"},
		{"past end", 99, 5, ""},
		{"count past end", 6, 99, "world"},
		{"negative offset clamps", -4, 5, "hello"},
		{"zero count", 0, 0, ""},
	}
	for _, tt := range tests {
		if got := Slice(s, tt.off, tt.count); got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

// Package storagecost answers one question: is it worth paying gas to delete
// on-chain state?
//
// On gno.land every byte of realm state locks GNOT, and the lock is refunded
// to whoever signs the transaction that frees the byte. Deleting state is
// therefore paid work, and whether a given deletion pays depends on two prices
// that move independently: the storage price, a chain parameter, and the gas
// price of the day. A contract cannot know the second one, so it cannot decide
// on its own behalf whether to compact, reindex or reap. It can only publish
// the size of the prize and let a caller do the arithmetic.
//
// This package is that arithmetic. It is pure integer maths with no chain
// imports, so a realm can call it inside a Render and an off-chain bot can
// reuse the identical formula.
//
// The single fact worth remembering is the ratio. One byte freed refunds 100
// ugnot, and at the lowest gas price mainnet has actually accepted one ugnot
// buys 1000 gas. So a byte is worth 100,000 gas, and any deletion costing less
// than that per byte pays for itself.
//
// Demo realm: gno.land/r/nym-moultest123/x/reaper/v0.
package storagecost

import "gno.land/p/nt/ufmt/v0"

const (
	// DefaultStoragePrice is the ugnot locked per byte of realm state, the
	// default of the chain's vm:p:storage_price parameter. It is governance
	// settable, so read it from the chain rather than trusting this constant
	// when real money depends on the answer.
	DefaultStoragePrice int64 = 100

	// GasPerUgnotFloor is how much gas one ugnot buys at the lowest gas price
	// mainnet has been observed to accept, 0.001 ugnot per gas. It is a floor,
	// not a promise: the fee a node requires tracks gas_wanted, so asking for
	// more headroom raises the fee proportionally.
	GasPerUgnotFloor int64 = 1000

	// payloadOverheadNum/payloadOverheadDen approximate what a payload really
	// costs once the realm has wrapped it in an object. Measured at 1.85x: ten
	// 1,024-byte strings in a realm slice cost 18,984 bytes of state, 1,898
	// each. It is an estimate and nothing more. The authoritative number is
	// the chain's own, from the vm/qstorage query or a StorageDepositEvent.
	payloadOverheadNum int64 = 185
	payloadOverheadDen int64 = 100

	ugnotPerGNOT int64 = 1_000_000
)

// Refund is the deposit returned for freeing bytes at the given price per
// byte. Returns 0 for non-positive inputs rather than panicking, so a Render
// on a realm with no state still works.
func Refund(bytes, pricePerByte int64) int64 {
	if bytes <= 0 || pricePerByte <= 0 {
		return 0
	}
	return bytes * pricePerByte
}

// BreakEvenBytes is the fewest bytes whose refund covers a fee: the point
// where a cleanup stops costing money and starts making it. Below this many
// bytes the transaction is charity.
func BreakEvenBytes(feeUgnot, pricePerByte int64) int64 {
	if pricePerByte <= 0 {
		return 0
	}
	if feeUgnot <= 0 {
		return 0
	}
	// Round up: freeing exactly feeUgnot/pricePerByte bytes must cover the fee.
	return (feeUgnot + pricePerByte - 1) / pricePerByte
}

// GasFee is the fee a transaction asking for gasWanted must pay at a gas price
// of num/den ugnot per gas, rounded up.
//
// The fee tracks gas_wanted rather than gas_used, so unused headroom is paid
// for. Pass the ceiling you will actually put in the transaction, not what you
// expect to burn.
func GasFee(gasWanted, num, den int64) int64 {
	if gasWanted <= 0 || num <= 0 || den <= 0 {
		return 0
	}
	return (gasWanted*num + den - 1) / den
}

// FloorGasFee is GasFee at the lowest gas price mainnet has accepted.
func FloorGasFee(gasWanted int64) int64 {
	return GasFee(gasWanted, 1, GasPerUgnotFloor)
}

// EstimateBytes guesses the realm state a payload of this many bytes will
// occupy, applying the measured object overhead.
//
// It is for sizing a bounty in a Render, where being within a factor of two
// beats reporting the raw payload length. Never settle an accounting question
// with it.
func EstimateBytes(payloadBytes int64) int64 {
	if payloadBytes <= 0 {
		return 0
	}
	return payloadBytes * payloadOverheadNum / payloadOverheadDen
}

// Quote is a complete answer for one candidate cleanup.
type Quote struct {
	Bytes     int64 // bytes the cleanup would free
	Refund    int64 // ugnot returned for them
	Fee       int64 // ugnot the transaction will cost
	Net       int64 // Refund - Fee; negative means it costs more than it pays
	BreakEven int64 // bytes needed to cover Fee
}

// Worth reports whether the cleanup pays for itself.
func (q Quote) Worth() bool { return q.Net > 0 }

// String renders the quote as one line of markdown-safe text, for a Render.
func (q Quote) String() string {
	verdict := "not worth it yet"
	if q.Worth() {
		verdict = "worth " + FormatGNOT(q.Net)
	}
	return ufmt.Sprintf(
		"%d bytes, refunds %s against %s of gas, break-even %d bytes: %s",
		q.Bytes, FormatGNOT(q.Refund), FormatGNOT(q.Fee), q.BreakEven, verdict,
	)
}

// Evaluate prices one cleanup: freeing bytes in a transaction asking for
// gasWanted, at a storage price of pricePerByte and a gas price of num/den
// ugnot per gas.
func Evaluate(bytes, pricePerByte, gasWanted, num, den int64) Quote {
	fee := GasFee(gasWanted, num, den)
	refund := Refund(bytes, pricePerByte)
	return Quote{
		Bytes:     bytes,
		Refund:    refund,
		Fee:       fee,
		Net:       refund - fee,
		BreakEven: BreakEvenBytes(fee, pricePerByte),
	}
}

// EvaluateAtFloor is Evaluate at the default storage price and the floor gas
// price: the best case, and the one to quote when advertising a bounty.
func EvaluateAtFloor(bytes, gasWanted int64) Quote {
	return Evaluate(bytes, DefaultStoragePrice, gasWanted, 1, GasPerUgnotFloor)
}

// FormatGNOT renders ugnot as GNOT with six decimal places and trailing zeros
// trimmed, because a bounty shown in ugnot is unreadable and gno has no
// floats.
func FormatGNOT(amount int64) string {
	neg := amount < 0
	if neg {
		amount = -amount
	}
	whole := amount / ugnotPerGNOT
	frac := amount % ugnotPerGNOT

	out := ufmt.Sprintf("%d", whole)
	if frac != 0 {
		// Left-pad the fraction to six digits, then trim trailing zeros.
		digits := ufmt.Sprintf("%d", frac)
		for len(digits) < 6 {
			digits = "0" + digits
		}
		for len(digits) > 1 && digits[len(digits)-1] == '0' {
			digits = digits[:len(digits)-1]
		}
		out += "." + digits
	}
	if neg {
		out = "-" + out
	}
	return out + " GNOT"
}

package storagecost

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestRefund(t *testing.T) {
	tests := []struct {
		name  string
		bytes int64
		price int64
		want  int64
	}{
		{"one byte at the default price", 1, DefaultStoragePrice, 100},
		{"the measured reap", 17835, DefaultStoragePrice, 1783500},
		{"the measured compact", 830, DefaultStoragePrice, 83000},
		{"zero bytes", 0, DefaultStoragePrice, 0},
		{"negative bytes are not a credit", -100, DefaultStoragePrice, 0},
		{"a free chain refunds nothing", 1000, 0, 0},
		{"a ten-fold price rise", 1000, 1000, 1000000},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			uassert.Equal(t, tt.want, Refund(tt.bytes, tt.price))
		})
	}
}

func TestBreakEvenBytes(t *testing.T) {
	tests := []struct {
		name string
		fee  int64
		want int64
	}{
		// A 2.6M gas call at the floor costs 2,600 ugnot, so 26 bytes.
		{"the canonical 2.6M gas call", 2600, 26},
		{"rounds up, never down", 101, 2},
		{"exactly one byte", 100, 1},
		{"a fee below one byte still needs a byte", 1, 1},
		{"no fee, no threshold", 0, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := BreakEvenBytes(tt.fee, DefaultStoragePrice)
			uassert.Equal(t, tt.want, got)
			// The definition: this many bytes covers the fee, one fewer does not.
			if tt.want > 0 {
				uassert.True(t, Refund(got, DefaultStoragePrice) >= tt.fee)
				uassert.False(t, Refund(got-1, DefaultStoragePrice) >= tt.fee)
			}
		})
	}
	uassert.Equal(t, int64(0), BreakEvenBytes(1000, 0))
}

func TestGasFee(t *testing.T) {
	// The floor mainnet has actually accepted: 1 ugnot per 1000 gas.
	uassert.Equal(t, int64(5000), FloorGasFee(5_000_000))
	uassert.Equal(t, int64(2500), FloorGasFee(2_500_000))
	// Rounds up, so a fee is never short.
	uassert.Equal(t, int64(1), FloorGasFee(1))
	uassert.Equal(t, int64(0), FloorGasFee(0))
	// The harness price used in the measurements, 1.2 ugnot per gas.
	uassert.Equal(t, int64(6_000_000), GasFee(5_000_000, 12, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 0, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 1, 0))
}

func TestEvaluateReproducesTheMeasuredReap(t *testing.T) {
	// The measured run: 17,835 bytes freed by a call that used 4,120,876 gas,
	// so gas_wanted 5,000,000 at the floor. Net +1,778,500 ugnot.
	q := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t, int64(1783500), q.Refund)
	uassert.Equal(t, int64(5000), q.Fee)
	uassert.Equal(t, int64(1778500), q.Net)
	uassert.Equal(t, int64(50), q.BreakEven)
	uassert.True(t, q.Worth())
}

func TestEvaluateReproducesTheMeasuredCompact(t *testing.T) {
	q := EvaluateAtFloor(830, 2_500_000)
	uassert.Equal(t, int64(83000), q.Refund)
	uassert.Equal(t, int64(2500), q.Fee)
	uassert.Equal(t, int64(80500), q.Net)
	uassert.True(t, q.Worth())
}

func TestEvaluateAtTheHarnessPriceIsALoss(t *testing.T) {
	// The same reap priced at 1.2 ugnot/gas, 1200x the floor, loses money.
	// This is why the gas price cannot be baked into a contract.
	q := Evaluate(17835, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t, int64(6_000_000), q.Fee)
	uassert.False(t, q.Worth())
	uassert.True(t, q.Net < 0)
}

func TestQuoteString(t *testing.T) {
	worth := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t,
		"17835 bytes, refunds 1.7835 GNOT against 0.005 GNOT of gas, break-even 50 bytes: worth 1.7785 GNOT",
		worth.String())

	loss := Evaluate(10, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t,
		"10 bytes, refunds 0.001 GNOT against 6 GNOT of gas, break-even 60000 bytes: not worth it yet",
		loss.String())
}

func TestFormatGNOT(t *testing.T) {
	tests := []struct {
		amount int64
		want   string
	}{
		{0, "0 GNOT"},
		{1, "0.000001 GNOT"},
		{100, "0.0001 GNOT"},
		{1_000_000, "1 GNOT"},
		{1_500_000, "1.5 GNOT"},
		{1_783_500, "1.7835 GNOT"},
		{978_743_800, "978.7438 GNOT"},
		{-2_100, "-0.0021 GNOT"},
		{1_000_001, "1.000001 GNOT"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, FormatGNOT(tt.amount))
	}
}

func TestEstimateBytes(t *testing.T) {
	// Measured: a 1,024-byte payload occupied 1,898 bytes of realm state.
	uassert.Equal(t, int64(1894), EstimateBytes(1024))
	uassert.Equal(t, int64(0), EstimateBytes(0))
	uassert.Equal(t, int64(0), EstimateBytes(-5))
	// Monotonic, which is all a bounty estimate really needs.
	uassert.True(t, EstimateBytes(2048) > EstimateBytes(1024))
}

package vmkit

import "errors"

// ErrTruncated is returned by every Reader method that runs past the end of
// the buffer. A snapshot is consensus state, so a short read is always a hard
// error and never a zero value.
var ErrTruncated = errors.New("vmkit: truncated snapshot")

// ErrBadSnapshot is returned when a snapshot is well-formed but not for this
// machine: wrong magic, wrong version, or a field outside its legal range.
var ErrBadSnapshot = errors.New("vmkit: snapshot is not for this machine")

// Writer builds a snapshot. Every integer is fixed-width big-endian and every
// byte slice is length-prefixed, so the encoding is canonical: the same
// machine state always produces the same bytes, on every node.
//
// Machines are not required to use it, but a machine that invents its own
// layout owes the zoo an explanation, because the cross-VM snapshot cost
// comparison only means something when the encodings match.
type Writer struct {
	buf []byte
}

// NewWriter returns a Writer with room for n bytes reserved up front.
func NewWriter(n int) *Writer {
	if n < 0 {
		n = 0
	}
	return &Writer{buf: make([]byte, 0, n)}
}

// Byte appends one byte.
func (w *Writer) Byte(b byte) { w.buf = append(w.buf, b) }

// Uint32 appends a 4-byte big-endian value.
func (w *Writer) Uint32(v uint32) {
	w.buf = append(w.buf, byte(v>>24), byte(v>>16), byte(v>>8), byte(v))
}

// Uint64 appends an 8-byte big-endian value.
func (w *Writer) Uint64(v uint64) {
	w.buf = append(w.buf,
		byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32),
		byte(v>>24), byte(v>>16), byte(v>>8), byte(v))
}

// Int appends a signed value, zig-zag encoded into a Uint64 so that small
// negative numbers do not cost eight 0xff bytes.
func (w *Writer) Int(v int64) {
	u := uint64(v) << 1
	if v < 0 {
		u = ^u
	}
	w.Uint64(u)
}

// Bytes appends a length-prefixed byte slice.
func (w *Writer) Bytes(p []byte) {
	w.Uint32(uint32(len(p)))
	w.buf = append(w.buf, p...)
}

// String appends a length-prefixed string.
func (w *Writer) String(s string) { w.Bytes([]byte(s)) }

// Out returns the encoded bytes.
func (w *Writer) Out() []byte { return w.buf }

// Reader consumes a snapshot written by [Writer].
//
// It latches the first error it hits: a caller may decode a whole struct and
// check [Reader.Err] once at the end, instead of after every field. Every
// method returns a zero value once the Reader is in error.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader over b.
func NewReader(b []byte) *Reader { return &Reader{buf: b} }

// Err returns the first error hit, or nil.
func (r *Reader) Err() error { return r.err }

// Remaining reports how many bytes are left unread.
func (r *Reader) Remaining() int {
	if r.pos > len(r.buf) {
		return 0
	}
	return len(r.buf) - r.pos
}

// Fail latches err, so a machine can reject a field its own rules forbid and
// have it surface through [Reader.Err] like any decoding failure.
func (r *Reader) Fail(err error) {
	if r.err == nil {
		r.err = err
	}
}

func (r *Reader) take(n int) []byte {
	if r.err != nil {
		return nil
	}
	if n < 0 || r.pos+n > len(r.buf) {
		r.err = ErrTruncated
		return nil
	}
	out := r.buf[r.pos : r.pos+n]
	r.pos += n
	return out
}

// Byte reads one byte.
func (r *Reader) Byte() byte {
	p := r.take(1)
	if p == nil {
		return 0
	}
	return p[0]
}

// Uint32 reads a 4-byte big-endian value.
func (r *Reader) Uint32() uint32 {
	p := r.take(4)
	if p == nil {
		return 0
	}
	return uint32(p[0])<<24 | uint32(p[1])<<16 | uint32(p[2])<<8 | uint32(p[3])
}

// Uint64 reads an 8-byte big-endian value.
func (r *Reader) Uint64() uint64 {
	p := r.take(8)
	if p == nil {
		return 0
	}
	return uint64(p[0])<<56 | uint64(p[1])<<48 | uint64(p[2])<<40 | uint64(p[3])<<32 |
		uint64(p[4])<<24 | uint64(p[5])<<16 | uint64(p[6])<<8 | uint64(p[7])
}

// Int reads a zig-zag encoded signed value written by [Writer.Int].
func (r *Reader) Int() int64 {
	u := r.Uint64()
	v := int64(u >> 1)
	if u&1 != 0 {
		v = ^v
	}
	return v
}

// Bytes reads a length-prefixed byte slice. The result is a copy, so a
// machine can keep it without aliasing the snapshot it was handed.
func (r *Reader) Bytes() []byte {
	n := int(r.Uint32())
	p := r.take(n)
	if p == nil {
		return nil
	}
	out := make([]byte, n)
	copy(out, p)
	return out
}

// String reads a length-prefixed string.
func (r *Reader) String() string {
	p := r.take(int(r.Uint32()))
	if p == nil {
		return ""
	}
	return string(p)
}

package vmkit

// Unmetered is the fuel value that disables the budget: a [Meter] built with
// it never reports exhaustion. It exists so a benchmark can measure the
// dispatch loop without the meter in it, and so a trusted caller can run a
// program to completion in one slice. Gas remains the real backstop.
const Unmetered int64 = -1

// Meter is a fuel budget being spent. It allocates nothing after
// construction, because it sits in the hot path of every guest instruction.
type Meter struct {
	budget int64 // Unmetered, or the number of units this slice may spend
	used   int64
}

// NewMeter returns a meter good for `budget` units, or an unmetered one when
// budget is [Unmetered]. A budget of zero is a meter with nothing to spend,
// which is a legitimate way to ask "is this instance still runnable".
func NewMeter(budget int64) *Meter {
	if budget < 0 {
		budget = Unmetered
	}
	return &Meter{budget: budget}
}

// Charge spends n units and reports whether they were available. On false
// nothing is spent, so the caller can stop before executing the instruction
// it could not pay for. That ordering is what makes a resumed machine
// re-execute exactly the instruction it stopped at, and no other.
func (m *Meter) Charge(n int64) bool {
	if m.budget == Unmetered {
		m.used += n
		return true
	}
	if m.used+n > m.budget {
		return false
	}
	m.used += n
	return true
}

// Used reports how much fuel has been spent.
func (m *Meter) Used() int64 { return m.used }

// Remaining reports what is left, or [Unmetered].
func (m *Meter) Remaining() int64 {
	if m.budget == Unmetered {
		return Unmetered
	}
	return m.budget - m.used
}

// Exhausted reports whether the next single unit would fail.
func (m *Meter) Exhausted() bool { return !m.affordable(1) }

func (m *Meter) affordable(n int64) bool {
	return m.budget == Unmetered || m.used+n <= m.budget
}

package vmkit

import "errors"

// ErrNotGranted is returned by a [Host] for a capability the instance was
// never given. A guest that ignores the error and keeps going is a guest bug;
// a machine should turn it into a [Trapped] status.
var ErrNotGranted = errors.New("vmkit: capability not granted")

// Host is everything a guest program can reach outside its own memory.
//
// It is deliberately small, and deliberately handed in rather than looked up:
// a guest has exactly the authority its [Host] carries. Gno realm code has
// ambient authority through the realm frame, so the guest is where the
// capability-secure version can actually be tried.
//
// Every method must be deterministic across replays of the same block. Now
// and Height come from the chain, never from a wall clock.
type Host interface {
	// Caller is the address that called the realm running this guest.
	Caller() address
	// Origin is the address that signed the transaction.
	Origin() address
	// Now is block time in Unix seconds, never wall time.
	Now() int64
	// Height is the block height.
	Height() int64

	// Get reads from storage scoped to this instance. A miss is nil.
	Get(key []byte) []byte
	// Set writes to storage scoped to this instance.
	Set(key, val []byte)

	// Input is the immutable call input for this slice of execution: the
	// guest's calldata, argv, or stdin depending on the machine. A machine
	// tracks its own read cursor, in its snapshot, so that resuming reads
	// the byte it had not read yet.
	Input() []byte
	// Output appends to the guest's output buffer.
	Output(p []byte)

	// Emit writes a chain event. kv is a flat list of alternating keys and
	// values; an odd trailing element is dropped.
	Emit(typ string, kv ...string)
	// Send transfers amount ugnot to `to`, and returns [ErrNotGranted]
	// unless the deploying realm funded this instance with a budget.
	Send(to address, amount int64) error
	// Log records a diagnostic line. Never consensus-relevant.
	Log(msg string)
}

package vmkit

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// ErrNoInstance is returned when an id names nothing.
var ErrNoInstance = errors.New("vmkit: no such instance")

// ErrBudgetExhausted is returned when an instance has already spent its total
// fuel budget, so there is nothing left to step.
var ErrBudgetExhausted = errors.New("vmkit: instance fuel budget exhausted")

// Instance is one guest program as a realm stores it: the code, the machine
// state between slices, and the accounting that survives the transaction.
//
// It holds a snapshot rather than a [Machine], on purpose. A realm keeps
// bytes; the machine is rebuilt for the slice that needs it and thrown away
// after. That is what makes the storage cost of a paused program measurable,
// which is the whole kill criterion for continuations: if resuming costs more
// than re-running, continuations are theater.
type Instance struct {
	ID    string
	Owner address
	VM    string // which guest machine the Program is for

	Program  []byte
	Snapshot []byte

	Status Status
	Trap   string

	// FuelUsed is the total across every slice run so far.
	FuelUsed int64
	// FuelBudget caps FuelUsed across the instance's whole life, or is
	// [Unmetered] for no cap.
	FuelBudget int64

	// Slices counts how many transactions have stepped this instance.
	Slices int64

	Output []byte
}

// NewInstance returns an instance ready for its first slice.
func NewInstance(id string, owner address, vm string, program []byte, budget int64) *Instance {
	if budget < 0 {
		budget = Unmetered
	}
	prog := make([]byte, len(program))
	copy(prog, program)
	return &Instance{
		ID:         id,
		Owner:      owner,
		VM:         vm,
		Program:    prog,
		Status:     Running,
		FuelBudget: budget,
	}
}

// Remaining reports the fuel left in the instance's total budget, or
// [Unmetered].
func (i *Instance) Remaining() int64 {
	if i.FuelBudget == Unmetered {
		return Unmetered
	}
	left := i.FuelBudget - i.FuelUsed
	if left < 0 {
		return 0
	}
	return left
}

// Slice returns how much fuel the next call to [Instance.Run] may spend when
// the caller asks for `want`: `want` clamped to what the budget still allows.
func (i *Instance) Slice(want int64) int64 {
	left := i.Remaining()
	if left == Unmetered {
		return want
	}
	if want == Unmetered || want > left {
		return left
	}
	return want
}

// Run steps m for one slice of at most `fuel` units and folds the result back
// into the instance: the new snapshot, the status, the fuel spent, and
// anything the guest wrote to h.
//
// m must be a fresh machine loaded from i.Program; Run restores i.Snapshot
// into it when there is one, so the caller never has to remember the order.
// The instance is left untouched when Restore fails, which means a snapshot
// that cannot be decoded costs the caller gas but never corrupts the stored
// program.
func (i *Instance) Run(m Machine, h Host, fuel int64) error {
	if i.Status.Done() && i.Status != Running {
		return ErrBudgetExhausted
	}
	if len(i.Snapshot) > 0 {
		if err := m.Restore(i.Snapshot); err != nil {
			return err
		}
	}
	slice := i.Slice(fuel)
	if slice == 0 {
		i.Status = OutOfFuel
		return ErrBudgetExhausted
	}

	used, status := m.Step(h, slice)

	i.FuelUsed += used
	i.Slices++
	i.Snapshot = m.Snapshot()
	i.Status = status
	i.Trap = TrapReason(m)
	if status == Running && i.Remaining() == 0 {
		i.Status = OutOfFuel
	}
	return nil
}

// Store is the avl-backed set of instances a realm owns, keyed by id.
type Store struct {
	tree *avl.Tree
}

// NewStore returns an empty store.
func NewStore() *Store { return &Store{tree: avl.NewTree()} }

// Set writes an instance, replacing any instance with the same id.
func (s *Store) Set(i *Instance) {
	if i == nil {
		return
	}
	s.tree.Set(i.ID, i)
}

// Get returns the instance with this id, or nil.
func (s *Store) Get(id string) *Instance {
	v := s.tree.Get(id)
	if v == nil {
		return nil
	}
	inst, ok := v.(*Instance)
	if !ok {
		return nil
	}
	return inst
}

// Remove deletes an instance and reports whether it existed.
func (s *Store) Remove(id string) bool {
	_, removed := s.tree.Remove(id)
	return removed
}

// Size returns how many instances are stored.
func (s *Store) Size() int { return s.tree.Size() }

// Iterate walks every instance in key order, stopping early when fn returns
// true.
func (s *Store) Iterate(fn func(*Instance) bool) {
	s.tree.Iterate("", "", func(_ string, v any) bool {
		inst, ok := v.(*Instance)
		if !ok {
			return false
		}
		return fn(inst)
	})
}

// ReverseIterate walks every instance in descending key order, which is how a
// realm renders newest-first when ids are zero-padded and ascending.
func (s *Store) ReverseIterate(fn func(*Instance) bool) {
	s.tree.ReverseIterate("", "", func(_ string, v any) bool {
		inst, ok := v.(*Instance)
		if !ok {
			return false
		}
		return fn(inst)
	})
}

// Package vmkit is the host ABI shared by every guest virtual machine that
// runs inside a gno realm: a stepping contract with an explicit fuel budget,
// a capability-scoped [Host], and a snapshot format that lets a guest program
// outlive the transaction that started it.
//
// A guest VM implements [Machine]. Everything else in this package is the
// machinery a VM should not have to write twice: the [Meter], the [Codec] the
// snapshots are built from, an in-memory [TestHost], and the avl-backed
// [Store] a realm keeps its instances in.
//
// The three things the ABI exists to fix:
//
//   - Fuel is the interface, not the backstop. Running out of fuel yields
//     [OutOfFuel] plus a machine that can be snapshotted, never a panic. Gas
//     still bounds the transaction, but a guest that stops is a normal outcome.
//   - Continuations. Snapshot and Restore mean a program runs across blocks.
//     The realm stores the bytes, and the next caller pays for the next slice.
//     Gno realm code itself cannot pause; a guest can.
//   - Capabilities, not ambient authority. A guest gets exactly the [Host] it
//     was handed. No Send without a grant, no storage outside its own scope.
//
// Live demo: [r/moul/x/vm/bfdemo](/r/nym-moultest123/x/vm/bfdemo/v0), running the
// [p/moul/x/vm/bf](/p/nym-moultest123/x/vm/bf/v0) guest.
package vmkit

// Status is the outcome of a call to [Machine.Step].
type Status int

const (
	// Running means the machine stopped because it ran out of the fuel
	// handed to this slice, but the program has not finished. It is
	// resumable: snapshot it, and step it again later.
	Running Status = iota

	// Halted means the program reached its end. Terminal.
	Halted

	// Trapped means the guest did something the machine refuses to do:
	// an invalid instruction, an out-of-range access, a capability it was
	// not granted. Terminal.
	Trapped

	// OutOfFuel means the instance exhausted its total budget, not just the
	// fuel for this slice. Terminal unless the owner raises the budget.
	OutOfFuel
)

// String renders the status as the lowercase word used in realm output.
func (s Status) String() string {
	switch s {
	case Running:
		return "running"
	case Halted:
		return "halted"
	case Trapped:
		return "trapped"
	case OutOfFuel:
		return "out of fuel"
	}
	return "unknown"
}

// Done reports whether the status is terminal, i.e. stepping again is
// pointless without operator intervention.
func (s Status) Done() bool { return s != Running }

// Machine is one guest virtual machine, mid-execution.
//
// Step runs until the program halts, traps, or burns `fuel` units, whichever
// comes first, and reports how much fuel it actually used. A Machine must
// charge at least one unit per guest instruction so that a fuel budget is a
// real bound on work; beyond that the unit is the VM's own business, and
// [r/moul/x/vm/bfdemo](/r/nym-moultest123/x/vm/bfdemo/v0) compares them by measurement
// rather than by trusting the number.
//
// Snapshot must round-trip through Restore: a machine stepped to exhaustion,
// snapshotted, restored and stepped again must produce exactly what the same
// machine stepped in one go would have. That property is what makes a guest
// program a contract instead of a function call.
type Machine interface {
	Step(h Host, fuel int64) (used int64, status Status)
	Snapshot() []byte
	Restore(b []byte) error
}

// Trapper is an optional refinement of [Machine]: a machine that can explain
// why it trapped. Kept out of [Machine] so the core ABI stays three methods.
type Trapper interface {
	// Trap returns the reason for a [Trapped] status, or "" when the
	// machine has not trapped.
	Trap() string
}

// TrapReason returns m's trap reason when m implements [Trapper], else "".
func TrapReason(m Machine) string {
	if t, ok := m.(Trapper); ok {
		return t.Trap()
	}
	return ""
}

package vmkit

import "gno.land/p/nt/avl/v0"

// TestHost is a deterministic in-memory [Host] for unit tests and for
// measuring a machine without a chain under it.
//
// Nothing here reads the chain, so a test that uses it produces the same
// numbers on every host. Storage is an avl tree rather than a map because gno
// map iteration order is unspecified, and [TestHost.Keys] has to be stable for
// a test to assert on it.
//
// Send is denied unless [TestHost.Grant] funded a budget, which is how the
// capability rule gets tested: a guest that tries to send without a grant must
// come back [Trapped], not silently succeed.
type TestHost struct {
	caller address
	origin address
	now    int64
	height int64

	store *avl.Tree // hex key -> []byte

	in     []byte
	out    []byte
	events []string
	logs   []string

	sendBudget int64
	sends      []Transfer
}

// Transfer records one successful [TestHost.Send].
type Transfer struct {
	To     address
	Amount int64
}

// NewTestHost returns a host with no capabilities granted, height 1, time 0,
// and empty input.
func NewTestHost() *TestHost {
	return &TestHost{
		height: 1,
		store:  avl.NewTree(),
	}
}

// WithCaller sets the address the guest sees as its caller and origin.
func (h *TestHost) WithCaller(a address) *TestHost {
	h.caller, h.origin = a, a
	return h
}

// WithOrigin overrides the origin separately from the caller.
func (h *TestHost) WithOrigin(a address) *TestHost { h.origin = a; return h }

// WithTime sets the block time in Unix seconds.
func (h *TestHost) WithTime(t int64) *TestHost { h.now = t; return h }

// WithHeight sets the block height.
func (h *TestHost) WithHeight(n int64) *TestHost { h.height = n; return h }

// WithInput sets the guest's call input.
func (h *TestHost) WithInput(p []byte) *TestHost {
	h.in = make([]byte, len(p))
	copy(h.in, p)
	return h
}

// Grant funds the send capability with a budget in ugnot. Without it, Send
// returns [ErrNotGranted].
func (h *TestHost) Grant(budget int64) *TestHost { h.sendBudget = budget; return h }

func (h *TestHost) Caller() address { return h.caller }
func (h *TestHost) Origin() address { return h.origin }
func (h *TestHost) Now() int64      { return h.now }
func (h *TestHost) Height() int64   { return h.height }
func (h *TestHost) Input() []byte   { return h.in }

func (h *TestHost) Get(key []byte) []byte {
	v := h.store.Get(hexKey(key))
	if v == nil {
		return nil
	}
	stored := v.([]byte)
	out := make([]byte, len(stored))
	copy(out, stored)
	return out
}

func (h *TestHost) Set(key, val []byte) {
	cp := make([]byte, len(val))
	copy(cp, val)
	h.store.Set(hexKey(key), cp)
}

func (h *TestHost) Output(p []byte) { h.out = append(h.out, p...) }

func (h *TestHost) Emit(typ string, kv ...string) {
	line := typ
	for i := 0; i+1 < len(kv); i += 2 {
		line += " " + kv[i] + "=" + kv[i+1]
	}
	h.events = append(h.events, line)
}

func (h *TestHost) Send(to address, amount int64) error {
	if amount <= 0 || amount > h.sendBudget {
		return ErrNotGranted
	}
	h.sendBudget -= amount
	h.sends = append(h.sends, Transfer{To: to, Amount: amount})
	return nil
}

func (h *TestHost) Log(msg string) { h.logs = append(h.logs, msg) }

// Out returns everything the guest has written, as bytes.
func (h *TestHost) Out() []byte { return h.out }

// OutString returns everything the guest has written, as a string.
func (h *TestHost) OutString() string { return string(h.out) }

// ResetOut discards the output buffer, so one host can measure several runs.
func (h *TestHost) ResetOut() { h.out = nil }

// Events returns the rendered events, in emission order.
func (h *TestHost) Events() []string { return h.events }

// Logs returns the diagnostic lines, in emission order.
func (h *TestHost) Logs() []string { return h.logs }

// Sends returns the transfers that succeeded, in order.
func (h *TestHost) Sends() []Transfer { return h.sends }

// Keys returns every storage key the guest wrote, hex-encoded, in sorted
// order.
func (h *TestHost) Keys() []string {
	out := []string{}
	h.store.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

const hexDigits = "0123456789abcdef"

// hexKey encodes a raw key as hex so that arbitrary bytes, including a zero
// byte, survive being used as an avl key.
func hexKey(key []byte) string {
	out := make([]byte, 0, len(key)*2)
	for _, c := range key {
		out = append(out, hexDigits[c>>4], hexDigits[c&0x0f])
	}
	return string(out)
}

package vmkit

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// counter is a toy [Machine] used to test the kit itself without dragging in
// a real guest VM: it writes one byte per step and halts after `total` of
// them. Anything that works here is a property of the ABI, not of brainfuck.
type counter struct {
	total int64
	done  int64
	trap  string
}

func (c *counter) Step(h Host, fuel int64) (int64, Status) {
	m := NewMeter(fuel)
	var used int64
	for c.done < c.total {
		if !m.Charge(1) {
			return used, Running
		}
		used++
		c.done++
		h.Output([]byte{byte('a' + (c.done-1)%26)})
	}
	return used, Halted
}

func (c *counter) Snapshot() []byte {
	w := NewWriter(24)
	w.Int(c.total)
	w.Int(c.done)
	w.String(c.trap)
	return w.Out()
}

func (c *counter) Restore(b []byte) error {
	r := NewReader(b)
	total := r.Int()
	done := r.Int()
	trap := r.String()
	if err := r.Err(); err != nil {
		return err
	}
	c.total, c.done, c.trap = total, done, trap
	return nil
}

func (c *counter) Trap() string { return c.trap }

func TestStatusString(t *testing.T) {
	cases := []struct {
		s    Status
		want string
		done bool
	}{
		{Running, "running", false},
		{Halted, "halted", true},
		{Trapped, "trapped", true},
		{OutOfFuel, "out of fuel", true},
		{Status(99), "unknown", true},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, tc.s.String())
		uassert.Equal(t, tc.done, tc.s.Done())
	}
}

func TestMeterCharge(t *testing.T) {
	m := NewMeter(10)
	uassert.True(t, m.Charge(4))
	uassert.Equal(t, int64(4), m.Used())
	uassert.Equal(t, int64(6), m.Remaining())

	// A charge that does not fit spends nothing, so the caller can stop
	// before the instruction it cannot pay for.
	uassert.False(t, m.Charge(7))
	uassert.Equal(t, int64(4), m.Used())

	uassert.True(t, m.Charge(6))
	uassert.True(t, m.Exhausted())
	uassert.False(t, m.Charge(1))
}

func TestMeterUnmetered(t *testing.T) {
	m := NewMeter(Unmetered)
	uassert.True(t, m.Charge(1 << 40))
	uassert.False(t, m.Exhausted())
	uassert.Equal(t, Unmetered, m.Remaining())
}

func TestMeterZeroBudget(t *testing.T) {
	m := NewMeter(0)
	uassert.True(t, m.Exhausted())
	uassert.False(t, m.Charge(1))
	uassert.Equal(t, int64(0), m.Used())
}

func TestCodecRoundTrip(t *testing.T) {
	w := NewWriter(0)
	w.Byte(0xab)
	w.Uint32(0xdeadbeef)
	w.Uint64(0x0102030405060708)
	w.Int(-1234567)
	w.Int(0)
	w.Int(1234567)
	w.Bytes([]byte{0, 1, 2, 255})
	w.String("gno.land")

	r := NewReader(w.Out())
	uassert.Equal(t, uint64(0xab), uint64(r.Byte()))
	uassert.Equal(t, uint64(0xdeadbeef), uint64(r.Uint32()))
	uassert.Equal(t, uint64(0x0102030405060708), r.Uint64())
	uassert.Equal(t, int64(-1234567), r.Int())
	uassert.Equal(t, int64(0), r.Int())
	uassert.Equal(t, int64(1234567), r.Int())
	uassert.Equal(t, 4, len(r.Bytes()))
	uassert.Equal(t, "gno.land", r.String())
	uassert.NoError(t, r.Err())
	uassert.Equal(t, 0, r.Remaining())
}

func TestCodecIsCanonical(t *testing.T) {
	// The same state must always produce the same bytes: a snapshot is
	// consensus state, so two nodes encoding it differently is a fork.
	build := func() []byte {
		w := NewWriter(0)
		w.Int(-7)
		w.String("x")
		w.Uint32(9)
		return w.Out()
	}
	uassert.Equal(t, string(build()), string(build()))
}

func TestCodecTruncated(t *testing.T) {
	r := NewReader([]byte{1, 2})
	r.Uint64()
	uassert.ErrorIs(t, r.Err(), ErrTruncated)
	// Once latched, every later read is a zero value and the error stands.
	uassert.Equal(t, "", r.String())
	uassert.ErrorIs(t, r.Err(), ErrTruncated)
}

func TestCodecBytesAreCopied(t *testing.T) {
	w := NewWriter(0)
	w.Bytes([]byte{1, 2, 3})
	buf := w.Out()
	r := NewReader(buf)
	got := r.Bytes()
	buf[len(buf)-1] = 99 // mutate the snapshot under the reader
	uassert.Equal(t, 3, len(got))
	uassert.Equal(t, uint64(3), uint64(got[2]))
}

func TestTestHostStorage(t *testing.T) {
	h := NewTestHost()
	uassert.Equal(t, 0, len(h.Get([]byte("missing"))))

	h.Set([]byte{0, 1}, []byte("zero-prefixed"))
	h.Set([]byte("k"), []byte("v"))
	uassert.Equal(t, "zero-prefixed", string(h.Get([]byte{0, 1})))
	uassert.Equal(t, "v", string(h.Get([]byte("k"))))

	// Keys are hex so a zero byte survives, and sorted so a test can pin
	// them.
	keys := h.Keys()
	uassert.Equal(t, 2, len(keys))
	uassert.Equal(t, "0001", keys[0])
	uassert.Equal(t, "6b", keys[1])
}

func TestTestHostStorageIsCopied(t *testing.T) {
	h := NewTestHost()
	val := []byte("abc")
	h.Set([]byte("k"), val)
	val[0] = 'z'
	uassert.Equal(t, "abc", string(h.Get([]byte("k"))))

	got := h.Get([]byte("k"))
	got[0] = 'z'
	uassert.Equal(t, "abc", string(h.Get([]byte("k"))))
}

func TestTestHostSendNeedsAGrant(t *testing.T) {
	to := address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

	h := NewTestHost()
	uassert.ErrorIs(t, h.Send(to, 100), ErrNotGranted)
	uassert.Equal(t, 0, len(h.Sends()))

	h.Grant(150)
	uassert.NoError(t, h.Send(to, 100))
	uassert.Equal(t, 1, len(h.Sends()))
	uassert.Equal(t, int64(100), h.Sends()[0].Amount)

	// The grant is a budget, not a switch.
	uassert.ErrorIs(t, h.Send(to, 100), ErrNotGranted)
	uassert.NoError(t, h.Send(to, 50))
}

func TestTestHostEventsAndInput(t *testing.T) {
	h := NewTestHost().WithInput([]byte("hi")).WithHeight(42).WithTime(1700000000)
	uassert.Equal(t, "hi", string(h.Input()))
	uassert.Equal(t, int64(42), h.Height())
	uassert.Equal(t, int64(1700000000), h.Now())

	h.Emit("run", "id", "1", "status", "halted")
	h.Emit("odd", "dangling")
	uassert.Equal(t, 2, len(h.Events()))
	uassert.Equal(t, "run id=1 status=halted", h.Events()[0])
	uassert.Equal(t, "odd", h.Events()[1]) // odd trailing element dropped
}

func TestInstanceRunsToCompletion(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	h := NewTestHost()
	uassert.NoError(t, inst.Run(&counter{total: 5}, h, Unmetered))
	uassert.Equal(t, "halted", inst.Status.String())
	uassert.Equal(t, int64(5), inst.FuelUsed)
	uassert.Equal(t, int64(1), inst.Slices)
	uassert.Equal(t, "abcde", h.OutString())
}

func TestInstanceResumesAcrossSlices(t *testing.T) {
	// The property that makes a guest program a contract: five slices of
	// one unit must equal one slice of five.
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	h := NewTestHost()
	for i := 0; i < 5; i++ {
		// A realm holds bytes, not a machine: every slice loads a fresh
		// one from the program and lets Restore carry the state over.
		uassert.NoError(t, inst.Run(&counter{total: 5}, h, 1))
	}
	uassert.Equal(t, "halted", inst.Status.String())
	uassert.Equal(t, int64(5), inst.FuelUsed)
	uassert.Equal(t, int64(5), inst.Slices)
	uassert.Equal(t, "abcde", h.OutString())
}

func TestInstanceStopsAtItsBudget(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("10"), 3)
	h := NewTestHost()
	uassert.NoError(t, inst.Run(&counter{total: 10}, h, Unmetered))
	uassert.Equal(t, "out of fuel", inst.Status.String())
	uassert.Equal(t, int64(3), inst.FuelUsed)
	uassert.Equal(t, int64(0), inst.Remaining())
	uassert.Equal(t, "abc", h.OutString())

	// A second call has nothing to spend and says so instead of looping.
	uassert.ErrorIs(t, inst.Run(&counter{}, h, Unmetered), ErrBudgetExhausted)
}

func TestInstanceSliceClamps(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", nil, 10)
	inst.FuelUsed = 7
	uassert.Equal(t, int64(3), inst.Slice(100))
	uassert.Equal(t, int64(2), inst.Slice(2))
	uassert.Equal(t, int64(3), inst.Slice(Unmetered))

	open := NewInstance("2", address("g1x"), "counter", nil, Unmetered)
	uassert.Equal(t, int64(5), open.Slice(5))
	uassert.Equal(t, Unmetered, open.Slice(Unmetered))
}

func TestInstanceRejectsABadSnapshot(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	inst.Snapshot = []byte{1, 2, 3} // too short for the counter's three fields
	err := inst.Run(&counter{}, NewTestHost(), Unmetered)
	uassert.ErrorIs(t, err, ErrTruncated)
	// The instance is untouched: a snapshot that cannot be decoded costs
	// gas but never corrupts the stored program.
	uassert.Equal(t, int64(0), inst.Slices)
	uassert.Equal(t, "5", string(inst.Program))
}

func TestStore(t *testing.T) {
	s := NewStore()
	uassert.Equal(t, 0, s.Size())
	uassert.Equal(t, true, s.Get("nope") == nil)

	s.Set(NewInstance("001", address("g1a"), "counter", nil, Unmetered))
	s.Set(NewInstance("002", address("g1b"), "counter", nil, Unmetered))
	s.Set(NewInstance("003", address("g1c"), "counter", nil, Unmetered))
	uassert.Equal(t, 3, s.Size())
	uassert.Equal(t, "002", s.Get("002").ID)

	ids := ""
	s.Iterate(func(i *Instance) bool { ids += i.ID + " "; return false })
	uassert.Equal(t, "001 002 003 ", ids)

	rev := ""
	s.ReverseIterate(func(i *Instance) bool { rev += i.ID + " "; return false })
	uassert.Equal(t, "003 002 001 ", rev)

	// Early stop.
	first := ""
	s.Iterate(func(i *Instance) bool { first = i.ID; return true })
	uassert.Equal(t, "001", first)

	uassert.True(t, s.Remove("002"))
	uassert.False(t, s.Remove("002"))
	uassert.Equal(t, 2, s.Size())
}

