// A board that renders every request ever filed is a page that grows without
// bound and a gas cost that grows with it, and this path is permanent. Assert
// the cap holds and that what it hides is counted rather than lost.
func TestRenderCapsEachTable(cur realm, t *testing.T) {
	reset()
	fund(200_000_000)

	const filed = Rows + 5
	for i := 0; i < filed; i++ {
		testing.SetRealm(testing.NewUserRealm(carl))
		Request(cross(cur), zoe.String(), 1_000_000, "batch")
	}
	urequire.Equal(t, int64(filed), Pending())

	page := Render("")
	uassert.Equal(t, Rows, countRows(page), "the open table is capped")
	uassert.True(t, contains(page, "5 more not shown"), "and the rest are counted")

	// Decide them all: the open table empties and the decided one caps in turn,
	// newest first, so the most recent decision is on the page and the oldest
	// is the one hidden.
	for id := int64(1); id <= filed; id++ {
		testing.SetRealm(testing.NewUserRealm(Owner))
		Deny(cross(cur), id, "batch")
	}
	page = Render("")
	uassert.Equal(t, int64(0), Pending())
	uassert.Equal(t, Rows, countRows(page), "the decided table is capped too")
	uassert.True(t, contains(page, "5 more not shown"))
	uassert.True(t, contains(page, ":req/"+strconv.FormatInt(int64(filed), 10)+")"), "newest is shown")
	uassert.False(t, contains(page, ":req/1)"), "oldest is the one hidden")

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

// countRows counts request rows on a page: every one links to :req/.
func countRows(page string) int {
	n, needle := 0, "](/r/nym-moultest123/faucet/v0:req/"
	for i := 0; i+len(needle) <= len(page); i++ {
		if page[i:i+len(needle)] == needle {
			n++
		}
	}
	return n
}

// Path is a hand-written const and the module line is in gnomod.toml, so
// nothing but this test stops them diverging. They must not: Address() derives
// the float from Path, while the banker in Approve spends from cur.Address(),
// which is derived by the VM. A divergence would make Balance() read a
// different account from the one the payout leaves, and the realm would refuse
// payouts it could afford while reporting a float it does not hold.
func TestPathMatchesTheRealmItIsDeployedAs(cur realm, t *testing.T) {
	uassert.Equal(t, cur.Address().String(), Address().String(),
		"Path disagrees with the module line in gnomod.toml")
}

package faucet

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Rows is how many requests each table on the board shows. The rest are
// counted, not rendered: the per-request page is always reachable by id.
const Rows = 20

// Render shows the float, the open asks and everything already decided.
//
// Two paths: "" is the whole board, "req/<id>" is one request.
//
// Every string on this page that a caller typed goes through sanitize before
// it is concatenated. A reason is arbitrary text from an arbitrary account and
// Render output is markdown that gnoweb parses, so an unescaped one can plant
// a link, an image beacon or gnoweb chrome on a page the realm is signing for.
// This realm's path is permanent, so that bug could only ever be fixed at a
// new path.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	if id, ok := reqPath(path); ok {
		return renderOne(id)
	}
	return renderBoard()
}

func renderBoard() string {
	var b strings.Builder

	b.WriteString("# GNOT faucet\n\n")
	b.WriteString(intro)
	b.WriteString("\n\n")

	b.WriteString("| | |\n| --- | ---: |\n")
	b.WriteString("| Float available | **" + gnot(Balance()) + " GNOT** |\n")
	b.WriteString("| Paid out | " + gnot(totalSent) + " GNOT over " +
		strconv.FormatInt(sentCount, 10) + " request(s) |\n")
	b.WriteString("| Open requests | " + strconv.FormatInt(pendingN, 10) + " |\n")
	b.WriteString("| Refused | " + strconv.FormatInt(deniedCount, 10) + " |\n")
	b.WriteString("| Cap per request | " + gnot(maxPerRequest) + " GNOT |\n")
	b.WriteString("| Float address | `" + Address().String() + "` |\n\n")

	b.WriteString("## Open\n\n")
	b.WriteString(table(true, pendingN))
	b.WriteString("\n## Decided\n\n")
	b.WriteString(table(false, sentCount+deniedCount))

	b.WriteString("\n## Approvers\n\n")
	approvers.Iterate("", "", func(k string, _ any) bool {
		b.WriteString("- `" + k + "`\n")
		return false
	})

	b.WriteString("\n" + howto + "\n")
	return b.String()
}

// table lists at most Rows requests: the open ones oldest first, because a
// queue is worked from the front, and the decided ones newest first, because
// nobody scrolls to the bottom of a ledger.
//
// It takes the total from the realm's counters rather than counting rows, so
// it can STOP iterating once the page is full. A Render that walks every
// request ever filed is a page that grows without bound and a gas cost that
// grows with it, and this realm's path is permanent, so that would only ever
// be fixable at a new path.
func table(open bool, total int64) string {
	if total == 0 {
		return "_Nothing here yet._\n"
	}
	var rows strings.Builder
	shown := int64(0)
	visit := func(_ string, v any) bool {
		r := v.(*request)
		if (r.Status == StatusPending) != open {
			return false
		}
		rows.WriteString("| [" + strconv.FormatInt(r.ID, 10) + "](" + Link + ":req/" +
			strconv.FormatInt(r.ID, 10) + ") | `" + r.To.String() + "` | " +
			gnot(r.Amount) + " | " + sanitize.TableCell(excerpt(r.Reason, 60)) + " | " +
			r.Status + " |\n")
		shown++
		return shown >= Rows // a true return stops the walk
	}
	if open {
		requests.Iterate("", "", visit)
	} else {
		requests.ReverseIterate("", "", visit)
	}

	out := "| # | To | GNOT | Why | State |\n| ---: | --- | ---: | --- | --- |\n" + rows.String()
	if rest := total - shown; rest > 0 {
		out += "\n_" + strconv.FormatInt(rest, 10) + " more not shown._\n"
	}
	return out
}

func renderOne(id int64) string {
	r := find(id)
	if r == nil {
		return "# Request " + strconv.FormatInt(id, 10) + "\n\n_No such request._\n"
	}
	var b strings.Builder
	b.WriteString("# Request " + strconv.FormatInt(r.ID, 10) + "\n\n")
	b.WriteString("| | |\n| --- | --- |\n")
	b.WriteString("| To | `" + r.To.String() + "` |\n")
	b.WriteString("| Amount | " + gnot(r.Amount) + " GNOT |\n")
	b.WriteString("| Filed by | `" + r.By.String() + "` |\n")
	b.WriteString("| Filed at height | " + strconv.FormatInt(r.Asked, 10) + " |\n")
	b.WriteString("| State | " + r.Status + " |\n")
	if r.Status != StatusPending {
		b.WriteString("| Decided by | `" + r.Judge.String() + "` |\n")
		b.WriteString("| Decided at height | " + strconv.FormatInt(r.Decided, 10) + " |\n")
	}
	b.WriteString("\n**Why:** " + sanitize.InlineText(r.Reason) + "\n")
	if r.Note != "" {
		b.WriteString("\n**Refused because:** " + sanitize.InlineText(r.Note) + "\n")
	}
	b.WriteString("\n[Back to the faucet](" + Link + ")\n")
	return b.String()
}

// reqPath parses "req/<id>".
func reqPath(path string) (int64, bool) {
	rest, ok := strings.CutPrefix(path, "req/")
	if !ok {
		return 0, false
	}
	id, err := strconv.ParseInt(rest, 10, 64)
	if err != nil || id <= 0 {
		return 0, false
	}
	return id, true
}

// excerpt cuts to width RUNES, never bytes: slicing a multi-byte character in
// half puts invalid UTF-8 on the page, and one emoji in a reason is enough.
// It cuts before escaping, because escaping inserts backslashes and cutting an
// already-escaped string can strand a lone one that escapes the chrome after
// it.
func excerpt(s string, width int) string {
	r := []rune(s)
	if len(r) <= width+1 {
		return s
	}
	return string(r[:width]) + "…"
}

// gnot renders ugnot as GNOT with the trailing zeros of the fraction trimmed,
// so 100000000 reads as 100 and 1500000 as 1.5.
func gnot(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg, ugnot = "-", -ugnot
	}
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := strconv.FormatInt(ugnot%1_000_000, 10)
	if frac == "0" {
		return neg + whole
	}
	for len(frac) < 6 {
		frac = "0" + frac
	}
	return neg + whole + "." + strings.TrimRight(frac, "0")
}

const (
	intro = "Somebody you trust has no GNOT and cannot use the public faucet. File a\n" +
		"request on their behalf, an approver releases it, and both halves stay on\n" +
		"this page with a reason attached. The faucet only ever spends what has been\n" +
		"sent to its own address."

	howto = "## How\n\n" +
		"`Request(to, amount, reason)` is open to anyone and moves no money.\n" +
		"`Approve(id, to, amount)` pays it, and only an approver can call it.\n\n" +
		"Send both in **one transaction**: a tm2 transaction stops at the first\n" +
		"message that fails and writes none of their state, so the ask and its\n" +
		"answer land together or not at all. Read `NextID` to address the approval,\n" +
		"and pass the recipient and the amount into it as well: if another request\n" +
		"takes that id first, the mismatch fails the transaction instead of paying\n" +
		"the wrong account."
)

package faucet

// ExampleRender pins the faucet as it ships: no requests, an empty float, one
// approver. That IS the deployed state, since nothing is seeded here.
//
// reset() first: realm globals persist for the whole test binary and examples
// run after every Test. The float is NOT a realm global and reset() cannot
// clear it, so every test above withdraws what it funded; a test that leaves
// coins behind shows up as a diff here, which is the point.
func ExampleRender() {
	reset()
	print(Render(""))
	// Output:
	// # GNOT faucet
	//
	// Somebody you trust has no GNOT and cannot use the public faucet. File a
	// request on their behalf, an approver releases it, and both halves stay on
	// this page with a reason attached. The faucet only ever spends what has been
	// sent to its own address.
	//
	// | | |
	// | --- | ---: |
	// | Float available | **0 GNOT** |
	// | Paid out | 0 GNOT over 0 request(s) |
	// | Open requests | 0 |
	// | Refused | 0 |
	// | Cap per request | 200 GNOT |
	// | Float address | `g18jy5sp2hx5n8kkwvvs3l908ynyqdxgfh44ay88` |
	//
	// ## Open
	//
	// _Nothing here yet._
	//
	// ## Decided
	//
	// _Nothing here yet._
	//
	// ## Approvers
	//
	// - `g1manfred47kzduec920z88wfr64ylksmdcedlf5`
	//
	// ## How
	//
	// `Request(to, amount, reason)` is open to anyone and moves no money.
	// `Approve(id, to, amount)` pays it, and only an approver can call it.
	//
	// Send both in **one transaction**: a tm2 transaction stops at the first
	// message that fails and writes none of their state, so the ask and its
	// answer land together or not at all. Read `NextID` to address the approval,
	// and pass the recipient and the amount into it as well: if another request
	// takes that id first, the mismatch fails the transaction instead of paying
	// the wrong account.
}

// ExampleRenderUnknownRequest pins the per-request path on the one state it
// can reach deterministically from a reset faucet. A request page proper needs
// a crossing call to exist, and an Example func cannot take `cur realm`, so
// the filled-in version is asserted in TestRenderEscapesTheReason instead.
func ExampleRenderUnknownRequest() {
	reset()
	print(Render("req/7"))
	// Output:
	// # Request 7
	//
	// _No such request._
}

// Package faucet hands a small amount of GNOT to someone who has none, on the
// record, in two calls that are meant to travel in one transaction.
//
// The chain's own faucet is gated and the people who most need a first coin
// are exactly the people who cannot ask for one: an empty account cannot pay
// the gas to call anything. So somebody else files the request on their
// behalf, an approver releases it, and both halves are on chain with a reason
// attached.
//
// # Why two calls and not one bank send
//
// [Request] is permissionless and [Approve] is not. Splitting them puts the
// ask, its reason and who made it on chain even when the answer is no, and
// makes every payout name the request it settles. A plain send would leave a
// transfer with no why, and no way to refuse one in public.
//
// They are meant to be sent together. A tm2 transaction carries a LIST of
// messages, runs them in order and stops at the first failure, and a failed
// transaction writes none of their state: only the fee and the sequence
// survive (tm2/pkg/sdk/baseapp.go, runMsgs and WriteCheckpoint). So a request
// and its approval in one transaction either both happen or neither does.
//
// # The id the second message cannot know yet
//
// [Approve] names a request by id, and message 2 of a transaction cannot read
// what message 1 returned. A caller therefore reads [NextID] first and writes
// that number into the approval, which is a race: another Request landing in
// between shifts the id under it, and the approval would pay a stranger.
//
// That is why [Approve] also takes the recipient and the amount it believes it
// is approving, and refuses when the stored request disagrees. The race then
// costs a failed transaction instead of the wrong person's rent.
//
// # What bounds the damage
//
// The faucet spends only what has been sent to its own address, never the
// approver's balance, so the float is the ceiling and topping it up is a
// deliberate act. [MaxPerRequest] caps any single payout under that, and
// [Withdraw] takes the float back.
//
// # It is a private realm, which buys a code fix and costs the ledger
//
// gnomod.toml declares private = true, so the creator can redeploy this path
// with corrected code instead of abandoning it for a v1. That matters for a
// realm holding other people's rent money.
//
// The price is exact and was measured, not assumed: a redeploy re-runs every
// package initializer, so the float SURVIVES (coins live at the address, which
// is bank state) and everything on this page DOES NOT. Requests, approvers and
// counters all return to their init values. Fixing a bug here is therefore
// cheap in money and expensive in history, which is the right way round for a
// faucet and the wrong way round for a ledger anyone relies on.
//
// Two more consequences worth knowing before copying this: private is one-way
// and set at first deploy (a public path can never become private, nor the
// reverse), and no other realm may import this one or hold a reference to its
// objects.
package faucet

import (
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const (
	// Denom is the only coin this faucet holds or pays.
	Denom = "ugnot"
	// Path is this realm's package path; its float is held at the address
	// derived from it.
	Path = "gno.land/r/nym-moultest123/faucet/v1"
	// Link is Path as a gnoweb route.
	Link = "/r/nym-moultest123/faucet/v1"
)

// Owner funds the faucet, approves by default, and is the only account that
// can change who else approves or take the float back.
//
// Hardcoded rather than captured from the deployer: inside a plain
// `func Test(t *testing.T)` the gno test runner reports OriginCaller() as the
// EMPTY address, so an owner seeded from it is empty in every test and
// something else on chain. That divergence is where an authorization bug
// hides, so the address is written down.
const Owner = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

// The three states a request can be in. A request is decided exactly once.
const (
	StatusPending = "pending"
	StatusSent    = "sent"
	StatusDenied  = "denied"
)

const (
	// DefaultMaxPerRequest is the starting cap on a single payout, 200 GNOT.
	// It is a guard against a fat finger, not against a hostile approver:
	// an approver can raise nothing, but the Owner can.
	DefaultMaxPerRequest = 200_000_000

	// MaxReasonLen bounds the stored reason. It is rendered on a page, so it
	// is both a storage cost and a display one.
	MaxReasonLen = 280

	// idWidth pads the avl key. gno's ufmt supports no width flags, so the
	// padding is done by hand; unpadded numeric keys sort "1","10","2" and
	// the request list would lose its order past nine entries.
	idWidth = 12
)

// request is one ask. It is unexported because avl stores `any` and the
// readable surface of this realm is its views and its page, not a struct
// another realm would have to depend on.
type request struct {
	ID      int64
	To      address
	Amount  int64 // ugnot
	Reason  string
	By      address // who filed it, which is usually not who receives it
	Asked   int64   // chain height at filing
	Status  string
	Judge   address // who decided, zero while pending
	Decided int64   // chain height of the decision
	Note    string  // the denial reason; empty otherwise
}

var (
	requests  avl.Tree // padded id -> *request
	paid      avl.Tree // recipient address -> int64 ugnot received in total
	approvers avl.Tree // approver address -> bool

	nextID        int64
	maxPerRequest int64

	totalSent   int64
	sentCount   int64
	deniedCount int64
	pendingN    int64
)

func init() { reset() }

// reset installs an empty faucet. Also called by the tests: realm globals
// persist for a whole test binary and examples run after every Test, so a
// pinned Render has to start from a known state.
func reset() {
	requests = avl.Tree{}
	paid = avl.Tree{}
	approvers = avl.Tree{}
	approvers.Set(Owner.String(), true)
	nextID = 1
	maxPerRequest = DefaultMaxPerRequest
	totalSent, sentCount, deniedCount, pendingN = 0, 0, 0, 0
}

// Address is where the float sits: this realm's own package address. Fund the
// faucet by sending ugnot to it, with a plain bank send or with [Fund].
func Address() address { return chain.PackageAddress(Path) }

// Balance is what the faucet can actually pay out right now.
func Balance() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(Denom)
}

// NextID is the id the next [Request] will be given.
//
// Read it to build the [Approve] half of a two-message transaction, and pass
// the recipient and amount to Approve so that a request landing in between
// fails the transaction instead of being paid by it.
func NextID() int64 { return nextID }

// MaxPerRequest is the current cap on a single payout, in ugnot.
func MaxPerRequest() int64 { return maxPerRequest }

// TotalSent, SentCount, DeniedCount and Pending are the running tallies.
func TotalSent() int64   { return totalSent }
func SentCount() int64   { return sentCount }
func DeniedCount() int64 { return deniedCount }
func Pending() int64     { return pendingN }

// Requests is how many requests have ever been filed.
func Requests() int { return requests.Size() }

// IsApprover reports whether addr may approve or deny.
func IsApprover(addr string) bool { return approvers.Has(addr) }

// ReceivedBy is everything this faucet has ever paid to addr.
func ReceivedBy(addr string) int64 {
	if v := paid.Get(addr); v != nil {
		return v.(int64)
	}
	return 0
}

// Status is the state of request id: "pending", "sent", "denied", or "" when
// no such request exists.
func Status(id int64) string {
	r := find(id)
	if r == nil {
		return ""
	}
	return r.Status
}

// Fund credits the ugnot sent with the call to the float. Coins sent straight
// to [Address] land there too; they just do not emit an event.
func Fund(cur realm) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	// OriginSend is what the SIGNER attached, not what reached this realm. A
	// realm the user called keeps those coins and could call Fund any number of
	// times, booking each as a donation, so only a user call may read it.
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("faucet: Fund must be called directly by an account, with -send")
	}
	from := prev.Address()
	amount := unsafe.OriginSend().AmountOf(Denom)
	if amount <= 0 {
		panic("faucet: send some " + Denom + " with the call")
	}
	chain.Emit("Fund", "from", from.String(), "amount", strconv.FormatInt(amount, 10))
}

// Request files an ask for amount ugnot to be paid to `to`, and returns its
// id. Anyone may file, for anyone, which is the point: the account that needs
// the coins is the one that cannot pay to ask for them.
//
// Filing costs the filer gas and nothing else, and moves no money.
func Request(cur realm, to string, amount int64, reason string) int64 {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	by := cur.Previous().Address()
	dst := address(to)
	if !dst.IsValid() {
		panic("faucet: " + to + " is not a valid address")
	}
	if amount <= 0 {
		panic("faucet: amount must be a positive number of " + Denom)
	}
	if amount > maxPerRequest {
		panic("faucet: " + strconv.FormatInt(amount, 10) + Denom +
			" is over the per-request cap of " + strconv.FormatInt(maxPerRequest, 10) + Denom)
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("faucet: say what it is for")
	}
	if len(reason) > MaxReasonLen {
		panic("faucet: reason is longer than " + strconv.Itoa(MaxReasonLen) + " bytes")
	}

	id := nextID
	nextID++
	requests.Set(key(id), &request{
		ID:     id,
		To:     dst,
		Amount: amount,
		Reason: reason,
		By:     by,
		Asked:  runtime.ChainHeight(),
		Status: StatusPending,
	})
	pendingN++

	chain.Emit("Request",
		"id", strconv.FormatInt(id, 10),
		"to", dst.String(),
		"amount", strconv.FormatInt(amount, 10),
		"by", by.String(),
	)
	return id
}

// Approve pays request id out of the float. Approvers only.
//
// wantTo and wantAmount are not redundant: they are what makes it safe to put
// Approve in the same transaction as the Request it settles. The id has to be
// guessed from [NextID] before either message is signed, and this call refuses
// when the request sitting at that id is not the one the caller described.
func Approve(cur realm, id int64, wantTo string, wantAmount int64) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	judge := cur.Previous().Address()
	mustApprove(judge)

	r := find(id)
	if r == nil {
		panic("faucet: no request " + strconv.FormatInt(id, 10))
	}
	if r.Status != StatusPending {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " is already " + r.Status)
	}
	if r.To.String() != wantTo || r.Amount != wantAmount {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " pays " +
			strconv.FormatInt(r.Amount, 10) + Denom + " to " + r.To.String() +
			", not " + strconv.FormatInt(wantAmount, 10) + Denom + " to " + wantTo +
			"; the id moved under you, nothing was paid")
	}
	if bal := Balance(); bal < r.Amount {
		panic("faucet: float is " + strconv.FormatInt(bal, 10) + Denom +
			", request needs " + strconv.FormatInt(r.Amount, 10) + Denom)
	}

	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), r.To, chain.NewCoins(chain.NewCoin(Denom, r.Amount)))

	r.Status = StatusSent
	r.Judge = judge
	r.Decided = runtime.ChainHeight()
	paid.Set(r.To.String(), ReceivedBy(r.To.String())+r.Amount)
	totalSent += r.Amount
	sentCount++
	pendingN--

	chain.Emit("Approve",
		"id", strconv.FormatInt(id, 10),
		"to", r.To.String(),
		"amount", strconv.FormatInt(r.Amount, 10),
		"by", judge.String(),
	)
}

// Deny closes a request unpaid, with a reason that goes on the page. The
// reason is the whole value of denying in public rather than ignoring it.
func Deny(cur realm, id int64, why string) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	judge := cur.Previous().Address()
	mustApprove(judge)

	r := find(id)
	if r == nil {
		panic("faucet: no request " + strconv.FormatInt(id, 10))
	}
	if r.Status != StatusPending {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " is already " + r.Status)
	}
	why = strings.TrimSpace(why)
	if why == "" {
		panic("faucet: say why")
	}
	if len(why) > MaxReasonLen {
		panic("faucet: reason is longer than " + strconv.Itoa(MaxReasonLen) + " bytes")
	}

	r.Status = StatusDenied
	r.Judge = judge
	r.Decided = runtime.ChainHeight()
	r.Note = why
	deniedCount++
	pendingN--

	chain.Emit("Deny", "id", strconv.FormatInt(id, 10), "by", judge.String())
}

// AddApprover lets addr approve and deny. Owner only.
func AddApprover(cur realm, addr string) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	mustOwn(cur.Previous().Address())
	a := address(addr)
	if !a.IsValid() {
		panic("faucet: " + addr + " is not a valid address")
	}
	approvers.Set(a.String(), true)
	chain.Emit("AddApprover", "addr", a.String())
}

// RemoveApprover revokes addr. Owner only, and the Owner cannot be removed:
// a faucet with no approver is a faucet with a locked float.
func RemoveApprover(cur realm, addr string) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	mustOwn(cur.Previous().Address())
	if addr == Owner.String() {
		panic("faucet: the owner is always an approver")
	}
	// avl's Remove returns (value, removed), unlike Get which returns one
	// value; the comma-ok is required here and forbidden there.
	if _, removed := approvers.Remove(addr); !removed {
		panic("faucet: " + addr + " is not an approver")
	}
	chain.Emit("RemoveApprover", "addr", addr)
}

// SetMaxPerRequest changes the per-request cap, in ugnot. Owner only.
func SetMaxPerRequest(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	mustOwn(cur.Previous().Address())
	if amount <= 0 {
		panic("faucet: cap must be positive")
	}
	maxPerRequest = amount
	chain.Emit("SetMaxPerRequest", "amount", strconv.FormatInt(amount, 10))
}

// Withdraw returns amount ugnot of the float to the Owner. Owner only.
//
// This is what makes funding the faucet reversible, and it is deliberately
// not payable to an arbitrary address: an approver who wanted to move money
// somewhere has to file a request for it like everyone else.
func Withdraw(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic("faucet: spoofed realm")
	}
	mustOwn(cur.Previous().Address())
	if amount <= 0 {
		panic("faucet: amount must be positive")
	}
	if bal := Balance(); amount > bal {
		panic("faucet: float is " + strconv.FormatInt(bal, 10) + Denom)
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), Owner, chain.NewCoins(chain.NewCoin(Denom, amount)))
	chain.Emit("Withdraw", "amount", strconv.FormatInt(amount, 10))
}

func mustOwn(caller address) {
	if caller != Owner {
		panic("faucet: owner only")
	}
}

func mustApprove(caller address) {
	if !approvers.Has(caller.String()) {
		panic("faucet: " + caller.String() + " is not an approver")
	}
}

func find(id int64) *request {
	v := requests.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*request)
}

// key pads an id to idWidth digits so the avl tree iterates in filing order.
func key(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < idWidth {
		s = "0" + s
	}
	return s
}

package faucet

import (
	"strconv"

	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const (
	zoe  = address("g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz") // a friend with nothing
	kim  = address("g1jvh5ukk07dvd57fxefcp5aa29xaydxmxs7myyp") // a second approver
	carl = address("g1us8428u2a5satrlxzagqqa5m6vmuze025anjlj") // nobody in particular
)

func balanceOf(a address) int64 {
	return banker.NewReadonlyBanker().GetCoins(a).AmountOf(Denom)
}

// fund puts ugnot in the float the way a bank send to the realm address does,
// with no call involved. Approve spends this, so a test that funds more than
// it pays leaves a balance behind and ExampleRender sees it.
func fund(n int64) {
	testing.IssueCoins(Address(), chain.NewCoins(chain.NewCoin(Denom, n)))
}

func TestFreshFaucetIsEmptyAndOwned(t *testing.T) {
	reset()
	uassert.True(t, Owner.IsValid(), "the owner is a real address")
	uassert.True(t, Address().IsValid(), "the float address")
	uassert.True(t, zoe.IsValid())
	uassert.True(t, kim.IsValid())
	uassert.True(t, carl.IsValid())

	uassert.Equal(t, 0, Requests(), "nothing is seeded")
	uassert.Equal(t, int64(1), NextID())
	uassert.Equal(t, int64(0), TotalSent())
	uassert.Equal(t, int64(DefaultMaxPerRequest), MaxPerRequest())
	uassert.True(t, IsApprover(Owner.String()), "the owner approves by default")
	uassert.False(t, IsApprover(carl.String()))
	uassert.Equal(t, "", Status(1), "no such request")
}

// The whole point, end to end: carl asks on zoe's behalf, the owner releases
// it, and zoe (who could never have paid the gas to ask) has coins.
func TestRequestForAFriendThenApprove(cur realm, t *testing.T) {
	reset()
	urequire.Equal(t, int64(0), Balance(), "start from an empty float")
	fund(300_000_000)

	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 100_000_000, "no gas, needs to try the chain")
	uassert.Equal(t, int64(1), id)
	uassert.Equal(t, StatusPending, Status(id))
	uassert.Equal(t, int64(1), Pending())
	uassert.Equal(t, int64(0), balanceOf(zoe), "a request moves nothing")
	uassert.Equal(t, int64(2), NextID(), "and the next id is now readable")

	// The filer is not an approver just because they filed.
	testing.SetRealm(testing.NewUserRealm(carl))
	uassert.AbortsContains(t, cur, "is not an approver", func() {
		Approve(cross(cur), id, zoe.String(), 100_000_000)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	Approve(cross(cur), id, zoe.String(), 100_000_000)

	uassert.Equal(t, int64(100_000_000), balanceOf(zoe), "the coins landed")
	uassert.Equal(t, int64(200_000_000), Balance(), "out of the float, not the approver")
	uassert.Equal(t, StatusSent, Status(id))
	uassert.Equal(t, int64(100_000_000), TotalSent())
	uassert.Equal(t, int64(1), SentCount())
	uassert.Equal(t, int64(0), Pending())
	uassert.Equal(t, int64(100_000_000), ReceivedBy(zoe.String()))

	// A decision happens once.
	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "already sent", func() {
		Approve(cross(cur), id, zoe.String(), 100_000_000)
	})

	// Put the float back so ExampleRender starts from zero.
	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
	uassert.Equal(t, int64(0), Balance())
}

// The guard that makes it safe to sign Request and Approve in the same
// transaction before either has run. The approval names an id it had to guess
// from NextID; if a different request took that id, the amounts and the
// recipient no longer agree and nothing is paid.
func TestApproveRefusesWhenTheIDMovedUnderYou(cur realm, t *testing.T) {
	reset()
	fund(500_000_000)

	// What the caller read: the next id will be 1.
	urequire.Equal(t, int64(1), NextID())

	// What actually landed at id 1: somebody else's ask, first.
	testing.SetRealm(testing.NewUserRealm(kim))
	Request(cross(cur), kim.String(), 50_000_000, "me first")
	testing.SetRealm(testing.NewUserRealm(carl))
	Request(cross(cur), zoe.String(), 100_000_000, "for zoe")

	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "the id moved under you, nothing was paid", func() {
		Approve(cross(cur), 1, zoe.String(), 100_000_000)
	})
	uassert.Equal(t, int64(0), balanceOf(zoe), "nobody was paid")
	uassert.Equal(t, StatusPending, Status(1), "and nothing was decided")

	// The same guard catches a wrong amount at the right id.
	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "the id moved under you, nothing was paid", func() {
		Approve(cross(cur), 2, zoe.String(), 999_000_000)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	Approve(cross(cur), 2, zoe.String(), 100_000_000)
	uassert.Equal(t, int64(100_000_000), balanceOf(zoe))

	testing.SetRealm(testing.NewUserRealm(Owner))
	Deny(cross(cur), 1, "already funded elsewhere")
	uassert.Equal(t, StatusDenied, Status(1))
	uassert.Equal(t, int64(1), DeniedCount())
	uassert.Equal(t, int64(0), Pending())

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

func TestRequestRefusesBadInput(cur realm, t *testing.T) {
	reset()
	tests := []struct {
		name   string
		to     string
		amount int64
		reason string
		want   string
	}{
		{"not an address", "nope", 1_000_000, "hi", "is not a valid address"},
		{"zero", zoe.String(), 0, "hi", "must be a positive number"},
		{"negative", zoe.String(), -1, "hi", "must be a positive number"},
		{"over the cap", zoe.String(), DefaultMaxPerRequest + 1, "hi", "is over the per-request cap"},
		{"no reason", zoe.String(), 1_000_000, "   ", "say what it is for"},
	}
	for _, tt := range tests {
		testing.SetRealm(testing.NewUserRealm(carl))
		uassert.AbortsContains(t, cur, tt.want, func() {
