package collatz

import (
	"chain"
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// maxIters caps the Collatz walk so a hostile / huge input cannot loop
// forever on-chain. No known n stays below this bound and fails to reach 1.
const maxIters = 1000000

// maxSeqLen caps how many terms Render("/<n>") will print.
const maxSeqLen = 500

// Result is one recorded submission.
type Result struct {
	N     int64
	Steps int
	Peak  int64
	Who   address
}

// results maps a decimal-string key of N -> Result. avl.Tree keeps a
// deterministic order for iteration inside Render.
var results avl.Tree

// stopping returns the number of steps to reach 1 and the peak value seen,
// walking the Collatz (hailstone) map. It never mutates state.
func stopping(n int64) (steps int, peak int64) {
	peak = n
	cur := n
	for cur != 1 {
		if steps >= maxIters {
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
		steps++
	}
	return steps, peak
}

// Compute walks the hailstone sequence for n and records the result
// attributed to the caller. It is a crossing (state-mutating) func.
func Compute(cur realm, n int) {
	if n <= 0 {
		panic("n must be > 0")
	}
	caller := unsafe.PreviousRealm().Address()
	nn := int64(n)
	steps, peak := stopping(nn)

	res := Result{N: nn, Steps: steps, Peak: peak, Who: caller}
	key := strconv.FormatInt(nn, 10)
	results.Set(key, res)

	chain.Emit(
		"Computed",
		"n", key,
		"steps", strconv.Itoa(steps),
		"peak", strconv.FormatInt(peak, 10),
		"who", caller.String(),
	)
}

// byLongest implements sort.Interface, ordering results by steps desc,
// then peak desc, then n asc for stability.
type byLongest []Result

func (b byLongest) Len() int      { return len(b) }
func (b byLongest) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byLongest) Less(i, j int) bool {
	if b[i].Steps != b[j].Steps {
		return b[i].Steps > b[j].Steps
	}
	if b[i].Peak != b[j].Peak {
		return b[i].Peak > b[j].Peak
	}
	return b[i].N < b[j].N
}

// Render shows the leaderboard at root, or the full hailstone sequence for a
// given n at path "/<n>".
func Render(path string) string {
	p := strings.TrimPrefix(path, "/")
	if p == "" {
		return renderLeaderboard()
	}
	return renderSequence(p)
}

func renderLeaderboard() string {
	all := make([]Result, 0, results.Size())
	results.Iterate("", "", func(_ string, v interface{}) bool {
		all = append(all, v.(Result))
		return false
	})

	var sb strings.Builder
	sb.WriteString("# Collatz Explorer\n\n")
	sb.WriteString("Hailstone-sequence explorer. Call `Compute(n)` to record a run, ")
	sb.WriteString("or view a full sequence at `/<n>`.\n\n")

	if len(all) == 0 {
		sb.WriteString("_No sequences submitted yet._\n")
		return sb.String()
	}

	sort.Stable(byLongest(all))

	sb.WriteString("## Leaderboard — longest sequences\n\n")
	sb.WriteString("| # | n | steps | peak | who |\n")
	sb.WriteString("|---|---|-------|------|-----|\n")
	limit := len(all)
	if limit > 20 {
		limit = 20
	}
	for i := 0; i < limit; i++ {
		r := all[i]
		sb.WriteString("| " + strconv.Itoa(i+1) + " | ")
		sb.WriteString("[" + strconv.FormatInt(r.N, 10) + "](/r:" + strconv.FormatInt(r.N, 10) + ") | ")
		sb.WriteString(strconv.Itoa(r.Steps) + " | ")
		sb.WriteString(strconv.FormatInt(r.Peak, 10) + " | ")
		sb.WriteString(r.Who.String() + " |\n")
	}
	sb.WriteString("\n_" + strconv.Itoa(len(all)) + " sequence(s) recorded._\n")
	return sb.String()
}

func renderSequence(p string) string {
	n, err := strconv.ParseInt(p, 10, 64)
	var sb strings.Builder
	if err != nil || n <= 0 {
		sb.WriteString("# Invalid n\n\n`" + p + "` is not a positive integer.\n")
		return sb.String()
	}

	sb.WriteString("# Hailstone sequence for " + strconv.FormatInt(n, 10) + "\n\n")

	seq := make([]int64, 0, 64)
	cur := n
	var peak int64 = n
	truncated := false
	for {
		seq = append(seq, cur)
		if cur == 1 {
			break
		}
		if len(seq) >= maxSeqLen {
			truncated = true
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
	}

	parts := make([]string, len(seq))
	for i, v := range seq {
		parts[i] = strconv.FormatInt(v, 10)
	}
	sb.WriteString(strings.Join(parts, " → "))
	sb.WriteString("\n\n")
	sb.WriteString("- steps: " + strconv.Itoa(len(seq)-1) + "\n")
	sb.WriteString("- peak: " + strconv.FormatInt(peak, 10) + "\n")
	if truncated {
		sb.WriteString("\n_Sequence truncated at " + strconv.Itoa(maxSeqLen) + " terms._\n")
	}
	return sb.String()
}

package collatz

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestStopping(t *testing.T) {
	cases := []struct {
		n     int64
		steps int
		peak  int64
	}{
		{1, 0, 1},
		{2, 1, 2},
		{6, 8, 16},
		{7, 16, 52},
		{27, 111, 9232},
	}
	for _, c := range cases {
		steps, peak := stopping(c.n)
		uassert.Equal(t, c.steps, steps)
		uassert.Equal(t, c.peak, peak)
	}
}

func TestComputeAndLeaderboard(cur realm, t *testing.T) {
	addr := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(addr))

	Compute(cross(cur), 27)
	Compute(cross(cur), 6)

	out := Render("")
	uassert.True(t, strings.Contains(out, "Leaderboard"), "has leaderboard")
	uassert.True(t, strings.Contains(out, "9232"), "shows peak of 27")
	// 27 has more steps than 6, so it must appear first (rank 1).
	i27 := strings.Index(out, "[27]")
	i6 := strings.Index(out, "[6]")
	uassert.True(t, i27 >= 0 && i6 >= 0, "both rows present")
	uassert.True(t, i27 < i6, "27 ranked above 6")
}

func TestComputeRejectsNonPositive(cur realm, t *testing.T) {
	addr := testutils.TestAddress("bob")
	testing.SetRealm(testing.NewUserRealm(addr))
	uassert.AbortsWithMessage(t, cur, "n must be > 0", func() {
		Compute(cross(cur), 0)
	})
}

func TestRenderSequence(t *testing.T) {
	out := Render("/6")
	uassert.True(t, strings.Contains(out, "6 → 3 → 10 → 5 → 16 → 8 → 4 → 2 → 1"), "full seq for 6")
	uassert.True(t, strings.Contains(out, "steps: 8"), "reports 8 steps")

	bad := Render("/abc")
	uassert.True(t, strings.Contains(bad, "Invalid"), "rejects non-numeric path")
}

package connect4

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	cols = 7
	rows = 6
)

// cell values
const (
	empty = 0
	red   = 1 // 🔴 game creator (caller of NewGame)
	yel   = 2 // 🟡 opponent
)

// Game holds the full state of one Connect Four match.
// board is indexed board[row][col]; row 0 is the BOTTOM row.
type Game struct {
	ID       int64
	Red      address // 🔴 creator, moves first
	Yellow   address // 🟡 opponent
	Board    [rows][cols]int
	Turn     int  // whose turn: red or yel
	Winner   int  // empty until decided; red/yel = winner
	Draw     bool // true when board full with no winner
	Finished bool
}

var (
	games  = avl.NewTree() // id (zero-padded string) -> *Game
	nextID int64
)

func idKey(id int64) string {
	// zero-pad so avl iteration order matches numeric order for Render lists
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// NewGame creates a match between the caller (🔴) and opponent (🟡).
// Returns the new game id.
func NewGame(cur realm, opponent address) int64 {
	caller := unsafe.PreviousRealm().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if opponent.String() == "" {
		panic("opponent address is empty")
	}
	nextID++
	g := &Game{
		ID:     nextID,
		Red:    caller,
		Yellow: opponent,
		Turn:   red,
	}
	games.Set(idKey(g.ID), g)
	chain.Emit("GameCreated",
		"id", strconv.FormatInt(g.ID, 10),
		"red", caller.String(),
		"yellow", opponent.String(),
	)
	return g.ID
}

func getGame(id int64) (*Game, error) {
	v := games.Get(idKey(id))
	if v == nil {
		return nil, errors.New("game not found: " + strconv.FormatInt(id, 10))
	}
	return v.(*Game), nil
}

// Drop places the caller's disc into the given column (0-6).
// Enforces turn order by caller, rejects full columns, and detects
// a 4-in-a-row win or a draw.
func Drop(cur realm, gameID int64, column int) {
	if column < 0 || column >= cols {
		panic("column out of range (0-6)")
	}
	g, err := getGame(gameID)
	if err != nil {
		panic(err.Error())
	}
	if g.Finished {
		panic("game already finished")
	}

	caller := unsafe.PreviousRealm().Address()
	var mover int
	switch caller {
	case g.Red:
		mover = red
	case g.Yellow:
		mover = yel
	default:
		panic("caller is not a player in this game")
	}
	if mover != g.Turn {
		panic("not your turn")
	}

	// find lowest empty row in the column
	placed := -1
	for r := 0; r < rows; r++ {
		if g.Board[r][column] == empty {
			g.Board[r][column] = mover
			placed = r
			break
		}
	}
	if placed == -1 {
		panic("column is full")
	}

	if wins(&g.Board, placed, column, mover) {
		g.Winner = mover
		g.Finished = true
		chain.Emit("GameWon",
			"id", strconv.FormatInt(g.ID, 10),
			"winner", caller.String(),
		)
	} else if full(&g.Board) {
		g.Draw = true
		g.Finished = true
		chain.Emit("GameDraw", "id", strconv.FormatInt(g.ID, 10))
	} else {
		if g.Turn == red {
			g.Turn = yel
		} else {
			g.Turn = red
		}
		chain.Emit("DiscDropped",
			"id", strconv.FormatInt(g.ID, 10),
			"col", strconv.Itoa(column),
			"player", caller.String(),
		)
	}

	games.Set(idKey(g.ID), g)
}

func full(b *[rows][cols]int) bool {
	for c := 0; c < cols; c++ {
		if b[rows-1][c] == empty {
			return false
		}
	}
	return true
}

// wins checks whether the disc just placed at (r,c) for player p completes
// a run of 4 in any of the four directions.
func wins(b *[rows][cols]int, r, c, p int) bool {
	// direction pairs: horizontal, vertical, diag /, diag \
	dirs := [4][2]int{{0, 1}, {1, 0}, {1, 1}, {1, -1}}
	for _, d := range dirs {
		count := 1
		count += run(b, r, c, d[0], d[1], p)
		count += run(b, r, c, -d[0], -d[1], p)
		if count >= 4 {
			return true
		}
	}
	return false
}

func run(b *[rows][cols]int, r, c, dr, dc, p int) int {
	n := 0
	for i := 1; i < 4; i++ {
		rr := r + dr*i
		cc := c + dc*i
		if rr < 0 || rr >= rows || cc < 0 || cc >= cols {
			break
		}
		if b[rr][cc] != p {
			break
		}
		n++
	}
	return n
}

func glyph(v int) string {
	switch v {
	case red:
		return "🔴"
	case yel:
		return "🟡"
	default:
		return "·"
	}
}

// Render draws the board with 🔴🟡· and shows whose turn / the winner.
// path "" lists all games; path "<id>" shows a single board.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path == "" {
		return renderList()
	}
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil {
		return "# Connect Four\n\nInvalid game id: `" + path + "`\n"
	}
	g, err := getGame(id)
	if err != nil {
		return "# Connect Four\n\n" + err.Error() + "\n"
	}
	return renderGame(g)
}

func renderList() string {
	var sb strings.Builder
	sb.WriteString("# Connect Four\n\n")
	sb.WriteString("Two-player Connect Four on a 7×6 board. 🔴 is the game creator, 🟡 the opponent.\n\n")
	if games.Size() == 0 {
		sb.WriteString("_No games yet. Call `NewGame(opponent)` to start one._\n")
		return sb.String()
	}
	sb.WriteString("## Games\n\n")
	sb.WriteString("| ID | 🔴 Red | 🟡 Yellow | Status |\n")
	sb.WriteString("|----|--------|-----------|--------|\n")
	games.Iterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		status := ""
		switch {
		case g.Winner == red:
			status = "🔴 won"
		case g.Winner == yel:
			status = "🟡 won"
		case g.Draw:
			status = "draw"
		case g.Turn == red:
			status = "🔴 to move"
		default:
			status = "🟡 to move"
		}
		sb.WriteString("| [" + strconv.FormatInt(g.ID, 10) + "](/r:" + strconv.FormatInt(g.ID, 10) + ") | " +
			short(g.Red) + " | " + short(g.Yellow) + " | " + status + " |\n")
		return false
	})
	sb.WriteString("\nOpen a game by its id (e.g. path `1`).\n")
	return sb.String()
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:8] + "…" + s[len(s)-4:] + "`"
}

func renderGame(g *Game) string {
	var sb strings.Builder
	sb.WriteString("# Connect Four — Game " + strconv.FormatInt(g.ID, 10) + "\n\n")
	sb.WriteString("- 🔴 Red: `" + g.Red.String() + "`\n")
	sb.WriteString("- 🟡 Yellow: `" + g.Yellow.String() + "`\n\n")

	// status line
	switch {
	case g.Winner == red:
		sb.WriteString("**🔴 Red wins!**\n\n")
	case g.Winner == yel:
		sb.WriteString("**🟡 Yellow wins!**\n\n")
	case g.Draw:
		sb.WriteString("**Draw — board full.**\n\n")
	case g.Turn == red:
		sb.WriteString("**Turn: 🔴 Red**\n\n")
	default:
		sb.WriteString("**Turn: 🟡 Yellow**\n\n")
	}

	// board top-down (row rows-1 at top, row 0 at bottom)
	sb.WriteString("```\n")
	for r := rows - 1; r >= 0; r-- {
		for c := 0; c < cols; c++ {
			sb.WriteString(glyph(g.Board[r][c]))
		}
		sb.WriteString("\n")
	}
	// column indices
	for c := 0; c < cols; c++ {
		sb.WriteString(strconv.Itoa(c))
	}
	sb.WriteString("\n```\n\n")

	if !g.Finished {
		sb.WriteString("Drop a disc: `Drop(" + strconv.FormatInt(g.ID, 10) + ", <col 0-6>)`\n")
	}
	return sb.String()
}

package connect4

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice") // 🔴
	bob   = testutils.TestAddress("bob")   // 🟡
	carol = testutils.TestAddress("carol")
)

func resetState() {
	games = avl.NewTree()
	nextID = 0
}

// TestVerticalWin plays 🔴 stacking column 0 four high while 🟡 plays column 1.
func TestVerticalWin(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := NewGame(cross(cur), bob)
	uassert.Equal(t, int64(1), id)

	for i := 0; i < 3; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Drop(cross(cur), id,0)
		testing.SetRealm(testing.NewUserRealm(bob))
		Drop(cross(cur), id,1)
	}
	// alice's 4th disc in column 0 -> vertical win
	testing.SetRealm(testing.NewUserRealm(alice))
	Drop(cross(cur), id,0)

	g, err := getGame(id)
	uassert.NoError(t, err)
	uassert.True(t, g.Finished)
	uassert.Equal(t, red, g.Winner)

	out := Render("1")
	uassert.True(t, strings.Contains(out, "🔴 Red wins!"))
}

// TestTurnOrderAndErrors covers turn enforcement, non-player, full-column and range checks.
func TestTurnOrderAndErrors(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := NewGame(cross(cur), bob)

	// bob cannot move first (red starts)
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur,"not your turn", func() {
		Drop(cross(cur), id,0)
	})

	// stranger cannot play
	testing.SetRealm(testing.NewUserRealm(carol))
	uassert.AbortsWithMessage(t, cur,"caller is not a player in this game", func() {
		Drop(cross(cur), id,0)
	})

	// out-of-range column
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur,"column out of range (0-6)", func() {
		Drop(cross(cur), id,7)
	})

	// fill column 3: alice & bob alternate, 6 discs total
	col := 3
	for i := 0; i < 3; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Drop(cross(cur), id,col)
		testing.SetRealm(testing.NewUserRealm(bob))
		Drop(cross(cur), id,col)
	}
	// column now full; whoever is on turn overflows it
	g, _ := getGame(id)
	var mover address
	if g.Turn == red {
		mover = alice
	} else {
		mover = bob
	}
	testing.SetRealm(testing.NewUserRealm(mover))
	uassert.AbortsWithMessage(t, cur,"column is full", func() {
		Drop(cross(cur), id,col)
	})
}

// TestHorizontalWin: 🔴 across columns 0-3 on the bottom row.
func TestHorizontalWin(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	id := NewGame(cross(cur), bob)

	// alice drops cols 0,1,2 ; bob answers on row above (col 0,1,2)
	for c := 0; c < 3; c++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Drop(cross(cur), id,c)
		testing.SetRealm(testing.NewUserRealm(bob))
		Drop(cross(cur), id,c)
	}
	// alice completes col 3 on bottom row -> 0,1,2,3 horizontal
	testing.SetRealm(testing.NewUserRealm(alice))
	Drop(cross(cur), id,3)

	g, err := getGame(id)
	uassert.NoError(t, err)
	uassert.True(t, g.Finished)
	uassert.Equal(t, red, g.Winner)
}

// TestRenderList checks the listing view renders created games.
func TestRenderList(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	NewGame(cross(cur), bob)

	out := Render("")
	uassert.True(t, strings.Contains(out, "Connect Four"))
	uassert.True(t, strings.Contains(out, "to move"))
}

// Package counter implements "Counter Club": a single shared integer counter
// with a rolling history of the last 20 mutations. Anyone may Inc, Dec, or
// Reset the value; every change records the caller, the delta applied, the
// resulting value, and the block height it happened at.
package counter

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// maxHistory is the number of recent changes kept in the log.
const maxHistory = 20

// change is a single recorded mutation of the counter.
type change struct {
	caller address // who triggered the change
	delta  int     // how much the value moved (+1, -1, or reset amount)
	value  int     // the resulting counter value after the change
	height int64   // block height at which it occurred
}

// value is the current shared counter.
var value int

// total counts every mutation ever applied (not capped, unlike history).
var total int

// history holds the last maxHistory changes, oldest first.
var history []change

// record appends a change to the history, trimming to the last maxHistory.
func record(delta, newValue int) {
	c := change{
		caller: unsafe.PreviousRealm().Address(),
		delta:  delta,
		value:  newValue,
		height: runtime.ChainHeight(),
	}
	history = append(history, c)
	if len(history) > maxHistory {
		history = history[len(history)-maxHistory:]
	}
	total++
	chain.Emit(
		"CounterChange",
		"delta", strconv.Itoa(delta),
		"value", strconv.Itoa(newValue),
	)
}

// Inc adds one to the shared counter and logs the change.
func Inc(cur realm) int {
	value++
	record(1, value)
	return value
}

// Dec subtracts one from the shared counter and logs the change.
func Dec(cur realm) int {
	value--
	record(-1, value)
	return value
}

// Reset sets the shared counter back to zero and logs the change. The recorded
// delta is the amount required to bring the previous value to zero.
func Reset(cur realm) int {
	delta := -value
	value = 0
	record(delta, value)
	return value
}

// Value returns the current counter value (read-only helper).
func Value() int {
	return value
}

// Total returns the total number of mutations ever applied.
func Total() int {
	return total
}

// Render produces a Markdown view: the big current value, the total number of
// changes, and a table of the most recent changes (newest first).
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Counter Club\n\n")
	b.WriteString("A shared counter anyone can Inc, Dec, or Reset. ")
	b.WriteString("The last ")
	b.WriteString(strconv.Itoa(maxHistory))
	b.WriteString(" changes are logged below.\n\n")

	// Big current value.
	b.WriteString("## Current value\n\n")
	b.WriteString("# ")
	b.WriteString(strconv.Itoa(value))
	b.WriteString("\n\n")

	b.WriteString("**Total changes:** ")
	b.WriteString(strconv.Itoa(total))
	b.WriteString("\n\n")

	// Recent history, newest first.
	b.WriteString("## Recent history\n\n")
	if len(history) == 0 {
		b.WriteString("_No changes yet — be the first to count!_\n")
		return b.String()
	}

	b.WriteString("| # | Caller | Delta | New value | Height |\n")
	b.WriteString("|---|--------|-------|-----------|--------|\n")
	n := len(history)
	for i := n - 1; i >= 0; i-- {
		c := history[i]
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(n - i))
		b.WriteString(" | ")
		b.WriteString(c.caller.String())
		b.WriteString(" | ")
		b.WriteString(signed(c.delta))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(c.value))
		b.WriteString(" | ")
		b.WriteString(strconv.FormatInt(c.height, 10))
		b.WriteString(" |\n")
	}

	return b.String()
}

// signed formats an int with an explicit leading sign for non-negative values.
func signed(n int) string {
	if n >= 0 {
		return "+" + strconv.Itoa(n)
	}
	return strconv.Itoa(n)
}

package counter

// ExampleRender pins the realm's Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Counter Club
	//
	// A shared counter anyone can Inc, Dec, or Reset. The last 20 changes are logged below.
	//
	// ## Current value
	//
	// # 0
	//
	// **Total changes:** 0
	//
	// ## Recent history
	//
	// _No changes yet — be the first to count!_
}

// Package crowdfund is an accounting-only port of the classic Solidity
// Kickstarter-style crowdfunding contract to a gno.land realm.
//
// A creator Launches a campaign with a funding goal and a duration (in blocks).
// Backers Pledge (and may Unpledge before the deadline). After the deadline the
// creator can Claim if the goal was met, otherwise backers can Refund.
//
// No real coin moves: pledges are tracked as plain uint64 accounting, exactly
// like the mapping(address => uint) balances of the Solidity original.
package crowdfund

import (
	"strconv"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// Campaign holds the state of a single crowdfunding campaign.
type Campaign struct {
	ID       int
	Creator  address
	Goal     uint64
	Deadline int64     // block height after which the campaign is closed
	Pledged  uint64    // running total pledged
	Claimed  bool      // creator already claimed the funds
	pledges  *avl.Tree // backer address (string) -> pledged uint64
}

var (
	campaigns = avl.NewTree() // padded id -> *Campaign (ordered by id)
	nextID    = 1
)

// key zero-pads an id so avl iteration is in numeric order.
func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func mustGet(id int) *Campaign {
	v := campaigns.Get(key(id))
	if v == nil {
		panic("campaign not found")
	}
	return v.(*Campaign)
}

// Launch creates a new campaign owned by the caller and returns its id.
func Launch(cur realm, goal uint64, durationBlocks int) int {
	if goal == 0 {
		panic("goal must be > 0")
	}
	if durationBlocks <= 0 {
		panic("duration must be > 0")
	}
	caller := unsafe.PreviousRealm().Address()
	id := nextID
	nextID++
	c := &Campaign{
		ID:       id,
		Creator:  caller,
		Goal:     goal,
		Deadline: runtime.ChainHeight() + int64(durationBlocks),
		pledges:  avl.NewTree(),
	}
	campaigns.Set(key(id), c)
	chain.Emit("Launch",
		"id", strconv.Itoa(id),
		"creator", caller.String(),
		"goal", strconv.FormatUint(goal, 10))
	return id
}

// Pledge backs campaign id with amount (before the deadline).
func Pledge(cur realm, id int, amount uint64) {
	if amount == 0 {
		panic("amount must be > 0")
	}
	c := mustGet(id)
	if runtime.ChainHeight() > c.Deadline {
		panic("campaign ended")
	}
	caller := unsafe.PreviousRealm().Address()
	prev := uint64(0)
	if v := c.pledges.Get(caller.String()); v != nil {
		prev = v.(uint64)
	}
	c.pledges.Set(caller.String(), prev+amount)
	c.Pledged += amount
	chain.Emit("Pledge",
		"id", strconv.Itoa(id),
		"from", caller.String(),
		"amount", strconv.FormatUint(amount, 10))
}

// Unpledge withdraws amount from the caller's pledge (before the deadline).
func Unpledge(cur realm, id int, amount uint64) {
	if amount == 0 {
		panic("amount must be > 0")
	}
	c := mustGet(id)
	if runtime.ChainHeight() > c.Deadline {
		panic("campaign ended")
	}
	caller := unsafe.PreviousRealm().Address()
	v := c.pledges.Get(caller.String())
	if v == nil {
		panic("nothing pledged")
	}
	have := v.(uint64)
	if amount > have {
		panic("amount exceeds pledge")
	}
	if remaining := have - amount; remaining == 0 {
		c.pledges.Remove(caller.String())
	} else {
		c.pledges.Set(caller.String(), remaining)
	}
	c.Pledged -= amount
	chain.Emit("Unpledge",
		"id", strconv.Itoa(id),
		"from", caller.String(),
		"amount", strconv.FormatUint(amount, 10))
}

// Claim lets the creator take the funds if the goal was met after the deadline.
func Claim(cur realm, id int) {
	c := mustGet(id)
	if runtime.ChainHeight() <= c.Deadline {
		panic("campaign not ended")
	}
	caller := unsafe.PreviousRealm().Address()
	if caller != c.Creator {
		panic("only creator can claim")
	}
	if c.Pledged < c.Goal {
		panic("goal not reached")
	}
	if c.Claimed {
		panic("already claimed")
	}
	c.Claimed = true
	chain.Emit("Claim",
		"id", strconv.Itoa(id),
		"amount", strconv.FormatUint(c.Pledged, 10))
}

// Refund returns the caller's pledge if the campaign failed after the deadline.
func Refund(cur realm, id int) {
	c := mustGet(id)
	if runtime.ChainHeight() <= c.Deadline {
		panic("campaign not ended")
	}
	if c.Pledged >= c.Goal {
		panic("campaign succeeded, no refund")
	}
	caller := unsafe.PreviousRealm().Address()
	v := c.pledges.Get(caller.String())
	if v == nil {
		panic("nothing to refund")
	}
	amount := v.(uint64)
	c.pledges.Remove(caller.String())
	c.Pledged -= amount
	chain.Emit("Refund",
		"id", strconv.Itoa(id),
		"to", caller.String(),
		"amount", strconv.FormatUint(amount, 10))
}

// --- pure/read-only helpers (also used by Render) ---

// pct returns the funded percentage (0..100).
func pct(pledged, goal uint64) int {
	if goal == 0 {
		return 0
	}
	p := int(pledged * 100 / goal)
	if p > 100 {
		p = 100
	}
	return p
}

// progressBar renders a fixed-width ▓░ bar for pledged/goal.
func progressBar(pledged, goal uint64) string {
	const width = 20
	filled := 0
	if goal > 0 {
		filled = int(pledged * width / goal)
		if filled > width {
			filled = width
		}
	}
	bar := ""
	for i := 0; i < width; i++ {
		if i < filled {
			bar += "▓"
		} else {
			bar += "░"
		}
	}
	return bar
}

// state describes a campaign relative to a given block height.
func state(c *Campaign, height int64) string {
	if height <= c.Deadline {
		return "Active"
	}
	if c.Pledged >= c.Goal {
		if c.Claimed {
			return "Funded (claimed)"
		}
		return "Funded"
	}
	return "Failed"
}

// Render shows all campaigns with a progress bar, goal, pledged and state.
func Render(path string) string {
	if campaigns.Size() == 0 {
		return "# Crowdfund\n\nNo campaigns yet. Call `Launch(goal, durationBlocks)` to start one.\n"
	}
	height := runtime.ChainHeight()
	out := "# Crowdfund\n\n"
	out += "Current block height: **" + strconv.FormatInt(height, 10) + "**\n\n"
	campaigns.Iterate("", "", func(k string, v any) bool {
		c := v.(*Campaign)
		out += "## Campaign #" + strconv.Itoa(c.ID) + "\n\n"
		out += "`" + progressBar(c.Pledged, c.Goal) + "` " + strconv.Itoa(pct(c.Pledged, c.Goal)) + "%\n\n"
		out += "- State: **" + state(c, height) + "**\n"
		out += "- Goal: " + strconv.FormatUint(c.Goal, 10) + "\n"
		out += "- Pledged: " + strconv.FormatUint(c.Pledged, 10) + "\n"
		out += "- Deadline: block " + strconv.FormatInt(c.Deadline, 10) + "\n"
		out += "- Creator: `" + c.Creator.String() + "`\n\n"
		return false
	})
	return out
}

package crowdfund

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestProgressBarAndPct(t *testing.T) {
	uassert.Equal(t, "░░░░░░░░░░░░░░░░░░░░", progressBar(0, 100))
	uassert.Equal(t, "▓▓▓▓▓▓▓▓▓▓░░░░░░░░░░", progressBar(50, 100))
	uassert.Equal(t, "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓", progressBar(100, 100))
	// over-funded is capped at full width
	uassert.Equal(t, "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓", progressBar(250, 100))
	// zero goal never divides by zero
	uassert.Equal(t, "░░░░░░░░░░░░░░░░░░░░", progressBar(10, 0))

	uassert.Equal(t, 0, pct(0, 100))
	uassert.Equal(t, 25, pct(25, 100))
	uassert.Equal(t, 100, pct(100, 100))
	uassert.Equal(t, 100, pct(500, 100)) // capped
	uassert.Equal(t, 0, pct(5, 0))       // no goal
}

func TestState(t *testing.T) {
	active := &Campaign{Goal: 100, Pledged: 10, Deadline: 100}
	uassert.Equal(t, "Active", state(active, 50))
	uassert.Equal(t, "Active", state(active, 100)) // deadline block still active

	funded := &Campaign{Goal: 100, Pledged: 150, Deadline: 100}
	uassert.Equal(t, "Funded", state(funded, 101))

	claimed := &Campaign{Goal: 100, Pledged: 150, Deadline: 100, Claimed: true}
	uassert.Equal(t, "Funded (claimed)", state(claimed, 101))

	failed := &Campaign{Goal: 100, Pledged: 50, Deadline: 100}
	uassert.Equal(t, "Failed", state(failed, 101))

	// exactly meeting the goal counts as funded
	exact := &Campaign{Goal: 100, Pledged: 100, Deadline: 100}
	uassert.Equal(t, "Funded", state(exact, 200))
}

func TestKeyOrdering(t *testing.T) {
	uassert.Equal(t, "000000000001", key(1))
	uassert.Equal(t, "000000000042", key(42))
	// zero-padded keys keep numeric order under lexical string sort
	uassert.True(t, key(2) < key(10))
	uassert.True(t, key(9) < key(100))
}

