// resetState clears package globals between tests.
func resetState() {
	players = avl.Tree{}
	var zero address
	king = zero
	kingRoll = 0
	reignSince = 0
	nonce = 0
	totalRolls = 0
}

func TestPseudoRollDeterministicAndRanged(t *testing.T) {
	alice := testutils.TestAddress("alice")

	r1 := pseudoRoll(alice, 1, 100)
	r2 := pseudoRoll(alice, 1, 100)
	if r1 != r2 {
		t.Fatalf("same inputs must give same roll: %d != %d", r1, r2)
	}
	if r1 < 1 || r1 > 100 {
		t.Fatalf("roll must be in [1, 100], got %d", r1)
	}

	r3 := pseudoRoll(alice, 2, 100)
	if r1 == r3 {
		t.Fatal("different nonce should (almost always) change the roll")
	}
}

// Crossing test: takes `cur realm` so it can call crossing functions via
// cross(cur). SetRealm is called directly in this frame.
func TestRollCrownsFirstCallerThenSwapsOnHigherRoll(cur realm, t *testing.T) {
	resetState()

	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	testing.SetRealm(testing.NewUserRealm(alice))
	Roll(cross(cur))
	if !king.IsValid() {
		t.Fatal("someone should be king after first roll")
	}
	firstKing := king

	// Keep rolling as bob until bob out-rolls alice, or give up after a
	// generous number of attempts (rolls are deterministic per nonce/height,
	// so this always terminates locally).
	testing.SetRealm(testing.NewUserRealm(bob))
	for i := 0; i < 200 && king == firstKing; i++ {
		Roll(cross(cur))
	}

	if get(alice).reigns != 1 {
		t.Fatalf("alice should have exactly one recorded reign, got %d", get(alice).reigns)
	}
}

func TestRenderShowsNoKingThenKing(cur realm, t *testing.T) {
	resetState()
	if !strings.Contains(Render(""), "No king yet") {
		t.Fatal("expected empty-board placeholder")
	}

	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	Roll(cross(cur))

	out := Render("")
	if !strings.Contains(out, "Current king") {
		t.Fatal("expected current king section once someone rolled")
	}
	if !strings.Contains(out, "Blocks reigned") {
		t.Fatal("expected leaderboard header")
	}
}

package kudos

import (
	"chain"
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// counts maps an address (as string) -> number of kudos received.
var counts avl.Tree

// feed holds recent kudos, newest first, capped at feedCap entries.
var feed []kudo

const feedCap = 50

type kudo struct {
	from   address
	to     address
	reason string
}

// Give records a kudos from the caller to `to` with a reason.
// A caller cannot give kudos to themselves.
func Give(cur realm, to address, reason string) {
	from := unsafe.PreviousRealm().Address()
	if !to.IsValid() {
		panic("invalid recipient address")
	}
	if from == to {
		panic("cannot give kudos to yourself")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("reason must not be empty")
	}

	key := to.String()
	n := int64(0)
	if v := counts.Get(key); v != nil {
		n = v.(int64)
	}
	counts.Set(key, n+1)

	// prepend newest, cap the feed
	feed = append([]kudo{{from: from, to: to, reason: reason}}, feed...)
	if len(feed) > feedCap {
		feed = feed[:feedCap]
	}

	chain.Emit("KudosGiven", "from", from.String(), "to", to.String(), "reason", reason)
}

// entry is a leaderboard row used for deterministic sorting.
type entry struct {
	addr  string
	count int64
}

// byScore sorts by count desc, then address asc for stable ties.
type byScore []entry

func (s byScore) Len() int      { return len(s) }
func (s byScore) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byScore) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].addr < s[j].addr
}

func leaderboard() []entry {
	out := make([]entry, 0, counts.Size())
	counts.Iterate("", "", func(key string, value any) bool {
		out = append(out, entry{addr: key, count: value.(int64)})
		return false
	})
	sort.Sort(byScore(out))
	return out
}

// Render shows a leaderboard of most-received addresses and a recent feed.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Kudos\n\n")
	b.WriteString("Give props to addresses. `Give(to, reason)` records a kudos.\n\n")

	b.WriteString("## Leaderboard\n\n")
	lb := leaderboard()
	if len(lb) == 0 {
		b.WriteString("_No kudos yet._\n\n")
	} else {
		b.WriteString("| # | Address | Kudos |\n")
		b.WriteString("| --- | --- | --- |\n")
		for i, e := range lb {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + e.addr + " | " + strconv.FormatInt(e.count, 10) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Recent kudos\n\n")
	if len(feed) == 0 {
		b.WriteString("_Nothing here yet._\n")
	} else {
		for _, k := range feed {
			b.WriteString("- " + k.from.String() + " → " + k.to.String() + ": " + k.reason + "\n")
		}
	}

	return b.String()
}

