// Package multisig implements an M-of-N approval multisig realm.
//
// It is a port of the classic Solidity multisig idea: a fixed set of owners
// is configured once, any owner may create a proposal, owners approve it, and
// once the number of distinct approvals reaches the threshold the proposal is
// marked "Executed". This realm tracks approvals only — it does not move funds.
package multisig

import (
	"errors"
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// State of a single proposal.
type stateKind int

const (
	statePending stateKind = iota
	stateExecuted
)

func (s stateKind) String() string {
	if s == stateExecuted {
		return "Executed"
	}
	return "Pending"
}

// proposal is a single approval request.
type proposal struct {
	id          int
	description string
	proposer    address
	approvals   *avl.Tree // owner address string -> struct{}{}, distinct approvers
	state       stateKind
}

// Package-level persistent state.
var (
	owners      *avl.Tree // owner address string -> struct{}{}
	ownerCount  int
	threshold   int
	initialized bool

	proposals   *avl.Tree // decimal id string -> *proposal
	nextID      int
)

var (
	errAlreadyInit = errors.New("multisig: already initialized")
	errNotInit     = errors.New("multisig: not initialized")
	errBadThreshold = errors.New("multisig: threshold must be between 1 and number of owners")
	errNoOwners    = errors.New("multisig: at least one owner required")
	errNotOwner    = errors.New("multisig: caller is not an owner")
	errNoProposal  = errors.New("multisig: proposal not found")
	errDupApproval = errors.New("multisig: caller already approved this proposal")
	errExecuted    = errors.New("multisig: proposal already executed")
)

func init() {
	owners = avl.NewTree()
	proposals = avl.NewTree()
}

// caller returns the address of the realm/user that called into this realm.
func caller() address {
	return unsafe.PreviousRealm().Address()
}

func isOwner(a address) bool {
	return owners.Has(a.String())
}

// Setup configures the multisig exactly once. owners is a comma-separated list
// of bech32 addresses; threshold is the number of approvals required to execute
// a proposal. It panics (cross-realm abort) on invalid input or if already set.
func Setup(cur realm, ownersCSV string, thresholdN int) {
	if initialized {
		panic(errAlreadyInit)
	}

	parts := strings.Split(ownersCSV, ",")
	count := 0
	for _, p := range parts {
		a := strings.TrimSpace(p)
		if a == "" {
			continue
		}
		addr := address(a)
		if owners.Has(addr.String()) {
			continue // dedupe
		}
		owners.Set(addr.String(), struct{}{})
		count++
	}
	if count == 0 {
		panic(errNoOwners)
	}
	if thresholdN < 1 || thresholdN > count {
		panic(errBadThreshold)
	}

	ownerCount = count
	threshold = thresholdN
	initialized = true

	chain.Emit("Setup", "owners", strconv.Itoa(count), "threshold", strconv.Itoa(thresholdN))
}

// Propose creates a new proposal authored by an owner and returns its id.
func Propose(cur realm, description string) int {
	if !initialized {
		panic(errNotInit)
	}
	c := caller()
	if !isOwner(c) {
		panic(errNotOwner)
	}

	id := nextID
	nextID++

	p := &proposal{
		id:          id,
		description: description,
		proposer:    c,
		approvals:   avl.NewTree(),
		state:       statePending,
	}
	proposals.Set(strconv.Itoa(id), p)

	chain.Emit("Propose", "id", strconv.Itoa(id), "proposer", c.String())
	return id
}

// Approve records an owner's approval for a proposal. When the count of distinct
// approvals reaches the threshold, the proposal becomes Executed.
func Approve(cur realm, id int) {
	if !initialized {
		panic(errNotInit)
	}
	c := caller()
	if !isOwner(c) {
		panic(errNotOwner)
	}

	v := proposals.Get(strconv.Itoa(id))
	if v == nil {
		panic(errNoProposal)
	}
	p := v.(*proposal)
	if p.state == stateExecuted {
		panic(errExecuted)
	}
	if p.approvals.Has(c.String()) {
		panic(errDupApproval)
	}

	p.approvals.Set(c.String(), struct{}{})
	chain.Emit("Approve", "id", strconv.Itoa(id), "owner", c.String(), "approvals", strconv.Itoa(p.approvals.Size()))

	if p.approvals.Size() >= threshold {
		p.state = stateExecuted
		chain.Emit("Executed", "id", strconv.Itoa(id))
	}
}

// Render returns a Markdown view of the multisig configuration and proposals.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# M-of-N Multisig\n\n")

	if !initialized {
		b.WriteString("_Not initialized. Call `Setup(owners, threshold)` once._\n")
		return b.String()
	}

	b.WriteString("**Threshold:** ")
	b.WriteString(strconv.Itoa(threshold))
	b.WriteString(" of ")
	b.WriteString(strconv.Itoa(ownerCount))
	b.WriteString("\n\n## Owners\n\n")
	owners.Iterate("", "", func(key string, _ interface{}) bool {
		b.WriteString("- `")
		b.WriteString(key)
		b.WriteString("`\n")
		return false
	})

	b.WriteString("\n## Proposals\n\n")
	if proposals.Size() == 0 {
		b.WriteString("_No proposals yet._\n")
		return b.String()
	}

	b.WriteString("| ID | Description | Proposer | Approvals | State |\n")
	b.WriteString("|----|-------------|----------|-----------|-------|\n")
	proposals.Iterate("", "", func(_ string, v interface{}) bool {
		p := v.(*proposal)
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(p.id))
		b.WriteString(" | ")
		b.WriteString(p.description)
		b.WriteString(" | `")
		b.WriteString(p.proposer.String())
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(p.approvals.Size()))
		b.WriteString("/")
		b.WriteString(strconv.Itoa(threshold))
		b.WriteString(" | ")
		b.WriteString(p.state.String())
		b.WriteString(" |\n")
		return false
	})

	return b.String()
}

// Package numguess is a Number Guessing Game realm.
//
// A hidden target in 1..100 is derived deterministically from the block height
// at which the round started. Players call Guess(n) to receive "higher",
// "lower" or "correct". When a round is solved the winner is recorded on the
// leaderboard (ranked by fewest guesses) and anyone can start a fresh round.
package numguess

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// round holds the mutable state of the active game round.
type round struct {
	number      int    // 1-based round counter
	startHeight int64  // block height the round began at (entropy source)
	target      int    // hidden value in 1..100
	solved      bool   // set once someone guesses correctly
	lastHint    string // "higher" / "lower" / "correct" / "" for none yet
	winner      string // address of the solver, once solved
	winnerTries int    // attempts the winner needed
}

// winRecord is one leaderboard entry.
type winRecord struct {
	addr   string
	round  int
	tries  int
	target int
}

var (
	current *round
	// attempts counts guesses per address for the CURRENT round only.
	attempts = avl.NewTree() // addr(string) -> *int
	// leaderboard is append-only across all rounds; sorted on render.
	leaderboard []winRecord
)

func init() {
	current = newRound(1, runtime.ChainHeight())
}

// newRound builds a fresh round whose target derives deterministically from
// the start height. Gno has no runtime RNG, so height is the only entropy.
func newRound(number int, height int64) *round {
	return &round{
		number:      number,
		startHeight: height,
		target:      targetFromHeight(height),
		solved:      false,
		lastHint:    "",
	}
}

// targetFromHeight maps a block height to a hidden number in 1..100.
// Deterministic and cheap: a small integer mix so consecutive rounds don't
// land on obviously adjacent targets.
func targetFromHeight(h int64) int {
	if h < 0 {
		h = -h
	}
	mixed := (h*2654435761 + 12345)
	if mixed < 0 {
		mixed = -mixed
	}
	return int(mixed%100) + 1
}

// Guess submits a guess for the current round. It records the caller's attempt
// count and returns "higher", "lower" or "correct". Crossing function: caller
// invokes as Guess(cross(cur), n).
func Guess(cur realm, n int) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if n < 1 || n > 100 {
		panic("guess must be in 1..100")
	}
	if current.solved {
		panic("round already solved; call NewRound to start a fresh one")
	}

	caller := cur.Previous().Address().String()
	incAttempt(caller)

	var hint string
	switch {
	case n < current.target:
		hint = "higher"
	case n > current.target:
		hint = "lower"
	default:
		hint = "correct"
		current.solved = true
		current.winner = caller
		current.winnerTries = attemptsOf(caller)
		leaderboard = append(leaderboard, winRecord{
			addr:   caller,
			round:  current.number,
			tries:  current.winnerTries,
			target: current.target,
		})
		chain.Emit("RoundSolved",
			"round", strconv.Itoa(current.number),
			"winner", caller,
			"tries", strconv.Itoa(current.winnerTries),
		)
	}

	current.lastHint = hint
	return hint
}

// NewRound resets the game with a fresh target when the current round is
// solved. Panics if the current round is still open. Crossing function.
func NewRound(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if !current.solved {
		panic("current round is not solved yet")
	}

	next := current.number + 1
	current = newRound(next, runtime.ChainHeight())
	attempts = avl.NewTree() // per-round attempt counters reset
	chain.Emit("NewRound", "round", strconv.Itoa(next))
	return "round " + strconv.Itoa(next) + " started"
}

// incAttempt bumps the caller's attempt counter for the current round.
func incAttempt(addr string) {
	if v := attempts.Get(addr); v != nil {
		p := v.(*int)
		*p++
		return
	}
	one := 1
	attempts.Set(addr, &one)
}

// attemptsOf returns how many guesses addr has made this round.
func attemptsOf(addr string) int {
	if v := attempts.Get(addr); v != nil {
		return *(v.(*int))
	}
	return 0
}

// totalAttempts sums all attempts made in the current round.
func totalAttempts() int {
	total := 0
	attempts.Iterate("", "", func(_ string, v any) bool {
		total += *(v.(*int))
		return false
	})
	return total
}

// Render produces the gnoweb Markdown view of the current game state.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Number Guessing Game\n\n")
	b.WriteString("Guess the hidden number between **1** and **100**. ")
	b.WriteString("Each round's target is derived deterministically from the block height at which it started.\n\n")

	b.WriteString("## Current round\n\n")
	b.WriteString("- Round: **" + strconv.Itoa(current.number) + "**\n")
	b.WriteString("- Started at block height: " + strconv.FormatInt(current.startHeight, 10) + "\n")
	b.WriteString("- Attempts so far (this round): " + strconv.Itoa(totalAttempts()) + "\n")

	hint := current.lastHint
	if hint == "" {
		hint = "_no guesses yet_"
	} else {
		hint = "`" + hint + "`"
	}
	b.WriteString("- Last hint: " + hint + "\n")

	if current.solved {
		b.WriteString("- Status: **solved** by `" + current.winner + "` in " +
			strconv.Itoa(current.winnerTries) + " guess(es). ")
		b.WriteString("Call `NewRound()` to play again.\n")
	} else {
		b.WriteString("- Status: **open** — call `Guess(n)` to play.\n")
	}
	b.WriteString("\n")

	b.WriteString("## Leaderboard\n\n")
	b.WriteString(renderLeaderboard())

	b.WriteString("\n## How to play\n\n")
	b.WriteString("```\n")
	b.WriteString("Guess(n)     // n in 1..100 -> \"higher\" | \"lower\" | \"correct\"\n")
	b.WriteString("NewRound()   // start a fresh round once the current one is solved\n")
	b.WriteString("```\n")

	return b.String()
}

// renderLeaderboard formats winners ranked by fewest guesses (ties: earlier
// round first). Sorted on a copy so state is untouched.
func renderLeaderboard() string {
	if len(leaderboard) == 0 {
		return "_No winners yet — be the first!_\n"
	}

	ranked := make([]winRecord, len(leaderboard))
	copy(ranked, leaderboard)
	sortByFewestTries(ranked)

	var b strings.Builder
	b.WriteString("| Rank | Player | Round | Guesses | Target |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for i, w := range ranked {
		b.WriteString("| " + strconv.Itoa(i+1) + " | `" + w.addr + "` | " +
			strconv.Itoa(w.round) + " | " + strconv.Itoa(w.tries) + " | " +
			strconv.Itoa(w.target) + " |\n")
	}
	return b.String()
}

// sortByFewestTries does an in-place insertion sort: fewer tries first, then
// earlier round first on ties. Small n; insertion sort keeps it deterministic
// and dependency-free.
func sortByFewestTries(rs []winRecord) {
	for i := 1; i < len(rs); i++ {
		j := i
		for j > 0 && less(rs[j], rs[j-1]) {
			rs[j], rs[j-1] = rs[j-1], rs[j]
			j--
		}
	}
}

func less(a, b winRecord) bool {
	if a.tries != b.tries {
		return a.tries < b.tries
	}
	return a.round < b.round
}

package numguess

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
)

// resetGame re-initializes package globals so each test starts clean; init()
// runs only once for the whole test binary, and t.Run subtests don't reset it.
func resetGame(height int64) {
	current = newRound(1, height)
	attempts = avl.NewTree()
	leaderboard = nil
}

func TestTargetFromHeight(t *testing.T) {
	tests := []struct {
		name   string
		height int64
	}{
		{"zero", 0},
		{"one", 1},
		{"large", 123456},
		{"negative", -42},
	}
	for _, tt := range tests {
		got := targetFromHeight(tt.height)
		if got < 1 || got > 100 {
			t.Errorf("%s: targetFromHeight(%d)=%d, want in 1..100", tt.name, tt.height, got)
		}
		// determinism: same input -> same output
		if again := targetFromHeight(tt.height); again != got {
			t.Errorf("%s: non-deterministic: %d != %d", tt.name, again, got)
		}
	}
}

// TestGuessHigherLowerCorrect exercises the crossing Guess function, so it
// takes cur realm and calls through cross(cur).
func TestGuessHigherLowerCorrect(cur realm, t *testing.T) {
	resetGame(50)
	target := current.target

	low := target - 1
	if low < 1 {
		low = 1
	}
	high := target + 1
	if high > 100 {
		high = 100
	}

	if low != target {
		if got := Guess(cross(cur), low); got != "higher" {
			t.Errorf("Guess(%d) with target %d = %q, want higher", low, target, got)
		}
	}
	if high != target {
		if got := Guess(cross(cur), high); got != "lower" {
			t.Errorf("Guess(%d) with target %d = %q, want lower", high, target, got)
		}
	}

	got := Guess(cross(cur), target)
	if got != "correct" {
		t.Fatalf("Guess(%d) = %q, want correct", target, got)
	}
	if !current.solved {
		t.Error("round should be solved after correct guess")
	}
	if len(leaderboard) != 1 {
		t.Errorf("leaderboard len = %d, want 1", len(leaderboard))
	}
}

// TestNewRoundResets solves a round then verifies NewRound advances the round
// number and clears attempts.
func TestNewRoundResets(cur realm, t *testing.T) {
	resetGame(7)
	target := current.target

	Guess(cross(cur), target) // solve it
	if !current.solved {
		t.Fatal("expected solved round")
	}
	prevRound := current.number

	testing.SkipHeights(11) // change height so the next target can differ
	msg := NewRound(cross(cur))
	if current.number != prevRound+1 {
		t.Errorf("round number = %d, want %d", current.number, prevRound+1)
	}
	if current.solved {
		t.Error("fresh round should not be solved")
	}
	if totalAttempts() != 0 {
		t.Errorf("attempts should reset, got %d", totalAttempts())
	}
	if !strings.Contains(msg, "started") {
		t.Errorf("NewRound message = %q, want it to mention 'started'", msg)
	}
}

// TestRenderContainsState is a plain read — no cur.
func TestRenderContainsState(t *testing.T) {
	resetGame(3)
	out := Render("")
	for _, want := range []string{"Number Guessing Game", "Current round", "Leaderboard"} {
		if !strings.Contains(out, want) {
			t.Errorf("Render() missing %q", want)
		}
	}
}

// Package pixelcanvas is a shared 16x16 pixel canvas: anyone can paint one
// cell at a time from a fixed 9-colour palette, and the canvas renders in
// gnoweb as a grid of coloured blocks.
//
// The canvas is a flat [Size*Size]int of palette indices held in realm state —
// a fixed-size array rather than a tree, because every cell exists from the
// start and the grid is walked in full on every render. Painting is
// last-write-wins; the realm keeps who painted each cell and a per-address
// tally, so the board doubles as a contribution leaderboard.
//
// A stateful app with nothing reusable to extract, so it ships as a lone realm
// rather than a p/ library + demo pair.
package pixelcanvas

import (
	"sort"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Size is the canvas edge length; the canvas is Size x Size cells.
const Size = 16

// palette maps a colour index to the block rendered for it. Index 0 is the
// blank canvas. Kept parallel to paletteNames.
var palette = []string{"⬜", "🟥", "🟧", "🟨", "🟩", "🟦", "🟪", "🟫", "⬛"}

// paletteNames are the names Paint accepts, in palette order.
var paletteNames = []string{"white", "red", "orange", "yellow", "green", "blue", "purple", "brown", "black"}

// Package-level persistent state.
var (
	cells    [Size * Size]int // palette index per cell, row-major
	painters [Size * Size]string
	tally    = avl.NewTree() // address string -> *int paint count
	strokes  int             // total paints ever
	lastAt   int64           // height of the most recent paint
)

// Paint colours the cell at (x, y) and returns the total number of strokes.
//
// Coordinates are 0-based with (0,0) at the top-left. Colour is a palette name
// ("red", "blue", …) — see Palette. Painting over an existing cell is allowed:
// the canvas is last-write-wins, which is the whole point of a shared board.
func Paint(cur realm, x, y int, colour string) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can paint")
	}
	if x < 0 || x >= Size || y < 0 || y >= Size {
		panic("out of bounds: x and y must be in [0," + strconv.Itoa(Size-1) + "]")
	}
	idx := colourIndex(colour)
	if idx < 0 {
		panic("unknown colour " + strconv.Quote(colour) + "; see Palette()")
	}

	addr := prev.Address()
	i := y*Size + x
	cells[i] = idx
	painters[i] = addr.String()
	strokes++
	lastAt = runtime.ChainHeight()
	bump(addr.String())

	chain.Emit("Paint",
		"addr", addr.String(),
		"x", strconv.Itoa(x),
		"y", strconv.Itoa(y),
		"colour", paletteNames[idx],
	)
	return strokes
}

// colourIndex resolves a palette name to its index, or -1.
func colourIndex(name string) int {
	n := strings.ToLower(strings.TrimSpace(name))
	for i, p := range paletteNames {
		if p == n {
			return i
		}
	}
	return -1
}

// bump increments an address's paint tally.
func bump(addr string) {
	// avl/v0's Get returns a single `any`; a miss is a nil interface.
	if v := tally.Get(addr); v != nil {
		c := v.(*int)
		*c++
		return
	}
	one := 1
	tally.Set(addr, &one)
}

// At returns the palette name of the cell at (x, y), or "" when out of bounds.
func At(x, y int) string {
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return ""
	}
	return paletteNames[cells[y*Size+x]]
}

// PainterAt returns the address that last painted (x, y), or "" if untouched.
func PainterAt(x, y int) string {
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return ""
	}
	return painters[y*Size+x]
}

// Strokes returns how many paints the canvas has taken.
func Strokes() int { return strokes }

// Palette returns the accepted colour names, comma-separated.
func Palette() string { return strings.Join(paletteNames, ", ") }

// scorer is one row of the contribution leaderboard.
type scorer struct {
	addr  string
	count int
}

// byCount ranks painters by strokes descending, ties broken on address so the
// board is deterministic.
type byCount []scorer

func (s byCount) Len() int      { return len(s) }
func (s byCount) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byCount) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].addr < s[j].addr
}

// Render renders the canvas for gnoweb.
//
//	Render("")        / Render("/") -> the canvas, palette and leaderboard
//	Render("/<x>,<y>")              -> who painted that cell, and what colour
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Pixel Canvas\n\n")
	b.WriteString("A shared ")
	b.WriteString(strconv.Itoa(Size))
	b.WriteString("x")
	b.WriteString(strconv.Itoa(Size))
	b.WriteString(" canvas. Anyone can `Paint(x, y, colour)` — last write wins.\n\n")

	if q := parseArg(path); q != "" {
		return b.String() + renderCell(q)
	}

	b.WriteString(grid())
	b.WriteString("\n**")
	b.WriteString(strconv.Itoa(strokes))
	b.WriteString("** stroke")
	if strokes != 1 {
		b.WriteString("s")
	}
	b.WriteString(" · palette: ")
	b.WriteString(Palette())
	b.WriteString("\n")

	if board := leaderboard(); board != "" {
		b.WriteString("\n## Top painters\n\n")
		b.WriteString(board)
	}
	return b.String()
}

// grid renders the canvas as rows of coloured blocks.
func grid() string {
	var b strings.Builder
	for y := 0; y < Size; y++ {
		for x := 0; x < Size; x++ {
			b.WriteString(palette[cells[y*Size+x]])
		}
		b.WriteString("\n")
	}
	return b.String()
}

// leaderboard renders the top painters, or "" when nobody has painted.
func leaderboard() string {
	scores := []scorer{}
	tally.Iterate("", "", func(k string, v any) bool {
		scores = append(scores, scorer{addr: k, count: *(v.(*int))})
		return false
	})
	if len(scores) == 0 {
		return ""
	}
	sort.Sort(byCount(scores))
	if len(scores) > 5 {
		scores = scores[:5]
	}

	var b strings.Builder
	b.WriteString("| # | address | strokes |\n|---|---|---|\n")
	for i, s := range scores {
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(" | `")
		b.WriteString(s.addr)
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(s.count))
		b.WriteString(" |\n")
	}
	return b.String()
}

// renderCell renders a single "x,y" lookup.
func renderCell(q string) string {
	var b strings.Builder
	x, y, ok := parseCoord(q)
	if !ok {
		b.WriteString("_Expected `x,y` — e.g. `/3,7`._\n")
		return b.String()
	}
	b.WriteString("## Cell (")
	b.WriteString(strconv.Itoa(x))
	b.WriteString(", ")
	b.WriteString(strconv.Itoa(y))
	b.WriteString(")\n\n")
	b.WriteString(palette[cells[y*Size+x]])
	b.WriteString(" **")
	b.WriteString(At(x, y))
	b.WriteString("**\n\n")
	if p := PainterAt(x, y); p != "" {
		b.WriteString("Painted by `")
		b.WriteString(p)
		b.WriteString("`.\n")
	} else {
		b.WriteString("_Never painted._\n")
	}
	return b.String()
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

// parseCoord parses "x,y" and reports whether it is in bounds.
func parseCoord(s string) (int, int, bool) {
	i := strings.IndexByte(s, ',')
	if i < 0 {
		return 0, 0, false
	}
	x, err := strconv.Atoi(strings.TrimSpace(s[:i]))
	if err != nil {
		return 0, 0, false
	}
	y, err2 := strconv.Atoi(strings.TrimSpace(s[i+1:]))
	if err2 != nil {
		return 0, 0, false
	}
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return 0, 0, false
	}
	return x, y, true
}

package pixelcanvas

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// reset clears realm state between tests.
func reset() {
	for i := range cells {
		cells[i] = 0
		painters[i] = ""
	}
	tally = avl.NewTree()
	strokes = 0
	lastAt = 0
}

// paint runs a Paint as addr.
func paint(cur realm, addr address, x, y int, colour string) int {
	testing.SetRealm(testing.NewUserRealm(addr))
	return Paint(cross(cur), x, y, colour)
}

func TestPaintSetsCellAndPainter(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")

	uassert.Equal(t, 1, paint(cur, alice, 3, 7, "red"))
	uassert.Equal(t, "red", At(3, 7))
	uassert.Equal(t, alice.String(), PainterAt(3, 7))
	uassert.Equal(t, 1, Strokes())
}

// (x, y) is column, row — a paint at (3,7) must not land at (7,3).
func TestCoordinatesAreXThenY(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	paint(cur, alice, 3, 7, "blue")

	uassert.Equal(t, "blue", At(3, 7))
	uassert.Equal(t, "white", At(7, 3))
}

func TestLastWriteWins(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	paint(cur, alice, 0, 0, "red")
	paint(cur, bob, 0, 0, "green")

	uassert.Equal(t, "green", At(0, 0))
	uassert.Equal(t, bob.String(), PainterAt(0, 0))
	uassert.Equal(t, 2, Strokes()) // both strokes still counted
}

func TestOutOfBoundsPanics(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	cases := [][2]int{{-1, 0}, {0, -1}, {Size, 0}, {0, Size}}
