package timelock

// ExampleRender pins the realm's Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Timelock Controller
	//
	// Current chain height: **123**
	//
	// _No operations scheduled yet._
	//
	// Call `Schedule(action, delayBlocks)` to queue one.
}

// Package timelock is a simplified port of OpenZeppelin's TimelockController.
//
// Operations are scheduled with a delay (measured in blocks). A scheduled
// operation becomes executable only once the chain height reaches the
// operation's ready height. Until then it can be cancelled by anyone (this
// simplified port omits role-based access control). Once executed or
// cancelled, an operation is terminal.
//
// Solidity mapping:
//   - block.number      -> runtime.ChainHeight()
//   - msg.sender        -> unsafe.PreviousRealm().Address()
//   - require(...)       -> panic(...)
//   - events            -> chain.Emit(...)
//   - mapping(id => op) -> avl.Tree keyed by zero-padded id
package timelock

import (
	"strconv"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// State labels for an operation.
const (
	StatePending   = "Pending"   // scheduled, not yet ready
	StateReady     = "Ready"     // ready height reached, awaiting execution
	StateExecuted  = "Executed"  // terminal
	StateCancelled = "Cancelled" // terminal
)

// Operation is a single scheduled action.
type Operation struct {
	ID          int
	Action      string
	Proposer    address
	Scheduled   int64 // chain height at scheduling
	ReadyHeight int64 // executable once ChainHeight() >= ReadyHeight
	Done        bool  // executed
	Cancelled   bool
}

var (
	ops    = avl.NewTree() // key: paddedKey(id) -> *Operation
	nextID = 1
)

// Schedule registers a new operation to run after delayBlocks blocks and
// returns its id. delayBlocks must be >= 0.
func Schedule(cur realm, action string, delayBlocks int) int {
	if action == "" {
		panic("timelock: empty action")
	}
	if delayBlocks < 0 {
		panic("timelock: negative delay")
	}

	h := runtime.ChainHeight()
	id := nextID
	nextID++

	op := &Operation{
		ID:          id,
		Action:      action,
		Proposer:    unsafe.PreviousRealm().Address(),
		Scheduled:   h,
		ReadyHeight: h + int64(delayBlocks),
	}
	ops.Set(paddedKey(id), op)

	chain.Emit("Scheduled",
		"id", strconv.Itoa(id),
		"action", action,
		"readyHeight", strconv.FormatInt(op.ReadyHeight, 10),
	)
	return id
}

// Execute runs a ready operation. It panics if the operation is unknown,
// already terminal, or not yet ready.
func Execute(cur realm, id int) {
	op := mustGet(id)
	if op.Done {
		panic("timelock: already executed")
	}
	if op.Cancelled {
		panic("timelock: operation cancelled")
	}
	if runtime.ChainHeight() < op.ReadyHeight {
		panic("timelock: operation not ready")
	}
	op.Done = true

	chain.Emit("Executed", "id", strconv.Itoa(id), "action", op.Action)
}

// Cancel drops a pending or ready operation before it executes. It panics if
// the operation is unknown or already terminal.
func Cancel(cur realm, id int) {
	op := mustGet(id)
	if op.Done {
		panic("timelock: already executed")
	}
	if op.Cancelled {
		panic("timelock: already cancelled")
	}
	op.Cancelled = true

	chain.Emit("Cancelled", "id", strconv.Itoa(id), "action", op.Action)
}

// mustGet returns the operation or panics if absent.
func mustGet(id int) *Operation {
	v := ops.Get(paddedKey(id))
	if v == nil {
		panic("timelock: unknown operation")
	}
	return v.(*Operation)
}

// --- pure/read-only helpers (safe to unit-test) ---

// paddedKey returns a fixed-width, lexicographically sortable key for an id so
// avl iteration yields operations in id order.
func paddedKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// StateOf returns the display state of op at the given chain height.
func StateOf(op *Operation, height int64) string {
	switch {
	case op.Cancelled:
		return StateCancelled
	case op.Done:
		return StateExecuted
	case height >= op.ReadyHeight:
		return StateReady
	default:
		return StatePending
	}
}

// BlocksRemaining returns how many blocks remain before op is ready (0 if
// already ready or past).
func BlocksRemaining(op *Operation, height int64) int64 {
	if height >= op.ReadyHeight {
		return 0
	}
	return op.ReadyHeight - height
}

// Render implements the standard realm markdown view.
func Render(path string) string {
	h := runtime.ChainHeight()
	out := "# Timelock Controller\n\n"
	out += ufmt.Sprintf("Current chain height: **%d**\n\n", h)

	if ops.Size() == 0 {
		out += "_No operations scheduled yet._\n\n"
		out += "Call `Schedule(action, delayBlocks)` to queue one.\n"
		return out
	}

	out += ufmt.Sprintf("Total operations: **%d**\n\n", ops.Size())
	out += "| ID | Action | State | Ready @ | Blocks left | Proposer |\n"
	out += "|---:|--------|-------|--------:|------------:|----------|\n"

	ops.Iterate("", "", func(_ string, v any) bool {
		op := v.(*Operation)
		state := StateOf(op, h)
		left := BlocksRemaining(op, h)
		out += ufmt.Sprintf("| %d | %s | %s | %d | %d | %s |\n",
			op.ID, op.Action, state, op.ReadyHeight, left, op.Proposer.String())
		return false
	})
	return out
}

package timelock

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestStateOf(t *testing.T) {
	base := &Operation{ID: 1, Action: "upgrade", ReadyHeight: 100}

	// Before ready height -> Pending.
	uassert.Equal(t, StatePending, StateOf(base, 50))
	// At/after ready height -> Ready.
	uassert.Equal(t, StateReady, StateOf(base, 100))
	uassert.Equal(t, StateReady, StateOf(base, 150))

	// Executed and cancelled are terminal regardless of height.
	done := &Operation{ID: 2, ReadyHeight: 10, Done: true}
	uassert.Equal(t, StateExecuted, StateOf(done, 5))
	uassert.Equal(t, StateExecuted, StateOf(done, 999))

	cancelled := &Operation{ID: 3, ReadyHeight: 10, Cancelled: true}
	uassert.Equal(t, StateCancelled, StateOf(cancelled, 5))
	uassert.Equal(t, StateCancelled, StateOf(cancelled, 999))
}

func TestBlocksRemaining(t *testing.T) {
	op := &Operation{ID: 1, ReadyHeight: 100}

	uassert.Equal(t, int64(100), BlocksRemaining(op, 0))
	uassert.Equal(t, int64(40), BlocksRemaining(op, 60))
	// At ready height and beyond -> 0.
	uassert.Equal(t, int64(0), BlocksRemaining(op, 100))
	uassert.Equal(t, int64(0), BlocksRemaining(op, 250))
}

func TestPaddedKeyOrdering(t *testing.T) {
	// Keys must be fixed-width so lexical order matches numeric id order.
	uassert.True(t, paddedKey(2) < paddedKey(10))
	uassert.True(t, paddedKey(9) < paddedKey(100))
	uassert.Equal(t, len(paddedKey(1)), len(paddedKey(123456)))
}

// Package tipjar is a public tip jar. Anyone can send real ugnot with an
// optional message via Tip; the realm keeps a running leaderboard of the
// most generous tippers and a feed of the most recent tips, both shown in
// Render. Only the deployer (captured as owner at init time) can Withdraw
// the accumulated balance. State-mutating functions are crossing functions
// (`cur realm`) per the gno 0.9 interrealm convention.
package tipjar

import (
	"sort"
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const (
	denom         = "ugnot"
	maxRecent     = 10
	maxMessageLen = 140
)

// tipperStats is the persisted, accumulated record for one tipper.
type tipperStats struct {
	addr        address
	total       int64
	count       int
	lastMessage string
	lastHeight  int64
}

// tipEntry is one line in the recent-tips feed.
type tipEntry struct {
	from    address
	amount  int64
	message string
	height  int64
}

var (
	owner address // captured deployer, set once in init

	tippers avl.Tree // address string -> *tipperStats
	recent  []tipEntry

	totalReceived int64
	withdrawn     int64
	tipCount      int
)

func init() {
	owner = unsafe.OriginCaller()
}

// get returns the stored *tipperStats for addr, creating one if absent.
func get(addr address) *tipperStats {
	key := addr.String()
	if v := tippers.Get(key); v != nil {
		return v.(*tipperStats)
	}
	ts := &tipperStats{addr: addr}
	tippers.Set(key, ts)
	return ts
}

// Tip credits the caller's OriginSend ugnot to the jar and records it
// against their running total. Only an EOA calling directly via MsgCall may
// tip — see the payment-guard note on IsUserCall vs IsUser.
func Tip(cur realm, message string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can tip")
	}
	if len(message) > maxMessageLen {
		panic("message too long (max " + strconv.Itoa(maxMessageLen) + " chars)")
	}

	amount := unsafe.OriginSend().AmountOf(denom)
	if amount <= 0 {
		panic("send some ugnot to tip")
	}

	from := prev.Address()
	height := runtime.ChainHeight()

	ts := get(from)
	ts.total += amount
	ts.count++
	ts.lastMessage = message
	ts.lastHeight = height

	totalReceived += amount
	tipCount++

	recent = append(recent, tipEntry{from: from, amount: amount, message: message, height: height})
	if len(recent) > maxRecent {
		recent = recent[len(recent)-maxRecent:]
	}

	chain.Emit("Tip", "from", from.String(), "amount", strconv.FormatInt(amount, 10), "message", message)
	return "thanks for the " + strconv.FormatInt(amount, 10) + "ugnot tip!"
}

// Balance reports the ugnot still held by the jar (received minus withdrawn).
func Balance() int64 {
	return totalReceived - withdrawn
}

// Withdraw sends amount ugnot from the jar to the owner. Owner-only.
func Withdraw(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != owner {
		panic("only the owner can withdraw")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > Balance() {
		panic("amount exceeds available balance")
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), owner, chain.NewCoins(chain.NewCoin(denom, amount)))
	withdrawn += amount

	chain.Emit("Withdraw", "amount", strconv.FormatInt(amount, 10))
}

// byTotal implements sort.Interface, ranking tippers by total tipped
// descending, ties broken by tip count then address for a fully
// deterministic order.
type byTotal struct {
	stats []*tipperStats
}

func (b byTotal) Len() int      { return len(b.stats) }
func (b byTotal) Swap(i, j int) { b.stats[i], b.stats[j] = b.stats[j], b.stats[i] }
func (b byTotal) Less(i, j int) bool {
	if b.stats[i].total != b.stats[j].total {
		return b.stats[i].total > b.stats[j].total
	}
	if b.stats[i].count != b.stats[j].count {
		return b.stats[i].count > b.stats[j].count
	}
	return b.stats[i].addr.String() < b.stats[j].addr.String()
}

// leaderboard collects all tippers ranked by total tipped descending.
func leaderboard() []*tipperStats {
	stats := make([]*tipperStats, 0, tippers.Size())
	tippers.Iterate("", "", func(_ string, v any) bool {
		stats = append(stats, v.(*tipperStats))
		return false
	})
	sort.Stable(byTotal{stats: stats})
	return stats
}

// medal returns the emoji for a given zero-based rank, or "" past the podium.
func medal(rank int) string {
	switch rank {
	case 0:
		return "🥇"
	case 1:
		return "🥈"
	case 2:
		return "🥉"
	default:
		return ""
	}
}

// display returns a shortened address for table display.
func display(addr address) string {
	s := addr.String()
	if len(s) > 12 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// Render shows the jar's balance, the tipper leaderboard, and a feed of the
// most recent tips.
func Render(path string) string {
	out := "# 🫙 Tip Jar\n\n"
	out += "Send ugnot with `Tip(message)` to leave a tip and a note. " +
		"The owner can withdraw the accumulated balance with `Withdraw(amount)`.\n\n"

	out += "**Balance:** " + strconv.FormatInt(Balance(), 10) + "ugnot" +
		"  ·  **Total tips:** " + strconv.Itoa(tipCount) +
		"  ·  **All-time received:** " + strconv.FormatInt(totalReceived, 10) + "ugnot\n\n"

	stats := leaderboard()
	out += "## Leaderboard\n\n"
	if len(stats) == 0 {
		out += "_No tips yet. Be the first!_\n\n"
	} else {
		out += "| Rank | Tipper | Total tipped | Tips |\n"
		out += "| ---: | :--- | ---: | ---: |\n"
		for i, ts := range stats {
			rankCell := medal(i)
			if rankCell == "" {
				rankCell = strconv.Itoa(i + 1)
			}
			out += "| " + rankCell +
				" | " + display(ts.addr) +
				" | " + strconv.FormatInt(ts.total, 10) + "ugnot" +
				" | " + strconv.Itoa(ts.count) + " |\n"
		}
		out += "\n"
	}

	out += "## Recent tips\n\n"
	if len(recent) == 0 {
		out += "_Nothing yet._\n"
		return out
	}
	for i := len(recent) - 1; i >= 0; i-- {
		e := recent[i]
		out += "- **" + display(e.from) + "** tipped " + strconv.FormatInt(e.amount, 10) +
			"ugnot at block " + strconv.FormatInt(e.height, 10)
		if e.message != "" {
			out += ": _" + e.message + "_"
		}
		out += "\n"
	}
	return out
}

