// Package todos is a shared, on-chain to-do board realm.
//
// Anyone can add an item; the caller's address is recorded as the author.
// Items can be toggled (open/done) or removed. Render exposes the board as
// Markdown checkboxes with open/done counts, newest item first.
package todos

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// item is one entry on the board. `address` is the uverse bech32 type — it is
// persistable (unlike a `realm` value), so it is safe to store across txs.
type item struct {
	id     int
	text   string
	done   bool
	author address
}

var (
	// items is keyed by zero-padded id string so avl iteration is ordered by id.
	items  avl.Tree
	nextID int
)

// Add appends a new item authored by the caller and returns its id.
//
// Crossing function: takes `cur realm` first (gno 0.9 interrealm convention),
// authenticates with cur.IsCurrent() before trusting cur.Previous().
func Add(cur realm, text string) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	text = strings.TrimSpace(text)
	if text == "" {
		panic("todos: text must not be empty")
	}

	author := cur.Previous().Address()

	nextID++
	id := nextID
	items.Set(idKey(id), &item{
		id:     id,
		text:   text,
		done:   false,
		author: author,
	})
	return id
}

// Toggle flips the done state of the item with the given id.
func Toggle(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := items.Get(idKey(id))
	if v == nil {
		panic("todos: item not found: #" + strconv.Itoa(id))
	}
	it := v.(*item)
	it.done = !it.done
}

// Remove deletes the item with the given id.
func Remove(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if _, removed := items.Remove(idKey(id)); !removed {
		panic("todos: item not found: #" + strconv.Itoa(id))
	}
}

// idKey renders an id as a fixed-width, zero-padded key so avl.Tree's
// byte-lexicographic ordering matches numeric id ordering.
func idKey(id int) string {
	s := strconv.Itoa(id)
	const width = 12
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// shortAddr renders an address as "g1abc…" (first 6 chars + ellipsis).
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 6 {
		return s
	}
	return s[:6] + "…"
}

// counts returns the number of open and done items.
func counts() (open, done int) {
	items.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*item).done {
			done++
		} else {
			open++
		}
		return false
	})
	return open, done
}

// Render returns the board as Markdown. Newest item (highest id) first.
//
// Render is NOT a crossing function (no `cur realm` param) — it is read-only
// and invoked by gnoweb, not via MsgCall.
func Render(path string) string {
	open, done := counts()

	var b strings.Builder
	b.WriteString("# Shared To-Do Board\n\n")
	b.WriteString(strconv.Itoa(open) + " open · ")
	b.WriteString(strconv.Itoa(done) + " done · ")
	b.WriteString(strconv.Itoa(open+done) + " total\n\n")

	if open+done == 0 {
		b.WriteString("_No items yet. Add one with `Add(text)`._\n")
		return b.String()
	}

	// Collect in ascending id order, then emit newest first.
	var lines []string
	items.Iterate("", "", func(_ string, v interface{}) bool {
		it := v.(*item)
		mark := " "
		if it.done {
			mark = "x"
		}
		line := "- [" + mark + "] #" + strconv.Itoa(it.id) + " " +
			it.text + " (" + shortAddr(it.author) + ")"
		lines = append(lines, line)
		return false
	})

	for i := len(lines) - 1; i >= 0; i-- {
		b.WriteString(lines[i])
		b.WriteString("\n")
	}

	return b.String()
}

package todos

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
)

// reset clears package globals between tests (t.Run/subtests do not reset them).
func reset() {
	items = avl.Tree{}
	nextID = 0
}

// TestAddToggleRemove exercises the full lifecycle through the crossing API.
// Crossing test: takes `cur realm` and calls via cross(cur).
func TestAddToggleRemove(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	id1 := Add(cross(cur), "buy milk")
	if id1 != 1 {
		t.Fatalf("Add first id = %d, want 1", id1)
	}
	id2 := Add(cross(cur), "walk dog")
	if id2 != 2 {
		t.Fatalf("Add second id = %d, want 2", id2)
	}

	open, done := counts()
	if open != 2 || done != 0 {
		t.Fatalf("after adds: open=%d done=%d, want 2/0", open, done)
	}

	// Toggle #1 done.
	Toggle(cross(cur), 1)
	open, done = counts()
	if open != 1 || done != 1 {
		t.Fatalf("after toggle: open=%d done=%d, want 1/1", open, done)
	}

	// Toggle #1 back to open.
	Toggle(cross(cur), 1)
	open, done = counts()
	if open != 2 || done != 0 {
		t.Fatalf("after re-toggle: open=%d done=%d, want 2/0", open, done)
	}

	// Remove #1.
	Remove(cross(cur), 1)
	open, done = counts()
	if open != 1 || done != 0 {
		t.Fatalf("after remove: open=%d done=%d, want 1/0", open, done)
	}
	if items.Has(idKey(1)) {
		t.Fatalf("item #1 still present after Remove")
	}
}

// TestRender checks the Markdown output shape and counts. Render is not a
// crossing function, so this is a plain test — but the Add calls that seed
// state still need a realm, so it also takes `cur realm`.
func TestRender(cur realm, t *testing.T) {
	reset()

	// Empty board.
	empty := Render("")
	if !strings.Contains(empty, "0 open · 0 done · 0 total") {
		t.Fatalf("empty render missing zero counts:\n%s", empty)
	}
	if !strings.Contains(empty, "No items yet") {
		t.Fatalf("empty render missing placeholder:\n%s", empty)
	}

	bob := testutils.TestAddress("bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	Add(cross(cur), "first")
	Add(cross(cur), "second")
	Add(cross(cur), "third")
	Toggle(cross(cur), 2) // mark #2 done

	out := Render("")

	// Counts line: 2 open, 1 done, 3 total.
	if !strings.Contains(out, "2 open · 1 done · 3 total") {
		t.Fatalf("render counts wrong:\n%s", out)
	}
	// Done checkbox for #2.
	if !strings.Contains(out, "- [x] #2 second") {
		t.Fatalf("render missing done item #2:\n%s", out)
	}
	// Open checkbox for #1.
	if !strings.Contains(out, "- [ ] #1 first") {
		t.Fatalf("render missing open item #1:\n%s", out)
	}
	// Newest first: #3 must appear before #1.
	if strings.Index(out, "#3 third") > strings.Index(out, "#1 first") {
		t.Fatalf("render not newest-first:\n%s", out)
	}
	// Author short form present.
	if !strings.Contains(out, "(g1") {
		t.Fatalf("render missing author short address:\n%s", out)
	}
}

// TestIDKeyOrdering verifies idKey produces lexicographically-ordered keys so
// avl iteration matches numeric id order. Non-crossing: plain signature.
func TestIDKeyOrdering(t *testing.T) {
	if idKey(2) >= idKey(10) {
		t.Fatalf("idKey(2)=%q should sort before idKey(10)=%q", idKey(2), idKey(10))
	}
	if idKey(9) >= idKey(100) {
		t.Fatalf("idKey(9)=%q should sort before idKey(100)=%q", idKey(9), idKey(100))
	}
	if len(idKey(1)) != 12 {
		t.Fatalf("idKey width = %d, want 12", len(idKey(1)))
	}
}

// Package trivia is a rotating multiple-choice trivia quiz realm.
//
// One question is live at a time. Anyone can call Answer with a choice
// index; the first caller to answer correctly scores a point and the quiz
// advances to the next question. The starting question is picked
// deterministically from the block height at deploy time so repeated
// deploys don't always open on question one.
package trivia

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// question is one fixed trivia entry.
type question struct {
	text       string
	choices    [4]string
	correctIdx int
}

// round holds the mutable state of the currently open question.
type round struct {
	number   int // 1-based round counter, increments forever
	qIdx     int // index into questions for this round
	attempts int // guesses made against this round so far
	solved   bool
	winner   string
}

var (
	questions = []question{
		{"What is the smallest prime number?", [4]string{"0", "1", "2", "3"}, 2},
		{"Which gas does a plant primarily absorb for photosynthesis?", [4]string{"Oxygen", "Nitrogen", "Carbon dioxide", "Hydrogen"}, 2},
		{"How many continents are there on Earth?", [4]string{"5", "6", "7", "8"}, 2},
		{"In binary, what is 1 + 1?", [4]string{"2", "10", "11", "0"}, 1},
		{"What does 'HTTP' stand for?", [4]string{"HyperText Transfer Protocol", "High Transfer Text Protocol", "Home Tool Transfer Protocol", "HyperText Transmission Path"}, 0},
		{"Which planet is known as the Red Planet?", [4]string{"Venus", "Jupiter", "Mars", "Saturn"}, 2},
		{"What is the time complexity of binary search?", [4]string{"O(n)", "O(log n)", "O(n^2)", "O(1)"}, 1},
		{"Who wrote the original Go proverb 'Don't communicate by sharing memory'?", [4]string{"Linus Torvalds", "Rob Pike", "Guido van Rossum", "Brendan Eich"}, 1},
	}

	current *round
	scores  = avl.NewTree() // addr(string) -> *int, points across all rounds

	totalCorrect int // lifetime count of correctly-answered questions
)

func init() {
	current = newRound(1, runtime.ChainHeight())
}

// newRound builds a fresh round. The question index cycles through the fixed
// list, offset by a height-derived starting point so consecutive deploys
// don't all open on the same question.
func newRound(number int, height int64) *round {
	return &round{
		number: number,
		qIdx:   questionIndex(number, height),
	}
}

// questionIndex maps a round number and a height (entropy source for the
// starting offset) to a slot in the questions slice. Deterministic and pure
// so it's easy to unit test.
func questionIndex(number int, height int64) int {
	if height < 0 {
		height = -height
	}
	n := len(questions)
	offset := int(height % int64(n))
	return (offset + number - 1) % n
}

// Answer submits a choice (0..3) for the current question. Crossing
// function: caller invokes as Answer(cross(cur), choiceIdx).
func Answer(cur realm, choiceIdx int) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	q := questions[current.qIdx]
	if choiceIdx < 0 || choiceIdx >= len(q.choices) {
		panic("choice must be in 0.." + strconv.Itoa(len(q.choices)-1))
	}
	if current.solved {
		panic("this question is already solved; the next one is already live")
	}

	current.attempts++
	caller := cur.Previous().Address().String()

	if choiceIdx != q.correctIdx {
		return "Wrong — try again."
	}

	current.solved = true
	current.winner = caller
	addScore(caller)
	totalCorrect++

	chain.Emit("QuestionSolved",
		"round", strconv.Itoa(current.number),
		"winner", caller,
		"answer", q.choices[choiceIdx],
	)

	solvedRound := current.number
	current = newRound(solvedRound+1, runtime.ChainHeight())

	return "Correct! The answer was \"" + q.choices[choiceIdx] + "\". A new question is now live."
}

// addScore bumps addr's lifetime point count.
func addScore(addr string) {
	if v := scores.Get(addr); v != nil {
		p := v.(*int)
		*p++
		return
	}
	one := 1
	scores.Set(addr, &one)
}

func scoreOf(addr string) int {
	if v := scores.Get(addr); v != nil {
		return *(v.(*int))
	}
	return 0
}

// leaderboardEntry is a snapshot row used only for rendering, sorted by
// score descending.
type leaderboardEntry struct {
	addr  string
	score int
}

func leaderboard() []leaderboardEntry {
	var rows []leaderboardEntry
	scores.Iterate("", "", func(addr string, v any) bool {
		rows = append(rows, leaderboardEntry{addr: addr, score: *(v.(*int))})
		return false
	})
	// simple insertion sort by score desc; leaderboards here stay small.
	for i := 1; i < len(rows); i++ {
		j := i
		for j > 0 && rows[j-1].score < rows[j].score {
			rows[j-1], rows[j] = rows[j], rows[j-1]
			j--
		}
	}
	return rows
}

// Render produces the gnoweb Markdown view of the quiz.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Trivia Quiz\n\n")
	b.WriteString("A rotating on-chain trivia quiz. Call `Answer(choiceIdx)` with 0-3 ")
	b.WriteString("to answer the current question — first correct answer scores the point ")
	b.WriteString("and a new question goes live.\n\n")

	q := questions[current.qIdx]
	b.WriteString("## Round " + strconv.Itoa(current.number) + "\n\n")
	b.WriteString("**" + q.text + "**\n\n")
	letters := [4]string{"A", "B", "C", "D"}
	for i, c := range q.choices {
		b.WriteString("- **" + letters[i] + "** (" + strconv.Itoa(i) + "): " + c + "\n")
	}
	b.WriteString("\n- Attempts so far this round: " + strconv.Itoa(current.attempts) + "\n\n")

	b.WriteString("## Leaderboard\n\n")
	rows := leaderboard()
	if len(rows) == 0 {
		b.WriteString("_No one has scored yet — be the first!_\n\n")
	} else {
		b.WriteString("| Player | Points |\n|---|---|\n")
		for _, r := range rows {
			b.WriteString("| `" + r.addr + "` | " + strconv.Itoa(r.score) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("Total questions answered correctly across all rounds: " + strconv.Itoa(totalCorrect) + "\n\n")

	b.WriteString("## How to play\n\n")
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath gno.land/r/g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz/trivia \\\n")
	b.WriteString("  -func Answer -args <0|1|2|3> ...\n")
	b.WriteString("```\n")

	return b.String()
}

package trivia

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
)

// resetQuiz re-initializes package globals so each test starts clean; init()
// only runs once for the whole test binary.
func resetQuiz(height int64) {
	current = newRound(1, height)
	scores = avl.NewTree()
	totalCorrect = 0
}

func TestQuestionIndexDeterministic(t *testing.T) {
	n := len(questions)
	for _, h := range []int64{0, 1, 42, 12345, -7} {
		idx := questionIndex(1, h)
		if idx < 0 || idx >= n {
			t.Errorf("questionIndex(1, %d) = %d, want in 0..%d", h, idx, n-1)
		}
		if again := questionIndex(1, h); again != idx {
			t.Errorf("questionIndex(1, %d) non-deterministic: %d != %d", h, again, idx)
		}
	}
	// consecutive rounds should walk sequentially through the list
	first := questionIndex(1, 0)
	second := questionIndex(2, 0)
	if second != (first+1)%n {
		t.Errorf("round 2 index = %d, want %d", second, (first+1)%n)
	}
}

// TestAnswerCorrectAdvances exercises the crossing Answer function, so it
// takes cur realm and calls through cross(cur).
func TestAnswerCorrectAdvances(cur realm, t *testing.T) {
	resetQuiz(10)
	q := questions[current.qIdx]
	prevRound := current.number

	// wrong answer first: pick any index that isn't correct
	wrong := (q.correctIdx + 1) % len(q.choices)
	got := Answer(cross(cur), wrong)
	if got != "Wrong — try again." {
		t.Errorf("Answer(wrong) = %q, want wrong message", got)
	}
	if current.solved {
		t.Error("round should not be solved after a wrong answer")
	}

	got = Answer(cross(cur), q.correctIdx)
	if !strings.HasPrefix(got, "Correct!") {
		t.Errorf("Answer(correct) = %q, want it to start with Correct!", got)
	}
	if current.number != prevRound+1 {
		t.Errorf("round number = %d, want %d", current.number, prevRound+1)
	}
	if totalCorrect != 1 {
		t.Errorf("totalCorrect = %d, want 1", totalCorrect)
	}
	if len(leaderboard()) != 1 {
		t.Errorf("leaderboard len = %d, want 1", len(leaderboard()))
	}
}

// TestRenderContainsState is a plain read — no cur.
func TestRenderContainsState(t *testing.T) {
	resetQuiz(5)
	out := Render("")
	for _, want := range []string{"Trivia Quiz", "Round", "Leaderboard"} {
		if !strings.Contains(out, want) {
			t.Errorf("Render() missing %q", want)
		}
	}
}

// Package urlshort is a simple on-chain URL alias registry.
//
// Callers register an `alias -> url` mapping they own. An alias can only be
// claimed once; the owner may later update the target URL, but nobody else can
// overwrite an alias they do not own. A per-alias click counter is bumped every
// time the alias is resolved through Render("/<alias>").
package urlshort

import (
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// entry is the persisted record for a single alias.
type entry struct {
	url    string
	owner  address
	note   string
	clicks int
}

// aliases maps alias (string) -> *entry, kept in an avl.Tree for deterministic
// iteration order in Render.
var aliases avl.Tree

// isAlphanumeric reports whether s is non-empty and made only of [0-9A-Za-z].
func isAlphanumeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9':
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		default:
			return false
		}
	}
	return true
}

// Shorten registers `alias -> url` owned by the caller.
//
// Rules:
//   - alias must be non-empty and alphanumeric;
//   - url must be non-empty;
//   - if the alias is unclaimed, it is created owned by the caller;
//   - if it is already claimed by the caller, the url/note are updated;
//   - if it is claimed by someone else, the call aborts.
func Shorten(cur realm, alias string, url string, note string) {
	if !isAlphanumeric(alias) {
		panic("alias must be non-empty and alphanumeric")
	}
	if url == "" {
		panic("url must be non-empty")
	}

	caller := unsafe.PreviousRealm().Address()

	if v := aliases.Get(alias); v != nil {
		e := v.(*entry)
		if e.owner != caller {
			panic("alias already taken by another owner")
		}
		e.url = url
		e.note = note
		chain.Emit("AliasUpdated", "alias", alias, "owner", caller.String())
		return
	}

	e := &entry{url: url, owner: caller, note: note, clicks: 0}
	aliases.Set(alias, e)
	chain.Emit("AliasCreated", "alias", alias, "owner", caller.String())
}

// Remove deletes an alias owned by the caller. Aborts if the alias does not
// exist or the caller is not the owner.
func Remove(cur realm, alias string) {
	v := aliases.Get(alias)
	if v == nil {
		panic("alias not found")
	}
	e := v.(*entry)
	caller := unsafe.PreviousRealm().Address()
	if e.owner != caller {
		panic("only the owner can remove an alias")
	}
	aliases.Remove(alias)
	chain.Emit("AliasRemoved", "alias", alias, "owner", caller.String())
}

// Lookup returns the target url for an alias and whether it exists. It is a
// read-only helper and does NOT increment the click counter.
func Lookup(alias string) (string, bool) {
	v := aliases.Get(alias)
	if v == nil {
		return "", false
	}
	return v.(*entry).url, true
}

// Render renders Markdown. The root path lists every alias; "/<alias>" shows a
// single alias detail and bumps its click counter.
func Render(path string) string {
	if path == "" || path == "/" {
		return renderIndex()
	}

	alias := strings.TrimPrefix(path, "/")
	v := aliases.Get(alias)
	if v == nil {
		return "# URL Shortener\n\nNo alias named `" + alias + "`.\n\n[← all aliases](/)\n"
	}

	e := v.(*entry)
	e.clicks++

	var b strings.Builder
	b.WriteString("# 🔗 " + alias + "\n\n")
	b.WriteString("**Target:** <" + e.url + ">\n\n")
	b.WriteString("**Owner:** " + e.owner.String() + "\n\n")
	if e.note != "" {
		b.WriteString("**Note:** " + e.note + "\n\n")
	}
	b.WriteString("**Clicks:** " + itoa(e.clicks) + "\n\n")
	b.WriteString("[← all aliases](/)\n")
	return b.String()
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# 🔗 URL Shortener\n\n")

	if aliases.Size() == 0 {
		b.WriteString("_No aliases registered yet._\n\n")
		b.WriteString("Call `Shorten(alias, url, note)` to register one.\n")
		return b.String()
	}

	b.WriteString("| Alias | Target | Owner | Clicks |\n")
	b.WriteString("|-------|--------|-------|--------|\n")
	aliases.Iterate("", "", func(key string, value interface{}) bool {
		e := value.(*entry)
		b.WriteString("| [" + key + "](/" + key + ") | <" + e.url + "> | " +
			short(e.owner.String()) + " | " + itoa(e.clicks) + " |\n")
		return false
	})
	b.WriteString("\nTotal aliases: " + itoa(aliases.Size()) + "\n")
	return b.String()
}

// short truncates a long address for the index table.
func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// itoa converts a non-negative int to its decimal string without importing
// strconv (kept minimal & deterministic).
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

