}

func TestBindAfterUnion(t *testing.T) {
	n, _ := newNs(t, "/bin/ls", "/usr/glenda/bin/rc")
	if err := n.Bind("/usr/glenda/bin", "/bin", MAFTER); err != nil {
		t.Fatalf("bind -a: %v", err)
