	// |---|---|
	// | Rate (tokens/block) | 0.5 |
	// | Burst (capacity) | 5 |
	// | Clock height | 123 |
	//
	// ## Callers
	//
	// _No caller has hit the limiter yet._
	//
	// ---
	// Call `Allow(cur)` to consume a token; read `Tokens(addr)` for a caller's balance.
}

// Package pairreg is the registry every AMM pair instance announces itself to,
// and the unified frontend over all of them.
//
// It is the third artifact of the instance-per-realm pattern: one shared
// p/moul/x/pair/v0 holding the logic, N tiny realms holding one pair each, and
// this realm knowing all of them.
//
// # Why registration cannot be faked, and code cannot be trusted
//
// Register keys an instance by cur.Previous().PkgPath(), which the runtime
// supplies, so an instance cannot claim a path that is not its own. That is
// the whole on-chain guarantee. It is NOT a guarantee about the code at that
// path: gno has no way to read another package's source from inside a realm,
// so nothing here can check that an instance really runs the shared template.
// The mirror image of Ethereum's CREATE2, which proves the code and says
// nothing legible about who deployed it.
//
// Consequences a reader of the index must keep in mind:
//
//   - Reserves shown here are CLAIMED. They are read live from the instance's
//     own struct, which is honest for an instance running the template and
//     arbitrary for one that does not.
//   - Several instances may exist for the same token couple. That is allowed
//     on purpose; there is no canonical pair and no factory to enforce one.
//   - Approving tokens to an instance risks exactly what was approved. Read
//     the instance's source (vm/qfile on its path) before funding it.
//
// # Why the registry can read live state at all
//
// Instances register a *pair.Pair pointer, not an address, the way grc20reg
// registers a *grc20.Token. One vm/qrender here therefore renders the real
// state of every instance, with no indexer and no multicall. It is safe
// because pair.Pair holds only concrete types: an interface or a func field
// would let a hostile instance hand foreign code to this realm's frame.
package pairreg

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nym-moultest123/x/pair/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Entry is one registered instance.
type Entry struct {
	Path   string     // the instance realm's package path, supplied by the runtime
	Pair   *pair.Pair // live pointer into the instance's own storage
	Height int64      // chain height at registration
}

// entries maps instance path -> *Entry. couples maps a pair ID
// ("keyA~keyB") -> int, how many instances claim that couple.
var (
	entries avl.Tree
	couples avl.Tree
)

// Register records the calling realm as an instance. Call it from the
// instance's init, so that deploying and listing are one transaction:
//
//	func init(cur realm) {
//		p = pair.New(keyA, keyB, grc20reg.MustGet(keyA), grc20reg.MustGet(keyB))
//		pairreg.Register(cross(cur), p)
//	}
//
// Permissionless by design: anyone may deploy an instance under their own
// address namespace and land here. Spam is self funded, since the registering
// transaction pays for the storage it adds.
func Register(cur realm, p *pair.Pair) {
	caller := cur.Previous()
	path := caller.PkgPath()
	if path == "" {
		panic("pairreg: only a realm can register")
	}
	if p == nil {
		panic("pairreg: nil pair")
	}
	if entries.Has(path) {
		panic("pairreg: already registered: " + path)
	}

	entries.Set(path, &Entry{Path: path, Pair: p, Height: runtime.ChainHeight()})
	couples.Set(p.ID(), countFor(p.ID())+1)

	chain.Emit("RegisterPair",
		"path", path,
		"pair", p.ID(),
	)
}

// Get returns the entry for an instance path, or nil.
func Get(path string) *Entry {
	v := entries.Get(path)
	if v == nil {
		return nil
	}
	return v.(*Entry)
}

// Size returns how many instances are registered.
func Size() int { return entries.Size() }

// Couples returns how many distinct token couples are represented.
func Couples() int { return couples.Size() }

// InstancesFor returns the instance paths claiming a given couple id.
func InstancesFor(id string) []string {
	out := []string{}
	entries.Iterate("", "", func(_ string, value any) bool {
		e := value.(*Entry)
		if e.Pair.ID() == id {
			out = append(out, e.Path)
		}
		return false
	})
	return out
}

// Render is the unified frontend: the index of every instance with its live
// state, or one instance's own page when path is an instance path.
func Render(path string) string {
	if path != "" {
		e := Get(path)
		if e == nil {
			return "# 404\n\nNo instance registered at `" + path + "`.\n"
		}
		out := e.Pair.Render("")
		out += "\n---\n\n"
		out += ufmt.Sprintf("Instance: [`%s`](%s) · registered at height %d · %d instance(s) claim this couple.\n",
			e.Path, webPath(e.Path), e.Height, countFor(e.Pair.ID()))
		return out
	}

	out := "# AMM pairs\n\n"
	out += "One realm per token couple, all running [p/moul/x/pair/v0](/p/nym-moultest123/x/pair/v0). "
	out += "Anyone can deploy one under their own namespace and it lands here.\n\n"

	if entries.Size() == 0 {
		out += "_No instance yet._\n"
		return out
	}

	out += ufmt.Sprintf("%d instance(s), %d couple(s).\n\n", entries.Size(), couples.Size())
	out += "**Reserves below are claimed by each instance, not verified.** "
	out += "Nothing on chain can check that an instance runs the shared template; read its source before funding it.\n\n"
	out += "| pair | reserves | LP shares | providers | instance |\n"
	out += "|---|---|---|---|---|\n"
	entries.Iterate("", "", func(key string, value any) bool {
		e := value.(*Entry)
		symA, symB := e.Pair.Symbols()
		resA, resB := e.Pair.Reserves()
		out += ufmt.Sprintf("| [%s/%s](/r/nym-moultest123/x/pairreg/v0:%s) | %d %s / %d %s | %d | %d | [`%s`](%s) |\n",
			symA, symB, key,
			resA, symA, resB, symB,
			e.Pair.TotalShares(), e.Pair.Providers(),
			shortPath(e.Path), webPath(e.Path))
		return false
	})
	return out
}

//
// Internals.
//

func countFor(id string) int {
	v := couples.Get(id)
	if v == nil {
		return 0
	}
	return v.(int)
}

// webPath turns a package path into a gnoweb link.
func webPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i:]
	}
	return "/" + pkgPath
}

// shortPath drops the chain domain, which is the same on every row.
func shortPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i+1:]
	}
	return pkgPath
}

package pairreg

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// Loaded on its own, the registry has no instances: the index says so rather
// than rendering an empty table.
func TestRenderEmpty(t *testing.T) {
	out := Render("")
	uassert.True(t, strings.Contains(out, "# AMM pairs"))
	uassert.True(t, strings.Contains(out, "No instance yet"))
	uassert.Equal(t, 0, Size())
	uassert.Equal(t, 0, Couples())
}

func TestRenderUnknownInstance(t *testing.T) {
	out := Render("gno.land/r/nope/v0")
	uassert.True(t, strings.Contains(out, "# 404"))
	uassert.True(t, Get("gno.land/r/nope/v0") == nil)
	uassert.Equal(t, 0, len(InstancesFor("a~b")))
}

// A gnoweb link is the package path minus the chain domain.
func TestWebPath(t *testing.T) {
	uassert.Equal(t, "/r/nym-moultest123/x/pairs/aaabbb/v0", webPath("gno.land/r/nym-moultest123/x/pairs/aaabbb/v0"))
	uassert.Equal(t, "r/moul/x/pairs/aaabbb/v0", shortPath("gno.land/r/nym-moultest123/x/pairs/aaabbb/v0"))
}

// Package b58demo is a small gnoweb demo of the Base58 codec provided by the
// [p/moul/x/daily/b58](/p/nym-moultest123/x/daily/b58/v0) library: it renders the alphabet,
// a gallery of worked examples, and an interactive hex → Base58 round-tripper.
//
// It contains no codec logic of its own — everything comes from `b58.Encode`,
// `b58.Decode` and `b58.Alphabet`.
package b58demo

import (
	"encoding/hex"
	"strings"

	"gno.land/p/nym-moultest123/x/daily/b58/v0"
)

// Render produces the gnoweb Markdown view.
//
//   - "/"        → the alphabet + a small gallery of worked examples.
//   - "/<hex>"   → decode the hex input to bytes, show its Base58, and the
//     hex-encoded decoded round-trip to prove Encode/Decode are inverse.
func Render(path string) string {
	arg := strings.TrimPrefix(path, "/")
	arg = strings.TrimSpace(arg)

	if arg == "" {
		return renderHome()
	}
	return renderHex(arg)
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Base58 (Bitcoin alphabet)\n\n")
	sb.WriteString("Demo of the [`p/moul/x/daily/b58`](/p/nym-moultest123/x/daily/b58/v0) library — ")
	sb.WriteString("base conversion from raw bytes (base-256) to base-58, using the ")
	sb.WriteString("Bitcoin alphabet (no `0`, `O`, `I`, `l`), pure byte-slice math, no `math/big`.\n\n")

	sb.WriteString("## Alphabet\n\n")
	sb.WriteString("```\n")
	sb.WriteString(b58.Alphabet)
	sb.WriteString("\n```\n\n")
	sb.WriteString("58 characters, index 0…57.\n\n")

	sb.WriteString("## Examples\n\n")
	sb.WriteString("| input (utf-8) | hex | Base58 |\n")
	sb.WriteString("|---|---|---|\n")
	examples := []string{"", "hello world", "gno.land", "Bitcoin"}
	for _, e := range examples {
		h := hex.EncodeToString([]byte(e))
		if h == "" {
			h = "(empty)"
		}
		label := e
		if label == "" {
			label = "(empty)"
		}
		sb.WriteString("| `" + label + "` | `" + h + "` | `" + b58.Encode([]byte(e)) + "` |\n")
	}
	sb.WriteString("\n")

	sb.WriteString("Leading zero bytes → leading `1`s:\n\n")
	sb.WriteString("| bytes | Base58 |\n|---|---|\n")
	sb.WriteString("| `[0x00]` | `" + b58.Encode([]byte{0}) + "` |\n")
	sb.WriteString("| `[0x00 0x00 0x00]` | `" + b58.Encode([]byte{0, 0, 0}) + "` |\n\n")

	sb.WriteString("## Try it\n\n")
	sb.WriteString("Append a hex string to the path to encode/round-trip it:\n\n")
	sb.WriteString("- `/68656c6c6f` — the bytes for \"hello\"\n")
	sb.WriteString("- `/00000000` — four zero bytes\n")
	sb.WriteString("- `/deadbeef`\n")
	return sb.String()
}

func renderHex(arg string) string {
	var sb strings.Builder
	sb.WriteString("# Base58 — round-trip\n\n")
	sb.WriteString("[← alphabet & examples](/r/nym-moultest123/x/daily/b58demo/v0)\n\n")

	raw, err := hex.DecodeString(arg)
	if err != nil {
		sb.WriteString("**Invalid hex input.**\n\n")
		sb.WriteString("`" + arg + "` is not a valid hex string. ")
		sb.WriteString("Provide an even number of hex digits, e.g. `/deadbeef`.\n")
		return sb.String()
	}

	encoded := b58.Encode(raw)
	decoded := b58.Decode(encoded)
	roundTrip := hex.EncodeToString(decoded)

	inHex := arg
	if inHex == "" {
		inHex = "(empty)"
	}
	outHex := roundTrip
	if outHex == "" {
		outHex = "(empty)"
	}
	enc := encoded
	if enc == "" {
		enc = "(empty)"
	}

	sb.WriteString("| step | value |\n|---|---|\n")
	sb.WriteString("| hex input | `" + inHex + "` |\n")
	sb.WriteString("| bytes | `" + byteList(raw) + "` |\n")
	sb.WriteString("| **Base58** | `" + enc + "` |\n")
	sb.WriteString("| decoded (hex) | `" + outHex + "` |\n\n")

	if roundTrip == arg {
		sb.WriteString("✓ Round-trip matches: `Decode(Encode(x)) == x`.\n")
	} else {
		sb.WriteString("✗ Round-trip mismatch.\n")
	}
	return sb.String()
}

// byteList renders a byte slice as a compact space-separated hex list.
func byteList(b []byte) string {
	if len(b) == 0 {
		return "(none)"
	}
	const digits = "0123456789abcdef"
	out := make([]byte, 0, len(b)*3)
	for i, c := range b {
		if i > 0 {
			out = append(out, ' ')
		}
		out = append(out, digits[c>>4], digits[c&0x0f])
	}
	return string(out)
}

