// Package soundexdemo is a small gnoweb demo of the Soundex phonetic algorithm
// provided by the [p/moul/x/daily/soundex](/p/nym-moultest123/x/daily/soundex/v0) library:
// it groups a small name list by phonetic key so the "sounds alike" clusters
// are visible.
//
// It contains no phonetic logic of its own. Stateless, so Render is
// deterministic — names are grouped in first-seen order, never by iterating a
// map.
package soundexdemo

import (
	"strings"

	"gno.land/p/nym-moultest123/x/daily/soundex/v0"
)

// names include several deliberate near-collisions.
var names = []string{
	"Robert", "Rupert", "Rubin",
	"Ashcraft", "Ashcroft",
	"Tymczak", "Pfister", "Honeyman",
}

// Render renders the demo for gnoweb.
//
//	Render("")       / Render("/") -> the name table + clusters
//	Render("/<name>")              -> that name's key
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Soundex\n\n")
	b.WriteString("Phonetic keys for English names, demoing the ")
	b.WriteString("[`p/moul/x/daily/soundex`](/p/nym-moultest123/x/daily/soundex/v0) library.\n\n")

	if q := parseArg(path); q != "" {
		k := soundex.Encode(q)
		b.WriteString("## `")
		b.WriteString(q)
		b.WriteString("`\n\n")
		if k == "" {
			b.WriteString("_No ASCII letters — no key._\n")
		} else {
			b.WriteString("key: **")
			b.WriteString(k)
			b.WriteString("** (normalized: `")
			b.WriteString(soundex.Normalize(q))
			b.WriteString("`)\n")
		}
		return b.String()
	}

	b.WriteString("| name | key |\n|---|---|\n")
	for _, n := range names {
		b.WriteString("| ")
		b.WriteString(n)
		b.WriteString(" | `")
		b.WriteString(soundex.Encode(n))
		b.WriteString("` |\n")
	}

	// group by key, preserving first-seen order (never iterate a map)
	b.WriteString("\n## Sounds alike\n\n")
	keys := []string{}
	byKey := map[string][]string{}
	for _, n := range names {
		k := soundex.Encode(n)
		if _, seen := byKey[k]; !seen {
			keys = append(keys, k)
		}
		byKey[k] = append(byKey[k], n)
	}
	for _, k := range keys {
		if len(byKey[k]) < 2 {
			continue
		}
		b.WriteString("- **")
		b.WriteString(k)
		b.WriteString("**: ")
		b.WriteString(strings.Join(byKey[k], ", "))
		b.WriteString("\n")
	}

	b.WriteString("\n> A *blocking* key for finding candidates, never proof that two names match.\n")
	return b.String()
}

func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

package sparklinedemo

// ExampleRender pins the realm's Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Sparklines
	//
	// A numeric series as one line of block characters, demoing the [`p/moul/x/daily/sparkline`](/p/nym-moultest123/x/daily/sparkline/v0) library.
	//
	// ## A series
	//
	// `▁▁▂▄▃▅█▆▅▃▂▁`
	//
	// `3, 5, 9, 14, 12, 18, 25, 21, 16, 11, 7, 4`
	//
	// Scaled between its own bounds, `3` and `25`. The shape is the point; the axis is not.
	//
	// ## The ramp
	//
	// `▁▂▃▄▅▆▇█` — eight levels, low to high.
	//
	// | value | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 |
	// |---|---|---|---|---|---|---|---|---|
	// | level | `▁` | `▂` | `▃` | `▄` | `▅` | `▆` | `▇` | `█` |
	//
	// ## A flat series
	//
	// `▅▅▅▅` — `1000, 1000, 1000, 1000`
	//
	// Mid-ramp, not along the floor. A series that never moves has no shape, but drawing it at the bottom would claim it was *zero*, which is a different thing and a wrong one.
	//
	// ## Negatives
	//
	// `▁▃▄▅█▅▂` — `-8, -3, 0, 4, 9, 2, -5`
	//
	// Nothing special: the window is the minimum and maximum, wherever zero happens to fall.
	//
	// ## A fixed window clamps
	//
	// `-20, 0, 25, 50, 75, 100, 140` against `0..100`:
	//
	// `▁▁▂▄▆██`
	//
	// `-20` pins to the floor and `140` to the ceiling. Choosing the window keeps a percentage readable, and one outlier cannot flatten the rest of the picture — or break the realm that drew it.
	//
	// ## Rounding is floor
	//
	// | value in `0..100` | level |
	// |---|---|
	// | 0 | `▁` |
	// | 14 | `▁` |
	// | 50 | `▄` |
	// | 85 | `▆` |
	// | 99 | `▇` |
	// | 100 | `█` |
	//
	// Only the maximum itself reaches the top of the ramp, so the peak of a series is always visually distinct.
	//
	// ## Why integers
	//
	// Scaling is integer division throughout. Render output has to be byte-identical on every validating node, and floating point is the usual way that quietly stops being true.
}

// Package sparklinedemo is a small gnoweb demo of the block-character series
// renderer provided by the [p/moul/x/daily/sparkline](/p/nym-moultest123/x/daily/sparkline/v0)
// library: it sparks a few fixed series and shows the three behaviours worth
// knowing before using it in a realm — flat series, clamping, and floor
// rounding.
//
// It contains no rendering logic of its own. Stateless, so Render is
// deterministic.
package sparklinedemo

import (
	"strconv"
	"strings"

	"gno.land/p/nym-moultest123/x/daily/sparkline/v0"
)

// series are fixed rather than derived from chain state: a demo whose output
// moved with the block height could not be pinned by an example test.
var (
	traffic = []int{3, 5, 9, 14, 12, 18, 25, 21, 16, 11, 7, 4}
	flat    = []int{1000, 1000, 1000, 1000}
	swing   = []int{-8, -3, 0, 4, 9, 2, -5}
	pct     = []int{-20, 0, 25, 50, 75, 100, 140}
)

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/") -> the full demo
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Sparklines\n\n")
	b.WriteString("A numeric series as one line of block characters, demoing the ")
	b.WriteString("[`p/moul/x/daily/sparkline`](/p/nym-moultest123/x/daily/sparkline/v0) library.\n\n")

	b.WriteString("## A series\n\n")
	lo, hi, _ := sparkline.Bounds(traffic)
	b.WriteString("`" + sparkline.Ints(traffic) + "`\n\n")
	b.WriteString(ints(traffic) + "\n\n")
	b.WriteString("Scaled between its own bounds, `" + strconv.Itoa(lo) + "` and `" +
		strconv.Itoa(hi) + "`. The shape is the point; the axis is not.\n\n")

	b.WriteString("## The ramp\n\n")
	b.WriteString("`" + sparkline.Levels + "` — eight levels, low to high.\n\n")
	b.WriteString("| value | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|---|\n")
	b.WriteString("| level |")
	for v := 0; v <= 7; v++ {
		b.WriteString(" `" + sparkline.Scaled([]int{v}, 0, 7) + "` |")
	}
	b.WriteString("\n\n")

	b.WriteString("## A flat series\n\n")
	b.WriteString("`" + sparkline.Ints(flat) + "` — " + ints(flat) + "\n\n")
	b.WriteString("Mid-ramp, not along the floor. A series that never moves has no ")
	b.WriteString("shape, but drawing it at the bottom would claim it was *zero*, ")
	b.WriteString("which is a different thing and a wrong one.\n\n")

	b.WriteString("## Negatives\n\n")
	b.WriteString("`" + sparkline.Ints(swing) + "` — " + ints(swing) + "\n\n")
	b.WriteString("Nothing special: the window is the minimum and maximum, wherever ")
	b.WriteString("zero happens to fall.\n\n")

	b.WriteString("## A fixed window clamps\n\n")
	b.WriteString(ints(pct) + " against `0..100`:\n\n")
	b.WriteString("`" + sparkline.Scaled(pct, 0, 100) + "`\n\n")
	b.WriteString("`-20` pins to the floor and `140` to the ceiling. Choosing the ")
	b.WriteString("window keeps a percentage readable, and one outlier cannot flatten ")
	b.WriteString("the rest of the picture — or break the realm that drew it.\n\n")

	b.WriteString("## Rounding is floor\n\n")
	b.WriteString("| value in `0..100` | level |\n")
	b.WriteString("|---|---|\n")
	for _, v := range []int{0, 14, 50, 85, 99, 100} {
		b.WriteString("| " + strconv.Itoa(v) + " | `" +
			sparkline.Scaled([]int{v}, 0, 100) + "` |\n")
	}
	b.WriteString("\nOnly the maximum itself reaches the top of the ramp, so the peak ")
	b.WriteString("of a series is always visually distinct.\n\n")

	b.WriteString("## Why integers\n\n")
	b.WriteString("Scaling is integer division throughout. Render output has to be ")
	b.WriteString("byte-identical on every validating node, and floating point is the ")
	b.WriteString("usual way that quietly stops being true.\n")

	return b.String()
}

// ints formats a series as `a, b, c` for the prose around each sparkline.
func ints(values []int) string {
	parts := make([]string, len(values))
	for i, v := range values {
		parts[i] = strconv.Itoa(v)
	}
	return "`" + strings.Join(parts, ", ") + "`"
}

