	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsWithMessage(t, cur, "message must not be empty", func() {
		Leave(cross(cur), "   ", 5)
	})
