package impl

import (
	"testing"

	facade "gno.land/r/nym-moultest123/x/upgrade/adminreg/facade/v0"
	implv0 "gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v0"

	"gno.land/p/nt/uassert/v0"
)

// TestProposeThenAccept checks the two-step shape: deploying nominates, and
// only an owner transaction naming a path promotes it.
//
// Both impl realms are imported here, so both have already nominated themselves
// by the time this runs, and neither is serving.
func TestProposeThenAccept(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(facade.Ownable.Owner()))

	uassert.Equal(t, 2, len(facade.Candidates()), "both versions nominated themselves")
	uassert.Equal(t, "", facade.Live(), "nominating is not serving")
	uassert.AbortsContains(t, cur, "no implementation accepted", func() {
		facade.Greet("world")
	})

	// Accepting names a path, not an object: this is a plain maketx call.
	facade.Accept(cross(cur), "gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v0")
	uassert.Equal(t, "impl/v0", facade.Version())
	uassert.Equal(t, "hello, world", facade.Greet("world"))

	// The upgrade, and the rollback, are the same single call.
	facade.Accept(cross(cur), "gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v1")
	uassert.Equal(t, "HELLO, world!", facade.Greet("world"))
	facade.Accept(cross(cur), implv0.Path)
	uassert.Equal(t, "hello, world", facade.Greet("world"))
	facade.Accept(cross(cur), Path)

	// A path nobody nominated cannot be accepted, however owned you are.
	uassert.AbortsContains(t, cur, "no candidate at", func() {
		facade.Accept(cross(cur), "gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v9")
	})

	// A non-owner cannot accept even a legitimate candidate.
	testing.SetRealm(testing.NewUserRealm("g1w4ek2u33ta047h6lta047h6lta047h6ldvdwpn"))
	uassert.AbortsContains(t, cur, "caller is not owner", func() {
		facade.Accept(cross(cur), implv0.Path)
	})

	uassert.Equal(t, "adminreg/facade/v0 [open]\n"+
		"live: impl/v1 (gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v1)\n"+
		"HELLO, world!\n"+
		"candidates: 2\n"+
		"- gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v0\n"+
		"- gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v1\n", facade.Render(""))
}

// TestDispatchCost100 does 100 dispatches through this pattern's entry point,
// so `gno test -print-runtime-metrics` prints a cycle count for a known
// workload. Its twin is TestDispatchCost100 in schema/impl/gen1.
//
func TestDispatchCost100(cur realm, t *testing.T) {
	// Runs after TestProposeThenAccept, which leaves v1 live, and before
	// TestLadder, which freezes. Reads only, so it disturbs neither.
	for i := 0; i < 100; i++ {
		facade.Greet("world")
	}
	uassert.Equal(t, "HELLO, world!", facade.Greet("world"))
}

// TestLadder walks the three rungs and checks the ratchet refuses to loosen.
//
// Runs after TestProposeThenAccept on purpose: every rung is one-way, so the
// tests that need to propose and accept freely must already have run.
func TestLadder(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(facade.Ownable.Owner()))
	uassert.Equal(t, facade.StageOpen, facade.Stage())

	// Rung 2: no new code, but rolling back among what exists still works.
	facade.Close(cross(cur))
	uassert.Equal(t, facade.StageClosed, facade.Stage())
	uassert.AbortsContains(t, cur, "no new candidate may be proposed", func() {
		Propose(cross(cur))
	})
	facade.Accept(cross(cur), implv0.Path)
	uassert.Equal(t, "hello, world", facade.Greet("world"), "rollback survives Close")
	facade.Accept(cross(cur), Path)

	// The ratchet only turns one way, even for the owner.
	uassert.AbortsContains(t, cur, "only tightens", func() {
		facade.Close(cross(cur))
	})

	// Rung 3: nothing is accepted again.
	facade.Freeze(cross(cur))
	uassert.Equal(t, facade.StageFrozen, facade.Stage())
	uassert.AbortsContains(t, cur, "is frozen", func() {
		facade.Accept(cross(cur), implv0.Path)
	})
	uassert.AbortsContains(t, cur, "only tightens", func() {
		facade.Freeze(cross(cur))
	})

	// What was live stays live, and the render says which rung it is on.
	uassert.Equal(t, "HELLO, world!", facade.Greet("world"))
	uassert.Equal(t, "adminreg/facade/v0 [frozen]\n"+
		"live: impl/v1 (gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v1)\n"+
		"HELLO, world!\n"+
		"candidates: 2\n"+
		"- gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v0\n"+
		"- gno.land/r/nym-moultest123/x/upgrade/adminreg/impl/v1\n", facade.Render(""))
}

// untrusted-render: records are seeded in init or derived from lazy/v0's own
// init; this realm exposes no setter, so no caller string ever reaches Render.
//
// Package lazy is version 1 of the "lazy migration" upgrade pattern
// (pattern D of the exploration; see ../README.md).
//
// v1 changes the stored shape (Score widens, Active is new) and migrates one
// record at a time, on first touch, paid for by whoever touched it. There is
// no migration transaction and no pause.
//
// The catch on today's gno: migrating on read MUTATES, so the read path has to
// be a crossing function. Get therefore costs a transaction and is invisible to
// vm/qeval and to Render. Peek is the honest read-only half, and it reports the
// pre-migration answer for records that have not been touched yet.
package lazy

import (
	v0 "gno.land/r/nym-moultest123/x/upgrade/lazy/v0"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Record is v1's shape: Score widened to int64 and scaled by 1000, plus a new
// Active flag that migrated records get set to true.
type Record struct {
	Name   string
	Score  int64
	Active bool
}

func (r *Record) String() string {
	if r == nil {
		return "nil"
	}
	return ufmt.Sprintf("v1{%s %d %t}", r.Name, r.Score, r.Active)
}

var records = avl.NewTree()

func init() {
	records.Set("cyd", &Record{Name: "cyd", Score: 3000, Active: true})
}

// migrate converts a v0 record into a v1 one. Kept separate from Get so the
// conversion is testable without a write.
func migrate(old *v0.Record) *Record {
	return &Record{
		Name:   old.Name + "-migrated",
		Score:  int64(old.Score) * 1000,
		Active: true,
	}
}

// Get returns a record, migrating it from v0 on first touch.
//
// Crossing, because the migration writes. That is the cost of the pattern: the
// cheapest possible read is now a transaction.
func Get(cur realm, key string) *Record {
	if v := records.Get(key); v != nil {
		return v.(*Record)
	}
	old := v0.Get(key)
	if old == nil {
		return nil
	}
	r := migrate(old)
	records.Set(key, r)
	return r
}

// Peek is the read-only half: it never migrates, so a record that has not been
// touched yet reads as its v0 self converted on the fly and NOT stored.
func Peek(key string) *Record {
	if v := records.Get(key); v != nil {
		return v.(*Record)
	}
	if old := v0.Get(key); old != nil {
		return migrate(old)
	}
	return nil
}

// Migrated is how many records have actually moved over.
func Migrated() int {
	return records.Size()
}

// Pending is how many v0 records have never been touched. It is only a bound:
// v0 keeps every record it ever had, migrated or not.
func Pending() int {
	n := 0
	for _, k := range []string{"ada", "bob"} {
		if records.Get(k) == nil && v0.Get(k) != nil {
			n++
		}
	}
	return n
}

func Render(_ string) string {
	out := ufmt.Sprintf("lazy/v1: %d migrated, %d pending in v0\n", Migrated(), Pending())
	records.Iterate("", "", func(k string, v any) bool {
		out += ufmt.Sprintf("- %s: %s\n", k, v.(*Record).String())
		return false
	})
	return out
}

package lazy

import (
	"testing"

	v0 "gno.land/r/nym-moultest123/x/upgrade/lazy/v0"

	"gno.land/p/nt/uassert/v0"
)

// TestLazyMigration walks a record from v0 into v1 on first touch and checks
// what the two halves of the read path report on either side of it.
func TestLazyMigration(cur realm, t *testing.T) {
	uassert.Equal(t, 1, Migrated(), "only v1's own seed has moved")
	uassert.Equal(t, 2, Pending(), "both v0 records are untouched")

	// Peek converts without storing: the answer is right, the state is not moved.
	uassert.Equal(t, "v1{ada-migrated 1000 true}", Peek("ada").String())
	uassert.Equal(t, 1, Migrated(), "Peek must not migrate")

	// Get migrates.
	uassert.Equal(t, "v1{ada-migrated 1000 true}", Get(cross(cur), "ada").String())
	uassert.Equal(t, 2, Migrated(), "ada has moved over")
	uassert.Equal(t, 1, Pending())

	// Migrating COPIES: v0 still holds (and still pays for) the original.
	uassert.Equal(t, 2, v0.Size(), "v0 never shrinks")
	uassert.Equal(t, "v0{ada 1}", v0.Get("ada").String())

	// A second Get is a plain hit, not a second migration.
	uassert.Equal(t, "v1{ada-migrated 1000 true}", Get(cross(cur), "ada").String())
	uassert.Equal(t, 2, Migrated())

	// A key in neither version is nil in both halves.
	uassert.True(t, Get(cross(cur), "zoe") == nil)
	uassert.True(t, Peek("zoe") == nil)

	// v1's own records are untouched by any of this.
	uassert.Equal(t, "v1{cyd 3000 true}", Get(cross(cur), "cyd").String())

	uassert.Equal(t, "lazy/v1: 2 migrated, 1 pending in v0\n"+
		"- ada: v1{ada-migrated 1000 true}\n"+
		"- cyd: v1{cyd 3000 true}\n", Render(""))
}

// Package lock is version 1 of the "retire the predecessor" upgrade pattern
// (pattern B of the exploration; see ../README.md).
//
// v1 refuses every write until v0 has been retired. That is the whole point:
// at most one version is writable at any height, so v1 can safely fold v0's
// frozen total into its own and report a single authoritative number, the
// thing pattern A cannot do.
package lock

import (
	v0 "gno.land/r/nym-moultest123/x/upgrade/lock/v0"

	"gno.land/p/nt/ufmt/v0"
)

// Predecessor is the version this one supersedes.
const Predecessor = "gno.land/r/nym-moultest123/x/upgrade/lock/v0"

var counter int

// Inc adds n once the predecessor is frozen.
func Inc(cur realm, n int) {
	assertPredecessorRetired()
	counter += n
}

// Get returns the predecessor's frozen total plus this version's own.
func Get() int {
	return v0.Get() + counter
}

// Live reports whether the handover has happened.
func Live() bool {
	return v0.Successor() == "gno.land/r/nym-moultest123/x/upgrade/lock/v1"
}

func assertPredecessorRetired() {
	if !Live() {
		panic("lock/v1 is not live yet, " + Predecessor + " must be retired onto it first")
	}
}

func Render(_ string) string {
	if !Live() {
		return ufmt.Sprintf("lock/v1: waiting for %s to retire\n", Predecessor)
	}
	return ufmt.Sprintf("lock/v1: %d (own %d + retired v0 %d)\n", Get(), counter, v0.Get())
}

package lock

import (
	"testing"

	v0 "gno.land/r/nym-moultest123/x/upgrade/lock/v0"

	"gno.land/p/nt/uassert/v0"
)

// TestHandover walks the whole one-writer-at-a-time sequence in order: only v0
// writes, then the retirement flips it, then only v1 writes.
func TestHandover(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(v0.Ownable.Owner()))

	// Before the handover: v0 writes, v1 refuses.
	v0.Inc(cross(cur), 10)
	uassert.False(t, Live(), "v1 must not be live before the handover")
	uassert.AbortsContains(t, cur, "not live yet", func() {
		Inc(cross(cur), 1)
	})
	uassert.Equal(t, 10, Get(), "v1 already reports v0's running total")

	// The handover itself.
	v0.Retire(cross(cur), "gno.land/r/nym-moultest123/x/upgrade/lock/v1")
	uassert.True(t, Live(), "v1 must be live once v0 names it")

	// After: v0 refuses, v1 writes, the total is single-valued.
	uassert.AbortsContains(t, cur, "is retired", func() {
		v0.Inc(cross(cur), 1)
	})
	Inc(cross(cur), 100)
	uassert.Equal(t, 110, Get(), "v1 folds v0's frozen total into its own")
	uassert.Equal(t, 10, v0.Get(), "v0's total is frozen where it stopped")

	// Retirement is one-way.
	uassert.AbortsContains(t, cur, "already retired", func() {
		v0.Retire(cross(cur), "gno.land/r/nym-moultest123/x/upgrade/lock/v2")
	})

	uassert.Equal(t, "lock/v1: 110 (own 100 + retired v0 10)\n", Render(""))
	uassert.Equal(t, "lock/v0: 10 (retired, use gno.land/r/nym-moultest123/x/upgrade/lock/v1)\n", v0.Render(""))
}

