	fs.WriteFile("/bin/ls", "system\n", 100)
	fs.WriteFile("/usr/glenda/bin/ls", "mine\n", 100)
	run(t, sh, "bind -b /usr/glenda/bin /bin")

	if got := run(t, sh, "ls /bin"); got != "ls\nls\n" {
		t.Errorf("a union lists both, as Plan 9 does: %q", got)
