func itoaTest(n int) string {
	if n == 0 {
		return "0"
	}
	s := ""
	for n > 0 {
		s = string(rune(byte(n%10)+byte(48))) + s
		n /= 10
	}
	return s
}

// Package bullscows is a shared on-chain Bulls & Cows puzzle: one secret
// 4-digit code (distinct digits) per round, guessed cooperatively/competitively
// by anyone who calls Guess. Bulls = right digit, right spot. Cows = right
// digit, wrong spot. Whoever hits 4 bulls wins the round and a leaderboard
// entry; a fresh secret is drawn immediately after.
package bullscows

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nym-moultest123/kit/ui/v0"
)

const (
	maxHistory = 10
	maxRecords = 5
)

type guessLog struct {
	player   string
	guess    string
	bulls    int
	cows     int
}

type record struct {
	player   string
	attempts int
	round    int
}

var (
	secret   [4]int
	round    int
	attempts int
	history  []guessLog
	records  []record
)

func init() {
	round = 1
	secret = newSecret(seedFor(round))
}

// seedFor derives a per-round PRNG seed from the current chain height so
// nobody can precompute the next secret before the round actually starts.
func seedFor(r int) int64 {
	return runtime.ChainHeight()*1000003 + int64(r)*7919 + 17
}

// nextRand is a minimal LCG (glibc constants) — no crypto strength needed
// for a casual puzzle, just enough spread across digits.
func nextRand(seed int64) int64 {
	return (seed*1103515245 + 12345) & 0x7fffffff
}

func newSecret(seed int64) [4]int {
	var used [10]bool
	var digits [4]int
	s := seed
	for i := 0; i < 4; i++ {
		for {
			s = nextRand(s)
			d := int(s % 10)
			if !used[d] {
				used[d] = true
				digits[i] = d
				break
			}
		}
	}
	return digits
}

// parseGuess validates a 4-digit, distinct-digit guess string.
func parseGuess(guess string) ([4]int, bool) {
	var out [4]int
	if len(guess) != 4 {
		return out, false
	}
	var used [10]bool
	for i := 0; i < 4; i++ {
		c := guess[i]
		if c < '0' || c > '9' {
			return out, false
		}
		d := int(c - '0')
		if used[d] {
			return out, false
		}
		used[d] = true
		out[i] = d
	}
	return out, true
}

// score returns (bulls, cows) for guess against target, assuming both have
// distinct digits (guaranteed by parseGuess / newSecret).
func score(target, guess [4]int) (int, int) {
	bulls, cows := 0, 0
	for i := 0; i < 4; i++ {
		if guess[i] == target[i] {
			bulls++
			continue
		}
		for j := 0; j < 4; j++ {
			if i != j && guess[i] == target[j] {
				cows++
				break
			}
		}
	}
	return bulls, cows
}

func addHistory(l guessLog) {
	history = append(history, l)
	if len(history) > maxHistory {
		history = history[len(history)-maxHistory:]
	}
}

// addRecord keeps the top maxRecords fastest solves, ascending by attempts.
func addRecord(r record) {
	records = append(records, r)
	for i := len(records) - 1; i > 0 && records[i].attempts < records[i-1].attempts; i-- {
		records[i], records[i-1] = records[i-1], records[i]
	}
	if len(records) > maxRecords {
		records = records[:maxRecords]
	}
}

func startNewRound() {
	round++
	attempts = 0
	history = nil
	secret = newSecret(seedFor(round))
}

// Guess submits a 4-distinct-digit code against the current round's secret.
// Returns the bulls/cows feedback, or "solved!" text when it's a win.
func Guess(cur realm, guess string) string {
	digits, ok := parseGuess(guess)
	if !ok {
		panic("guess must be 4 digits, 0-9, no repeats (e.g. \"1972\")")
	}

	player := cur.Previous().Address().String()
	attempts++
	bulls, cows := score(secret, digits)
	addHistory(guessLog{player: player, guess: guess, bulls: bulls, cows: cows})

	if bulls == 4 {
		wonRound := round
		wonAttempts := attempts
		addRecord(record{player: player, attempts: wonAttempts, round: wonRound})
		startNewRound()
		return "*** SOLVED *** " + guess + " was it — round " + strconv.Itoa(wonRound) +
			" cracked in " + strconv.Itoa(wonAttempts) + " guesses. New round " +
			strconv.Itoa(round) + " has begun, good luck!"
	}

	return guess + " -> " + strconv.Itoa(bulls) + " bulls, " + strconv.Itoa(cows) + " cows"
}

// GiveUp reveals the current secret and starts a fresh round without
// awarding a leaderboard record.
func GiveUp(cur realm) string {
	revealed := digitsToString(secret)
	oldRound := round
	startNewRound()
	return "round " + strconv.Itoa(oldRound) + "'s code was " + revealed +
		" — round " + strconv.Itoa(round) + " is live now."
}

func digitsToString(d [4]int) string {
	var sb strings.Builder
	for _, v := range d {
		sb.WriteString(strconv.Itoa(v))
	}
	return sb.String()
}

func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# Bulls & Cows\n\n")
	sb.WriteString("One shared secret 4-digit code (no repeated digits). Call `Guess(\"1972\")` ")
	sb.WriteString("to get **bulls** (right digit, right spot) and **cows** (right digit, wrong spot). ")
	sb.WriteString("First to 4 bulls wins the round; `GiveUp()` reveals the code and starts over.\n\n")

	sb.WriteString("## Round " + strconv.Itoa(round) + "\n\n")
	sb.WriteString("Attempts so far: **" + strconv.Itoa(attempts) + "**\n\n")

	if len(history) == 0 {
		sb.WriteString("_No guesses yet this round — be the first._\n\n")
	} else {
		sb.WriteString("### Recent guesses\n\n")
		sb.WriteString("| player | guess | bulls | cows |\n|---|---|---|---|\n")
		for i := len(history) - 1; i >= 0; i-- {
			h := history[i]
			sb.WriteString("| " + ui.AddrOf(h.player) + " | " + h.guess + " | " +
				strconv.Itoa(h.bulls) + " | " + strconv.Itoa(h.cows) + " |\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Leaderboard (fastest solves)\n\n")
	if len(records) == 0 {
		sb.WriteString("_Nobody has cracked a code yet._\n")
	} else {
		sb.WriteString("| rank | player | attempts | round |\n|---|---|---|---|\n")
		for i, r := range records {
			sb.WriteString("| " + strconv.Itoa(i+1) + " | " + ui.AddrOf(r.player) + " | " +
				strconv.Itoa(r.attempts) + " | " + strconv.Itoa(r.round) + " |\n")
		}
	}

	return sb.String()
}

package bullscows

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func TestParseGuess(t *testing.T) {
	cases := []struct {
		in string
		ok bool
	}{
		{"1972", true},
		{"0123", true},
		{"11 2", false},
		{"123", false},
		{"12345", false},
		{"1123", false}, // repeated digit
		{"12a3", false},
	}
	for _, c := range cases {
		if _, ok := parseGuess(c.in); ok != c.ok {
			t.Fatalf("parseGuess(%q) ok = %v, want %v", c.in, ok, c.ok)
		}
	}
}

func TestScore(t *testing.T) {
	target := [4]int{1, 9, 7, 2}

	if b, c := score(target, [4]int{1, 9, 7, 2}); b != 4 || c != 0 {
		t.Fatalf("exact match: got bulls=%d cows=%d, want 4/0", b, c)
	}
	if b, c := score(target, [4]int{2, 7, 9, 1}); b != 0 || c != 4 {
		t.Fatalf("full rotation: got bulls=%d cows=%d, want 0/4", b, c)
	}
	if b, c := score(target, [4]int{1, 3, 4, 5}); b != 1 || c != 0 {
		t.Fatalf("one bull: got bulls=%d cows=%d, want 1/0", b, c)
	}
	if b, c := score(target, [4]int{5, 6, 7, 8}); b != 1 || c != 0 {
		t.Fatalf("no overlap but position 7: got bulls=%d cows=%d, want 1/0", b, c)
	}
}

func TestNewSecretDistinctDigits(t *testing.T) {
	for seed := int64(0); seed < 50; seed++ {
		d := newSecret(seed)
		var seen [10]bool
		for _, v := range d {
			if v < 0 || v > 9 {
				t.Fatalf("digit out of range: %d", v)
			}
			if seen[v] {
				t.Fatalf("newSecret(%d) = %v has repeated digit", seed, d)
			}
			seen[v] = true
		}
	}
}

func TestAddRecordKeepsFastestSorted(t *testing.T) {
	records = nil
	addRecord(record{player: "a", attempts: 10, round: 1})
	addRecord(record{player: "b", attempts: 3, round: 2})
	addRecord(record{player: "c", attempts: 7, round: 3})
	addRecord(record{player: "d", attempts: 1, round: 4})
	addRecord(record{player: "e", attempts: 9, round: 5})
	addRecord(record{player: "f", attempts: 2, round: 6}) // pushes out the worst

	if len(records) != maxRecords {
		t.Fatalf("len(records) = %d, want %d", len(records), maxRecords)
	}
	want := []int{1, 2, 3, 7, 9}
	for i, w := range want {
		if records[i].attempts != w {
			t.Fatalf("records[%d].attempts = %d, want %d", i, records[i].attempts, w)
		}
	}
}

func TestAddHistoryCaps(t *testing.T) {
	history = nil
	for i := 0; i < maxHistory+5; i++ {
		addHistory(guessLog{player: "p", guess: strconv.Itoa(i), bulls: 0, cows: 0})
	}
	if len(history) != maxHistory {
		t.Fatalf("len(history) = %d, want %d", len(history), maxHistory)
	}
	if history[len(history)-1].guess != strconv.Itoa(maxHistory+4) {
		t.Fatalf("history did not keep the most recent entries")
	}
}

// Crossing: Guess mutates realm state, needs cur realm + cross(cur).
func TestGuessRoundtrip(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	round = 1
	attempts = 0
	history = nil
	records = nil
	secret = [4]int{1, 9, 7, 2}

	out := Guess(cross(cur), "1234")
	if !strings.Contains(out, "bulls") {
		t.Fatalf("Guess() = %q, want bulls/cows feedback", out)
	}
	if attempts != 1 {
		t.Fatalf("attempts = %d, want 1", attempts)
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	out = Guess(cross(cur), "1972")
	if !strings.Contains(out, "SOLVED") {
		t.Fatalf("Guess() = %q, want a solved message", out)
	}
	if round != 2 {
		t.Fatalf("round = %d, want 2 (new round should start on solve)", round)
	}
	if len(records) != 1 || records[0].attempts != 2 {
		t.Fatalf("records = %v, want one entry with attempts=2", records)
	}
}

func TestGiveUpStartsNewRound(cur realm, t *testing.T) {
	round = 1
	attempts = 3
	secret = [4]int{4, 5, 6, 7}

	out := GiveUp(cross(cur))
	if !strings.Contains(out, "4567") {
		t.Fatalf("GiveUp() = %q, want it to reveal 4567", out)
	}
	if round != 2 || attempts != 0 {
		t.Fatalf("round=%d attempts=%d, want round=2 attempts=0", round, attempts)
	}
}

package bullscows

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// clear restores the globals to their init() state so assertions do not depend
// on which tests ran first. Realm globals live for the whole test binary.
func clear() {
	round = 1
	attempts = 0
	history = nil
	records = nil
	secret = newSecret(seedFor(round))
}

// ExampleRender pins the fresh-round view: no guesses, empty leaderboard.
func ExampleRender() {
	clear()
	print(Render(""))
	// Output:
	// # Bulls & Cows
	//
	// One shared secret 4-digit code (no repeated digits). Call `Guess("1972")` to get **bulls** (right digit, right spot) and **cows** (right digit, wrong spot). First to 4 bulls wins the round; `GiveUp()` reveals the code and starts over.
	//
	// ## Round 1
	//
	// Attempts so far: **0**
	//
	// _No guesses yet this round — be the first._
	//
	// ## Leaderboard (fastest solves)
	//
	// _Nobody has cracked a code yet._
}

// TestRenderHistoryNewestFirst checks the guess table is reverse-chronological.
func TestRenderHistoryNewestFirst(t *testing.T) {
	clear()
	addHistory(guessLog{player: "alice", guess: "1234", bulls: 1, cows: 2})
	addHistory(guessLog{player: "bob", guess: "5678", bulls: 0, cows: 1})

	out := Render("")
	uassert.True(t, strings.Contains(out, "### Recent guesses"), "history section should appear")
	uassert.True(t, strings.Contains(out, "| `bob` | 5678 | 0 | 1 |\n| `alice` | 1234 | 1 | 2 |\n"),
		"newest guess should be listed first")
	uassert.False(t, strings.Contains(out, "_No guesses yet"), "empty-history notice should be gone")
}

// TestRenderLeaderboard checks solved records render in rank order.
func TestRenderLeaderboard(t *testing.T) {
	clear()
	addRecord(record{player: "carol", attempts: 3, round: 1})
	addRecord(record{player: "dave", attempts: 7, round: 2})

	out := Render("")
	uassert.True(t, strings.Contains(out, "| 1 | `carol` | 3 | 1 |\n| 2 | `dave` | 7 | 2 |\n"),
		"leaderboard should rank fastest first")
	uassert.False(t, strings.Contains(out, "_Nobody has cracked a code yet._"),
		"empty-leaderboard notice should be gone")
}

// TestRenderShortensLongAddresses checks the bech32 addresses players actually
// have get elided rather than blowing out the table.
func TestRenderShortensLongAddresses(t *testing.T) {
	clear()
	long := "g1manfred47kzduec920z88wfr64ylksmdcedlf5"
	addHistory(guessLog{player: long, guess: "1234", bulls: 0, cows: 0})

	out := Render("")
	uassert.False(t, strings.Contains(out, long), "full address should not be rendered")
	uassert.True(t, strings.Contains(out, "| `"+long[:8]+"…"+long[len(long)-4:]+"` | 1234 |"),
		"address should be shortened to prefix…suffix")
}

// TestRenderTracksRoundAndAttempts checks the counters reach the page.
func TestRenderTracksRoundAndAttempts(t *testing.T) {
	clear()
	round = 4
	attempts = 11

	out := Render("")
	uassert.True(t, strings.Contains(out, "## Round 4\n"), "round should be shown")
	uassert.True(t, strings.Contains(out, "Attempts so far: **11**"), "attempts should be shown")
}

// TestRenderIgnoresPath documents that Render has no sub-routes.
func TestRenderIgnoresPath(t *testing.T) {
	clear()
	uassert.Equal(t, Render(""), Render("/anything"))
}

// Package closestguess is a blind, multiplayer number-guessing puzzle.
//
// Unlike a classic higher/lower guessing game, closestguess gives NO feedback
// per guess. Each round hides a target in 1..1000 (derived deterministically
// from the block height the round started at); every address may submit
// exactly one blind Guess for the round. Whenever someone calls Reveal, the
// round closes: the target is disclosed, the guess with the smallest absolute
// distance wins (ties go to whoever guessed first), the winner is recorded on
// the leaderboard, and a fresh round starts immediately.
package closestguess

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nym-moultest123/kit/ui/v0"
)

const (
	minTarget = 1
	maxTarget = 1000
)

// roundT holds the mutable state of the open round. The target stays hidden
// (never rendered, never returned) until Reveal closes the round.
type roundT struct {
	number      int
	startHeight int64
	target      int
}

// winRecord is one closed-round result, kept for the leaderboard.
type winRecord struct {
	round    int
	winner   string
	target   int
	guess    int
	distance int
	players  int
}

// guessEntry is one address's blind guess for the current round.
type guessEntry struct {
	addr string
	n    int
}

var (
	current *roundT
	// entries holds one guessEntry per address for the CURRENT round only, in
	// submission order (so Reveal can break distance ties in favor of
	// whoever guessed first). Reset on every Reveal. A plain slice is fine
	// here: rounds are player-scoped and small, unlike long-lived global
	// state where avl.Tree would matter.
	entries []guessEntry
	// leaderboard is append-only across all rounds; sorted on render.
	leaderboard []winRecord
)

func init() {
	current = newRound(1, runtime.ChainHeight())
}

// newRound builds a fresh round whose hidden target derives deterministically
// from the start height and round number. Gno has no runtime RNG, so mixing
// height with the round number is the only available entropy, and it also
// keeps consecutive rounds at the same height from repeating a target.
func newRound(number int, height int64) *roundT {
	return &roundT{
		number:      number,
		startHeight: height,
		target:      targetFromHeight(height, number),
	}
}

func targetFromHeight(h int64, round int) int {
	if h < 0 {
		h = -h
	}
	span := int64(maxTarget - minTarget + 1)
	mixed := h*2654435761 + int64(round)*40503 + 12345
	if mixed < 0 {
		mixed = -mixed
	}
	return int(mixed%span) + minTarget
}

// Guess records the caller's single blind guess for the current round. It
// returns no hint about correctness — that is the whole point of the puzzle.
// Crossing function: caller invokes as Guess(cross(cur), n).
func Guess(cur realm, n int) string {
	if n < minTarget || n > maxTarget {
		panic("guess must be in " + strconv.Itoa(minTarget) + ".." + strconv.Itoa(maxTarget))
	}

	caller := cur.Previous().Address().String()
	if hasGuessed(caller) {
		panic("you already guessed this round; wait for Reveal()")
	}

	entries = append(entries, guessEntry{addr: caller, n: n})

	chain.Emit("GuessSubmitted",
		"round", strconv.Itoa(current.number),
		"player", caller,
	)

	return "guess recorded for round " + strconv.Itoa(current.number) + " (" +
		strconv.Itoa(len(entries)) + " player(s) so far) — call Reveal() to see who's closest"
}

func hasGuessed(addr string) bool {
	for _, e := range entries {
		if e.addr == addr {
			return true
		}
	}
	return false
}

// Reveal closes the current round: discloses the target, crowns whoever
// landed closest (ties favor the earliest guesser), records a leaderboard
// entry, and opens a fresh round. Panics if nobody has guessed yet.
// Crossing function.
func Reveal(cur realm) string {
	if len(entries) == 0 {
		panic("no guesses submitted yet this round")
	}

	target := current.target
	winner := entries[0]
	best := distance(winner.n, target)
	for _, e := range entries[1:] {
		if d := distance(e.n, target); d < best {
			best = d
			winner = e
		}
	}

	rec := winRecord{
		round:    current.number,
		winner:   winner.addr,
		target:   target,
		guess:    winner.n,
		distance: best,
		players:  len(entries),
	}
	leaderboard = append(leaderboard, rec)

	chain.Emit("RoundRevealed",
		"round", strconv.Itoa(rec.round),
		"winner", winner.addr,
		"target", strconv.Itoa(target),
		"distance", strconv.Itoa(best),
	)

	closedRound := current.number
	current = newRound(closedRound+1, runtime.ChainHeight())
	entries = nil

	return "round " + strconv.Itoa(closedRound) + " revealed: target was " + strconv.Itoa(target) +
		" — " + ui.AddrOf(winner.addr) + " wins, guessed " + strconv.Itoa(winner.n) +
		" (distance " + strconv.Itoa(best) + ") among " + strconv.Itoa(rec.players) +
		" player(s). Round " + strconv.Itoa(current.number) + " is now open."
}

func distance(guess, target int) int {
	d := guess - target
	if d < 0 {
		d = -d
	}
	return d
}

// Render produces the gnoweb Markdown view. The current round's target and
// individual guess values are never shown — only the player count — so
// rendering the page can't leak the puzzle.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Closest Guess\n\n")
	b.WriteString("A blind, multiplayer number-guessing puzzle. Each round hides a target in ")
	b.WriteString("**" + strconv.Itoa(minTarget) + ".." + strconv.Itoa(maxTarget) + "**. ")
	b.WriteString("Call `Guess(n)` once per round — you get no feedback. ")
	b.WriteString("Anyone can call `Reveal()` to close the round: the target is disclosed and ")
	b.WriteString("whoever landed closest wins.\n\n")

	b.WriteString("## Current round\n\n")
	b.WriteString("- Round: **" + strconv.Itoa(current.number) + "**\n")
	b.WriteString("- Started at block height: " + strconv.FormatInt(current.startHeight, 10) + "\n")
	b.WriteString("- Players guessed so far: " + strconv.Itoa(len(entries)) + "\n")
	b.WriteString("- Status: **open** — target hidden until `Reveal()` is called.\n\n")

	b.WriteString("## Leaderboard (closest-ever wins)\n\n")
	b.WriteString(renderLeaderboard())

	b.WriteString("\n## How to play\n\n")
	b.WriteString("```\n")
	b.WriteString("Guess(n)   // n in 1..1000, one shot per address per round, no feedback\n")
	b.WriteString("Reveal()   // closes the round: reveals target, crowns the closest guess\n")
	b.WriteString("```\n")

	return b.String()
}

// renderLeaderboard formats closed rounds ranked by smallest distance (ties:
// earlier round first). Sorted on a copy so state is untouched.
func renderLeaderboard() string {
	if len(leaderboard) == 0 {
		return "_No round has been revealed yet — be the first to call `Reveal()`!_\n"
	}

	ranked := make([]winRecord, len(leaderboard))
	copy(ranked, leaderboard)
	sortByClosest(ranked)

	var b strings.Builder
	b.WriteString("| Rank | Player | Round | Target | Guess | Distance | Players |\n")
	b.WriteString("|---|---|---|---|---|---|---|\n")
	for i, w := range ranked {
		b.WriteString("| " + strconv.Itoa(i+1) + " | " + ui.AddrOf(w.winner) + " | " +
			strconv.Itoa(w.round) + " | " + strconv.Itoa(w.target) + " | " +
			strconv.Itoa(w.guess) + " | " + strconv.Itoa(w.distance) + " | " +
			strconv.Itoa(w.players) + " |\n")
	}
	return b.String()
}

// sortByClosest does an in-place insertion sort: smallest distance first,
// then earlier round first on ties. Small n; insertion sort keeps it
// deterministic and dependency-free.
func sortByClosest(rs []winRecord) {
	for i := 1; i < len(rs); i++ {
		j := i
		for j > 0 && closer(rs[j], rs[j-1]) {
			rs[j], rs[j-1] = rs[j-1], rs[j]
			j--
		}
	}
}

func closer(a, b winRecord) bool {
	if a.distance != b.distance {
		return a.distance < b.distance
	}
	return a.round < b.round
}

package closestguess

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

// resetGame re-initializes package globals so each test starts clean; init()
// runs only once for the whole test binary.
func resetGame(height int64) {
	current = newRound(1, height)
	entries = nil
	leaderboard = nil
}

func TestTargetFromHeight(t *testing.T) {
	tests := []struct {
		name   string
		height int64
	}{
		{"zero", 0},
		{"one", 1},
		{"large", 123456},
		{"negative", -42},
	}
	for _, tt := range tests {
		got := targetFromHeight(tt.height, 1)
		if got < minTarget || got > maxTarget {
			t.Errorf("%s: targetFromHeight(%d,1)=%d, want in %d..%d", tt.name, tt.height, got, minTarget, maxTarget)
		}
		if again := targetFromHeight(tt.height, 1); again != got {
			t.Errorf("%s: non-deterministic: %d != %d", tt.name, again, got)
		}
	}

	// Different round numbers at the same height should (almost always) mix
	// to different targets, so consecutive rounds don't repeat.
	a := targetFromHeight(100, 1)
	b := targetFromHeight(100, 2)
	if a == b {
		t.Errorf("targetFromHeight(100,1) == targetFromHeight(100,2) == %d, want them to differ", a)
	}
}

func TestDistance(t *testing.T) {
	cases := []struct{ a, b, want int }{
		{5, 5, 0},
		{5, 8, 3},
		{8, 5, 3},
		{0, 1000, 1000},
	}
	for _, c := range cases {
		if got := distance(c.a, c.b); got != c.want {
			t.Errorf("distance(%d,%d) = %d, want %d", c.a, c.b, got, c.want)
		}
	}
}

// TestGuessRejectsOutOfRangeAndDuplicate exercises the crossing Guess
// function, so it takes cur realm and calls through cross(cur). A panic
// raised across the crossing call boundary isn't catchable by a plain
// defer/recover; revive() is the boundary-aware way to assert on it.
func TestGuessRejectsOutOfRangeAndDuplicate(cur realm, t *testing.T) {
	resetGame(10)

	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	if r := revive(func() { Guess(cross(cur), 0) }); r == nil {
		t.Error("Guess(0) should panic: out of range")
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	msg := Guess(cross(cur), 500)
	if !strings.Contains(msg, "recorded") {
		t.Errorf("Guess(500) = %q, want it to mention 'recorded'", msg)
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	if r := revive(func() { Guess(cross(cur), 501) }); r == nil {
		t.Error("second Guess from the same address should panic")
	}
}

// TestRevealPicksClosestAndStartsNewRound exercises Guess + Reveal together.
func TestRevealPicksClosestAndStartsNewRound(cur realm, t *testing.T) {
	resetGame(50)
	target := current.target
	prevRound := current.number

	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	far := target + 100
	if far > maxTarget {
		far = target - 100
	}
	if far < minTarget {
		far = minTarget
	}
	near := target + 1
	if near > maxTarget {
		near = target - 1
	}
	if near < minTarget {
		near = minTarget
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	Guess(cross(cur), far)
	testing.SetRealm(testing.NewUserRealm(bob))
	Guess(cross(cur), near)

	msg := Reveal(cross(cur))
	if !strings.Contains(msg, "revealed") {
		t.Errorf("Reveal() = %q, want it to mention 'revealed'", msg)
	}
	if len(leaderboard) != 1 {
		t.Fatalf("leaderboard len = %d, want 1", len(leaderboard))
	}
	if leaderboard[0].winner != bob.String() {
		t.Errorf("winner = %q, want %q (closer guess)", leaderboard[0].winner, bob.String())
	}
	if current.number != prevRound+1 {
		t.Errorf("round number = %d, want %d", current.number, prevRound+1)
	}
	if len(entries) != 0 {
		t.Errorf("entries should reset after Reveal, got %d", len(entries))
	}
}

// TestRevealPanicsWithNoGuesses checks the panic path via revive() (see the
// note on TestGuessRejectsOutOfRangeAndDuplicate).
func TestRevealPanicsWithNoGuesses(cur realm, t *testing.T) {
	resetGame(1)
	if r := revive(func() { Reveal(cross(cur)) }); r == nil {
		t.Error("Reveal() with no guesses should panic")
