// Package microblog is a public microblog wall for gno.land.
//
// Anyone can Post a short message (<= maxMsgLen chars). Every post records
// the caller address, the message, and the block height at which it was made.
// Render displays the wall newest-first, 20 posts per page, with pagination
// driven by the Render path (e.g. "?page=2" or "/2").
package microblog

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nym-moultest123/kit/ui/v0"
)

// maxMsgLen is the maximum length (in bytes) of a single post.
const maxMsgLen = 280

// pageSize is how many posts a single Render page shows.
const pageSize = 20

// post is a single microblog entry.
type post struct {
	Author string // bech32 address of the poster
	Msg    string // the message body
	Height int64  // block height at which it was posted
}

// posts is the append-only wall, in chronological (oldest-first) order.
// Render reverses this view to show newest-first.
var posts []post

// Post publishes msg to the wall. It is a crossing function: callers invoke it
// with Post(cross(cur), "hello"). It panics if msg is empty or longer than
// maxMsgLen bytes.
func Post(cur realm, msg string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if len(msg) == 0 {
		panic("microblog: empty message")
	}
	if len(msg) > maxMsgLen {
		panic("microblog: message too long (max " + strconv.Itoa(maxMsgLen) + " bytes)")
	}

	author := unsafe.PreviousRealm().Address()

	posts = append(posts, post{
		Author: author.String(),
		Msg:    msg,
		Height: runtime.ChainHeight(),
	})

	chain.Emit("Post", "author", author.String(), "len", strconv.Itoa(len(msg)))
}

// Count returns the total number of posts on the wall.
func Count() int {
	return len(posts)
}

// Render renders the wall as Markdown, newest-first, pageSize posts per page.
// The page is parsed from path: "?page=N", "?p=N", "/N", or a bare "N" all
// select page N (1-indexed). Anything else defaults to page 1.
func Render(path string) string {
	total := len(posts)
	page := parsePage(path)

	var b strings.Builder
	b.WriteString("# Microblog Wall\n\n")

	if total == 0 {
		b.WriteString("_No posts yet. Be the first to post._\n")
		return b.String()
	}

	pages := (total + pageSize - 1) / pageSize
	if page < 1 {
		page = 1
	}
	if page > pages {
		page = pages
	}

	b.WriteString(strconv.Itoa(total))
	b.WriteString(" posts total · page ")
	b.WriteString(strconv.Itoa(page))
	b.WriteString(" of ")
	b.WriteString(strconv.Itoa(pages))
	b.WriteString("\n\n")

	// Newest-first: post index total-1 is newest. For page p (1-indexed),
	// skip (p-1)*pageSize newest posts, then take up to pageSize.
	start := total - 1 - (page-1)*pageSize
	end := start - pageSize + 1
	if end < 0 {
		end = 0
	}

	for i := start; i >= end; i-- {
		p := posts[i]
		b.WriteString("- **")
		b.WriteString(ui.AddrOf(p.Author))
		b.WriteString("** · height ")
		b.WriteString(strconv.FormatInt(p.Height, 10))
		b.WriteString("\n\n  ")
		b.WriteString(ui.Inline(p.Msg))
		b.WriteString("\n")
	}

	b.WriteString("\n")
	b.WriteString(renderNav(page, pages))
	return b.String()
}

// renderNav builds a simple prev/next navigation footer as Markdown links.
func renderNav(page, pages int) string {
	var b strings.Builder
	if page > 1 {
		b.WriteString("[← newer](?page=")
		b.WriteString(strconv.Itoa(page - 1))
		b.WriteString(")")
	}
	if page > 1 && page < pages {
		b.WriteString(" · ")
	}
	if page < pages {
		b.WriteString("[older →](?page=")
		b.WriteString(strconv.Itoa(page + 1))
		b.WriteString(")")
	}
	if b.Len() == 0 {
		return ""
	}
	return b.String() + "\n"
}

// parsePage extracts the 1-indexed page number from a Render path. It accepts
// "?page=N", "?p=N", "/N", and a bare "N". Unrecognized input yields page 1.
func parsePage(path string) int {
	path = strings.TrimSpace(path)
	if path == "" {
		return 1
	}

	// Query form: "?page=2&foo=bar" or "?p=2".
	if idx := strings.IndexByte(path, '?'); idx >= 0 {
		query := path[idx+1:]
		for _, part := range strings.Split(query, "&") {
			kv := strings.SplitN(part, "=", 2)
			if len(kv) != 2 {
				continue
			}
			if kv[0] == "page" || kv[0] == "p" {
				if n, err := strconv.Atoi(strings.TrimSpace(kv[1])); err == nil {
					return n
				}
			}
		}
		return 1
	}

	// Path form: "/2" or "2".
	seg := strings.TrimPrefix(path, "/")
	if n, err := strconv.Atoi(seg); err == nil {
		return n
	}
	return 1
}

package microblog

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// resetWall clears package state between tests (globals persist in-process,
// and subtests do not reset them — do it explicitly).
func resetWall() { posts = nil }

// asUser must be inlined into each test: SetRealm affects the calling frame
// only. We therefore call it directly in the test bodies below.

func TestPostAndCount(cur realm, t *testing.T) {
	resetWall()

	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "hello wall")

	if got := Count(); got != 1 {
		t.Fatalf("Count() = %d, want 1", got)
	}
	if posts[0].Msg != "hello wall" {
		t.Errorf("Msg = %q, want %q", posts[0].Msg, "hello wall")
	}
	if posts[0].Author != alice.String() {
		t.Errorf("Author = %q, want %q", posts[0].Author, alice.String())
	}
}

func TestPostTooLongPanics(cur realm, t *testing.T) {
	resetWall()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("bob")))

	// Aborts from a cross(cur) call cannot be caught by a plain recover();
	// assert on the abort message instead.
	uassert.AbortsWithMessage(t, cur, "microblog: message too long (max 280 bytes)", func() {
		Post(cross(cur), strings.Repeat("x", maxMsgLen+1))
	})
}

func TestPostEmptyPanics(cur realm, t *testing.T) {
	resetWall()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("bob")))

	// Aborts from a cross(cur) call cannot be caught by a plain recover();
	// assert on the abort message instead.
	uassert.AbortsWithMessage(t, cur, "microblog: empty message", func() {
		Post(cross(cur), "")
	})
}

func TestPostMaxLenOK(cur realm, t *testing.T) {
	resetWall()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("carol")))

	// Exactly maxMsgLen bytes must be accepted.
	Post(cross(cur), strings.Repeat("y", maxMsgLen))
	if got := Count(); got != 1 {
		t.Fatalf("Count() = %d, want 1 for exactly-max message", got)
	}
}

func TestRenderEmpty(t *testing.T) {
	resetWall()
	out := Render("")
	if !strings.Contains(out, "No posts yet") {
		t.Errorf("empty Render should mention no posts, got:\n%s", out)
	}
}

func TestRenderNewestFirstAndPagination(cur realm, t *testing.T) {
	resetWall()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("dave")))

	// 25 posts -> 2 pages (20 + 5).
	for i := 0; i < 25; i++ {
		Post(cross(cur), "msg"+itoa(i))
	}

	if got := Count(); got != 25 {
		t.Fatalf("Count() = %d, want 25", got)
	}

	page1 := Render("")
	// Newest (msg24) must appear before older (msg5) on page 1.
	i24 := strings.Index(page1, "msg24")
	i5 := strings.Index(page1, "msg5")
	if i24 < 0 || i5 < 0 {
		t.Fatalf("page 1 missing expected posts: msg24=%d msg5=%d", i24, i5)
	}
	if i24 > i5 {
		t.Errorf("page 1 not newest-first: msg24 at %d should precede msg5 at %d", i24, i5)
	}
	if !strings.Contains(page1, "page 1 of 2") {
		t.Errorf("page 1 header wrong, got:\n%s", page1)
	}

	// Page 2 via query form must contain the oldest post.
	page2 := Render("?page=2")
	if !strings.Contains(page2, "msg0") {
		t.Errorf("page 2 should contain oldest msg0, got:\n%s", page2)
	}
	if !strings.Contains(page2, "page 2 of 2") {
		t.Errorf("page 2 header wrong, got:\n%s", page2)
	}

	// Path form "/2" should equal query form "?page=2".
	if Render("/2") != page2 {
		t.Errorf("path form /2 differs from query form ?page=2")
	}
}

func TestParsePage(t *testing.T) {
	cases := []struct {
		in   string
		want int
	}{
		{"", 1},
		{"?page=3", 3},
		{"?p=4", 4},
		{"/2", 2},
		{"5", 5},
		{"?page=abc", 1},
		{"garbage", 1},
	}
	for _, c := range cases {
		if got := parsePage(c.in); got != c.want {
			t.Errorf("parsePage(%q) = %d, want %d", c.in, got, c.want)
		}
	}
}

// itoa is a tiny local int->string helper for building test messages.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package moodstone

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nym-moultest123/kit/ui/v0"
)

// Entry holds a single mood log.
type Entry struct {
	Author address
	Mood   string
	Note   string
	Block  int64
}

var entries []Entry

var validMoods = []string{"happy", "sad", "excited", "calm", "anxious", "angry", "neutral"}

func isValid(mood string) bool {
	for _, m := range validMoods {
		if m == mood {
			return true
		}
	}
	return false
}

func emoji(mood string) string {
	switch mood {
	case "happy":
		return "😊"
	case "sad":
		return "😢"
	case "excited":
		return "🎉"
	case "calm":
		return "😌"
	case "anxious":
		return "😰"
	case "angry":
		return "😠"
	case "neutral":
		return "😐"
	}
	return "❓"
}

func bar(count, total int) string {
	if total == 0 {
		return strings.Repeat("░", 20)
	}
	filled := (count * 20) / total
	return strings.Repeat("▓", filled) + strings.Repeat("░", 20-filled)
}

// LogMood records the caller's current mood with an optional note.
// mood must be one of: happy sad excited calm anxious angry neutral
func LogMood(_ realm, mood, note string) {
	mood = strings.ToLower(strings.TrimSpace(mood))
	if !isValid(mood) {
		panic("invalid mood; choose from: " + strings.Join(validMoods, ", "))
	}
	entries = append(entries, Entry{
		Author: unsafe.OriginCaller(),
		Mood:   mood,
		Note:   strings.TrimSpace(note),
		Block:  runtime.ChainHeight(),
	})
}

// TotalEntries returns the total number of mood logs on record.
func TotalEntries() int {
	return len(entries)
}

// MoodCount returns how many times the given mood has been logged.
func MoodCount(mood string) int {
	mood = strings.ToLower(strings.TrimSpace(mood))
	n := 0
	for _, e := range entries {
		if e.Mood == mood {
			n++
		}
	}
	return n
}

// DominantMood returns the most-logged mood, or "none" if no entries.
func DominantMood() string {
	if len(entries) == 0 {
		return "none"
	}
	counts := make(map[string]int)
	for _, e := range entries {
		counts[e.Mood]++
	}
	best := ""
	bestN := 0
	for _, m := range validMoods {
		if counts[m] > bestN {
			bestN = counts[m]
			best = m
		}
	}
	return best
}

func Render(path string) string {
	out := "# 🪨 Moodstone — On-chain Mood Tracker\n\n"
	out += "> Log how you feel. Watch how the community feels. Immutably, on Gno.\n\n"

	total := len(entries)

	// Community stats table
	out += "## 📊 Community Vibes\n\n"
	if total == 0 {
		out += "*No moods logged yet — be the first!*\n\n"
	} else {
		counts := make(map[string]int)
		for _, e := range entries {
			counts[e.Mood]++
		}
		out += "| Mood | Count | Distribution |\n"
		out += "|------|-------|--------------|\n"
		for _, m := range validMoods {
			c := counts[m]
			pct := 0
			if total > 0 {
				pct = (c * 100) / total
			}
			out += "| " + emoji(m) + " " + m + " | " + strconv.Itoa(c) +
				" | `" + bar(c, total) + "` " + strconv.Itoa(pct) + "% |\n"
		}
		dom := DominantMood()
		out += "\n**Total entries:** " + strconv.Itoa(total) +
			" · **Dominant mood:** " + emoji(dom) + " " + dom + "\n\n"
	}

	// Recent entries (newest first, max 10)
	out += "## 📝 Recent Entries\n\n"
	if total == 0 {
		out += "*Nothing here yet.*\n\n"
	} else {
		start := total - 10
		if start < 0 {
			start = 0
		}
		for i := total - 1; i >= start; i-- {
			e := entries[i]
			line := "- " + emoji(e.Mood) + " **" + e.Mood + "**"
			if e.Note != "" {
				line += ": *" + e.Note + "*"
			}
			line += " — " + ui.Addr(e.Author) + " at block " +
				strconv.FormatInt(e.Block, 10)
			out += line + "\n"
		}
		out += "\n"
	}

	// How to use
	out += "## 🚀 How to Use\n\n"
	out += "```bash\n"
	out += "gnokey maketx call \\\n"
	out += "  -pkgpath gno.land/r/g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz/moodstone \\\n"
	out += "  -func LogMood \\\n"
	out += "  -args 'happy' -args 'Just shipped something awesome!'\n"
	out += "```\n\n"
	out += "**Valid moods:** " + strings.Join(validMoods, " · ") + "\n"

	return out
}

