)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

// resetState clears package-level state between tests so cases are independent.
func resetState() {
	polls = nil
	nextID = 0
}

func TestParseOptions(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  []string
	}{
		{"simple", "a,b,c", []string{"a", "b", "c"}},
		{"trims spaces", " yes , no ", []string{"yes", "no"}},
		{"drops empties", "a,,b, ,c", []string{"a", "b", "c"}},
		{"single", "only", []string{"only"}},
		{"all blank", " , ,", nil},
	}
	for _, tt := range tests {
		got := parseOptions(tt.input)
		if len(got) != len(tt.want) {
			t.Errorf("%s: len = %d, want %d (%v)", tt.name, len(got), len(tt.want), got)
			continue
		}
		for i := range got {
			if got[i] != tt.want[i] {
				t.Errorf("%s: [%d] = %q, want %q", tt.name, i, got[i], tt.want[i])
			}
		}
	}
}

func TestCreateAndVote(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))

	id := CreatePoll(cross(cur), "Best chain?", "gno,eth,btc")
	if id != 0 {
		t.Fatalf("first poll id = %d, want 0", id)
	}
	if PollCount() != 1 {
		t.Fatalf("PollCount = %d, want 1", PollCount())
	}

	// alice votes gno.
	Vote(cross(cur), id, 0)

	// bob votes eth.
	testing.SetRealm(testing.NewUserRealm(bob))
	Vote(cross(cur), id, 1)

	// carol votes gno.
	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), id, 0)

	p := getPoll(id)
	if p.Tallies[0] != 2 {
		t.Errorf("gno tally = %d, want 2", p.Tallies[0])
	}
	if p.Tallies[1] != 1 {
		t.Errorf("eth tally = %d, want 1", p.Tallies[1])
	}
	if total(p.Tallies) != 3 {
		t.Errorf("total = %d, want 3", total(p.Tallies))
	}
}

func TestDoubleVotePanics(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))

	id := CreatePoll(cross(cur), "Coffee or tea?", "coffee,tea")
	Vote(cross(cur), id, 0)

	// A second vote by the same address aborts (cross-realm panic).
	uassert.AbortsWithMessage(t, cur, "address already voted on this poll", func() {
		Vote(cross(cur), id, 1)
	})
}

func TestVoteBounds(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))

	id := CreatePoll(cross(cur), "A or B?", "a,b")

	uassert.AbortsWithMessage(t, cur, "option index out of range", func() {
		Vote(cross(cur), id, 5)
	})
}

func TestCreatePollNeedsTwoOptions(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsWithMessage(t, cur, "a poll needs at least 2 options", func() {
		CreatePoll(cross(cur), "One?", "only")
	})
}

func TestRender(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))

	// Empty index.
	if got := Render(""); !strings.Contains(got, "No polls yet") {
		t.Errorf("empty Render should mention no polls, got:\n%s", got)
	}

	id := CreatePoll(cross(cur), "Pick one", "x,y")
	Vote(cross(cur), id, 0)

	// Index lists the poll and bar chart glyphs.
	idx := Render("")
	if !strings.Contains(idx, "Pick one") {
		t.Errorf("index missing question:\n%s", idx)
	}
	if !strings.Contains(idx, "▓") || !strings.Contains(idx, "░") {
		t.Errorf("index missing bar glyphs:\n%s", idx)
	}
	if !strings.Contains(idx, "Total votes: 1") {
		t.Errorf("index missing total votes:\n%s", idx)
	}
	if !strings.Contains(idx, "100%") {
		t.Errorf("index missing 100%% for the sole vote:\n%s", idx)
	}

	// Single-poll path.
	single := Render("0")
	if !strings.Contains(single, "Poll #0") {
		t.Errorf("single Render missing poll header:\n%s", single)
	}

	// Unknown path.
	if got := Render("99"); !strings.Contains(got, "not found") {
		t.Errorf("unknown poll should say not found, got:\n%s", got)
	}
}

package polls

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// What a creator may store is bounded, and the root page renders a fixed
// window of the newest polls whatever the count.
func TestPollsAreBounded(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("bounded")))
	uassert.AbortsContains(t, cur, "question too long", func() { CreatePoll(cross(cur), strings.Repeat("q", MaxQuestionLen+1), "a,b") })
	uassert.AbortsContains(t, cur, "at most", func() { CreatePoll(cross(cur), "many", strings.Repeat("o,", MaxOptions)+"o") })
	for len(polls) < IndexRecent+3 {
		CreatePoll(cross(cur), "filler", "a,b")
	}
	uassert.Equal(t, IndexRecent, strings.Count(Render(""), "## Poll #"))
}

// The poll count is bounded globally.
func TestPollCountIsBounded(cur realm, t *testing.T) {
	before := len(polls)
	for len(polls) < MaxPolls {
		polls = append(polls, &Poll{ID: len(polls), Question: "q", Options: []string{"a", "b"}, Tallies: []int{0, 0}})
	}
	defer func() { polls = polls[:before] }()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("latecomer")))
	uassert.AbortsContains(t, cur, "polls is full", func() { CreatePoll(cross(cur), "one more", "a,b") })
}

// Polls past the newest page stay reachable: the index links to the next
// page, and a page past the end says so instead of wrapping.
func TestOlderPollsArePaged(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("pager")))
	for len(polls) < IndexRecent+1 {
		CreatePoll(cross(cur), "filler", "a,b")
	}
	idx := Render("")
	uassert.True(t, strings.Contains(idx, "(/r/nym-moultest123/x/daily/polls/v1:page/2)"), idx)
	p2 := Render("page/2")
	uassert.True(t, strings.Contains(p2, "## Poll #0:"), p2)
	uassert.True(t, strings.Contains(Render("page/9223372036854775807"), "No such page"))
}

