	m, ok := get(alice)
	uassert.True(t, ok, "expected a mine")
	uassert.Equal(t, int64(1), m.level)
	uassert.Equal(t, int64(0), m.prestige)
	uassert.Equal(t, t0, m.anchor)
	uassert.Equal(t, int64(0), m.pending)
}

