// Package lastwords is one string, on chain, forever.
//
// There is a single message slot. Pay more than the last writer paid and the
// slot is yours; when the clock finally runs out, whatever is in it stays there
// permanently. The artefact at the end is the point, so the game is a bidding
// war over an epitaph rather than over a prize.
//
// The three rules exist because the obvious version of this game does not end
// and does not pay:
//
//  1. THE CLOCK TERMINATES. Every write pushes the deadline a fifth of the way
//     to a hard end fixed when the slot opened, and no write can push it past
//     that. A constant extension per action has no end: the pot grows faster
//     than the price of the next write, so there is always a rational next
//     write and the game runs until everyone is bored or broke.
//  2. THE LAST WRITER DOES NOT TAKE THE POT. They take the slot, which is what
//     they were bidding for. The pot is split among everyone ELSE who wrote,
//     pro rata to what they paid. Winner-takes-all makes the second-to-last
//     writer the mark and everyone knows it, which is why nobody joins.
//  3. HALF OF EVERY PAYMENT GOES TO THE WRITER BEING DISPLACED, immediately.
//     A zero-sum game minus gas has no reason for a second player. Overwriting
//     somebody pays them, so being overwritten early is not a loss.
//
// Nothing is ever pushed: payouts are credited to an internal ledger and swept
// by Withdraw. A realm that pays inside a loop over its roster is a gas bomb
// that eventually bricks, and the bigger the game gets the more certain that
// is.
//
// The pieces are libraries, and the realm is the wiring:
// [p/moul/x/games/clock](/p/nym-moultest123/x/games/clock/v0) owns the deadline and its
// guards, [p/moul/x/games/prorata](/p/nym-moultest123/x/games/prorata/v0) owns the split,
// and [p/moul/x/daily/pullpayment](/p/nym-moultest123/x/daily/pullpayment/v0) owns the
// credit ledger.
package lastwords

import (
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nym-moultest123/x/daily/pullpayment/v0"
	"gno.land/p/nym-moultest123/x/games/clock/v0"
	"gno.land/p/nym-moultest123/x/games/prorata/v0"
	"gno.land/p/nt/avl/v0"
)

const denom = "ugnot"

// The rules, fixed at deploy. Times are block heights.
const (
	// Window is how long the slot stays open with nobody writing.
	Window = int64(2000)
	// Floor is the minimum a write leaves on the clock, so the last stretch
	// stays long enough for a transaction to land in. Without it a decaying
	// extension shrinks to nothing and whoever holds at that moment wins by
	// being unreachable rather than by paying.
	Floor = int64(300)
	// Life is the hard end. No write can push the deadline past start+Life.
	Life = int64(100000)
	// BumpPct is how much of the gap to the hard end a write buys.
	BumpPct = int64(20)
	// DividendPct is the share of a payment credited to the writer being
	// displaced; the rest goes to the pot.
	DividendPct = int64(50)

	// MinWrite is the base price of the slot, in ugnot.
	MinWrite = int64(1000000)
	// PerByte is charged on top, in ugnot per byte of the message. The chain's
	// own storage deposit is 100 ugnot per byte, so this is that plus a premium
	// for occupying the only slot there is.
	PerByte = int64(1000)
	// MaxLen caps the message in bytes, because the message IS the storage
	// cost and an uncapped one is an unbounded write priced at a constant.
	MaxLen = 280
)

var (
	clk     *clock.Clock
	ledger  = pullpayment.New()
	message string
	author  address
	paid    int64    // what the current holder paid
	pot     int64    // what settlement will split
	writers avl.Tree // address string -> int64 total paid
	order   []string // writers in first-write order, so the split is deterministic
	writes  int64
	settled bool
)

func init() {
	open(runtime.ChainHeight())
}

// open resets the game to a fresh slot at height h. It is the only place the
// clock is built, so tests and init cannot disagree about the rules.
func open(h int64) {
	c, err := clock.New(h, Window, Floor, Life)
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	clk = c
	ledger = pullpayment.New()
	message = ""
	author = ""
	paid = 0
	pot = 0
	writers = avl.Tree{}
	order = nil
	writes = 0
	settled = false
}

// Price returns what msg costs to write right now, in ugnot: a base, plus a
// charge per byte, and always at least one ugnot more than the current holder
// paid. Query it before sending; an underpaying write is refused, not refunded.
func Price(msg string) int64 {
	price := MinWrite + int64(len(msg))*PerByte
	if next := paid + 1; next > price {
		price = next
	}
	return price
}

// Write puts msg in the slot and makes the caller its holder. The caller must
// send at least Price(msg) ugnot with the transaction.
//
// Half of the payment is credited to the writer being displaced and the rest
// joins the pot. The deadline is pushed a fifth of the way toward the hard end,
// never past it, and never to less than Floor from now.
//
// Only a direct user transaction may write, so the payment envelope cannot be
// spoofed by an ephemeral MsgRun realm.
func Write(cur realm, msg string) {
	if !cur.Previous().IsUserCall() {
		panic("lastwords: write must be a direct user transaction")
	}
	h := runtime.ChainHeight()
	if clk.Expired(h) {
		panic("lastwords: the slot is closed, these are somebody's last words now")
	}
	if msg == "" {
		panic("lastwords: message must not be empty")
	}
	if len(msg) > MaxLen {
		panic("lastwords: message must be at most " + strconv.Itoa(MaxLen) + " bytes")
	}
	if strings.ContainsAny(msg, "\n\r") {
		panic("lastwords: message must be a single line")
	}

	price := Price(msg)
	sent := unsafe.OriginSend().AmountOf(denom)
	if sent < price {
		panic("lastwords: sent " + strconv.FormatInt(sent, 10) +
			" ugnot, price is " + strconv.FormatInt(price, 10))
	}

	caller := cur.Previous().Address()

	// The displaced writer is paid first, out of the payment that displaced
	// them. Credited, never sent: see the package doc.
	dividend := int64(0)
	if author != "" {
		dividend = sent * DividendPct / 100
		if err := ledger.Credit(author.String(), dividend); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot += sent - dividend

	key := caller.String()
	if _, seen := writers.Get(key).(int64); !seen {
		order = append(order, key)
	}
	writers.Set(key, totalPaid(key)+sent)

	message = msg
	author = caller
	paid = sent
	writes++

	deadline, err := clk.BumpShare(h, BumpPct)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	chain.Emit("Write",
		"author", key,
		"paid", strconv.FormatInt(sent, 10),
		"dividend", strconv.FormatInt(dividend, 10),
		"deadline", strconv.FormatInt(deadline, 10),
	)
}

// Settle closes the game once the clock has run out, splitting the pot among
// every writer EXCEPT the one holding the slot, pro rata to what each paid.
//
// Anyone may call it: leaving settlement to an interested party is how a pot
// stays unclaimed. It moves no coins, it credits the ledger; Withdraw is what
// pays. If the holder is the only writer there is nobody else to split with,
// so the pot returns to them.
func Settle(cur realm) {
	h := runtime.ChainHeight()
	if !clk.Expired(h) {
		panic("lastwords: still open until height " + strconv.FormatInt(clk.Deadline(), 10))
	}
	if settled {
		panic("lastwords: already settled")
	}
	settled = true
	if pot == 0 {
		return
	}

	holder := author.String()
	payees := []string{}
	weights := []int64{}
	for _, k := range order {
		if k == holder {
			continue
		}
		payees = append(payees, k)
		weights = append(weights, totalPaid(k))
	}
	if len(payees) == 0 {
		// The holder wrote every word there is. Nobody to share with.
		payees = []string{holder}
		weights = []int64{1}
	}

	shares, err := prorata.Split(pot, weights)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	// A zero share is dropped: CreditMany refuses a non-positive amount, and
	// crediting nothing is not a payment anyway.
	dst := []string{}
	amounts := []int64{}
	for i, s := range shares {
		if s > 0 {
			dst = append(dst, payees[i])
			amounts = append(amounts, s)
		}
	}
	if len(dst) > 0 {
		if err := ledger.CreditMany(dst, amounts); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot = 0

	chain.Emit("Settle",
		"holder", holder,
		"writes", strconv.FormatInt(writes, 10),
		"payees", strconv.Itoa(len(dst)),
	)
}

// Withdraw pays the caller everything credited to them and returns the amount.
// Dividends are claimable while the game runs; settlement shares only after
// Settle.
func Withdraw(cur realm) int64 {
	caller := cur.Previous().Address()
	amount, err := ledger.Withdraw(caller.String())
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", caller.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Message returns the slot's current contents, raw. Render is what escapes it.
func Message() string { return message }

// Author returns who holds the slot.
func Author() address { return author }

// Pot returns what settlement will split.
func Pot() int64 { return pot }

// Deadline returns the height the slot closes at.
func Deadline() int64 { return clk.Deadline() }

// Owed returns what an address can Withdraw right now.
func Owed(addr address) int64 { return ledger.Balance(addr.String()) }

// totalPaid returns what an address has paid in total, zero if it never wrote.
func totalPaid(key string) int64 {
	v, ok := writers.Get(key).(int64)
	if !ok {
		return 0
	}
	return v
}

func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	s := strconv.FormatInt(whole, 10)
	if frac == 0 {
		return s
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	for len(f) > 1 && f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return s + "." + f
}

package lastwords

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nym-moultest123/kit/ui/v0"
)

// Render shows the slot, the clock and the money. The message is caller-typed
// text, so it goes through ui.Inline: a stored string that renders as markdown
// is a phishing link on a page nobody can edit, and this realm's whole product
// is a string somebody else wrote.
func Render(path string) string {
	h := runtime.ChainHeight()
	var b strings.Builder

	b.WriteString("# Last Words\n\n")

	if message == "" {
		b.WriteString("_The slot is empty. Whoever writes last, writes forever._\n\n")
	} else {
		b.WriteString("> " + ui.Inline(message) + "\n\n")
		b.WriteString("by " + ui.AddrOf(author.String()) + ", for " + gnot(paid) + " GNOT\n\n")
	}

	closed := clk.Expired(h)
	b.WriteString("## The clock\n\n")
	if closed {
		b.WriteString("**Closed** at height " + strconv.FormatInt(clk.Deadline(), 10) + ". ")
		if settled {
			b.WriteString("Settled: the pot has been credited, call `Withdraw` to sweep yours.\n\n")
		} else {
			b.WriteString("Anyone may call `Settle` to split the pot.\n\n")
		}
	} else {
		b.WriteString("Open for another **" + strconv.FormatInt(clk.Remaining(h), 10) +
			"** blocks, until height " + strconv.FormatInt(clk.Deadline(), 10) + ".\n\n")
		if clk.Final() {
			b.WriteString("This is the **last stretch**: the deadline has reached the hard end at " +
				strconv.FormatInt(clk.HardEnd(), 10) + " and no write can move it again.\n\n")
		} else {
			b.WriteString("Hard end at height " + strconv.FormatInt(clk.HardEnd(), 10) +
				". A write buys " + strconv.FormatInt(BumpPct, 10) +
				"% of the gap to it, never less than " + strconv.FormatInt(Floor, 10) + " blocks.\n\n")
		}
	}

	b.WriteString("## The money\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Pot | " + gnot(pot) + " GNOT |\n")
	b.WriteString("| Price of the next write | " + gnot(Price("")) + " GNOT, plus " +
		strconv.FormatInt(PerByte, 10) + " ugnot per byte |\n")
	b.WriteString("| Writes | " + strconv.FormatInt(writes, 10) + " |\n")
	b.WriteString("| Writers | " + strconv.Itoa(len(order)) + " |\n")
	b.WriteString("| Owed, unswept | " + gnot(ledger.TotalOwed()) + " GNOT |\n\n")

	b.WriteString("The holder does **not** take the pot. It goes to everyone else who wrote, ")
	b.WriteString("pro rata to what they paid. Half of every payment is credited to the writer ")
	b.WriteString("it displaced, immediately.\n\n")

	if !ledger.IsEmpty() {
		b.WriteString("## Owed\n\n| address | ugnot |\n|---|---|\n")
		shown := 0
		ledger.Iterate(func(payee string, amount int64) bool {
			b.WriteString("| " + ui.AddrOf(payee) + " | " + strconv.FormatInt(amount, 10) + " |\n")
			shown++
			return shown >= 20
		})
		b.WriteString("\nCall `Withdraw` to sweep yours.\n")
	}

	return b.String()
}

package kitindexdemo

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// seed builds a fixed board without crossing anything, so an example can set up
// its own state.
//
// An Example has no realm token, so it cannot call Post, and the state the
// tests happen to leave is not a contract. Writing the globals directly is the
// escape hatch AGENTS.md names: same package, no crossing, fully deterministic.
func seed() {
	reset()
	add := func(who address, tag, body string, height int64) {
		id := notes.Add(&note{Author: who, Tag: tag, Body: body, Height: height})
		if err := byTag.Add(tag, id); err != nil {
			panic(err)
		}
		if err := byAuthor.Add(who.String(), id); err != nil {
			panic(err)
		}
	}
	add(alice, "gno", "the index is two containers and one function", 123)
	add(bob, "gno", "and the function is where the correctness is", 124)
	add(alice, "storage", "you are charged for objects, not for data", 125)
}

// The root page carries TWO consecutive blank lines, which an // Output: block
// can never pin: gno collapses them, exactly as Go does. So the root is
// asserted with uassert.Equal and a backtick literal, which preserves them,
// and only the pages without that shape get an Example.
//
// This is the order of preference AGENTS.md names, and the root page is the
// case that forces the second rung.
func TestRenderRoot(t *testing.T) {
	seed()
	want := `# Notes by tag

3 note(s) under 2 tag(s), by 2 author(s).


| tag | notes |
| --- | --- |
| [gno](/r/nym-moultest123/x/kitindexdemo/v0:tag/gno) | 2 |
| [storage](/r/nym-moultest123/x/kitindexdemo/v0:tag/storage) | 1 |

[Post a note](/r/nym-moultest123/x/kitindexdemo/v0$help&func=Post&body=&tag=)

`
	uassert.Equal(t, want, Render(""))
}

// ExampleRender_tag pins one tag's page, which is the lookup the library is for.
func ExampleRender_tag() {
	seed()
	print(Render("tag/gno"))
	// Output:
	// # #gno
	// | # | author | tag | note | height |
	// | --- | --- | --- | --- | --- |
	// | 1 | `g1v9kxjc…40gh` | `gno` | the index is two containers and one function | 123 |
	// | 2 | `g1vfhkyh…vdhu` | `gno` | and the function is where the correctness is | 124 |
}

// untrusted-render: the tag is charset-checked to [a-z0-9-] at write time and
// is the only stored string interpolated raw; the body is a caller's text and
// goes through ui.Cell at every call site that renders it.

// Package kitindexdemo is a notes board whose only job is to show
// gno.land/p/nym-moultest123/kit/index doing the thing a realm with a store always ends
// up needing: answering "every note tagged gno" as cheaply as it answers
// "note 7".
//
// There is no logic of its own here. The records are a kit/store, the two
// lookups are kit/index, the page is kit/ui, and what is worth reading is the
// shape: every write touches the store and both indexes in ONE function, which
// is the entire correctness argument for keeping them in separate containers.
//
// Demo of the p/moul/kit/index library.
package kitindexdemo

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nym-moultest123/kit/index/v0"
	"gno.land/p/nym-moultest123/kit/store/v0"
)

// MaxBody is the longest note this realm accepts, in bytes.
//
// A bound rather than none: every byte stored here locks a storage deposit,
// paid by whoever signs the write and refunded to whoever signs the delete
// (EFFECTIVE_GNO.md section 9.2), and an unbounded write is an unbounded
// state the realm carries forever.
const MaxBody = 280

// MaxTagLen bounds the index key for the same reason, and small because a tag
// is a label rather than a sentence.
const MaxTagLen = 24

// PageSize is how many tags the root page shows.
const PageSize = 20

// MaxNotes and MaxPerAuthor bound the WHOLE board, which MaxBody does not.
//
// A per-call length limit bounds one write and nothing else: a caller posting
// one-byte notes in a loop grows the store and both indexes without limit. "An unbounded container a third party can grow is an
// unbounded storage deposit someone is paying for" is a rule this realm exists
// to demonstrate, so it had better obey it.
//
// Two caps rather than one, and what each buys is narrower than it looks.
// MaxNotes bounds the state, which is the property this realm promises.
// MaxPerAuthor stops one ADDRESS, not one actor: addresses are free, so fifty
// fresh ones at twenty notes each still fill the board and lock everyone else
// out until somebody retracts. Keeping a board open to strangers needs
// something a griefer cannot mint for free, a deposit or an expiry, which this
// demo does not carry. Retracting frees a slot, so neither cap is a one-way door.
//
// MaxPerAuthor is answered by byAuthor.Count, which is the index doing the job
// it was added for.
const (
	MaxNotes     = 1000
	MaxPerAuthor = 20
)

type note struct {
	Author address
	Tag    string
	Body   string
	Height int64
}

var (
	notes    = store.Named("note")
	byTag    index.Index
	byAuthor index.Index
)

// Post files a note under a tag and returns its id.
//
// The store write and both index writes happen here, in this order, in one
// frame. An abort anywhere in it leaves none of them applied, which is what
// makes three containers safe to keep apart.
func Post(cur realm, tag, body string) int64 {
	who := caller(cur)
	tag = normaliseTag(tag)
	assertBody(body)
	assertRoom(who)

	id := notes.Add(&note{
		Author: who,
		Tag:    tag,
		Body:   body,
		Height: runtime.ChainHeight(),
	})
	mustIndex(byTag.Add(tag, id))
	mustIndex(byAuthor.Add(who.String(), id))
	return int64(id)
}

// Retract removes a note. Only its author may, and the store and both indexes
// are unwound together.
func Retract(cur realm, id int64) {
	who := caller(cur)
	sid, ok := store.ParseID(strconv.FormatInt(id, 10))
	if !ok {
		panic("kitindexdemo: not an id: " + strconv.FormatInt(id, 10))
	}
	n, ok := notes.Get(sid)
	if !ok {
		panic("kitindexdemo: note #" + sid.String() + " not found")
	}
	rec := n.(*note)
	if rec.Author != who {
		panic("kitindexdemo: note #" + sid.String() + " is not yours")
	}
	notes.Remove(sid)
	byTag.Remove(rec.Tag, sid)
	byAuthor.Remove(rec.Author.String(), sid)
}

// caller is the one place this realm decides who is acting: the realm token is
// checked before it is walked, because an unchecked token is not a caller.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("kitindexdemo: spoofed realm")
	}
	return cur.Previous().Address()
}

func mustIndex(err error) {
	if err != nil {
		panic(err)
	}
}

// normaliseTag lowercases and validates the tag.
//
// Validated at WRITE time rather than escaped at render time, deliberately: a
// tag is also an index key and a path segment, so a tag that could carry a
// pipe or a slash would break the table and the URL as well as the page. The
// charset is the narrowest thing that still reads as a label.
func normaliseTag(tag string) string {
	tag = strings.ToLower(strings.TrimSpace(tag))
	if tag == "" || len(tag) > MaxTagLen {
		panic("kitindexdemo: a tag is 1 to " + strconv.Itoa(MaxTagLen) + " characters")
	}
	for _, r := range tag {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
		default:
			panic("kitindexdemo: a tag is [a-z0-9-], got " + strconv.Quote(tag))
		}
	}
	return tag
}

// assertRoom refuses a write the board has no room for, globally or for this
// address. Checked before the store write, so a refusal costs the caller the
// gas of three reads and nothing is half-applied.
func assertRoom(who address) {
	if notes.Len() >= MaxNotes {
		panic("kitindexdemo: the board is full at " + strconv.Itoa(MaxNotes) +
			" notes; retract one to free a slot")
	}
	if n := byAuthor.Count(who.String()); n >= MaxPerAuthor {
		panic("kitindexdemo: " + who.String() + " already has " + strconv.Itoa(n) +
			" notes, the limit is " + strconv.Itoa(MaxPerAuthor))
	}
}

func assertBody(body string) {
	if strings.TrimSpace(body) == "" {
		panic("kitindexdemo: the body is empty")
	}
	if len(body) > MaxBody {
		panic("kitindexdemo: the body is " + strconv.Itoa(len(body)) +
			" bytes, the limit is " + strconv.Itoa(MaxBody))
	}
}

package kitindexdemo

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nym-moultest123/kit/index/v0"
	"gno.land/p/nym-moultest123/kit/store/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset puts the realm back to its init() state.
//
// Realm globals persist for the whole test binary and examples run after every
// Test, so without this an ExampleRender's pinned output depends silently on
// which tests ran before it. Assigning the globals directly is allowed here:
// same package, and it crosses nothing.
func reset() {
	notes = store.Named("note")
	byTag = index.Index{}
	byAuthor = index.Index{}
}

func TestPostIndexesInBothDirections(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "first")

	uassert.Equal(t, 1, notes.Len())
	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byAuthor.Count(alice.String()))

	got := byTag.Lookup("gno")
	urequire.Equal(t, 1, len(got))
	uassert.Equal(t, store.ID(id).String(), got[0].String())
}

func TestTagIsNormalisedAtWriteTime(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "  GNO  ", "mixed case and spaces")

	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byTag.Keys())
}

// The tag is an index key AND a path segment, so it is validated rather than
// escaped: a tag carrying a pipe or a slash breaks the table and the URL, not
// only the sentence.
func TestTagRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	for _, tc := range []struct {
		name string
		tag  string
		want string
	}{
		{"empty", "", "a tag is 1 to 24 characters"},
		{"blank", "   ", "a tag is 1 to 24 characters"},
		{"too long", "aaaaaaaaaaaaaaaaaaaaaaaaa", "a tag is 1 to 24 characters"},
		{"a pipe", "a|b", "a tag is [a-z0-9-]"},
		{"a slash", "a/b", "a tag is [a-z0-9-]"},
		{"markdown", "a]b", "a tag is [a-z0-9-]"},
		{"a space inside", "a b", "a tag is [a-z0-9-]"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			uassert.AbortsContains(t, cur, tc.want, func() {
				Post(cross(cur), tc.tag, "body")
			})
		})
	}
	uassert.Equal(t, 0, notes.Len())
}

func TestBodyRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsContains(t, cur, "the body is empty", func() {
		Post(cross(cur), "gno", "   ")
	})

	long := ""
	for i := 0; i <= MaxBody; i++ {
		long += "x"
	}
	uassert.AbortsContains(t, cur, "the limit is 280", func() {
		Post(cross(cur), "gno", long)
	})
	uassert.Equal(t, 0, notes.Len())
}

func TestOnlyTheAuthorMayRetract(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "alice's note")

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "is not yours", func() {
		Retract(cross(cur), id)
	})
	uassert.Equal(t, 1, notes.Len())

	testing.SetRealm(testing.NewUserRealm(alice))
	Retract(cross(cur), id)
	uassert.Equal(t, 0, notes.Len())
}

// The store and both indexes have to come apart together, or a later Render
// walks ids the store no longer holds.
func TestRetractUnwindsEveryContainer(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), "gno", "one")
	Post(cross(cur), "gno", "two")

	Retract(cross(cur), id)

	uassert.Equal(t, 1, notes.Len())
	uassert.Equal(t, 1, byTag.Count("gno"))
	uassert.Equal(t, 1, byAuthor.Count(alice.String()))
}

func TestRetractRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))

	uassert.AbortsContains(t, cur, "not found", func() { Retract(cross(cur), 99) })
	uassert.AbortsContains(t, cur, "not an id", func() { Retract(cross(cur), 0) })
	uassert.AbortsContains(t, cur, "not an id", func() { Retract(cross(cur), -1) })
}

// A body is a caller's markdown and must not be able to write the page around
// it. ui.Cell is what stops a pipe from opening a column.
func TestARenderedBodyCannotBreakTheTable(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "gno", "a | b [x](http://evil)")

	got := Render("tag/gno")
	uassert.False(t, strings.Contains(got, "| a | b ["),
		"the raw body must not reach the table")
	uassert.True(t, strings.Contains(got, "\\|"),
		"the pipe must be escaped")
}

func TestRenderOfAnUnknownPage(t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render("nope"), "Not found"))
	uassert.True(t, strings.Contains(Render("tag"), "No tag given."))
	uassert.True(t, strings.Contains(Render("author"), "No author given."))
}

// MaxBody bounds one write. These bound the bill, which is the thing the realm
// actually pays.
func TestPerAuthorCap(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < MaxPerAuthor; i++ {
		Post(cross(cur), "gno", "note "+strconv.Itoa(i))
	}
	uassert.AbortsContains(t, cur, "the limit is 20", func() {
		Post(cross(cur), "gno", "one too many")
	})

	// Another address is unaffected, which is the whole reason the cap is
	// per author and not only global.
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "gno", "bob still fits")
	uassert.Equal(t, MaxPerAuthor+1, notes.Len())
}

// Retracting frees a slot, so the cap is not a one-way door.
func TestRetractingFreesASlot(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	first := Post(cross(cur), "gno", "note 0")
	for i := 1; i < MaxPerAuthor; i++ {
		Post(cross(cur), "gno", "note "+strconv.Itoa(i))
	}
	uassert.AbortsContains(t, cur, "the limit is 20", func() {
		Post(cross(cur), "gno", "blocked")
	})

	Retract(cross(cur), first)
	Post(cross(cur), "gno", "now it fits")
	uassert.Equal(t, MaxPerAuthor, notes.Len())
}

// The page number is user input on the Render path. One outside 1..Pages is
// clamped into it, so it never renders an empty board under a footer that
// says "page -1 of 2".
func TestRenderClampsThePageNumber(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < PageSize; i++ {
		Post(cross(cur), "t"+strconv.Itoa(i), "x")
	}
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "t-last", "x")
	urequire.Equal(t, 2, byTag.Pages(PageSize))

	first, last := Render("?page=1"), Render("?page=2")
	uassert.Equal(t, first, Render("?page=-1"))
	uassert.Equal(t, first, Render("?page=0"))
	uassert.Equal(t, last, Render("?page=999"))
	uassert.True(t, strings.Contains(last, "page 2 of 2"))
}

// Links are absolute. gnoweb serves this realm at .../kitindexdemo/v0, so a
// "./kitindexdemo:tag/x" link resolves to .../kitindexdemo/kitindexdemo:tag/x,
// a package that does not exist.
func TestRenderLinksAreAbsolute(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i <= PageSize; i++ {
		if i == MaxPerAuthor {
			testing.SetRealm(testing.NewUserRealm(bob))
		}
		Post(cross(cur), "t"+strconv.Itoa(i), "x")
	}
	out := Render("")
	uassert.True(t, strings.Contains(out, "](/r/nym-moultest123/x/kitindexdemo/v0:tag/t0)"), out)
	uassert.True(t, strings.Contains(out, "](/r/nym-moultest123/x/kitindexdemo/v0:?page=2)"), out)
	uassert.False(t, strings.Contains(out, "](./"), out)
}

// realmURL must follow the module line, or a version bump ships dead links.
func TestRealmURLMatchesTheModule(cur realm, t *testing.T) {
	uassert.Equal(t, "gno.land"+realmURL, cur.PkgPath())
}

// The global cap is what bounds the realm's whole storage bill, so its
// refusal is pinned, and pinned as refusing BEFORE any write: the store and
// both indexes are exactly as full as they were.
func TestTheBoardIsFull(cur realm, t *testing.T) {
	reset()
	for i := 0; i < MaxNotes; i++ {
		notes.Add(&note{Author: bob, Tag: "gno", Body: "x"})
	}
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "the board is full", func() {
		Post(cross(cur), "gno", "one too many")
	})
	uassert.Equal(t, MaxNotes, notes.Len())
	uassert.Equal(t, 0, byTag.Len())
	uassert.Equal(t, 0, byAuthor.Count(alice.String()))
