}

// Package reactions is a reaction block any realm can embed, keyed on the page
// it appears on rather than on the realm that stores it.
//
// It is the shape the web settled on for this in 2010: one hosted widget, the
// same snippet pasted everywhere, deciding what to show from the page
// identifier it is handed. Here the snippet is two lines of gno:
//
//	import "gno.land/r/nym-moultest123/reactions/v0"
//
//	func Render(path string) string {
//		return body + reactions.RenderBlock()
//	}
//
// [RenderBlock] takes no argument because it does not need one: a plain read
// exported by a realm and called by another opens no realm frame, so
// unsafe.CurrentRealm() inside it reports the CALLER. The host realm's own path
// is the page key, and nothing has to be configured, registered or passed.
// [RenderBlockFor] is the explicit form, for a realm that renders more than one
// page or already holds its path as a constant.
//
// The host realm stores nothing. Every tally lives here, so a realm can add
// reactions without a redeploy the next time it wants to change them, and a
// reader's reaction survives the host realm being replaced.
//
// # What it is not
//
// Not a comment system. There is no text field anywhere, which is what makes
// it possible to run with no moderation at all: six emoji, one reaction per
// address per page, changeable and removable. The page shows the tally and who
// reacted last. That is the whole feature.
package reactions

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	rx "gno.land/p/nym-moultest123/reactions/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from unsafe.CurrentRealm(),
// which reports the CALLER in every read this realm exports and would therefore
// build every link against whichever realm embedded the block.
const realmPath = "gno.land/r/nym-moultest123/reactions/v0"

// board holds every page's tally.
//
// A redeploy would wipe it, which is why this realm is not private (see
// gnomod.toml): the state here belongs to everyone who reacted, and the only
// honest way to change this realm is a v1 beside it.
var board = rx.NewBoard()

// React records the caller's reaction to page.
//
// page is a package path, the full one: "gno.land/r/nym-moultest123/home". It does not
// have to be a realm that embeds the block, and nothing checks that it exists.
// A page is just a name, which is what lets a realm key the block on something
// finer than itself.
//
// key is one of the palette names, not a glyph: "up", "heart", "fire", "party",
// "rocket", "eyes". Render("") lists them with their emoji.
//
// One reaction per address per page. Reacting again with a different key moves
// it; reacting with the same key changes nothing but the "last reaction" line.
func React(cur realm, page, key string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !rx.Valid(key) {
		panic("reactions: no such reaction: " + key)
	}
	if !rx.ValidPage(page) {
		panic("reactions: not a page key: " + page)
	}

	who := unsafe.PreviousRealm().Address()
	board.React(page, who, key, runtime.ChainHeight())
	chain.Emit("React", "page", page, "key", key, "who", who.String())
}

// Unreact removes the caller's reaction from page. It aborts when there is
// none, rather than succeeding silently, so a misspelled page key is visible
// instead of looking like a no-op.
func Unreact(cur realm, page string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	who := unsafe.PreviousRealm().Address()
	if !board.Unreact(page, who) {
		panic("reactions: nothing to remove on " + page)
	}
	chain.Emit("Unreact", "page", page, "who", who.String())
}

// RenderBlock returns the block for the realm CALLING it, which is the form a
// host realm embeds.
//
// It has no cur realm parameter on purpose. A plain read is borrowed: gno opens
// no realm frame for it, so unsafe.CurrentRealm() reports the caller's path and
// the block keys itself with no argument. Adding a cur realm here would
// silently reverse that and key every embed to this realm instead.
//
// Calling it from inside this realm therefore keys on this realm, which is
// never what a caller wants; the views below use the unexported blockFor.
func RenderBlock() string {
	return blockFor(unsafe.CurrentRealm().PkgPath())
}

// RenderBlockFor is [RenderBlock] for a named page. Use it from a crossing
// function, where there is no caller to read off the stack, or when one realm
// renders several pages.
func RenderBlockFor(page string) string { return blockFor(page) }

// blockFor is the shared body, so no exported read of this realm calls another
// and picks up the wrong path.
func blockFor(page string) string {
	return rx.Block(realmPath, page, board.Page(page))
}

// Count reports how many addresses have a reaction on page.
func Count(page string) int { return board.Page(page).Total() }

// CountOf reports how many addresses hold one particular reaction on page.
func CountOf(page, key string) int { return board.Page(page).Count(key) }

// ReactionOf returns who's current reaction key on page, or "" when they have
// none. A host realm can use it to say "you reacted" without reading the tree.
func ReactionOf(page string, who address) string { return board.Page(page).Of(who) }

// Last returns the most recent reaction on page: the palette key, the address,
// and the height. The key is "" when the page has never been reacted to.
func Last(page string) (key string, who address, height int64) {
	return board.Page(page).Last()
}

// Pages reports how many pages have ever been reacted to.
func Pages() int { return board.Pages() }

package reactions

import (
	"strconv"
	"strings"
	"testing"

	rx "gno.land/p/nym-moultest123/reactions/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const homePage = "gno.land/r/nym-moultest123/home"

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset clears realm state. Realm globals live for the whole test binary, and
// the Example runs after every Test, so everything that renders starts here.
func reset() { board = rx.NewBoard() }

func TestReactAndUnreact(cur realm, t *testing.T) {
	reset()

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)
	testing.SetRealm(testing.NewUserRealm(bob))
	React(cross(cur), homePage, rx.KeyFire)

	uassert.Equal(t, 2, Count(homePage))
	uassert.Equal(t, 1, CountOf(homePage, rx.KeyUp))
	uassert.Equal(t, rx.KeyUp, ReactionOf(homePage, alice))
	uassert.Equal(t, 1, Pages())

	key, who, _ := Last(homePage)
	uassert.Equal(t, rx.KeyFire, key)
	uassert.Equal(t, bob, who)

	testing.SetRealm(testing.NewUserRealm(alice))
	Unreact(cross(cur), homePage)
	uassert.Equal(t, 1, Count(homePage))
	uassert.Equal(t, "", ReactionOf(homePage, alice))
}

func TestReadsOnAnUntouchedPageAreZero(t *testing.T) {
	reset()
	uassert.Equal(t, 0, Count("gno.land/r/nobody/here"))
	uassert.Equal(t, 0, CountOf("gno.land/r/nobody/here", rx.KeyUp))
	uassert.Equal(t, "", ReactionOf("gno.land/r/nobody/here", alice))
	key, _, _ := Last("gno.land/r/nobody/here")
	uassert.Equal(t, "", key)
}

func TestReactRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: no such reaction: poop", func() {
		React(cross(cur), homePage, "poop")
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: not a page key: not a path", func() {
		React(cross(cur), "not a path", rx.KeyUp)
	})

	uassert.Equal(t, 0, Pages(), "a refused reaction creates no page")
}

// TestUnreactAbortsRatherThanNoOp is the deliberate asymmetry: a misspelled
// page key on Unreact has to be visible, or a reader thinks they removed
// something they did not.
func TestUnreactAbortsRatherThanNoOp(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: nothing to remove on "+homePage, func() {
		Unreact(cross(cur), homePage)
	})
}

// TestRenderBlockForIsWhatTheBlockLinksTo pins the property a host realm
// depends on: every link in the embedded block points at THIS realm, not at
// the realm that embedded it, and carries the page key as an argument.
func TestRenderBlockForIsWhatTheBlockLinksTo(t *testing.T) {
	reset()
	got := RenderBlockFor(homePage)
	uassert.True(t, strings.Contains(got, "(/r/nym-moultest123/reactions/v0$help&func=React&"),
		"the txlink targets this realm")
	uassert.True(t, strings.Contains(got, "page=gno.land%2Fr%2Fmoul%2Fhome"),
		"and carries the host page as the parameter")
	uassert.False(t, strings.Contains(got, "/r/nym-moultest123/home$help"),
		"never the host realm, which has no React to call")
}

// TestRenderBlockKeysOnTheCaller is the borrowed-read rule this realm's whole
// ergonomics rest on: RenderBlock has no cur realm parameter, so gno opens no
// frame for it and unsafe.CurrentRealm() reports whoever called.
//
// In-package there is no other realm to call from, so what this pins is the
// half that can be pinned here: RenderBlock agrees with RenderBlockFor when
// the caller IS this realm. The cross-realm half is measured in AGENTS.md
// (2026-09-22) and is the same mechanism r/moul/config's TopBlock uses.
func TestRenderBlockKeysOnTheCaller(t *testing.T) {
	reset()
	uassert.Equal(t, RenderBlockFor(realmPath), RenderBlock())
	uassert.NotEqual(t, RenderBlockFor(homePage), RenderBlock(),
		"and a different page is a different block")
}

func TestRenderPageView(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)

	got := Render(homePage)
	uassert.True(t, strings.HasPrefix(got, "# gno\\.land/r/nym-moultest123/home\n"),
		"the heading is the page key, escaped: ui.Inline backslashes the dot")
	uassert.True(t, strings.Contains(got, "Last reaction: \U0001F44D by "))
	uassert.True(t, strings.Contains(got, "Remove my reaction"))
	uassert.True(t, strings.Contains(got, "[The board](/r/nym-moultest123/reactions/v0)"))
}

func TestRenderRejectsAPathThatIsNotAPageKey(t *testing.T) {
	reset()
	got := Render("[click](http://e.vil)")
	uassert.True(t, strings.HasPrefix(got, "# Not a page\n"))
	uassert.False(t, strings.Contains(got, "](http://e.vil)"),
		"a render path is escaped before it is shown back")
}

// TestRenderHomeShowsTheBoard uses uassert rather than an Example because the
// page contains consecutive blank lines, which gno collapses inside an
// // Output: block.
func TestRenderHomeShowsTheBoard(cur realm, t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render(""), "*No page has been reacted to yet.*"))

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyParty)

	got := Render("")
	uassert.True(t, strings.Contains(got,
		"| [gno\\.land/r/nym-moultest123/home](/r/nym-moultest123/reactions/v0:gno.land/r/nym-moultest123/home) | 1 |"),
		"the cell text is escaped, the URL is not: they are different contexts")
	uassert.True(t, strings.Contains(got, "import \"gno.land/r/nym-moultest123/reactions/v0\""),
		"the homepage is the getting-started doc, and the snippet is copy-pasteable")
	for _, k := range rx.Keys() {
		uassert.True(t, strings.Contains(got, "| `"+k+"` | "+rx.Emoji(k)+" |"), k)
	}
}

// TestBoardIndexIsCapped: the number of pages is unbounded, the index is not.
func TestBoardIndexIsCapped(cur realm, t *testing.T) {
	reset()
	for i := 0; i < maxListed+3; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		// Zero-padded, because avl keys sort as strings and ufmt has no width
		// flags: "p9" would otherwise sort between "p10" and "p11".
		n := strconv.Itoa(i)
		if len(n) < 2 {
			n = "0" + n
		}
		React(cross(cur), "gno.land/r/spam/p"+n, rx.KeyUp)
	}
	uassert.Equal(t, maxListed+3, Pages())

	got := Render("")
	uassert.Equal(t, maxListed, strings.Count(got, "(/r/nym-moultest123/reactions/v0:gno.land/r/spam/"))
	uassert.True(t, strings.Contains(got, "28 pages in total, 25 shown."))
}

package reactions

import (
	"strconv"
	"strings"

	"gno.land/p/nym-moultest123/kit/ui/v0"
	rx "gno.land/p/nym-moultest123/reactions/v0"
)

// maxListed caps the board index. The number of pages is unbounded (anyone can
// react to any key), and a Render that grows with it would eventually be too
// expensive to serve. The cap is on the INDEX only: every page keeps its own
// view at /r/nym-moultest123/reactions/v0:<page>, whether or not it is listed here.
const maxListed = 25

// Render serves two views:
//
//	""       the getting-started page: how to embed the block, plus the board
//	"<page>" one page's tally, where <page> is a package path
//
// The page view's path is the key itself, so the link under any embedded block
// is just this realm's path, a colon, and the page. That is why a page key may
// contain a colon of its own: "gno.land/r/you/blog:hello" reads back whole.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if !rx.ValidPage(path) {
		return "# Not a page\n\n" + ui.Inline(path) + " is not a page key: a key is a " +
			"package path, lowercase ASCII, at most " + strconv.Itoa(rx.MaxPageLen) +
			" bytes.\n\n[Back to the board](" + selfURL() + ")\n"
	}
	return renderPage(path)
}

// selfURL is this realm's own gnoweb path, derived from realmPath the same way
// every link in the block is, so there is one rule and not two. A function and
// not a package-level var: a package-level var in a realm is realm STATE,
// persisted and re-read on every call, which is a strange thing for a string
// the compiler could have folded.
func selfURL() string { return rx.RealmURL(realmPath) }

func renderHome() string {
	var b strings.Builder

	b.WriteString("# Reactions\n\n")
	b.WriteString("A reaction block any realm can embed. One line in your `Render`, no state ")
	b.WriteString("on your side, and readers get one-click reactions keyed on the page they ")
	b.WriteString("are looking at.\n\n")
	b.WriteString("It is not a comment system, on purpose. There is no text field anywhere, ")
	b.WriteString("which is what lets it run with no moderation: a closed palette, one ")
	b.WriteString("reaction per address per page, changeable and removable.\n\n")

	b.WriteString("## It looks like this\n\n")
	b.WriteString(blockFor(realmPath))
	b.WriteString("\nThat block is live and it is this realm's own page. Click one.\n\n")

	b.WriteString("## Add it to your realm\n\n")
	b.WriteString("```go\n")
	b.WriteString("import \"" + realmPath + "\"\n\n")
	b.WriteString("func Render(path string) string {\n")
	b.WriteString("\treturn body + reactions.RenderBlock()\n")
	b.WriteString("}\n")
	b.WriteString("```\n\n")
	b.WriteString("That is the whole integration. `RenderBlock` takes no argument because it ")
	b.WriteString("does not need one: a plain read exported by one realm and called by ")
	b.WriteString("another opens no realm frame, so it sees YOUR path and uses it as the ")
	b.WriteString("page key. Nothing to register, nothing to configure.\n\n")
	b.WriteString("For one block per article rather than one per realm, name the page ")
	b.WriteString("yourself with the path you already serve:\n\n")
	b.WriteString("```go\n")
	b.WriteString("return body + reactions.RenderBlockFor(\"gno.land/r/you/blog:\" + path)\n")
	b.WriteString("```\n\n")
	b.WriteString("Reactions are recorded here, not in your realm, so redeploying yours ")
	b.WriteString("never loses them.\n\n")

	b.WriteString("## The palette\n\n")
	t := ui.NewTable("key", "")
	for _, k := range rx.Keys() {
		t.Row("`"+k+"`", rx.Emoji(k))
	}
	b.WriteString(t.String())
	b.WriteString("\nSix, and the set is closed. `React` aborts on anything else, which is ")
	b.WriteString("the entire moderation policy.\n\n")

	b.WriteString("## The board\n\n")
	b.WriteString(renderBoard())

	return b.String()
}

// renderBoard lists pages in key order, not by activity. Key order is the order
// the tree already walks, so the listing is stable between identical calls;
// ranking would need a second index maintained on every write, which is a lot
// of machinery for a table nobody navigates by.
func renderBoard() string {
	n := board.Pages()
	if n == 0 {
		return ui.Empty("No page has been reacted to yet.")
	}

	t := ui.NewTable("page", "reactions", "last")
	board.Each(func(page string, p *rx.Page) bool {
		key, who, _ := p.Last()
		last := "-"
		if key != "" {
			last = rx.Emoji(key) + " " + ui.Addr(who)
		}
		t.Row(
			"["+ui.Cell(page)+"]("+rx.PageURL(realmPath, page)+")",
			strconv.Itoa(p.Total()),
			last,
		)
		return t.Len() >= maxListed
	})

	out := t.String()
	if n > maxListed {
		out += "\n" + strconv.Itoa(n) + " pages in total, " + strconv.Itoa(maxListed) +
			" shown. Every page has its own view at `" + selfURL() + ":<page>`.\n"
	}
	return out
}

func renderPage(page string) string {
	p := board.Page(page)

	var b strings.Builder
	b.WriteString("# " + ui.Inline(page) + "\n\n")
	b.WriteString(blockFor(page))
	b.WriteString("\n")

	if p.Total() == 0 {
		b.WriteString(ui.Empty("Nobody is reacting to this page right now."))
	} else {
		t := ui.NewTable("", "reaction", "addresses")
		for _, k := range rx.Keys() {
			if c := p.Count(k); c > 0 {
				t.Row(rx.Emoji(k), "`"+k+"`", strconv.Itoa(c))
			}
		}
		b.WriteString(t.String())
	}

	if key, who, height := p.Last(); key != "" {
		b.WriteString("\nLast reaction: " + rx.Emoji(key) + " by " + ui.Addr(who) +
			" at height " + strconv.FormatInt(height, 10) + ".\n")
	}

	b.WriteString("\n" + ui.ActionIn(realmPath, "Remove my reaction", "Unreact", "page", page))
	b.WriteString(" · [The board](" + selfURL() + ")\n")
	return b.String()
}

// Package nativeify turns a GRC20 into a native coin, which is wugnot run
// backwards.
//
// wugnot takes GNOT, a coin the bank holds, and issues a GRC20 receipt for it,
// because a GRC20 can be pulled by a contract and a native coin cannot. This
// realm takes a GRC20, escrows it, and issues a native denom against it 1:1,
// because a native coin can do four things a GRC20 cannot:
//
//   - move with no realm call at all (`gnokey maketx send`, from any wallet)
//   - ride the `-send` envelope of a call, so it can PAY for something
//   - sit beside GNOT on an account page, with nothing registered anywhere
//   - be named as the gas denom by a chain whose genesis says so
//
// # What you give up, and it is not small
//
// A native coin cannot be pulled. `banker.SendCoins` refuses any `from` that is
// not the banker's own realm address, so there is no allowance, no
// `TransferFrom`, and no way for an AMM, an escrow or a subscription to take
// what you approved. Everything downstream of `Approve` stops working the moment
// a coin becomes native. That is not a gap in this realm; it is the property
// that makes the wrapping worth doing in the other direction.
//
// And the issuer of a native coin can always delete a balance: `RemoveCoin`
// takes an arbitrary address. This realm never calls it on an address other than
// its own, [Unwrap] explains why in detail, and the gnomod.toml explains why this
// path is public rather than redeployable. Those three together are the entire
// guarantee. There is no on-chain way to prove a negative about code.
//
// # The exchange rate is 1, always
//
// One smallest unit of the underlying is one unit of the coin. Not 10^decimals:
// the bank has no notion of divisibility, so a token with 6 decimals wrapped
// here produces a coin counted in the token's own smallest units, and the 6 is
// carried to `r/moul/x/nativereg` as a display hint and nowhere else.
//
// Solvency is therefore a plain equality that anybody can check without trusting
// this realm's bookkeeping: the GRC20 balance at this realm's address equals the
// total supply of the denom. [Solvency] computes it from both sides.
//
// Play money to try it on: `r/moul/x/grc20faucet/v0`.
package nativeify

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strings"

	"gno.land/p/nym-moultest123/x/envelope/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/nym-moultest123/x/nativereg/v0"
)

// Path is this realm's package path, which every denom it issues embeds.
const Path = "gno.land/r/nym-moultest123/x/nativeify/v0"

// MinBase and MaxBase bound a base denom name. The chain enforces exactly this
// (`isValidBaseDenom` in the banker stdlib): a lowercase letter, then 2 to 15
// more lowercase letters or digits. Validating here rather than letting the
// banker abort is the difference between a usable error and a stack trace.
const (
	MinBase = 3
	MaxBase = 16
)

type pair struct {
	base    string // base denom name, unique in this realm
	denom   string // the full chain denom
	key     string // grc20reg key of the underlying
	creator address
	height  int64
}

var (
	byBase = avl.NewTree() // base name -> *pair
	byKey  = avl.NewTree() // grc20reg key -> *pair
	bases  []string        // creation order, for a stable Render
	home   address         // this realm's address: where every escrow sits
)

func init(cur realm) {
	home = cur.Address()
}

// Home is the address to approve on the underlying token before wrapping. Every
// escrow this realm holds sits there.
func Home() address { return home }

// Nativeify creates the native counterpart of a GRC20 registered in
// `r/nt/grc20reg`, and returns its denom. It issues nothing: [Wrap] does that.
//
// `base` is the part of the denom after the colon, yours to choose, unique in
// this realm and in the chain's charset. One native denom per underlying token:
// a second one would double the chain's per-denom storage for no new capability,
// and realm-denom balances live under their own store keys, which are not
// gas-metered.
func Nativeify(cur realm, tokenKey, base string) string {
	under := grc20reg.MustGet(tokenKey)
	assertBase(base)
	if byBase.Get(base) != nil {
		panic("this realm already issues " + base)
	}
	if v := byKey.Get(tokenKey); v != nil {
		panic(ufmt.Sprintf("%s is already native here as %s", under.GetSymbol(), v.(*pair).denom))
	}

	p := &pair{
		base:    base,
		denom:   chain.CoinDenom(Path, base),
		key:     tokenKey,
		creator: cur.Previous().Address(),
		height:  runtime.ChainHeight(),
	}
	byBase.Set(base, p)
	byKey.Set(tokenKey, p)
	bases = append(bases, base)

	// This realm is the issuer named inside the denom, so it is the only thing
	// on the chain that can describe it. The decimals travel as a display hint;
	// the bank still counts whole units.
	nativereg.Register(cross(cur), p.denom,
		under.GetName()+" (native)", "n"+under.GetSymbol(), under.GetDecimals(),
		"1:1 native wrapper of "+tokenKey+", redeemable at "+Path)
	return p.denom
}

// Wrap escrows `amount` of the underlying and issues the same number of native
// coins to the caller.
//
// You must `Approve` this realm's address on the underlying token first, through
// that token's own realm. Until you do, this realm has no authority over your
// balance at all, and Wrap fails with "insufficient allowance", which is the
// system working.
func Wrap(cur realm, base string, amount int64) int64 {
	p := mustPair(base)
	if amount <= 0 {
		panic("wrap a positive amount")
	}
	who := cur.Previous().Address()

	// Last point at which nothing has moved.
	under := grc20reg.MustGet(p.key)
	if err := under.RealmTeller(0, cur).TransferFrom(0, cur, who, home, amount); err != nil {
		panic(err)
	}
	banker.NewBanker(banker.BankerTypeRealmIssue, cur).IssueCoin(who, p.denom, amount)
	return amount
}

// Unwrap destroys the native coins attached to this call and releases the same
// number of underlying GRC20 units to the caller.
//
// # Why you have to send the coins rather than let this realm take them
//
// This realm holds a `BankerTypeRealmIssue` banker, and `RemoveCoin` takes an
// arbitrary address, so it could delete the caller's coins directly and save
// them a flag. It does not, and the reason is worth stating where somebody
// copying this will read it: a realm whose normal operation is to remove coins
// from addresses that did not hand them over has no way left to demonstrate that
// it only ever does so consensually. Every `RemoveCoin` here names this realm's
// own address, which anybody can check by reading the source, and the coins get
// to that address the only way a native coin ever moves, by their holder pushing
// them.
//
// So: attach them.
//
//	-send <amount>/gno.land/r/nym-moultest123/x/nativeify/v0:<base>
func Unwrap(cur realm, base string) int64 {
	p := mustPair(base)
	// Reading the envelope is also what makes this call payable at all: MsgCall
	// rejects a message whose coins no code looked at.
	amount := envelope.Require(p.denom)
	who := cur.Previous().Address()

	// Destroy the receipt before releasing the backing, so a failure between the
	// two can only ever leave the pair over-collateralized.
	banker.NewBanker(banker.BankerTypeRealmIssue, cur).RemoveCoin(home, p.denom, amount)
	under := grc20reg.MustGet(p.key)
	if err := under.RealmTeller(0, cur).Transfer(0, cur, who, amount); err != nil {
		panic(err)
	}
	return amount
}

// Denom returns the denom this realm issues for a base name.
func Denom(base string) string { return mustPair(base).denom }

// TokenKey returns the grc20reg key of the underlying behind a base name.
func TokenKey(base string) string { return mustPair(base).key }

// Bases returns every base name this realm issues, in creation order.
func Bases() []string {
	out := make([]string, len(bases))
	copy(out, bases)
	return out
}

// Solvency returns what is escrowed and what is issued for a base name. They are
// read from two different places on the chain, the GRC20 ledger and the bank,
// and this realm's own bookkeeping is not consulted for either: if they ever
// disagree, the disagreement is the answer.
func Solvency(base string) (escrowed, issued int64) {
	p := mustPair(base)
	escrowed = grc20reg.MustGet(p.key).BalanceOf(home)
	issued = banker.NewReadonlyBanker().TotalCoin(p.denom)
	return escrowed, issued
}

// IsSolvent reports whether every coin issued for a base name is backed.
//
// It allows escrowed > issued, which is what a donation to this realm's address
// looks like and cannot hurt anybody, and refuses the reverse.
func IsSolvent(base string) bool {
	escrowed, issued := Solvency(base)
	return escrowed >= issued
}

// Underlying returns the underlying token behind a base name, for a caller that
// wants its name, symbol or decimals.
func Underlying(base string) *grc20.Token {
	return grc20reg.MustGet(mustPair(base).key)
}

func mustPair(base string) *pair {
	v := byBase.Get(base)
	if v == nil {
		panic("this realm does not issue " + base)
	}
	return v.(*pair)
}

// assertBase applies the chain's own base-denom rule before the banker does, so
// the caller reads a sentence instead of a stack trace.
func assertBase(base string) {
	if len(base) < MinBase || len(base) > MaxBase {
		panic(ufmt.Sprintf("base %q is %d characters, must be %d to %d",
			base, len(base), MinBase, MaxBase))
	}
	for i := 0; i < len(base); i++ {
		c := base[i]
		lower := c >= 'a' && c <= 'z'
		digit := c >= '0' && c <= '9'
		if lower || (i > 0 && digit) {
			continue
		}
		panic(ufmt.Sprintf("base %q: a base denom is a lowercase letter followed by "+
			"lowercase letters or digits, and %q is not", base, string(c)))
	}
	if strings.Contains(base, ":") { // unreachable past the charset loop; belt and braces
		panic("a base denom cannot contain a colon")
	}
}

package nativeify

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nym-moultest123/x/envelope/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/nym-moultest123/x/grc20faucet/v0"
	"gno.land/r/nym-moultest123/x/nativereg/v0"
)

// Two things about the harness shape every test below.
//
// testing.SetRealm governs only the crossing calls made from the frame that
// called it, so every account switch is inline in the test body.
//
// The BANK does not carry over between test functions while realm state does,
// so native balances, TotalCoin and the escrowed GRC20 cannot be compared
// across tests. Everything here is asserted as a delta inside one test.

func TestNativeifyCreatesThePair(cur realm, t *testing.T) {
	alice := testutils.TestAddress("nf-alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	denom := Nativeify(cross(cur), grc20faucet.RedKey, "nred")
	uassert.Equal(t, "/gno.land/r/nym-moultest123/x/nativeify/v0:nred", denom)
	uassert.Equal(t, denom, Denom("nred"))
	uassert.Equal(t, grc20faucet.RedKey, TokenKey("nred"))

	// The denom names this realm, so this realm is the only thing on the chain
	// that can describe it, and it did.
	e := nativereg.MustGet(denom)
	uassert.Equal(t, Path, e.Issuer)
	uassert.Equal(t, "nRED", e.Symbol)
	uassert.Equal(t, 4, e.Decimals, "the underlying's decimals travel as a display hint")

	uassert.AbortsContains(t, cur, "already issues nred", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, "nred")
	})
	uassert.AbortsContains(t, cur, "already native here", func() {
		Nativeify(cross(cur), grc20faucet.RedKey, "nred2")
	})
	uassert.AbortsContains(t, cur, "unknown token", func() {
		Nativeify(cross(cur), "gno.land/r/nope/nope.NOPE", "nnope")
	})
}

func TestBaseNameFollowsTheChainsRule(cur realm, t *testing.T) {
	bob := testutils.TestAddress("nf-bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	// The chain's own rule, applied here so the caller reads a sentence instead
	// of a banker stack trace: a lowercase letter, then 2 to 15 more lowercase
	// letters or digits.
	uassert.AbortsContains(t, cur, "is 2 characters", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, "ab")
	})
	uassert.AbortsContains(t, cur, "is 17 characters", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, strings.Repeat("a", 17))
	})
	uassert.AbortsContains(t, cur, "is not", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, "nBLUE")
	})
	uassert.AbortsContains(t, cur, "is not", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, "1blue")
	})
	uassert.AbortsContains(t, cur, "is not", func() {
		Nativeify(cross(cur), grc20faucet.BlueKey, "n-blue")
	})

	// And one that is legal all the way through.
	uassert.Equal(t, "/gno.land/r/nym-moultest123/x/nativeify/v0:nblue1",
		Nativeify(cross(cur), grc20faucet.BlueKey, "nblue1"))
}

func TestWrapNeedsAnAllowanceFirst(cur realm, t *testing.T) {
	carol := testutils.TestAddress("nf-carol")
	testing.SetRealm(testing.NewUserRealm(carol))
	grc20faucet.Claim(cross(cur))

	// Until the holder names this realm on the underlying token, this realm has
	// no authority over their balance whatsoever. That is the GRC20 half of the
	// trade, and it is the half a native coin does not have.
	uassert.AbortsContains(t, cur, "allowance", func() { Wrap(cross(cur), "nred", 1_000) })
	uassert.Equal(t, int64(0), envelope.BalanceOf(carol, Denom("nred")))
}

func TestWrapEscrowsAndIssues(cur realm, t *testing.T) {
	dave := testutils.TestAddress("nf-dave")
	testing.SetRealm(testing.NewUserRealm(dave))
	grc20faucet.Claim(cross(cur))
	grc20faucet.Approve(cross(cur), "RED", Home(), 1_000_000)

	denom := Denom("nred")
	redBefore := grc20faucet.BalanceOf("RED", dave)
	escrowBefore, issuedBefore := Solvency("nred")

	got := Wrap(cross(cur), "nred", 400_000)

	uassert.Equal(t, int64(400_000), got)
	uassert.Equal(t, redBefore-400_000, grc20faucet.BalanceOf("RED", dave), "the GRC20 left the holder")
	uassert.Equal(t, escrowBefore+400_000, grc20faucet.BalanceOf("RED", Home()), "and landed in escrow")
	uassert.Equal(t, int64(400_000), envelope.BalanceOf(dave, denom), "the native coin is at the bank, 1:1")

	escrowAfter, issuedAfter := Solvency("nred")
	uassert.Equal(t, escrowBefore+400_000, escrowAfter)
	uassert.Equal(t, issuedBefore+400_000, issuedAfter)
	uassert.True(t, IsSolvent("nred"), "every coin issued is backed")

	uassert.AbortsContains(t, cur, "positive amount", func() { Wrap(cross(cur), "nred", 0) })
	uassert.AbortsContains(t, cur, "does not issue", func() { Wrap(cross(cur), "ghost", 1) })
}

func TestUnwrapDestroysTheCoinAndReleasesTheBacking(cur realm, t *testing.T) {
	erin := testutils.TestAddress("nf-erin")
	denom := Denom("nred")

	testing.SetRealm(testing.NewUserRealm(erin))
	grc20faucet.Claim(cross(cur))
	grc20faucet.Approve(cross(cur), "RED", Home(), 1_000_000)
	Wrap(cross(cur), "nred", 300_000)

	// On chain the -send envelope moves the coins to this realm's address before
	// Unwrap runs. The harness has no bank-send primitive, so the credit is
	// issued here; SetOriginSend is the half the realm actually reads.
	sent := chain.NewCoins(chain.NewCoin(denom, 120_000))
	testing.IssueCoins(Home(), sent)
	testing.SetOriginSend(sent)

	redBefore := grc20faucet.BalanceOf("RED", erin)
	escrowBefore := grc20faucet.BalanceOf("RED", Home())
	_, issuedBefore := Solvency("nred")

	got := Unwrap(cross(cur), "nred")

	uassert.Equal(t, int64(120_000), got)
	uassert.Equal(t, redBefore+120_000, grc20faucet.BalanceOf("RED", erin), "the backing came back")
	uassert.Equal(t, escrowBefore-120_000, grc20faucet.BalanceOf("RED", Home()), "escrow shrank by the same")
	_, issuedAfter := Solvency("nred")
	uassert.Equal(t, issuedBefore-120_000, issuedAfter,
		"the coins were destroyed, not moved: total supply fell")

	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "must be paid", func() { Unwrap(cross(cur), "nred") })
}

